// Permanent spec for the authored spell effects. Replaces the throwaway
// probes, add a new `it(...)` block per spell and `npm test` re-verifies
// everything in milliseconds.
import { describe, it, expect } from "vitest";
import { card, mkCreature, scenario, byId } from "./testkit";
import { Rng } from "./rng";
import { playCard, endTurn, startTurn, canPlayCard, drawCard, resolvePendingAction, cancelPendingAction, validPendingTargets, runTrigger, claimReserve, plantSeed, seedPlantCost, resolveDeathsAndWin, withAuras, fireContreCoup, createInitialState, applyMulligan, effectiveCost, creatureCost, MAX_HAND } from "./rules";
import type { DofusInstance, GameEvent } from "./state";
import { validSpawnCells, validSeedCells, spellDamageReductionAgainst } from "./queries";
import { applyEffects, resolveDynamicValue, transformCreature, woundDofus, dofusInvulnerable, slideCreatureBack, bumpStat } from "./effects";
import { legalActions } from "../ai/actions";

// Give both sides a non-empty deck so the start-of-turn draw after an endTurn does not trigger
// deck-out FATIGUE (rule 11), used by tests that endTurn to exercise other mechanics (combat,
// Sinistro, Maluss…), not fatigue. The scenario() helper leaves decks empty; the drawer would
// otherwise fatigue all its Dofus by 1. Filler #16 is a plain card, harmless once in hand.
const withDecks = (s: ReturnType<typeof scenario>): ReturnType<typeof scenario> => ({
  ...s,
  players: {
    ...s.players,
    ally: { ...s.players.ally, deck: [16, 16, 16] },
    enemy: { ...s.players.enemy, deck: [16, 16, 16] },
  },
});

describe("Auto-dégât (« s'inflige N dégât ») : passe par l'ARMURE comme tout dégât subi", () => {
  const muguet = (id: number, armor: number) =>
    mkCreature(id, "ally", { x: 6, y: 2 }, {
      cardId: 946, triggers: card(946).triggers ?? [],
      currentLife: 6, baseLife: 6, armor, movementLeft: 0, hasAttacked: true,
    });
  it("#946 Muguet Tourmenté AVEC armure : l'auto-dégât de FIN DU TOUR entame l'AR, pas les PV", () => {
    card(946);
    const s = endTurn(withDecks(scenario([muguet(1, 2)])));
    expect(byId(s, 1)!.armor).toBe(1);       // 1 dégât absorbé par l'armure
    expect(byId(s, 1)!.currentLife).toBe(6); // PV intacts
  });
  it("#946 Muguet SANS armure : l'auto-dégât entame bien les PV (non-régression)", () => {
    card(946);
    const s = endTurn(withDecks(scenario([muguet(2, 0)])));
    expect(byId(s, 2)!.currentLife).toBe(5);
    expect(byId(s, 2)!.armor).toBe(0);
  });
});

describe("Une case ne porte jamais deux objets au sol", () => {
  it("Coffre + Pollinisation : la graine REMPLACE le butin sur la case de mort", () => {
    card(711); card(58);
    // Enemy Coffre on its start cell (x=1), so its death cell = the cell where its MORT drops the butin.
    // Pollinisation kills it and plants a seed on that same cell.
    const coffre = mkCreature(1, "enemy", { x: 1, y: 2 }, { cardId: 711, currentLife: 2, baseLife: 3, triggers: card(711).triggers ?? [] });
    const base = scenario([coffre], 58);
    const s = playCard(base, card(58), { x: 0, y: 0 });
    expect(byId(s, 1)).toBeFalsy(); // coffre mort
    const seedHere = (s.seeds ?? []).filter((g) => g.position.x === 1 && g.position.y === 2);
    expect(seedHere).toHaveLength(1);              // la graine est là...
    expect(seedHere[0].owner).toBe("ally");        // ...alliée (Pollinisation)
    expect((s.butins ?? []).some((b) => b.position.x === 1 && b.position.y === 2)).toBe(false); // the butin was replaced
    // Visible: the butin appeared (NEW_A_O_E loot) then disappeared (A_O_E_REMOVED), replaced by the seed.
    expect(s.log.some((e) => e.type === "A_O_E_REMOVED")).toBe(true);
  });
  it("plantation REFUSÉE sur une case déjà occupée par un objet (butin), cases au choix : on saute", () => {
    const base = scenario([]);
    const st = { ...base, butins: [{ position: { x: 6, y: 2 }, owner: "ally" as const }], players: { ...base.players, ally: { ...base.players.ally, seedReserve: 3, ap: 10 } } };
    const s = plantSeed(st, "ally", { x: 6, y: 2 });
    expect((s.seeds ?? []).some((g) => g.position.x === 6 && g.position.y === 2)).toBe(false); // pas planté
    expect(s.players.ally.seedReserve).toBe(3); // reserve + AP untouched (the action was refused, not just without a visible effect)
    expect(s.players.ally.ap).toBe(10);
  });
});

describe("playCard : joue l'EXEMPLAIRE sélectionné (handIndex), pas le moins cher", () => {
  // Deux Bouftou Noir #40 (coût 2) en main : slot 0 au coût PLEIN, slot 1 remisé de 1.
  const twoCopies = () => {
    const base = scenario([]);
    return { ...base, players: { ...base.players, ally: { ...base.players.ally, hand: [40, 40], handCostMods: [0, -1], ap: 20, maxAp: 20, deck: [] } } };
  };
  it("sans handIndex → le MOINS cher est dépensé (slot 1)", () => {
    const st = twoCopies();
    const s = playCard(st, card(40), { x: 8, y: 2 });
    expect(s.players.ally.handCostMods).toEqual([0]);            // slot 1 retiré → il reste le slot plein
    expect(st.players.ally.ap - s.players.ally.ap).toBe(1);      // a payé 2 − 1 = 1
  });
  it("avec handIndex=0 → l'exemplaire PLEIN est dépensé (slot 0), à son coût", () => {
    const st = twoCopies();
    const s = playCard(st, card(40), { x: 8, y: 2 }, { handIndex: 0 });
    expect(s.players.ally.handCostMods).toEqual([-1]);           // slot 0 removed → the discounted slot is left
    expect(st.players.ally.ap - s.players.ally.ap).toBe(2);      // a payé le coût PLEIN
  });
  it("handIndex périmé (hors main / mauvaise carte) → repli sur le moins cher", () => {
    const st = twoCopies();
    const s = playCard(st, card(40), { x: 8, y: 2 }, { handIndex: 9 }); // index hors main
    expect(s.players.ally.handCostMods).toEqual([0]);            // repli cheapest = slot 1
  });
  it("canPlayCard refuse l'exemplaire sélectionné trop cher même si un moins cher est jouable", () => {
    const base = scenario([]);
    const st = { ...base, players: { ...base.players, ally: { ...base.players.ally, hand: [40, 40], handCostMods: [0, -100], ap: 1, maxAp: 10 } } };
    expect(canPlayCard(st, card(40), { x: 8, y: 2 })).toBeNull();        // moins cher (slot 1) → jouable à 1 PA
    expect(canPlayCard(st, card(40), { x: 8, y: 2 }, 1)).toBeNull();     // slot 1 explicite → jouable
    expect(canPlayCard(st, card(40), { x: 8, y: 2 }, 0)).not.toBeNull(); // slot 0 (coût 2 > 1 PA) → refusé
  });
});

describe("Win condition (destroy 2 enemy real Dofus)", () => {
  const dof = (x: number, y: number, owner: "ally" | "enemy", kind: "real" | "fake", life = 5): DofusInstance =>
    ({ position: { x, y }, owner, currentLife: life, kind });
  // 3 living ally reals (so the ally never loses in these scenarios).
  const allyReals = (): DofusInstance[] => [dof(9, 0, "ally", "real"), dof(9, 2, "ally", "real"), dof(9, 4, "ally", "real")];
  it("ally WINS once 2 of the enemy's 3 real Dofus are gone", () => {
    const s = scenario([]);
    // Only 1 enemy real still alive → 2 destroyed.
    const dofuses = [...allyReals(), dof(0, 0, "enemy", "real")];
    const res = resolveDeathsAndWin(s, [], dofuses, [], new Set());
    expect(res.winner).toBe("ally");
  });
  it("No win when only 1 enemy real Dofus is gone", () => {
    const s = scenario([]);
    const dofuses = [...allyReals(), dof(0, 0, "enemy", "real"), dof(0, 2, "enemy", "real")];
    const res = resolveDeathsAndWin(s, [], dofuses, [], new Set());
    expect(res.winner).toBeNull();
  });
  it("destroying fake Dofus never wins (all 3 enemy reals still alive)", () => {
    const s = scenario([]);
    const dofuses = [...allyReals(), dof(0, 0, "enemy", "real"), dof(0, 2, "enemy", "real"), dof(0, 4, "enemy", "real")];
    const res = resolveDeathsAndWin(s, [], dofuses, [], new Set());
    expect(res.winner).toBeNull();
  });
});

describe("Dofus placement (random)", () => {
  const layout = (side: "ally" | "enemy") => {
    const s = scenario([]);
    return s.dofuses
      .filter((d) => d.owner === side)
      .sort((a, b) => a.position.y - b.position.y)
      .map((d) => d.kind);
  };
  it("each side has exactly 3 real + 2 fake Dofus", () => {
    for (const side of ["ally", "enemy"] as const) {
      const ks = layout(side);
      expect(ks.length).toBe(5);
      expect(ks.filter((k) => k === "real").length).toBe(3);
      expect(ks.filter((k) => k === "fake").length).toBe(2);
    }
  });
  it("the real/fake rows are randomised (not always rows 0,2,4)", () => {
    // Over many fresh matches we should see more than one distinct arrangement.
    const seen = new Set<string>();
    for (let i = 0; i < 40; i++) seen.add(layout("ally").join(""));
    expect(seen.size).toBeGreaterThan(1);
  });
  it("ally and enemy are randomised independently", () => {
    let differed = false;
    for (let i = 0; i < 40 && !differed; i++) {
      const s = scenario([]);
      const a = s.dofuses.filter((d) => d.owner === "ally").sort((x, y) => x.position.y - y.position.y).map((d) => d.kind).join("");
      const e = s.dofuses.filter((d) => d.owner === "enemy").sort((x, y) => x.position.y - y.position.y).map((d) => d.kind).join("");
      if (a !== e) differed = true;
    }
    expect(differed).toBe(true);
  });
});

describe("Tristepin (conditional initiative)", () => {
  const FS = (cs: ReturnType<typeof withAuras>, id: number) =>
    cs.find((c) => c.instanceId === id)!.properties.has("FirstStrike");
  it("#6 Tristepin gains initiative only while another allied Confrérie-du-Tofu member is in play", () => {
    card(6); // ensure the pool (and Tristepin's ConditionalFirstStrike) is registered
    const tristepin = mkCreature(1, "ally", { x: 6, y: 2 });
    tristepin.cardId = 6;
    expect(FS(withAuras([tristepin]), 1)).toBe(false); // alone → no initiative
    const bro = mkCreature(2, "ally", { x: 6, y: 1 }); bro.cardId = 28; // Cléophée (Tofu)
    expect(FS(withAuras([tristepin, bro]), 1)).toBe(true);  // ally Tofu present → initiative
    bro.currentLife = 0;
    expect(FS(withAuras([tristepin, bro]), 1)).toBe(false); // buddy dead → initiative lost
  });
  it("#6 Tristepin silenced loses its conditional initiative even with a Tofu ally present", () => {
    // silence takes away the creature's own abilities, including a conditional self keyword.
    card(6);
    const tristepin = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 6, silenced: true });
    const bro = mkCreature(2, "ally", { x: 6, y: 1 }, { cardId: 28 }); // Cléophée (Tofu), condition would be met
    expect(FS(withAuras([tristepin, bro]), 1)).toBe(false); // silenced → no conditional initiative
  });
  it("#6 Tristepin: an enemy Tofu member does not grant initiative (allied only)", () => {
    card(6);
    const tristepin = mkCreature(1, "ally", { x: 6, y: 2 }); tristepin.cardId = 6;
    const enemyBro = mkCreature(3, "enemy", { x: 4, y: 1 }); enemyBro.cardId = 28;
    expect(FS(withAuras([tristepin, enemyBro]), 1)).toBe(false);
  });
  it("#6 Tristepin: 'APPARITION Charge' charges its PM immediately, then stays summoning-sick", () => {
    const base = { ...scenario([], 6), prisms: [] };
    const s = playCard(base, card(6), { x: 8, y: 2 }); // summon → APPARITION ChargeSelf
    expect(s.creatures.find((c) => c.cardId === 6)!.position.x).toBe(5); // charged 3 PM now (8 → 5)
    // Summoning-sick: it must not advance again on the end-of-turn resolution.
    const after = endTurn(s);
    expect(after.creatures.find((c) => c.cardId === 6)!.position.x).toBe(5); // still at 5
  });
  it("#288 Protoflex: après sa charge d'APPARITION il reste en mal d'invocation, n'ATTAQUE PAS en fin de tour", () => {
    const base = { ...scenario([], 288), prisms: [] };
    const s = playCard(base, card(288), { x: 8, y: 2 }); // charge d'APPARITION dans le vide (8 → 3)
    const proto = s.creatures.find((c) => c.cardId === 288)!;
    expect(proto.hasAttacked).toBe(true); // still has summoning sickness after the charge (must not be reset to false)
    // An enemy ends up right in front of its cell after the charge: at end of turn, a creature with
    // summoning sickness must never play, so it must not engage it.
    const enemy = mkCreature(50, "enemy", { x: proto.position.x - 1, y: proto.position.y }, { currentLife: 3, baseLife: 3, hasAttacked: true, movementLeft: 0 });
    const injected = { ...s, creatures: [...s.creatures, enemy], players: { ...s.players, ally: { ...s.players.ally, deck: [16, 16, 16] }, enemy: { ...s.players.enemy, deck: [16, 16, 16] } } };
    const after = endTurn(injected);
    const enemyAfter = after.creatures.find((c) => c.instanceId === 50);
    expect(enemyAfter).toBeTruthy();          // l'ennemi est toujours là
    expect(enemyAfter!.currentLife).toBe(3);  // Intact : Protoflex n'a pas rejoué en fin de tour
  });
  it("#444 Lilotte EN JEU : sa charge ON_PLAY est un bonus, elle avance quand même en fin de tour", () => {
    card(444);
    // Lilotte in play since an earlier turn (no summoning sickness), PM 4.
    const lilotte = mkCreature(70, "ally", { x: 7, y: 0 }, { cardId: 444, triggers: card(444).triggers ?? [], movementLeft: 4, baseMovement: 4, currentLife: 3, baseLife: 3 });
    const base = { ...scenario([lilotte], 16), prisms: [] };
    const st = { ...base, players: { ...base.players, ally: { ...base.players.ally, deck: [16, 16, 16] }, enemy: { ...base.players.enemy, deck: [16, 16, 16] } } };
    const s = playCard(st, card(16), { x: 8, y: 4 }); // "quand vous jouez une carte" → it charges 1 cell (7 → 6)
    expect(byId(s, 70)!.position.x).toBe(6);
    expect(byId(s, 70)!.movementLeft).toBe(4); // end-of-turn budget restored (the charge is a bonus)
    const after = endTurn(s);
    expect(byId(after, 70)!.position.x).toBe(2); // avance normale de fin de tour : 4 PM (6 → 2)
  });
});

describe("Fléau (Dofus-only)", () => {
  it("#757 Fléau can target an allied dofus and an enemy dofus", () => {
    const s = scenario([], 757);
    // Dofuses are placed by createInitialState: ally on col 9, enemy on col 0.
    expect(canPlayCard(s, card(757), { x: 9, y: 0 })).toBeNull(); // allied dofus
    expect(canPlayCard(s, card(757), { x: 0, y: 0 })).toBeNull(); // enemy dofus
  });
  it("#757 Fléau cannot target a creature", () => {
    const foe = mkCreature(1, "enemy", { x: 4, y: 2 }, { currentLife: 5, baseLife: 5 });
    const ally = mkCreature(2, "ally", { x: 6, y: 2 }, { currentLife: 5, baseLife: 5 });
    const s = scenario([foe, ally], 757);
    expect(canPlayCard(s, card(757), { x: 4, y: 2 })).not.toBeNull(); // enemy creature → rejected
    expect(canPlayCard(s, card(757), { x: 6, y: 2 })).not.toBeNull(); // ally creature → rejected
  });
  it("#757 Fléau cannot target an empty cell", () => {
    const s = scenario([], 757);
    expect(canPlayCard(s, card(757), { x: 5, y: 2 })).not.toBeNull();
  });
  it("#757 Fléau deals its damage to the chosen dofus", () => {
    const s = scenario([], 757);
    const before = s.dofuses.find((d) => d.position.x === 0 && d.position.y === 0)!.currentLife;
    const s2 = playCard(s, card(757), { x: 0, y: 0 });
    const after = s2.dofuses.find((d) => d.position.x === 0 && d.position.y === 0)!.currentLife;
    expect(after).toBe(before - 1);
  });
  it("#757 Fléau is a token → goes to the SPECIAL tokenDiscard, never the normal discard", () => {
    // The Fléau is a token (isToken on the card data). When played it must not enter
    // the recoverable discard pile, it lands in the inaccessible tokenDiscard zone.
    expect(card(757).isToken).toBe(true);
    const s = scenario([], 757);
    const s2 = playCard(s, card(757), { x: 0, y: 0 });
    expect(s2.players.ally.discard).not.toContain(757);     // Not in the normal pile
    expect(s2.players.ally.tokenDiscard).toContain(757);    // in the special token pile
  });
});

describe("Havre-sac #1131 (inflige à un Dofus autant de dégâts que de Butins en jeu)", () => {
  const dofLife = (s: ReturnType<typeof scenario>) => s.dofuses.find((d) => d.position.x === 0 && d.position.y === 0)!.currentLife;
  it("deals damage to the targeted Dofus equal to the total butins in play (both sides, NumberOfLootsValue has no TeamFilter)", () => {
    const base = { ...scenario([], 1131), butins: [
      { position: { x: 6, y: 0 }, owner: "ally" as const },
      { position: { x: 5, y: 1 }, owner: "ally" as const },
      { position: { x: 3, y: 2 }, owner: "enemy" as const }, // an enemy butin counts too
    ] };
    const before = dofLife(base);
    const s = playCard(base, card(1131), { x: 0, y: 0 });
    expect(before - dofLife(s)).toBe(3); // 3 butins → 3 damage
  });
  it("deals 0 when no Butin is in play", () => {
    const base = { ...scenario([], 1131), butins: [] };
    const before = dofLife(base);
    const s = playCard(base, card(1131), { x: 0, y: 0 });
    expect(before - dofLife(s)).toBe(0);
  });
});

describe("Pelle Sismique #1104 (inflige aux invocations ADVERSES de la ligne, épargne les alliés, + Butin)", () => {
  it("damages only enemy creatures of the targeted row (allies spared), and digs a Butin on the cell", () => {
    card(1104);
    const allyRow = mkCreature(70, "ally", { x: 7, y: 2 }, { currentLife: 10, baseLife: 10 });
    const enemyRow = mkCreature(60, "enemy", { x: 4, y: 2 }, { currentLife: 10, baseLife: 10 });
    const allyOtherRow = mkCreature(71, "ally", { x: 6, y: 1 }, { currentLife: 10, baseLife: 10 });
    const enemyOtherRow = mkCreature(61, "enemy", { x: 4, y: 0 }, { currentLife: 10, baseLife: 10 });
    const base = scenario([allyRow, enemyRow, allyOtherRow, enemyOtherRow], 1104);
    const s0 = { ...base, prisms: [], butins: [], players: { ...base.players, ally: { ...base.players.ally, hand: [1104], handCostMods: [0], ap: 20, maxAp: 20 } } };
    expect(canPlayCard(s0, card(1104), { x: 6, y: 2 })).toBeNull(); // castable on an empty cell (picks the row)
    const s = playCard(s0, card(1104), { x: 6, y: 2 });
    expect(byId(s, 60)!.currentLife).toBe(7);  // enemy on the row: −3
    expect(byId(s, 70)!.currentLife).toBe(10); // ally on the row: untouched (this was the reported problem)
    expect(byId(s, 71)!.currentLife).toBe(10); // ally on another row: untouched
    expect(byId(s, 61)!.currentLife).toBe(10); // enemy on another row: untouched
    expect((s.butins ?? []).some((b) => b.position.x === 6 && b.position.y === 2 && b.owner === "ally")).toBe(true); // Butin dug
  });
});

describe("Pelle Sismique #1104, targeting rules (any cell + conditional Butin)", () => {
  // Cast on any cell of the board, enemy side included.
  it("is castable on any cell, enemy camp, an enemy creature, an object cell, an ally", () => {
    const enemy = mkCreature(60, "enemy", { x: 3, y: 2 });
    const ally = mkCreature(70, "ally", { x: 6, y: 2 });
    const base = { ...scenario([enemy, ally], 1104), prisms: [{ position: { x: 2, y: 1 }, owner: "enemy" as const, kind: "ap" as const }], butins: [] };
    expect(canPlayCard(base, card(1104), { x: 2, y: 0 })).toBeNull(); // empty enemy cell
    expect(canPlayCard(base, card(1104), { x: 3, y: 2 })).toBeNull(); // on an enemy creature
    expect(canPlayCard(base, card(1104), { x: 2, y: 1 })).toBeNull(); // on a board object
    expect(canPlayCard(base, card(1104), { x: 6, y: 2 })).toBeNull(); // on an ally
  });
  it("targeting an enemy that dies digs the Butin on its now-free cell (enemy side)", () => {
    const enemy = mkCreature(60, "enemy", { x: 3, y: 2 }, { currentLife: 3, baseLife: 3 });
    const base = { ...scenario([enemy], 1104), prisms: [], butins: [] };
    const s = playCard(base, card(1104), { x: 3, y: 2 });
    expect(s.creatures.some((c) => c.instanceId === 60 && c.currentLife > 0)).toBe(false); // died (-3)
    expect((s.butins ?? []).some((b) => b.position.x === 3 && b.position.y === 2 && b.owner === "ally")).toBe(true);
  });
  it("targeting an enemy that survives places no Butin (cell still occupied)", () => {
    const enemy = mkCreature(60, "enemy", { x: 3, y: 2 }, { currentLife: 10, baseLife: 10 });
    const base = { ...scenario([enemy], 1104), prisms: [], butins: [] };
    const s = playCard(base, card(1104), { x: 3, y: 2 });
    expect(byId(s, 60)!.currentLife).toBe(7); // survived
    expect((s.butins ?? []).some((b) => b.position.x === 3 && b.position.y === 2)).toBe(false);
  });
  it("targeting a board object destroys it and drops the Butin on the cell", () => {
    const base = { ...scenario([], 1104), butins: [], prisms: [{ position: { x: 3, y: 2 }, owner: "enemy" as const, kind: "ap" as const }] };
    const s = playCard(base, card(1104), { x: 3, y: 2 });
    expect((s.prisms ?? []).some((p) => p.position.x === 3 && p.position.y === 2)).toBe(false); // object destroyed
    expect((s.butins ?? []).some((b) => b.position.x === 3 && b.position.y === 2 && b.owner === "ally")).toBe(true);
  });
  it("targeting an ally places no Butin (and the ally is spared)", () => {
    const ally = mkCreature(70, "ally", { x: 6, y: 2 }, { currentLife: 10, baseLife: 10 });
    const base = { ...scenario([ally], 1104), prisms: [], butins: [] };
    const s = playCard(base, card(1104), { x: 6, y: 2 });
    expect(byId(s, 70)!.currentLife).toBe(10); // AoE is enemies-only
    expect((s.butins ?? []).some((b) => b.position.x === 6 && b.position.y === 2)).toBe(false);
  });
});

describe("Bain de Sang #1316 (subit autant de dégâts que d'invocations blessées en jeu, puis charge d'autant)", () => {
  it("deals damage = number of wounded creatures (both sides), then charges the target that many cells", () => {
    card(1316);
    const woundedAlly = mkCreature(70, "ally", { x: 7, y: 1 }, { currentLife: 3, baseLife: 5 });   // wounded
    const woundedEnemy = mkCreature(71, "enemy", { x: 3, y: 1 }, { currentLife: 2, baseLife: 5 });  // wounded
    const fullAlly = mkCreature(72, "ally", { x: 8, y: 0 }, { currentLife: 5, baseLife: 5 });        // Not wounded → not counted
    const target = mkCreature(60, "enemy", { x: 4, y: 2 }, { currentLife: 10, baseLife: 10 });       // full target
    const base = scenario([woundedAlly, woundedEnemy, fullAlly, target], 1316);
    const s0 = { ...base, prisms: [], players: { ...base.players, ally: { ...base.players.ally, hand: [1316], handCostMods: [0], ap: 20, maxAp: 20 } } };
    const s = playCard(s0, card(1316), { x: 4, y: 2 });
    expect(byId(s, 60)!.currentLife).toBe(8);        // 10 − 2 (two wounded creatures)
    expect(byId(s, 60)!.position).toEqual({ x: 6, y: 2 }); // then charged 2 cells forward (enemy → +x)
  });
  it("with no wounded creature: 0 damage and no charge", () => {
    card(1316);
    const target = mkCreature(60, "enemy", { x: 4, y: 2 }, { currentLife: 10, baseLife: 10 });
    const base = scenario([target], 1316);
    const s0 = { ...base, prisms: [], players: { ...base.players, ally: { ...base.players.ally, hand: [1316], handCostMods: [0], ap: 20, maxAp: 20 } } };
    const s = playCard(s0, card(1316), { x: 4, y: 2 });
    expect(byId(s, 60)!.currentLife).toBe(10);       // no wounded → 0 damage
    expect(byId(s, 60)!.position).toEqual({ x: 4, y: 2 }); // no charge
  });
});

describe("Instantina #371 (APPARITION : 2 dégâts, ou 5 si vous avez ≥ 5 PA en réserve)", () => {
  // The APPARITION opens a single-target damage pick; the amount is 2 normally, 5 when the
  // owner's AP reserve is at least 5 (NumberOfLootsValue-style threshold resolved on the reserve).
  const cast = (reserve: number) => {
    card(371);
    const foe = mkCreature(60, "enemy", { x: 4, y: 2 }, { currentLife: 10, baseLife: 10 });
    const base = scenario([foe], 371);
    const s0 = { ...base, prisms: [], players: { ...base.players, ally: { ...base.players.ally, hand: [371], handCostMods: [0], ap: 10, maxAp: 10, apReserve: reserve } } };
    let s = playCard(s0, card(371), { x: 8, y: 2 });
    expect(s.pendingAction!.filter).toBe("any_creature"); // APPARITION opens a damage pick
    s = resolvePendingAction(s, { x: 4, y: 2 }); // pick the enemy
    return 10 - byId(s, 60)!.currentLife;
  };
  it("deals 2 when the reserve is below 5", () => {
    expect(cast(4)).toBe(2);
  });
  it("deals 5 when the reserve is at least 5", () => {
    expect(cast(5)).toBe(5);
  });
});

describe("Sinistro #215 (équipement sur un Dofus allié : tir FIN DU TOUR, détruit si le Dofus est blessé)", () => {
  // Cast #215 on an allied Dofus (castTarget AlliedDofusWithoutEquipement). row-2 ally Dofus = (9,2).
  const dofAt = (s: ReturnType<typeof scenario>, x: number, y: number) =>
    s.dofuses.find((d) => d.position.x === x && d.position.y === y)!;
  const equip = (creatures: CreatureInstance[], extraHand: number[] = []) => {
    card(215); card(757);
    const base = scenario(creatures, 215, ...extraHand);
    const s0 = { ...base, prisms: [], players: { ...base.players, ally: { ...base.players.ally, hand: [215, ...extraHand], handCostMods: [0, ...extraHand.map(() => 0)], ap: 30, maxAp: 30 } } };
    return playCard(s0, card(215), { x: 9, y: 2 }); // equip the row-2 ally Dofus
  };
  it("attaches to the targeted allied Dofus without damaging it", () => {
    const s = equip([]);
    expect(dofAt(s, 9, 2).sinistroAttached).toBe(true);
    expect(dofAt(s, 9, 2).currentLife).toBe(5); // placement deals no damage (full Dofus)
  });
  it("cannot target an already-equipped Dofus, nor an enemy Dofus", () => {
    const s = equip([], [215]); // a 2nd Sinistro left in hand after equipping (9,2)
    expect(canPlayCard(s, card(215), { x: 9, y: 2 })).not.toBeNull(); // already equipped → rejected
    expect(canPlayCard(s, card(215), { x: 0, y: 2 })).not.toBeNull(); // enemy Dofus → rejected (Allied only)
    expect(canPlayCard(s, card(215), { x: 9, y: 0 })).toBeNull();     // a free allied Dofus → legal
  });
  it("FIN DU TOUR: shoots the first enemy creature on its row for 1 (allies in front do not block)", () => {
    const blocker = mkCreature(70, "ally", { x: 7, y: 2 }, { movementLeft: 0, hasAttacked: true }); // in front, will not move/block
    const foe = mkCreature(60, "enemy", { x: 4, y: 2 }, { currentLife: 10, baseLife: 10, movementLeft: 0, hasAttacked: true });
    const s = endTurn(equip([blocker, foe]));
    expect(byId(s, 60)!.currentLife).toBe(9); // 1 damage, ally blocker skipped
  });
  it("FIN DU TOUR: with no creature on the row, hits the enemy Dofus of that row for 1", () => {
    const before = dofAt(equip([]), 0, 2).currentLife;
    const s = endTurn(withDecks(equip([])));
    expect(dofAt(s, 0, 2).currentLife).toBe(before - 1);
  });
  it("is destroyed when its host Dofus is wounded (the Dofus still takes the damage)", () => {
    let s = equip([], [757]); // Fléau #757 in hand
    s = playCard(s, card(757), { x: 9, y: 2 }); // wound the equipped own Dofus
    expect(dofAt(s, 9, 2).currentLife).toBe(4);          // host took the 1 damage…
    expect(dofAt(s, 9, 2).sinistroAttached).toBeFalsy(); // …and the Sinistro is gone
  });
});

describe("Diod Dewit #337 (APPARITION : placez un Sinistro sur un Dofus allié choisi, pose ciblée)", () => {
  const dofAt = (s: ReturnType<typeof scenario>, x: number, y: number) =>
    s.dofuses.find((d) => d.position.x === x && d.position.y === y)!;
  const play337 = (extraHand: number[] = []) => {
    card(337); card(215);
    const base = scenario([], 337, ...extraHand);
    const s0 = { ...base, prisms: [], players: { ...base.players, ally: { ...base.players.ally, hand: [337, ...extraHand], handCostMods: [0, ...extraHand.map(() => 0)], ap: 30, maxAp: 30 } } };
    return playCard(s0, card(337), { x: 8, y: 2 });
  };
  it("is held off the board and opens an allied-Dofus pick (deferred summon)", () => {
    const s = play337();
    expect(s.creatures.some((c) => c.cardId === 337)).toBe(false); // not placed yet
    expect(s.pendingAction!.filter).toBe("ally_dofus_no_equipment");
  });
  it("picking an allied Dofus lands Diod Dewit and attaches the Sinistro to that Dofus", () => {
    let s = play337();
    s = resolvePendingAction(s, { x: 9, y: 0 }); // choose the row-0 ally Dofus
    expect(s.creatures.some((c) => c.cardId === 337)).toBe(true); // Diod Dewit landed
    expect(dofAt(s, 9, 0).sinistroAttached).toBe(true);   // the chosen Dofus is equipped
    expect(dofAt(s, 9, 2).sinistroAttached).toBeFalsy();  // others are not
    expect(s.pendingAction).toBeNull();
  });
  it("declining on the board lands Diod Dewit with no Sinistro (secondary target is optional)", () => {
    const s = resolvePendingAction(play337(), { x: 7, y: 2 }); // a non-Dofus board cell → land, no Sinistro
    expect(s.creatures.some((c) => c.cardId === 337)).toBe(true); // landed
    expect(s.dofuses.some((d) => d.sinistroAttached)).toBe(false); // no Sinistro placed
  });
  it("clicking off the board cancels: Diod Dewit back to hand, no Sinistro", () => {
    const s = cancelPendingAction(play337());
    expect(s.creatures.some((c) => c.cardId === 337)).toBe(false); // not placed
    expect(s.players.ally.hand).toContain(337);                    // back in hand
    expect(s.dofuses.some((d) => d.sinistroAttached)).toBe(false);
  });
  it("the pick excludes an already-equipped Dofus", () => {
    // Equip (9,2) first via the #215 spell, then play Diod Dewit, (9,2) must not be a valid target.
    let s = play337([215]);
    s = resolvePendingAction(s, { x: 7, y: 2 }); // decline on board → land Diod Dewit without equipping
    s = playCard(s, card(215), { x: 9, y: 2 }); // Sinistro #215 onto (9,2)
    expect(dofAt(s, 9, 2).sinistroAttached).toBe(true);
    expect(canPlayCard(s, card(215), { x: 9, y: 2 })).not.toBeNull(); // equipped → #215 cannot re-target it
    const free = validPendingTargets({ ...s, pendingAction: { side: "ally", prompt: "", filter: "ally_dofus_no_equipment", pendingEffects: [], sourceInstanceId: -1 } });
    expect(free.some((c) => c.x === 9 && c.y === 2)).toBe(false); // equipped Dofus excluded from the pick
    expect(free.some((c) => c.x === 9 && c.y === 0)).toBe(true);  // a free ally Dofus is offered
  });
});

describe("Nécronomigore #700 (équipement Dofus : compte à rebours 6, puis 5 à TOUS les Dofus adverses)", () => {
  card(700); card(215); card(385);
  const withBigDecks = <T extends ReturnType<typeof scenario>>(s: T): T => ({
    ...s,
    players: {
      ...s.players,
      ally: { ...s.players.ally, deck: Array(20).fill(385) },
      enemy: { ...s.players.enemy, deck: Array(20).fill(385) }, // both decks stocked → no fatigue skews the Dofus PV
    },
  });
  const allyDofPos = (s: ReturnType<typeof scenario>) => s.dofuses.find((d) => d.owner === "ally")!.position;
  const hostAt = (s: ReturnType<typeof scenario>, pos: { x: number; y: number }) =>
    s.dofuses.find((d) => d.owner === "ally" && d.position.x === pos.x && d.position.y === pos.y)!;
  const play700 = () => {
    const sc = scenario([]);
    const pos = allyDofPos(sc);
    const base = { ...sc, prisms: [], players: { ...sc.players, ally: { ...sc.players.ally, hand: [700], handCostMods: [0], ap: 20, maxAp: 20 } } };
    return { s: playCard(base, card(700), pos), pos };
  };

  it("se pose sur un Dofus allié (compteur 6), SANS dégât, et occupe le slot d'équipement", () => {
    const { s, pos } = play700();
    const host = hostAt(s, pos);
    expect(host.necronomigoreCounter).toBe(6);             // compteur armé à 6
    expect(host.currentLife).toBe(5);                      // aucun dégât à la pose (bindata DamageData{5} supprimé)
    expect(canPlayCard(s, card(700), pos)).not.toBeNull(); // déjà équipé → 2e Nécronomigore refusé
  });

  it("partage le slot d'équipement avec le Sinistro #215 (un Dofus équipé refuse l'autre)", () => {
    const { s, pos } = play700();
    const s2 = { ...s, players: { ...s.players, ally: { ...s.players.ally, hand: [215], handCostMods: [0], ap: 20, maxAp: 20 } } };
    expect(canPlayCard(s2, card(215), pos)).not.toBeNull(); // Sinistro refused on a Dofus that is already equipped
  });

  it("le compteur décrémente à chaque fin de TON tour, sans dégât avant 0", () => {
    const { s, pos } = play700();
    const s1 = endTurn(withBigDecks({ ...s, prisms: [] }));  // fin de TON tour → 6→5, pas de tir
    expect(hostAt(s1, pos).necronomigoreCounter).toBe(5);
    expect(s1.dofuses.filter((d) => d.owner === "enemy").every((d) => d.currentLife === 5)).toBe(true); // aucun Dofus adverse touché
  });

  it("au tick 0, inflige 5 à TOUS les Dofus adverses (alliés intacts) et reste armé", () => {
    const sc = withBigDecks(scenario([]));
    const pos = allyDofPos(sc);
    const dofuses = sc.dofuses.map((d) => {
      if (d.owner === "ally" && d.position.x === pos.x && d.position.y === pos.y) return { ...d, necronomigoreCounter: 1 };
      if (d.owner === "enemy") return { ...d, currentLife: 10, baseLife: 10 }; // 10 PV pour observer les 5 (sinon détruits = victoire)
      return d;
    });
    const s1 = endTurn({ ...sc, prisms: [], dofuses });
    expect(s1.dofuses.filter((d) => d.owner === "enemy").every((d) => d.currentLife === 5)).toBe(true); // chacun a pris 5
    expect(hostAt(s1, pos).necronomigoreCounter).toBe(0);                                                // reste armé (tire chaque tour)
    expect(s1.dofuses.filter((d) => d.owner === "ally").every((d) => d.currentLife === 5)).toBe(true);   // alliés jamais touchés
  });

  it("un Nécronomigore déjà armé (compteur 0) détruit toute la ligne adverse → victoire", () => {
    const sc = withBigDecks(scenario([]));
    const pos = allyDofPos(sc);
    const dofuses = sc.dofuses.map((d) => (d.owner === "ally" && d.position.x === pos.x && d.position.y === pos.y ? { ...d, necronomigoreCounter: 0 } : d));
    const s1 = endTurn({ ...sc, prisms: [], dofuses }); // deals 5 to all enemy Dofus (5 HP) → all captured
    expect(s1.winner).toBe("ally");
  });

  it("ne tire PAS pendant le tour adverse (seulement à TES fins de tour)", () => {
    const sc = withBigDecks(scenario([]));
    const pos = allyDofPos(sc);
    const dofuses = sc.dofuses.map((d) => (d.owner === "ally" && d.position.x === pos.x && d.position.y === pos.y ? { ...d, necronomigoreCounter: 0 } : d));
    const s1 = endTurn({ ...sc, prisms: [], dofuses, activeSide: "enemy" as const }); // fin du tour ADVERSE
    expect(s1.dofuses.filter((d) => d.owner === "enemy").every((d) => d.currentLife === 5)).toBe(true); // the allied Nécronomigore did not fire
    expect(s1.winner).toBeFalsy();
  });

  it("Fusion en cascade: 6 Orbes → 2 Orbes Dorés → 1 Nécronomigore (#700)", () => {
    const sc = scenario([]); // #1217 = NÉCROME simple
    const base = { ...sc, prisms: [], players: { ...sc.players, ally: { ...sc.players.ally, hand: [1217, 708, 708, 708, 708, 708], handCostMods: [0, 0, 0, 0, 0, 0], ap: 20, maxAp: 20 } } };
    const held = playCard(base, card(1217), { x: 8, y: 2 });   // 1217 part → main [708×5]
    const landed = resolvePendingAction(held, { x: 7, y: 2 }); // décline sur le plateau → +1 Orbe de base → 6 Orbes fusionnent
    const hand = landed.players.ally.hand;
    expect(hand.filter((id) => id === 708).length).toBe(0);    // toutes les Orbes consommées
    expect(hand.filter((id) => id === 594).length).toBe(0);    // the 2 Orbes Dorés too (merged)
    expect(hand.filter((id) => id === 700).length).toBe(1);    // → 1 Nécronomigore
  });
});

describe("Championne Périmée #634 (Enutrof NÉCROME + Phorzerker : pick combiné Phorreur OU Dofus)", () => {
  const ORBE = 708;
  const cnt = (s: ReturnType<typeof scenario>, id: number) => s.players.ally.hand.filter((x) => x === id).length;
  const play = () => {
    card(634); card(16); card(800); card(708);
    const ph = mkCreature(50, "ally", { x: 8, y: 1 }, { cardId: 16, currentAttack: 2, baseAttack: 2, currentLife: 1, baseLife: 1, triggers: card(16).triggers ?? [] });
    const enemy = mkCreature(60, "enemy", { x: 4, y: 2 }, { currentLife: 5, baseLife: 5, movementLeft: 3, baseMovement: 3 });
    const base = scenario([ph, enemy], 634);
    const s0 = { ...base, prisms: [], players: { ...base.players, ally: { ...base.players.ally, hand: [634], handCostMods: [0], ap: 20, maxAp: 20 } } };
    return playCard(s0, card(634), { x: 8, y: 0 });
  };
  it("holds the Énutrof off-board and opens the combined Phorreur/Dofus pick (no base Orbe yet)", () => {
    const s = play();
    expect(s.creatures.some((c) => c.cardId === 634)).toBe(false);    // held off-board (deferred)
    expect(s.pendingAction!.filter).toBe("ally_phorreur_or_unrevealed_dofus");
    expect(cnt(s, ORBE)).toBe(0);                                     // base Orbe granted only at landing
  });
  it("clicking a PHORREUR fuses (Phorzerker #800, summed AT/PV, Énutrof PM, Phorreur banished, no 2nd Orbe, APPARITION cancelled)", () => {
    let s = play();
    s = resolvePendingAction(s, { x: 8, y: 1 });
    const fused = s.creatures.find((c) => c.position.x === 8 && c.position.y === 0)!;
    expect(fused.cardId).toBe(800);
    expect(fused.currentAttack).toBe(5); // 3 (Championne) + 2 (Phorreur)
    expect(fused.currentLife).toBe(5);   // 4 + 1
    expect(fused.baseMovement).toBe(3);  // Championne's PM
    expect(fused.costOverride).toBe(4);  // in-play cost = Championne's cost (#634), not token 800's 3
    expect(creatureCost(fused)).toBe(4);
    expect(byId(s, 50)).toBeUndefined();        // Phorreur banished
    expect(s.players.ally.banished).toContain(16);
    expect(cnt(s, ORBE)).toBe(1);               // base Orbe only (no reveal)
    expect(byId(s, 60)!.baseMovement).toBe(3);  // APPARITION did not fire (fusion cancels it), enemy PM unchanged
  });
  it("clicking an unrevealed DOFUS reveals it for a 2nd Orbe, then fires the APPARITION", () => {
    let s = play();
    const dof = s.dofuses.find((d) => d.owner === "ally" && !d.revealed)!.position;
    s = resolvePendingAction(s, dof);
    expect(s.dofuses.find((d) => d.position.x === dof.x && d.position.y === dof.y)!.revealed).toBe(true);
    expect(cnt(s, ORBE)).toBe(2);               // base + 2nd Orbe
    expect(s.creatures.some((c) => c.cardId === 634)).toBe(true); // stays Championne (not fused)
    expect(byId(s, 60)!.baseMovement).toBe(2);  // APPARITION fired (enemy PM → 2)
  });
  it("clicking ELSEWHERE on the board lands it normally: no fusion, no 2nd Orbe, base Orbe + APPARITION", () => {
    const s = resolvePendingAction(play(), { x: 7, y: 0 }); // a non-target board cell → land + decline
    expect(s.creatures.some((c) => c.cardId === 634)).toBe(true); // placed
    expect(byId(s, 50)).not.toBeUndefined();    // Phorreur intact
    expect(cnt(s, ORBE)).toBe(1);               // base Orbe (at landing) only
    expect(byId(s, 60)!.baseMovement).toBe(2);  // APPARITION fired
  });
  it("clicking off the board cancels the play: card back to hand, no Orbe, Phorreur intact, no APPARITION", () => {
    const s = cancelPendingAction(play());
    expect(s.creatures.some((c) => c.cardId === 634)).toBe(false); // Not placed
    expect(s.players.ally.hand).toContain(634);  // card back in hand
    expect(byId(s, 50)).not.toBeUndefined();     // Phorreur intact
    expect(cnt(s, ORBE)).toBe(0);                // no base Orbe
    expect(byId(s, 60)!.baseMovement).toBe(3);   // APPARITION did not fire (enemy PM unchanged)
  });
});

