describe("Charge (immediate)", () => {
  it("#440 Potion de Vélocité advances the creature 3 cells at cast", () => {
    let s = scenario([mkCreature(9, "ally", { x: 6, y: 1 }, { movementLeft: 0, hasAttacked: true })], 440);
    s = playCard(s, card(440), { x: 6, y: 1 });
    expect(byId(s, 9)!.position.x).toBe(3); // moved now, no endTurn
  });
  it("#427 Charge resolves combat immediately into an enemy", () => {
    const ally = mkCreature(10, "ally", { x: 5, y: 2 }, { currentAttack: 2, currentLife: 5, baseLife: 5 });
    const foe = mkCreature(11, "enemy", { x: 4, y: 2 }, { currentLife: 1, currentAttack: 3, baseLife: 1 });
    let s = scenario([ally, foe], 427);
    s = playCard(s, card(427), { x: 5, y: 2 });
    expect(byId(s, 11)).toBeUndefined(); // enemy died
    expect(byId(s, 10)!.currentLife).toBe(2); // took the counter
  });
  it("#427 ne peut plus CIBLER un Mur (CanCharge original : !Statue && !Stunned && !Rooted)", () => {
    // Before the vocabulary check, the cast went through and the effect did nothing; the original game
    // refuses the target itself (castTarget AnySummonThatCanCharge).
    const s = scenario([mkCreature(12, "ally", { x: 5, y: 2 }, { properties: new Set(["Statue"]) })], 427);
    expect(canPlayCard(s, card(427), { x: 5, y: 2 })).not.toBeNull();
  });
  it("#427 a charged creature still advances its PM at end of turn (charge ≠ spending PM)", () => {
    // Charge = an extra immediate 2-cell burst; it must not eat the creature's
    // normal end-of-turn movement. Existing ally with 3 PM, no obstacles:
    //   charge 2 (7 → 5) now, then advance its 3 PM at resolution (5 → 2).
    const ally = mkCreature(13, "ally", { x: 7, y: 1 }, { movementLeft: 3, baseMovement: 3, hasAttacked: false, currentLife: 5, baseLife: 5, currentAttack: 1 });
    let s = scenario([ally], 427);
    s = { ...s, prisms: [] };
    s = playCard(s, card(427), { x: 7, y: 1 });
    expect(byId(s, 13)!.position.x).toBe(5);     // charged 2 now
    expect(byId(s, 13)!.movementLeft).toBe(3);   // PM budget restored, not consumed
    s = endTurn(s);
    expect(byId(s, 13)!.position.x).toBe(2);     // advanced its 3 PM at end of turn
  });
  it("#427 a charge that CONNECTS still does the natural end-of-turn encounter", () => {
    // Charge is a bonus: striking with the burst must not consume the creature's
    // turn. Ally (3 PM) charges 2 into a surviving enemy and hits it, then at end
    // of turn advances again and hits it a second time (its fin-de-tour attack).
    const ally = mkCreature(13, "ally", { x: 7, y: 1 }, { movementLeft: 3, baseMovement: 3, hasAttacked: false, currentLife: 20, baseLife: 20, currentAttack: 2 });
    const foe = mkCreature(20, "enemy", { x: 5, y: 1 }, { currentLife: 10, baseLife: 10, currentAttack: 1 });
    let s = scenario([ally, foe], 427);
    s = { ...s, prisms: [] };
    s = playCard(s, card(427), { x: 7, y: 1 });
    expect(byId(s, 13)!.position.x).toBe(6);     // charged up to the enemy, struck it
    expect(byId(s, 20)!.currentLife).toBe(8);    // first hit (charge): 10 − 2
    s = endTurn(s);
    expect(byId(s, 20)!.currentLife).toBe(6);    // natural end-of-turn encounter: another −2
  });
  it("#486 Autorité: charges the target ally all the way to the enemy wall (toWall)", () => {
    // "Charge jusqu'au Dofus adverse" → cells "toWall": down the empty lane the
    // creature stops in front of the enemy Dofus (column 0 → lands on x=1).
    const ally = mkCreature(14, "ally", { x: 7, y: 1 }, { currentAttack: 1, currentLife: 5, baseLife: 5, movementLeft: 3, baseMovement: 3 });
    let s = scenario([ally], 486);
    s = { ...s, prisms: [] };
    s = playCard(s, card(486), { x: 7, y: 1 });
    expect(byId(s, 14)!.position.x).toBe(1);
  });
  it("#130 Justice: the charged ally keeps its full end-of-turn PM, the charge is a bonus", () => {
    // Justice sets the target's AT to 3 then charges it 2 cells. handleCharge (inside applyEffects)
    // overwrote the target's movementLeft with the charge distance, which applyChargeOnSummon then saved
    // as its budget, permanently stealing 1 PM. In the report a Chef Grouilleux +1 PM aura looked lost
    // (net 3 instead of 4) because Justice's charge had already eaten that PM. The charged ally must keep
    // its full fin-de-tour advance on top of the bonus charge.
    const ally = mkCreature(30, "ally", { x: 5, y: 1 }, { movementLeft: 3, baseMovement: 3, hasAttacked: false, currentAttack: 1, currentLife: 5, baseLife: 5 });
    let s = scenario([ally]);
    s = { ...s, prisms: [], players: { ...s.players, ally: { ...s.players.ally, hand: [130], deck: [16, 16, 16], ap: 10, maxAp: 10 }, enemy: { ...s.players.enemy, deck: [16, 16, 16] } } };
    s = playCard(s, card(130), { x: 8, y: 1 });   // summon Justice on a back-row spawn cell
    s = resolvePendingAction(s, { x: 5, y: 1 });   // target the ally
    expect(byId(s, 30)!.position.x).toBe(3);       // charged 2 cells (5 → 3), a bonus move
    expect(byId(s, 30)!.currentAttack).toBe(3);    // AT set to 3
    expect(byId(s, 30)!.movementLeft).toBe(3);     // Full PM preserved (was wrongly 2 before the fix)
  });

  it("#130 Justice sur une invocation INAMOVIBLE (Rooted) : PAS de charge, mais l'AT passe quand même à 3", () => {
    // Arakne à Crochets #1457 makes everything Rooted. INAMOVIBLE = "pas de charge", but Justice's
    // SetAttack is not a move, so it applies.
    const rooted = mkCreature(30, "ally", { x: 5, y: 1 }, { movementLeft: 3, baseMovement: 3, hasAttacked: false, currentAttack: 1, currentLife: 5, baseLife: 5, properties: new Set(["Rooted"]) });
    let s = scenario([rooted]);
    s = { ...s, prisms: [], players: { ...s.players, ally: { ...s.players.ally, hand: [130], deck: [16, 16, 16], ap: 10, maxAp: 10 }, enemy: { ...s.players.enemy, deck: [16, 16, 16] } } };
    s = playCard(s, card(130), { x: 8, y: 1 });
    s = resolvePendingAction(s, { x: 5, y: 1 });
    expect(byId(s, 30)!.position.x).toBe(5);     // INAMOVIBLE : n'a PAS chargé
    expect(byId(s, 30)!.currentAttack).toBe(3);  // AT → 3 anyway (not a move)
    expect(byId(s, 30)!.movementLeft).toBe(3);   // PM intacts
  });

  it("#283 Jice Aouaire : une invocation INAMOVIBLE ne charge PAS avec le groupe", () => {
    card(283);
    const rooted = mkCreature(1, "ally", { x: 6, y: 2 }, { currentLife: 5, baseLife: 5, movementLeft: 3, baseMovement: 3, hasAttacked: false, properties: new Set(["Rooted"]) });
    const mover = mkCreature(2, "ally", { x: 6, y: 0 }, { currentLife: 5, baseLife: 5, movementLeft: 3, baseMovement: 3, hasAttacked: false }); // témoin non-Rooted
    const s0 = scenario([rooted, mover], 283);
    const s1 = { ...s0, prisms: [], players: { ...s0.players, ally: { ...s0.players.ally, hand: [283], handCostMods: [0], ap: 10, maxAp: 10 } } };
    const s = playCard(s1, card(283), { x: 8, y: 4 }); // Jice : « vos autres invocations chargent de 1 »
    expect(byId(s, 1)!.position.x).toBe(6); // Rooted : pas de charge de groupe
    expect(byId(s, 2)!.position.x).toBe(5); // le témoin a bien chargé de 1 (6 → 5)
  });
});

describe("Gangraîne #1439 (BoostMovementPoisonData)", () => {
  it("stamps the poison value on the picked creature", () => {
    let s = scenario([mkCreature(50, "ally", { x: 6, y: 1 }, { movementLeft: 0, hasAttacked: true })], 1439);
    s = playCard(s, card(1439), { x: 6, y: 1 });
    expect(byId(s, 50)!.movementPoison).toBe(1);
  });

  it("deals 1 damage per cell walked at end of turn", () => {
    // Open lane: the ally advances its 3 PM (6 → 3) and takes 1 dmg per cell = 3.
    const ally = mkCreature(51, "ally", { x: 6, y: 1 }, { movementLeft: 3, baseMovement: 3, hasAttacked: false, currentLife: 5, baseLife: 5, currentAttack: 1, movementPoison: 1 });
    let s = scenario([ally]);
    s = { ...s, prisms: [] };
    s = endTurn(s);
    expect(byId(s, 51)!.position.x).toBe(3); // moved 3 cells
    expect(byId(s, 51)!.currentLife).toBe(2); // 5 − 3×1
  });

  it("kills the creature mid-lane when the poison out-damages its life", () => {
    // 2 life, poison 1: dies on the 2nd cell, never reaches the wall.
    const ally = mkCreature(52, "ally", { x: 6, y: 1 }, { movementLeft: 5, baseMovement: 5, hasAttacked: false, currentLife: 2, baseLife: 2, currentAttack: 1, movementPoison: 1 });
    let s = scenario([ally]);
    s = { ...s, prisms: [] };
    s = endTurn(s);
    expect(byId(s, 52)).toBeUndefined(); // culled by resolveDeathsAndWin
  });

  it("ticks on a CHARGE too (immediate burst goes through the step loop)", () => {
    // Gangraîne then a 2-cell Charge (#427): the burst deals 2 poison damage.
    const ally = mkCreature(53, "ally", { x: 7, y: 1 }, { movementLeft: 3, baseMovement: 3, hasAttacked: false, currentLife: 5, baseLife: 5, currentAttack: 1 });
    let s = scenario([ally], 1439, 427);
    s = { ...s, prisms: [] };
    s = playCard(s, card(1439), { x: 7, y: 1 });
    s = playCard(s, card(427), { x: 7, y: 1 });
    expect(byId(s, 53)!.position.x).toBe(5); // charged 2
    expect(byId(s, 53)!.currentLife).toBe(3); // 5 − 2×1
  });

  it("stacks additively across two casts", () => {
    let s = scenario([mkCreature(54, "ally", { x: 6, y: 1 }, { movementPoison: 0 })], 1439, 1439);
    s = playCard(s, card(1439), { x: 6, y: 1 });
    s = playCard(s, card(1439), { x: 6, y: 1 });
    expect(byId(s, 54)!.movementPoison).toBe(2);
  });
});

describe("Déplacement forcé (poussée/glissement), interactions par case", () => {
  // A forced slide (push/attract/retreat) crosses the cells exactly like a walk: gangrène per cell +
  // token walk-over + prism pickup, one creature at a time. (Before: the slide was a plain relocation
  // with no interaction.)
  it("une créature gangrenée POUSSÉE subit la gangrène sur chaque case traversée", () => {
    // Esquive #239 (pure PushData 4, ally) on an ally with gangrène: it slides toward the allied wall
    // (Dofus x=9) 6→7→8 and takes 1 damage per cell = 2.
    const ally = mkCreature(900, "ally", { x: 6, y: 1 }, { currentLife: 5, baseLife: 5, movementPoison: 1, movementLeft: 0, hasAttacked: true });
    let s = scenario([ally], 239);
    s = { ...s, prisms: [], seeds: [], butins: [] };
    s = playCard(s, card(239), { x: 6, y: 1 });
    expect(byId(s, 900)!.position.x).toBe(8); // 6→7→8, bloqué par le Dofus en x=9
    expect(byId(s, 900)!.currentLife).toBe(3); // 5 − 2×1 gangrène
  });

  it("une créature POUSSÉE sur une graine ennemie la déclenche (1 dégât) et la consomme", () => {
    const ally = mkCreature(901, "ally", { x: 6, y: 1 }, { currentLife: 5, baseLife: 5, movementLeft: 0, hasAttacked: true });
    let s = scenario([ally], 239);
    s = { ...s, prisms: [], butins: [], seeds: [{ position: { x: 7, y: 1 }, owner: "enemy" }] };
    s = playCard(s, card(239), { x: 6, y: 1 });
    expect(byId(s, 901)!.currentLife).toBe(4); // graine ENNEMIE = 1 dégât en passant
    expect(s.seeds ?? []).toHaveLength(0);     // graine consommée par le passage
  });

  it("une créature POUSSÉE sur un prisme le ramasse pour SON camp (comme en marche)", () => {
    const ally = mkCreature(902, "ally", { x: 6, y: 1 }, { currentLife: 5, baseLife: 5, movementLeft: 0, hasAttacked: true });
    let s = scenario([ally], 239);
    s = { ...s, seeds: [], butins: [], prisms: [{ position: { x: 7, y: 1 }, owner: "ally", kind: "ap" }] };
    const before = s.players.ally.apReserve;
    s = playCard(s, card(239), { x: 6, y: 1 });
    expect(s.players.ally.apReserve).toBe(before + 1); // AP prism picked up by the sliding creature
    expect(s.prisms.some((p) => p.position.x === 7 && p.position.y === 1)).toBe(false); // consommé
  });

  it("un token (graine) déclenché par l'avance résout SON effet AVANT le combat, et peut l'annuler", () => {
    // Rule: "les tokens qui ne sont pas des invocations (glyphes, graines…) déclenchent leur effet AVANT
    // le début d'un potentiel combat avec l'invocation qui les a déclenchés". Shown by cancellation: an
    // attacker with 1 HP walks on an enemy seed (1 damage) placed right in front of an enemy. The seed
    // kills it on the way (token before combat), so the end-of-move engage does not happen and the enemy
    // is untouched. If combat came first, the enemy would take 5.
    const me = mkCreature(950, "ally", { x: 8, y: 1 }, {
      currentLife: 1, baseLife: 1, currentAttack: 5, baseAttack: 5,
      movementLeft: 2, baseMovement: 2, hasAttacked: false,
    });
    const foe = mkCreature(951, "enemy", { x: 6, y: 1 }, { currentLife: 10, baseLife: 10, movementLeft: 0, hasAttacked: true });
    let s = scenario([me, foe]);
    s = { ...s, prisms: [], butins: [], seeds: [{ position: { x: 7, y: 1 }, owner: "enemy" }] };
    s = endTurn(withDecks(s));
    expect(byId(s, 950)).toBeUndefined();        // tué par la graine en marchant dessus
    expect(byId(s, 951)!.currentLife).toBe(10);  // l'ennemi n'a JAMAIS été frappé (combat annulé)
    expect(s.seeds ?? []).toHaveLength(0);        // graine consommée par le passage
  });

  it("poussée de zone : glissement un à un, la plus proche du mur d'abord (jamais d'auto-blocage)", () => {
    // Peur #396 (AoePush enemies, distance 4) pushes 2 stacked enemies toward the enemy wall (x=0). Wall
    // first order: the front one (x=3) slides first → x=1 (Dofus at x=0 blocks), then the back one (x=4)
    // → x=2 (freed behind the front one). A wrong order would leave the back one stuck at x=3 behind the
    // front one that has not moved.
    const front = mkCreature(903, "enemy", { x: 3, y: 2 }, { currentLife: 5, baseLife: 5 });
    const back = mkCreature(904, "enemy", { x: 4, y: 2 }, { currentLife: 5, baseLife: 5 });
    let s = scenario([front, back], 396);
    s = { ...s, prisms: [], seeds: [], butins: [] };
    s = playCard(s, card(396), { x: 0, y: 0 }); // AlliedGod : la case de cast est ignorée
    expect(byId(s, 903)!.position.x).toBe(1); // l'avant atteint le mur
    expect(byId(s, 904)!.position.x).toBe(2); // the back one follows it into the freed cell
  });
});

describe("PM verrouillés pendant l'avance de fin de tour", () => {
  // The PM budget is frozen at the start of the advance: any PM change during the move (a kill that
  // removes an aura, a condition that flips, +PM when wounded / contre-coup) only takes effect next
  // turn; the current advance keeps its budget. Guaranteed by the design: `processCombatPhase` never
  // computes auras again in its loop, and post-combat triggers (CONTRE_COUP…) find movementLeft=0, so
  // movement.write does not raise the budget again (guard `movementLeft > 0`), it only stores it in
  // baseMovement.
  it("#366 Tristecoeur : le +1 PM de son CONTRE COUP ne rallonge pas l'avance (banké au tour suivant)", () => {
    // Tristecoeur (2 PM) kills an adjacent enemy in melee and takes damage → CONTRE COUP (+2 AT, +1 PM),
    // resolved after the advance. It moves exactly 2 cells this turn (6→5 kill →4), not 3; the +1 PM goes
    // into baseMovement for the next turn.
    const tris = mkCreature(1, "ally", { x: 6, y: 0 }, {
      cardId: 366, triggers: card(366).triggers ?? [],
      currentAttack: 5, baseAttack: 5, currentLife: 5, baseLife: 5,
      baseMovement: 2, movementLeft: 2, hasAttacked: false,
    });
    const foe = mkCreature(2, "enemy", { x: 5, y: 0 }, { currentAttack: 2, baseAttack: 2, currentLife: 1, baseLife: 1 });
    let s = scenario([tris, foe]);
    s = { ...s, prisms: [], seeds: [], butins: [] };
    s = endTurn(s);
    const t = byId(s, 1)!;
    expect(t.position.x).toBe(4);    // 6→5 (kill) →4 : ses 2 PM verrouillés, PAS 3
    expect(t.movementLeft).toBe(0);  // budget used up, not raised again by the CONTRE COUP
    expect(t.baseMovement).toBe(3);  // the +1 PM is stored for the next turn
    expect(t.currentAttack).toBe(7); // +2 AT du CONTRE COUP bien appliqué
  });
});

describe("Effets de FIN DE TOUR simultanés, pas d'interaction entre eux", () => {
  // Each FIN DE TOUR checks the board as it was when the turn was ended: an end-of-turn effect does not
  // see the changes caused by the other end-of-turn effects.
  it("#1432 Laghertha ne proc PAS si la seule blessure vient d'un Disciple de l'Agonie #1163 la même phase", () => {
    // Disciple (placed first, so it fires before Laghertha) deals 1 to itself at FIN DE TOUR. Without the
    // lock, Laghertha would see the wound and gain +1/+1; with the pre-phase snapshot, it does not.
    const disciple = mkCreature(1, "ally", { x: 6, y: 0 }, {
      cardId: 1163, triggers: card(1163).triggers ?? [],
      currentLife: 5, baseLife: 5, movementLeft: 0, hasAttacked: true,
    });
    const lag = mkCreature(2, "ally", { x: 6, y: 1 }, {
      cardId: 1432, triggers: card(1432).triggers ?? [],
      currentAttack: 3, baseAttack: 3, armor: 0, currentLife: 5, baseLife: 5, movementLeft: 0, hasAttacked: true,
    });
    let s = scenario([disciple, lag]); // ordre du tableau = ordre de fire FIN DE TOUR
    s = { ...s, prisms: [] };
    s = endTurn(s);
    expect(byId(s, 1)!.currentLife).toBe(4); // the Disciple did wound itself this turn
    expect(byId(s, 2)!.currentAttack).toBe(3); // Laghertha n'a PAS proc (aucun blessé pré-phase)
    expect(byId(s, 2)!.armor).toBe(0);
  });

  it("#1432 Laghertha proc bien si une invocation alliée était DÉJÀ blessée avant de finir le tour", () => {
    const wounded = mkCreature(1, "ally", { x: 6, y: 0 }, { currentLife: 2, baseLife: 5, movementLeft: 0, hasAttacked: true });
    const lag = mkCreature(2, "ally", { x: 6, y: 1 }, {
      cardId: 1432, triggers: card(1432).triggers ?? [],
      currentAttack: 3, baseAttack: 3, armor: 0, currentLife: 5, baseLife: 5, movementLeft: 0, hasAttacked: true,
    });
    let s = scenario([wounded, lag]);
    s = { ...s, prisms: [] };
    s = endTurn(s);
    expect(byId(s, 2)!.currentAttack).toBe(4); // blessé pré-phase → +1 AT
    expect(byId(s, 2)!.armor).toBe(1);          // +1 AR
  });

  it("deux Lomega #1512 + réserve à 0 → +2 PA", () => {
    card(1512);
    const mkLomega = (id: number, y: number) => mkCreature(id, "ally", { x: 6, y }, {
      cardId: 1512, triggers: card(1512).triggers ?? [], currentLife: 4, baseLife: 4, movementLeft: 0, hasAttacked: true,
    });
    const base = (reserve: number, ...lomegas: ReturnType<typeof mkLomega>[]) => {
      let s = withDecks(scenario(lomegas));
      s = { ...s, prisms: [], seeds: [], butins: [], players: { ...s.players, ally: { ...s.players.ally, apReserve: reserve } } };
      return endTurn(s);
    };
    // Two Lomega, empty reserve: the condition "si elle est vide" is read on the pre-phase snapshot
    // (reserve 0) for both → +1 each → +2. A naive sequential chain would only give +1.
    expect(base(0, mkLomega(1, 0), mkLomega(2, 1)).players.ally.apReserve).toBe(2);
    // Une seule Lomega, réserve vide → +1.
    expect(base(0, mkLomega(1, 0)).players.ally.apReserve).toBe(1);
    // Reserve already not empty when the turn ends → condition not met → +0 (stays at 1).
    expect(base(1, mkLomega(1, 0), mkLomega(2, 1)).players.ally.apReserve).toBe(1);
  });
});

describe("Ordre de pose = priorité aux effets simultanés", () => {
  // Simultaneous effects resolved in placement order: the oldest invocation (smallest instanceId) acts
  // first. Held by the `state.creatures` invariant (appended at summon, filtered at death, never
  // reordered), so iterating in array order = age order. Every reaction loop (FIN_DE_TOUR,
  // MORT/MORT_ADVERSE, prisme/Maluss #292, butin, ON_DAMAGE…) iterates in array order. Examples: triple
  // Maluss reveal = placement order; Coppa against Quartz.
  it("le plus ANCIEN exécute son FIN DE TOUR en premier (ordre d'âge, pas de position)", () => {
    // The old one (#1, smallest instanceId) is placed on a lower row (y=2) than the young one (#2, y=0): if
    // the engine ordered by position it would act second; it acts first because it is older.
    const older = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 1163, triggers: card(1163).triggers ?? [], currentLife: 5, baseLife: 5, movementLeft: 0, hasAttacked: true });
    const younger = mkCreature(2, "ally", { x: 6, y: 0 }, { cardId: 1163, triggers: card(1163).triggers ?? [], currentLife: 5, baseLife: 5, movementLeft: 0, hasAttacked: true });
    let s = scenario([older, younger]); // ordre tableau = ordre de pose = ordre d'âge
    s = { ...s, prisms: [] };
    s = endTurn(s);
    // Each Disciple deals 1 to itself at FIN DE TOUR (DAMAGE source==target==its id). The order of the two
    // events in the log shows the order of resolution.
    const selfDmgIdx = (id: number) => s.log.findIndex((e) => e.type === "DAMAGE" && (e as { sourceInstanceId?: number }).sourceInstanceId === id && (e as { targetInstanceId?: number }).targetInstanceId === id);
    const iOld = selfDmgIdx(1), iYoung = selfDmgIdx(2);
    expect(iOld).toBeGreaterThanOrEqual(0);
    expect(iYoung).toBeGreaterThanOrEqual(0);
    expect(iOld).toBeLessThan(iYoung); // le plus ancien (#1) résout en premier
  });
});

describe("MORT ADVERSE posthume, 4 cartes Cochon/Salamurai", () => {
  // Chuck Lapalette #1541, Guerrier Boudeur #1108, Perigourdin #884, Empereur Gemene #1271: their MORT
  // ADVERSE fires even if the reactor dies in the same wave (both die, area effect…), like a posthumous
  // contre-coup. The other Cochon MORT ADVERSE need the reactor to survive.
  it("#1271 Empereur Gemene : +1 PA en réserve même en MOURANT (kill mutuel) ce tour", () => {
    const gemene = mkCreature(1, "ally", { x: 2, y: 0 }, { cardId: 1271, triggers: card(1271).triggers ?? [], currentAttack: 5, baseAttack: 5, currentLife: 1, baseLife: 1, movementLeft: 1, baseMovement: 1, hasAttacked: false });
    const foe = mkCreature(2, "enemy", { x: 1, y: 0 }, { currentAttack: 5, baseAttack: 5, currentLife: 1, baseLife: 1 });
    let s = scenario([gemene, foe]);
    s = { ...s, prisms: [] };
    s = endTurn(s);
    expect(byId(s, 1)).toBeUndefined();       // Gemene mort dans l'échange
    expect(byId(s, 2)).toBeUndefined();       // l'ennemi aussi
    expect(s.players.ally.apReserve).toBe(1); // MORT ADVERSE posthume → +1 PA réserve
  });

  it("#1108 Guerrier Boudeur : inflige 2 à l'ennemi suivant même en MOURANT (kill mutuel)", () => {
    const boudeur = mkCreature(1, "ally", { x: 3, y: 0 }, { cardId: 1108, triggers: card(1108).triggers ?? [], currentAttack: 5, baseAttack: 5, currentLife: 1, baseLife: 1, movementLeft: 1, baseMovement: 1, hasAttacked: false });
    const foeA = mkCreature(2, "enemy", { x: 2, y: 0 }, { currentAttack: 5, baseAttack: 5, currentLife: 1, baseLife: 1 }); // tué en mêlée (mutuel)
    const foeB = mkCreature(3, "enemy", { x: 1, y: 0 }, { currentAttack: 0, baseAttack: 0, currentLife: 5, baseLife: 5 }); // reçoit les 2 posthumes
    let s = scenario([boudeur, foeA, foeB]);
    s = { ...s, prisms: [] };
    s = endTurn(s);
    expect(byId(s, 1)).toBeUndefined();      // Boudeur mort
    expect(byId(s, 2)).toBeUndefined();      // foe A mort
    expect(byId(s, 3)!.currentLife).toBe(3); // foe B : 5 − 2 (DamageInFront posthume depuis la case de Boudeur)
  });
});

describe("Tireurs (portée), déplacement & charge", () => {
  it("un tireur qui TUE au corps à corps (d=1) avance d'1 PM FORCÉ, même si une autre cible était à portée", () => {
    // Shooter with range 2. Foe A adjacent (d=1) killed; foe B already in range (d=2). It must move 1 cell
    // (into the freed cell) before shooting again; it does not stay in place shooting at B.
    const shooter = mkCreature(1, "ally", { x: 5, y: 0 }, { range: 2, currentAttack: 3, baseAttack: 3, currentLife: 5, baseLife: 5, movementLeft: 2, baseMovement: 2, hasAttacked: false });
    const foeA = mkCreature(2, "enemy", { x: 4, y: 0 }, { currentAttack: 0, baseAttack: 0, currentLife: 1, baseLife: 1 });
    const foeB = mkCreature(3, "enemy", { x: 3, y: 0 }, { currentAttack: 0, baseAttack: 0, currentLife: 10, baseLife: 10 });
    let s = scenario([shooter, foeA, foeB]);
    s = { ...s, prisms: [] };
    s = endTurn(s);
    expect(byId(s, 2)).toBeUndefined();      // foe A tué au corps à corps
    expect(byId(s, 1)!.position.x).toBe(4);  // moved 1 cell, forced, toward the freed cell
    expect(byId(s, 3)!.currentLife).toBe(7); // ré-engage foe B (désormais adjacent) en mêlée (10 − 3)
  });

  it("un tireur au CORPS À CORPS (d=1) qui INITIE prend le contre-coup", () => {
    // Range 2, enemy adjacent (d=1): this is not a shot (which would take no counter) but a melee, a
    // mutual exchange, so the shooter takes the hit back.
    const shooter = mkCreature(1, "ally", { x: 5, y: 0 }, { range: 2, currentAttack: 3, baseAttack: 3, currentLife: 5, baseLife: 5, movementLeft: 2, baseMovement: 2, hasAttacked: false });
    const foe = mkCreature(2, "enemy", { x: 4, y: 0 }, { currentAttack: 2, baseAttack: 2, currentLife: 10, baseLife: 10 });
    let s = scenario([shooter, foe]);
    s = { ...s, prisms: [] };
    s = endTurn(s);
    expect(byId(s, 2)!.currentLife).toBe(7); // ennemi frappé (10 − 3)
    expect(byId(s, 1)!.currentLife).toBe(3); // the shooter took the hit back (5 − 2), so this was not a shot
    expect(byId(s, 1)!.position.x).toBe(5);  // stayed in place (melee against a survivor)
  });

  it("un tireur qui TUE au corps à corps (d=1) subit quand même la riposte simultanée (pas d'initiative gratuite)", () => {
    // The killer and the target die together: killing at d=1 does not remove the hit back (that would be
    // Initiative, a separate power the shooter does not have).
    const shooter = mkCreature(1, "ally", { x: 5, y: 0 }, { range: 2, currentAttack: 5, baseAttack: 5, currentLife: 3, baseLife: 3, movementLeft: 2, baseMovement: 2, hasAttacked: false });
    const foe = mkCreature(2, "enemy", { x: 4, y: 0 }, { currentAttack: 3, baseAttack: 3, currentLife: 5, baseLife: 5 });
    let s = scenario([shooter, foe]);
    s = { ...s, prisms: [] };
    s = endTurn(s);
    expect(byId(s, 2)).toBeUndefined(); // ennemi tué (5 − 5)
    expect(byId(s, 1)).toBeUndefined(); // shooter killed by the simultaneous hit back (3 − 3)
  });

  it("un tireur à DISTANCE (d≥2) tire toujours sans riposte (inchangé)", () => {
    // At a distance, the shot stays one-way: no hit back, even against a big attacker.
    const shooter = mkCreature(1, "ally", { x: 6, y: 0 }, { range: 2, currentAttack: 3, baseAttack: 3, currentLife: 5, baseLife: 5, movementLeft: 2, baseMovement: 2, hasAttacked: false });
    const foe = mkCreature(2, "enemy", { x: 4, y: 0 }, { currentAttack: 9, baseAttack: 9, currentLife: 10, baseLife: 10 });
    let s = scenario([shooter, foe]);
    s = { ...s, prisms: [] };
    s = endTurn(s);
    expect(byId(s, 2)!.currentLife).toBe(7); // touché à d=2 (10 − 3)
    expect(byId(s, 1)!.currentLife).toBe(5); // AUCUNE riposte : c'est un tir
    expect(byId(s, 1)!.position.x).toBe(6);  // n'a pas bougé (a tiré depuis sa case)
  });

  it("un tireur qui CHARGE n'attaque qu'au CORPS À CORPS (mêlée + contre-coup), pas à distance", () => {
    // Shooter with range 3, enemy at d=2 (so in range if it fired). With a Charge, it advances and
    // engages in melee instead of shooting from its cell; the proof is that it moves and takes the
    // counter.
    const shooter = mkCreature(1, "ally", { x: 6, y: 0 }, { range: 3, currentAttack: 3, baseAttack: 3, currentLife: 5, baseLife: 5, movementLeft: 2, baseMovement: 2, hasAttacked: false });
    const foe = mkCreature(2, "enemy", { x: 4, y: 0 }, { currentAttack: 2, baseAttack: 2, currentLife: 5, baseLife: 5 });
    let s = scenario([shooter, foe], 427); // Charge 2 cases
    s = { ...s, prisms: [] };
    s = playCard(s, card(427), { x: 6, y: 0 });
    expect(byId(s, 1)!.position.x).toBe(5);  // a AVANCÉ (mêlée), pas tiré depuis x=6
    expect(byId(s, 1)!.currentLife).toBe(3); // took the melee counter (a shot takes none)
    expect(byId(s, 2)!.currentLife).toBe(2); // ennemi frappé en mêlée (5 − 3)
  });

  it("un tireur INVOQUÉ CE TOUR (mal d'invocation) chargé par Jice #283 avance MAIS ne tire pas", () => {
    // Evangelyne #498 (range 5) just summoned → summoning sickness (hasAttacked, 0 PM). Jice Aouaire
    // #283 (APPARITION: vos autres invocations chargent de 1 case) pushes it 1 cell (the forced charge
    // works despite summoning sickness), but the shooter stays "spent": it does not shoot at the end of
    // the turn. Before the fix, the charge reset hasAttacked=false and the shooter fired.
    card(283); card(498);
    const eva = mkCreature(50, "ally", { x: 8, y: 2 }, { cardId: 498, triggers: card(498).triggers ?? [], range: 5, currentAttack: 3, baseAttack: 3, currentLife: 3, baseLife: 3, baseMovement: 3, movementLeft: 0, hasAttacked: true });
    const foe = mkCreature(60, "enemy", { x: 3, y: 2 }, { currentLife: 10, baseLife: 10 });
    const base = scenario([eva, foe], 283);
    const s0 = { ...base, prisms: [], players: { ...base.players, ally: { ...base.players.ally, hand: [283], handCostMods: [0], ap: 10, maxAp: 10 } } };
    const afterCharge = playCard(s0, card(283), { x: 8, y: 4 }); // Jice invoquée → APPARITION charge Eva d'1 case
    expect(byId(afterCharge, 50)!.position.x).toBe(7);           // la charge imposée l'a bien avancée (8 → 7)
    const s = endTurn(withDecks(afterCharge));                   // avance de fin de tour (côté allié)
    expect(byId(s, 60)!.currentLife).toBe(10);                   // the shooter, which still had summoning sickness, did not shoot
  });
});

describe("Transformation, pas d'APPARITION + arrêt du déplacement", () => {
  it("partie A : une invocation transformée en Alibert #96 ne déclenche PAS son APPARITION (pas de Poêle #308)", () => {
    card(96); // ensure the pool is registered so transformCreature can resolve token #96
    let s = scenario([mkCreature(1, "ally", { x: 6, y: 0 }, { cardId: 9999, currentAttack: 5, baseAttack: 5, currentLife: 5, baseLife: 5 })]);
    const handBefore = [...s.players.ally.hand];
    const creatures = s.creatures.map((c) => ({ ...c, position: { ...c.position }, properties: new Set(c.properties) }));
    transformCreature(creatures[0], 96, "ally", []); // → Alibert #96 (« APPARITION : Ajoute une Poêle #308 »)
    s = { ...s, creatures };
    expect(byId(s, 1)!.cardId).toBe(96);             // transformée en Alibert
    expect(byId(s, 1)!.currentAttack).toBe(2);       // stats de base du token (AT 2), pas de buff d'APPARITION
    expect(s.players.ally.hand).toEqual(handBefore); // no Poêle added: the APPARITION did not fire
    expect(s.players.ally.hand).not.toContain(308);
  });

  it("partie B : Mulou #42 qui tue en mêlée RESTE sur place et ne se transforme qu'une fois (pas de kill-and-continue)", () => {
    const mulou = mkCreature(1, "ally", { x: 5, y: 0 }, { cardId: 42, triggers: card(42).triggers ?? [], currentAttack: 5, baseAttack: 5, currentLife: 5, baseLife: 5, movementLeft: 3, baseMovement: 3, hasAttacked: false });
    const foeA = mkCreature(2, "enemy", { x: 4, y: 0 }, { currentAttack: 0, baseAttack: 0, currentLife: 1, baseLife: 1 });
    const foeB = mkCreature(3, "enemy", { x: 3, y: 0 }, { currentAttack: 0, baseAttack: 0, currentLife: 1, baseLife: 1 });
    let s = scenario([mulou, foeA, foeB]);
    s = { ...s, prisms: [] };
    s = endTurn(s);
    expect(byId(s, 2)).toBeUndefined();      // foe A tué au corps à corps
    expect(byId(s, 3)!.currentLife).toBe(1); // foe B intact, pas de kill-and-continue
    expect(byId(s, 1)!.position.x).toBe(5);  // stayed in place (no break-through into the freed cell)
    expect(byId(s, 1)!.cardId).toBe(193);    // transformé UNE seule fois : #42 → #193 Milimulou Garou
  });
});

describe("Fatigue (deck-out)", () => {
  // Drawing from an empty deck: each of the player's Dofus takes 1 damage per missed card and is
  // revealed, in sweep order (ally = top to bottom, y going up). (scenario() = empty decks.)
  it("piocher sur une pioche vide inflige 1 à TOUS vos Dofus et les révèle, sans toucher l'adversaire", () => {
    let s = scenario([]);
    s = drawCard(s, "ally");
    const ally = s.dofuses.filter((d) => d.owner === "ally");
    expect(ally.every((d) => d.currentLife === 4)).toBe(true);  // tous −1 (5 → 4)
    expect(ally.every((d) => d.revealed === true)).toBe(true);  // tous révélés
    expect(s.dofuses.filter((d) => d.owner === "enemy").every((d) => d.currentLife === 5 && !d.revealed)).toBe(true);
  });

  it("piocher 3 fois sur une pioche vide = 3 dégâts à chaque Dofus (1 par carte manquée)", () => {
    let s = scenario([]);
    for (let i = 0; i < 3; i++) s = drawCard(s, "ally");
    expect(s.dofuses.filter((d) => d.owner === "ally").every((d) => d.currentLife === 2)).toBe(true); // 5 − 3
  });

  it("révélation dans l'ordre du balayage (allié : y 0→4)", () => {
    let s = scenario([]);
    s = drawCard(s, "ally");
    const order = s.log.filter((e) => e.type === "DOFUS_REVEALED").map((e) => (e as { at: { y: number } }).at.y);
    expect(order).toEqual([0, 1, 2, 3, 4]);
  });
});

describe("Règle 4, résolution RÉCURSIVE des réactions (LIFO)", () => {
  // A reaction that deals new damage in turn fires the CONTRE COUPs of the new victims (cascade).
  // Before: fireContreCoup scanned once (no cascade).
  const blast = (s: ReturnType<typeof scenario>, targetId: number): ReturnType<typeof scenario> => {
    const before = s.log.length;
    const s2 = {
      ...s,
      creatures: s.creatures.map((c) => (c.instanceId === targetId ? { ...c, currentLife: c.currentLife - 1 } : c)),
      log: [...s.log, { type: "DAMAGE" as const, targetInstanceId: targetId, damage: 1 }],
    };
    return fireContreCoup(s2, before);
  };

  it("cascade : L'Enklarveur #534 ↔ Prespic #478 font un ping-pong de CONTRE COUP jusqu'à la mort", () => {
    const enk = mkCreature(1, "ally", { x: 6, y: 3 }, { cardId: 534, triggers: card(534).triggers ?? [], currentAttack: 3, currentLife: 6, baseLife: 6 });
    const prespic = mkCreature(2, "ally", { x: 6, y: 4 }, { cardId: 478, triggers: card(478).triggers ?? [], currentAttack: 1, currentLife: 4, baseLife: 4 });
    let s = scenario([enk, prespic]);
    s = { ...s, prisms: [] };
    s = blast(s, 1); // blast on L'Enklarveur → recursive cascade
    // Without recursion: Prespic would take 1 (→3), L'Enklarveur untouched. With it: ping-pong until
    // Prespic dies (4 HP → 0), and the hit that kills it still fires its contre-coup ("qu'elle survive
    // ou non") → 4 hits back in all (6 − 1 blast − 4 = 1).
    expect(byId(s, 2)).toBeUndefined();        // Prespic mort par le ping-pong
    expect(byId(s, 1)!.currentLife).toBe(1);   // L'Enklarveur survit, mais a pris 4 ripostes (la 4e posthume)
  });

  it("combo INFINI (Kralamor soigne) : la boucle tourne et S'ARRÊTE via le garde-fou (cap), sans planter", () => {
    const pissenlit = mkCreature(1, "ally", { x: 7, y: 0 }, { cardId: 1595, triggers: card(1595).triggers ?? [], currentAttack: 2, currentLife: 4, baseLife: 4 });
    const kralamor = mkCreature(2, "ally", { x: 6, y: 1 }, { cardId: 228, triggers: card(228).triggers ?? [], currentAttack: 1, currentLife: 4, baseLife: 4, protectedByGuard: 3 });
    const bould = mkCreature(3, "ally", { x: 6, y: 2 }, { cardId: 300, triggers: card(300).triggers ?? [], currentAttack: 2, currentLife: 7, baseLife: 7 });
    const enk = mkCreature(4, "ally", { x: 6, y: 3 }, { cardId: 534, triggers: card(534).triggers ?? [], currentAttack: 3, currentLife: 6, baseLife: 6 });
    const prespic = mkCreature(5, "ally", { x: 6, y: 4 }, { cardId: 478, triggers: card(478).triggers ?? [], currentAttack: 1, currentLife: 4, baseLife: 4 });
    const eliacube = mkCreature(6, "ally", { x: 8, y: 2 }, { cardId: 250, triggers: card(250).triggers ?? [], currentAttack: 0, currentLife: 7, baseLife: 7, properties: new Set(["Statue"]) });
    let s = scenario([pissenlit, kralamor, bould, enk, prespic, eliacube]);
    s = { ...s, prisms: [] };
    s = blast(s, 4); // blast on L'Enklarveur
    // The infinite loop comes up naturally: Kralamor, protected by Bould (the GARDE DU CORPS even takes
    // area damage for it), stays alive and keeps healing the core, so nobody dies for good, and the
    // recursive CONTRE COUP cascade runs forever, stopped by the safety cap (wave cap). We check that
    // the whole core survives (support) and that the cascade ran up to the cap, with no timeout/crash.
    const cascadeHits = s.log.filter((e) => e.type === "DAMAGE").length;
    expect(byId(s, 2)).toBeDefined();          // Kralamor survit (AoE redirigée sur Bould) → soutien
    expect(byId(s, 1)).toBeDefined();          // Pissenlit survit (soigné)
    expect(byId(s, 4)).toBeDefined();          // L'Enklarveur survit
    expect(byId(s, 5)).toBeDefined();          // Prespic survit
    expect(cascadeHits).toBeGreaterThan(300);  // la boucle a tourné jusqu'au cap (garde-fou)
    expect(cascadeHits).toBeLessThan(5000);    // bornée, pas d'emballement non maîtrisé
    expect(s.players.ally.apReserve).toBeGreaterThan(20); // Eliacube a compté les itérations (1 PA / mort en cascade)
  });

});

describe("Eliacube #250, +1 PA réserve par mort", () => {
  it("ajoute 1 PA à la réserve de son propriétaire pour CHAQUE invocation qui meurt (n'importe quel camp)", () => {
    card(250);
    const eliacube = mkCreature(1, "ally", { x: 8, y: 2 }, { cardId: 250, currentAttack: 0, currentLife: 7, baseLife: 7, properties: new Set(["Statue"]) });
    const allyVictim = mkCreature(2, "ally", { x: 6, y: 2 }, { currentLife: 1, baseLife: 1 });
    const enemyVictim = mkCreature(3, "enemy", { x: 4, y: 2 }, { currentLife: 1, baseLife: 1 });
    let s = scenario([eliacube, allyVictim, enemyVictim]);
    s = { ...s, prisms: [] };
    const before = s.players.ally.apReserve;
    const creatures = s.creatures.map((c) => ({ ...c, position: { ...c.position }, properties: new Set(c.properties) }));
    creatures.find((c) => c.instanceId === 2)!.currentLife = 0;
    creatures.find((c) => c.instanceId === 3)!.currentLife = 0;
    s = resolveDeathsAndWin(s, creatures, s.dofuses.map((d) => ({ ...d, position: { ...d.position } })), [...s.log], new Set());
    expect(s.players.ally.apReserve).toBe(before + 2); // +1 par mort : allié + ennemi (n'importe quel camp)
  });
});

describe("GARDE DU CORPS vs INITIATIVE : le garde est une éponge passive, la protégée riposte EN LIGNE", () => {
  it("B (initiative) frappe A gardé par C ; le garde C absorbe passivement et A (la protégée = combattante) riposte EN LIGNE", () => {
    // A (ally) advances into B (enemy, initiative). C guards A: C absorbs the initiative strike like a
    // plain sponge (spell-type damage), without engaging. The fighter is A (the protected one), so its
    // hit back resolves inline in the exchange (A→B, 2), before C's CONTRE COUP (3 to the attacker) lands.
    // B (3 HP) takes 2 (A) then 3 (C's contre-coup) → dies; A did hit B.
    const A = mkCreature(1, "ally", { x: 5, y: 2 }, { currentAttack: 2, currentLife: 5, baseLife: 5, baseMovement: 1, movementLeft: 1, protectedByGuard: 3 });
    const B = mkCreature(2, "enemy", { x: 4, y: 2 }, { currentAttack: 1, currentLife: 3, baseLife: 3, properties: new Set(["FirstStrike"]) });
    const C = mkCreature(3, "ally", { x: 6, y: 1 }, { currentAttack: 1, currentLife: 5, baseLife: 5, triggers: [{ trigger: "CONTRE_COUP", effects: [{ type: "DamageData", Damage: 3, targetAttacker: true }] }] });
    let s = withDecks({ ...scenario([A, B, C]), activeSide: "ally" });
    s = endTurn(s);
    expect(byId(s, 2)).toBeUndefined(); // B meurt (2 de la riposte de A + 3 du contre-coup de C)
    expect(byId(s, 1)).toBeDefined();   // A survit (C a encaissé la frappe d'initiative)
    const aHitB = s.log.some((e) => {
      const ev = e as { type: string; sourceInstanceId?: number; targetInstanceId?: number };
      return ev.type === "DAMAGE" && ev.sourceInstanceId === 1 && ev.targetInstanceId === 2;
    });
    expect(aHitB).toBe(true); // A's hit back reaches B inline (the guard does not defer anything anymore)
  });

  it("BOUCLE : Jet le Pied Volant #158 gardé par C recharge tant que C survit aux coups de B (initiative)", () => {
    // A = Jet le Pied Volant (ON_DAMAGE → charges when an ally takes damage), guarded by C. B
    // (initiative) strikes → C (passive sponge) absorbs → A's ON_DAMAGE makes it charge B again → B
    // strikes again → C absorbs → ... the loop runs as long as C survives (not infinite). A hits back
    // inline at each cycle (the guard does not defer anything anymore). When C dies (8 HP / hits of 1),
    // guardOf(A) disappears and the loop stops on its own, bounded by C's HP (not the cap of 200).
    const A = mkCreature(1, "ally", { x: 5, y: 2 }, { cardId: 158, triggers: card(158).triggers ?? [], currentAttack: 2, currentLife: 5, baseLife: 5, baseMovement: 1, movementLeft: 1, protectedByGuard: 3 });
    const B = mkCreature(2, "enemy", { x: 4, y: 2 }, { currentAttack: 1, currentLife: 99, baseLife: 99, properties: new Set(["FirstStrike"]) });
    const C = mkCreature(3, "ally", { x: 6, y: 2 }, { currentAttack: 1, currentLife: 8, baseLife: 8 });
    let s = withDecks({ ...scenario([A, B, C]), activeSide: "ally" });
    s = endTurn(s);
    const cHits = s.log.filter((e) => { const ev = e as { type: string; targetInstanceId?: number }; return ev.type === "DAMAGE" && ev.targetInstanceId === 3; }).length;
    expect(cHits).toBeGreaterThan(3);            // a loop over several cycles (the bug only made about 1)
    expect(cHits).toBeLessThanOrEqual(8);        // terminaison NATURELLE (≤ PV de C), pas le garde-fou (cap 200)
    expect(byId(s, 3)).toBeUndefined();          // C (garde) mort → fin naturelle de la boucle
    expect(byId(s, 1)).toBeDefined();            // A survit
    expect(byId(s, 2)!.currentLife).toBeLessThan(99); // A hit back inline at each cycle → B did take damage
  });
  it("le garde du corps NE bouge PAS au milieu du combat qu'il éponge, son avance vient APRÈS la riposte", () => {
    // Reproduces the report: #158 (protected by a guard far behind) charges an allied Chevalier de Parme
    // (INITIATIVE). The guard absorbs the initiative strike, the protected creature hits back inline,
    // and only then does the guard take its end-of-turn advance. Before: the hit back was deferred to the
    // end of the sweep, so the guard moved in the middle of the fight (between the strike and the hit
    // back).
    const prot = mkCreature(33, "enemy", { x: 3, y: 2 }, { cardId: 158, baseAttack: 4, currentAttack: 4, baseLife: 6, currentLife: 6, baseMovement: 3, movementLeft: 3, protectedByGuard: 34 });
    const guard = mkCreature(34, "enemy", { x: 1, y: 1 }, { cardId: 320, baseAttack: 1, currentAttack: 1, baseLife: 4, currentLife: 4, baseMovement: 3, movementLeft: 3 });
    const chevalier = mkCreature(32, "ally", { x: 5, y: 2 }, { cardId: 1969, baseAttack: 3, currentAttack: 3, baseLife: 5, currentLife: 5, movementLeft: 0, hasAttacked: true, properties: new Set(["FirstStrike"]) });
    let s = withDecks({ ...scenario([prot, guard, chevalier]), activeSide: "enemy" });
    s = endTurn(s);
    const log = s.log;
    const firstGuardMove = log.findIndex((e) => (e as { type: string; instanceId?: number }).type === "FIGHT_OBJECT_MOVED" && (e as { instanceId?: number }).instanceId === 34);
    const protRiposte = log.findIndex((e) => { const ev = e as { type: string; sourceInstanceId?: number; targetInstanceId?: number }; return ev.type === "DAMAGE" && ev.sourceInstanceId === 33 && ev.targetInstanceId === 32; });
    expect(protRiposte).toBeGreaterThanOrEqual(0);          // the protected creature did hit back at the Chevalier
    expect(firstGuardMove).toBeGreaterThan(protRiposte);    // ... and the guard only moves after the hit back
  });
});

