describe("AoE spatial (row / cross / around)", () => {
  it("#1306 Mise en Garde buffs allies in the targeted RANGÉE (vertical column, same x) only", () => {
    // "rangée" = the vertical column (same x), not the horizontal row (see inShape + Incision #1417).
    const inCol = mkCreature(150, "ally", { x: 5, y: 0 }, { currentAttack: 2, baseAttack: 2 });
    const otherCol = mkCreature(151, "ally", { x: 6, y: 2 }, { currentAttack: 2, baseAttack: 2 }); // même ligne y=2, autre colonne
    const enemyCol = mkCreature(152, "enemy", { x: 5, y: 3 }, { currentAttack: 2, baseAttack: 2 }); // même colonne mais ennemi
    let s = scenario([inCol, otherCol, enemyCol], 1306);
    s = playCard(s, card(1306), { x: 5, y: 2 }); // pick column x=5
    expect(byId(s, 150)!.currentAttack).toBe(5); // ally in column 5 → +3
    expect(byId(s, 151)!.currentAttack).toBe(2); // ally in another column → no
    expect(byId(s, 152)!.currentAttack).toBe(2); // enemy in column → no (allies scope)
  });
  it("#1756 Brisure: détruit TOUTE l'AR de la cible PUIS lui inflige 2 (aux PV, l'AR ne l'absorbe pas)", () => {
    const tgt = mkCreature(160, "enemy", { x: 3, y: 2 }, { currentLife: 3, baseLife: 3, armor: 5 });
    let s = scenario([tgt], 1756);
    s = playCard(s, card(1756), { x: 3, y: 2 });
    expect(byId(s, 160)!.armor).toBe(0);        // AR détruite (pas juste −2)
    expect(byId(s, 160)!.currentLife).toBe(1);  // 3 − 2 aux PV (l'AR détruite n'absorbe rien)
  });
  it("#869 Championne Endoctrinée: APPARITION protège le Dofus allié de SA ligne ssi en sous-nombre ; pas de self-shield", () => {
    card(869);
    // outnumbered: 1 ally (itself) against 2 enemies → shield on the allied Dofus of its row (y=2)
    const champ = mkCreature(170, "ally", { x: 8, y: 2 }, { cardId: 869, triggers: card(869).triggers ?? [] });
    let s = runTrigger(scenario([champ, mkCreature(171, "enemy", { x: 3, y: 0 }, {}), mkCreature(172, "enemy", { x: 3, y: 1 }, {})]), "APPARITION", 170);
    expect(s.dofuses.find((d) => d.owner === "ally" && d.position.y === 2)!.shielded).toBe(true);   // Dofus de sa ligne protégé
    expect(s.dofuses.find((d) => d.owner === "ally" && d.position.y === 0)!.shielded ?? false).toBe(false); // autre ligne : non
    expect(byId(s, 170)!.properties.has("Shield")).toBe(false); // no shield on itself
    // not outnumbered: 2 allies against 1 enemy → no shield
    const champ2 = mkCreature(170, "ally", { x: 8, y: 2 }, { cardId: 869, triggers: card(869).triggers ?? [] });
    let s2 = runTrigger(scenario([champ2, mkCreature(173, "ally", { x: 7, y: 2 }, {}), mkCreature(174, "enemy", { x: 3, y: 0 }, {})]), "APPARITION", 170);
    expect(s2.dofuses.find((d) => d.owner === "ally" && d.position.y === 2)!.shielded ?? false).toBe(false);
  });
  it("#660 Duc Rex: ne commence PAS bouclier (il l'obtient seulement au ralliement)", () => {
    let s = scenario([], 660);
    s = { ...s, activeSide: "ally", players: { ...s.players, ally: { ...s.players.ally, hand: [660], handCostMods: [0], ap: 20, maxAp: 20 } } };
    s = playCard(s, card(660), { x: 8, y: 2 });
    expect(s.creatures.find((c) => c.cardId === 660)!.properties.has("Shield")).toBe(false);
  });
  it("#1676 Maître Féca: bouclier à VOS invocations ET à VOS Dofus (pas l'adversaire)", () => {
    const ally = mkCreature(180, "ally", { x: 6, y: 2 }, {});
    const enemy = mkCreature(181, "enemy", { x: 3, y: 2 }, {});
    let s = scenario([ally, enemy], 1676);
    s = { ...s, activeSide: "ally", players: { ...s.players, ally: { ...s.players.ally, hand: [1676], handCostMods: [0], ap: 20, maxAp: 20 } } };
    s = playCard(s, card(1676), { x: 9, y: 2 });
    expect(byId(s, 180)!.properties.has("Shield")).toBe(true);  // invocation alliée
    expect(byId(s, 181)!.properties.has("Shield")).toBe(false); // ennemi : non
    expect(s.dofuses.filter((d) => d.owner === "ally").every((d) => d.shielded)).toBe(true);   // TOUS les Dofus alliés
    expect(s.dofuses.filter((d) => d.owner === "enemy").some((d) => d.shielded)).toBe(false);  // aucun Dofus ennemi
  });
  it("#1395 Mot Protecteur heals creatures in the 3×3 around the cell", () => {
    const center = mkCreature(153, "ally", { x: 5, y: 2 }, { currentLife: 1, baseLife: 9 });
    const adj = mkCreature(154, "ally", { x: 6, y: 3 }, { currentLife: 1, baseLife: 9 });
    const far = mkCreature(155, "ally", { x: 8, y: 0 }, { currentLife: 1, baseLife: 9 });
    let s = scenario([center, adj, far], 1395);
    s = playCard(s, card(1395), { x: 5, y: 2 });
    expect(byId(s, 153)!.currentLife).toBe(4); // center +3
    expect(byId(s, 154)!.currentLife).toBe(4); // adjacent +3
    expect(byId(s, 155)!.currentLife).toBe(1); // far → no
  });
  it("#140 Fiole de Torpeur: détruit toute l'AR de la cible ET l'assomme (sans dégât)", () => {
    const tgt = mkCreature(156, "enemy", { x: 3, y: 2 }, { currentLife: 3, baseLife: 3, armor: 4 });
    let s = scenario([tgt], 140);
    s = { ...s, players: { ...s.players, ally: { ...s.players.ally, hand: [140], handCostMods: [0], ap: 20, maxAp: 20 } } };
    s = playCard(s, card(140), { x: 3, y: 2 });
    expect(byId(s, 156)!.armor).toBe(0);                       // AR détruite
    expect(byId(s, 156)!.properties.has("Stunned")).toBe(true); // assommée
    expect(byId(s, 156)!.currentLife).toBe(3);                  // no damage to HP
  });
  it("#172 Ronces Multiples silences creatures on the targeted row or column", () => {
    const onRow = mkCreature(156, "enemy", { x: 8, y: 2 }, { properties: new Set(["Shield"]) });
    const onCol = mkCreature(157, "enemy", { x: 5, y: 4 }, { resistance: 2 });
    const off = mkCreature(158, "enemy", { x: 8, y: 0 }, { properties: new Set(["Shield"]) });
    let s = scenario([onRow, onCol, off], 172);
    s = playCard(s, card(172), { x: 5, y: 2 }); // cross at (5,2)
    expect(byId(s, 156)!.properties.has("Shield")).toBe(false); // same row → silenced
    expect(byId(s, 157)!.resistance).toBe(0);                   // same column → silenced
    expect(byId(s, 158)!.properties.has("Shield")).toBe(true);  // off-cross → untouched
  });
});

