describe("Craps #10 (coin → scatter damage on enemy Dofus)", () => {
  const enemyDofusLife = (s: ReturnType<typeof scenario>) =>
    s.dofuses.filter((d) => d.owner === "enemy").reduce((a, d) => a + d.currentLife, 0);
  const allyDofusLife = (s: ReturnType<typeof scenario>) =>
    s.dofuses.filter((d) => d.owner === "ally").reduce((a, d) => a + d.currentLife, 0);

  it("deals exactly 6 (pile) or 3 (face) total, only to enemy Dofus", () => {
    let s = { ...scenario([], 10), rng: 12345 };
    const eBefore = enemyDofusLife(s), aBefore = allyDofusLife(s);
    s = playCard(s, card(10), { x: 0, y: 0 });
    const dealt = eBefore - enemyDofusLife(s);
    expect([3, 6]).toContain(dealt);            // coin → 6 or 3
    expect(allyDofusLife(s)).toBe(aBefore);     // ally Dofus untouched
  });

  it("both coin outcomes (6 and 3) are reachable across seeds; total always matches the roll", () => {
    const totals = new Set<number>();
    for (let seed = 1; seed <= 40; seed++) {
      let s = { ...scenario([], 10), rng: seed };
      const before = enemyDofusLife(s);
      s = playCard(s, card(10), { x: 0, y: 0 });
      totals.add(before - enemyDofusLife(s));
    }
    expect(totals).toEqual(new Set([3, 6])); // exactly these two outcomes, nothing else
  });

  it("is reproducible, the same seed scatters the same way", () => {
    const run = () => {
      let s = { ...scenario([], 10), rng: 777 };
      s = playCard(s, card(10), { x: 0, y: 0 });
      return s.dofuses.filter((d) => d.owner === "enemy").map((d) => d.currentLife).join(",");
    };
    expect(run()).toBe(run());
  });
});

