    let s = { ...scenario([welsh], 641), prisms: [] };
    s = playCard(s, card(641), { x: 8, y: 1 });
    expect(s.pendingAction).not.toBeNull();       // pick de révélation ouvert
    expect(byId(s, 70)!.currentAttack).toBe(2);   // rien encore tiré
    const dofus = s.dofuses.find((d) => d.owner === "ally" && d.currentLife > 0 && !d.revealed)!;
    s = resolvePendingAction(s, dofus.position);
    expect(s.pendingAction).toBeNull();
    expect(byId(s, 70)!.currentAttack).toBe(3);   // +1, une seule fois
    expect(byId(s, 70)!.armor).toBe(1);
