    const enemyCol = mkCreature(71, "enemy", { x: 4, y: 3 }, { currentAttack: 3, baseAttack: 3 });
    const otherCol = mkCreature(72, "ally", { x: 6, y: 1 }, { currentAttack: 2, baseAttack: 2 });
    let s = scenario([allyCol, enemyCol, otherCol], 149);
    s = { ...s, prisms: [] };
