  it("#152 Yugo: capturing a Dofus recycles it to the deck bottom, its CONTRE COUP does not fire", () => {
    // Yugo (a Confrérie du Tofu member) breaks through the ally wall. A capture sets currentLife=0
    // but deals no damage to the breaker, so its CONTRE COUP ("place le dernier membre de la Confrérie
    // de votre pioche dans votre main") must not fire. It used to: Yugo recycled to the deck bottom,
    // then the posthumous tutor pulled the bottom-most Confrérie member (itself) straight back to hand.
    const yugo = mkCreature(700, "enemy", { x: 8, y: 2 }, {
      cardId: 152, currentLife: 2, baseLife: 3, baseMovement: 3, movementLeft: 1, hasAttacked: false,
      triggers: [{ trigger: "CONTRE_COUP", effects: [{ type: "TutorFromDeck", from: "bottom", amount: 1, family: "BrotherhoodOfTheTofu" }] }],
    });
    const sc = scenario([yugo]);
    const base = {
      ...sc, activeSide: "enemy" as const, prisms: [], dofuses: [],
      players: {
        ...sc.players,
        ally: { ...sc.players.ally, deck: [16, 16, 16], deckCostMods: [0, 0, 0] },
        enemy: { ...sc.players.enemy, hand: [], handCostMods: [], deck: [16, 16], deckCostMods: [0, 0] },
      },
    };
    const s = endTurn(base);
    expect(byId(s, 700)).toBeUndefined();            // broke through → off the board
    expect(s.players.enemy.deck[0]).toBe(152);       // recycled to the bottom of the deck
    expect(s.players.enemy.deck.length).toBe(3);     // 152 + the two fillers, nothing tutored out
    expect(s.players.enemy.hand).not.toContain(152); // CONTRE COUP did not fire → not back in hand
  });
