describe("Stat-capped mass destroy", () => {
  // #880 Colère de Iop: "Détruit toutes les invocations ayant 2 AT ou moins."
  // A symmetric board wipe of weak creatures (both sides).
  it("#880 Colère de Iop: destroys every invocation with ≤2 AT, both sides; spares >2 AT", () => {
    const weakAlly = mkCreature(50, "ally", { x: 6, y: 1 }, { currentAttack: 2 });
    const strongAlly = mkCreature(51, "ally", { x: 6, y: 3 }, { currentAttack: 3 });
    const weakFoe = mkCreature(52, "enemy", { x: 4, y: 1 }, { currentAttack: 1 });
    const strongFoe = mkCreature(53, "enemy", { x: 4, y: 3 }, { currentAttack: 5 });
    let s = scenario([weakAlly, strongAlly, weakFoe, strongFoe], 880);
    s = { ...s, prisms: [] };
    s = playCard(s, card(880), { x: 5, y: 2 });
    expect(byId(s, 50)).toBeUndefined(); // 2 AT ally → destroyed
    expect(byId(s, 52)).toBeUndefined(); // 1 AT enemy → destroyed
    expect(byId(s, 51)).toBeDefined();   // 3 AT → spared
    expect(byId(s, 53)).toBeDefined();   // 5 AT → spared
  });
  it("#704 Plante Kanniboul: DÉBUT DU TOUR destroys all ≤2 AT invocations; itself (3 AT) survives", () => {
    const weakAlly = mkCreature(50, "ally", { x: 6, y: 1 }, { currentAttack: 2 });
    const weakFoe = mkCreature(51, "enemy", { x: 4, y: 1 }, { currentAttack: 1 });
    const strong = mkCreature(52, "ally", { x: 6, y: 3 }, { currentAttack: 4 });
    const plante = mkCreature(53, "ally", { x: 6, y: 2 }, { cardId: 704, currentAttack: 3 });
    plante.triggers = card(704).triggers ?? [];
    let s = scenario([weakAlly, weakFoe, strong, plante]);
    s = runTrigger(s, "DEBUT_DE_TOUR", 53);
    expect(byId(s, 50)).toBeUndefined(); // 2 AT → destroyed
    expect(byId(s, 51)).toBeUndefined(); // 1 AT → destroyed
    expect(byId(s, 52)).toBeDefined();   // 4 AT → spared
    expect(byId(s, 53)).toBeDefined();   // Plante (3 AT) → survives its own effect
  });
  // #840 Duelliste Spectral: "APPARITION : Détruit les invocations ayant 2 PV ou
  // moins si vous êtes en sous-nombre." The board wipe only fires when outnumbered.
  it("#840 Duelliste Spectral: APPARITION destroys ≤2 PV invocations when outnumbered", () => {
    const e1 = mkCreature(60, "enemy", { x: 4, y: 1 }, { currentLife: 2, baseLife: 2 });
    const e2 = mkCreature(61, "enemy", { x: 4, y: 3 }, { currentLife: 5, baseLife: 5 });
    let s = scenario([e1, e2], 840);
    s = { ...s, prisms: [] };
    s = playCard(s, card(840), { x: 8, y: 2 }); // ally count 1 (Duelliste) < enemy 2 → outnumbered
    s = resolvePendingAction(s, { x: 8, y: 0 }); // Duelliste is a deferred NÉCROME → decline on board: land it + fire its held APPARITION
    expect(byId(s, 60)).toBeUndefined(); // 2 PV enemy → destroyed
    expect(byId(s, 61)).toBeDefined();   // 5 PV → spared
  });
  it("#840 Duelliste Spectral: APPARITION does nothing when not outnumbered", () => {
    const e1 = mkCreature(62, "enemy", { x: 4, y: 1 }, { currentLife: 2, baseLife: 2 });
    let s = scenario([e1], 840);
    s = { ...s, prisms: [] };
    s = playCard(s, card(840), { x: 8, y: 2 }); // ally 1 (Duelliste) vs enemy 1 → not outnumbered
    s = resolvePendingAction(s, { x: 8, y: 0 }); // decline on board → land + fire the (no-op) APPARITION
    expect(byId(s, 62)).toBeDefined();   // spared (condition false)
  });
});

describe("Targeted bounce with AT cap", () => {
  // #452 Adamaï: "APPARITION : Remontez dans la main de son propriétaire une invocation ayant 3 AT ou
  // moins." A targeted pick capped at ≤3 AT; the picked creature goes back to its own owner's hand.
  it("#452 Adamaï: APPARITION bounces a chosen ≤3 AT creature to its owner's hand", () => {
    const weakFoe = mkCreature(50, "enemy", { x: 4, y: 2 }, { currentAttack: 2, cardId: 69 });
    let s = scenario([weakFoe], 452);
    s = { ...s, prisms: [] };
    s = playCard(s, card(452), { x: 8, y: 2 }); // summon Adamaï → APPARITION pick
    expect(s.pendingAction).not.toBeNull();
    expect(s.pendingAction!.maxAttack).toBe(3);
    s = resolvePendingAction(s, { x: 4, y: 2 }); // pick the ≤3 AT enemy
    expect(byId(s, 50)).toBeUndefined();           // left the board
    expect(s.players.enemy.hand).toContain(69);    // returned to its owner (enemy) hand
  });
  it("#452 Adamaï: a >3 AT creature is not a legal target (trigger declines, nothing bounced)", () => {
    const strongFoe = mkCreature(51, "enemy", { x: 4, y: 2 }, { currentAttack: 5, cardId: 69 });
    let s = scenario([strongFoe], 452);
    s = { ...s, prisms: [] };
    s = playCard(s, card(452), { x: 8, y: 2 });
    expect(s.pendingAction).toBeNull(); // no creature ≤3 AT (source excluded) → no pick
    expect(byId(s, 51)).toBeDefined();
  });
  // #526 Zaldior: "APPARITION : Remontez dans VOTRE main une invocation ayant 3
  // AT ou moins." A steal, the picked creature's card goes to the caster's hand,
  // not its owner's.
  it("#526 Zaldior: APPARITION steals a chosen ≤3 AT enemy into the caster's hand", () => {
    const weakFoe = mkCreature(52, "enemy", { x: 4, y: 2 }, { currentAttack: 2, cardId: 69 });
    let s = scenario([weakFoe], 526);
    s = { ...s, prisms: [] };
    s = playCard(s, card(526), { x: 8, y: 2 }); // summon Zaldior (ally)
    expect(s.pendingAction!.maxAttack).toBe(3);
    s = resolvePendingAction(s, { x: 4, y: 2 }); // pick the enemy
    expect(byId(s, 52)).toBeUndefined();
    expect(s.players.ally.hand).toContain(69);     // stolen into the caster (ally) hand
    expect(s.players.enemy.hand).not.toContain(69); // Not the owner's hand
  });
});

describe("Body swap, position + side", () => {
  // #272 Marline: "APPARITION : Échangez son corps avec une invocation adverse
  // ayant 3 AT ou moins." Marline and the picked enemy trade both their cells
  // and their owners (the enemy becomes yours where Marline stood; Marline
  // becomes the foe's where the enemy stood).
  it("#272 Marline: APPARITION swaps position and side with a chosen ≤3 AT enemy", () => {
    const foe = mkCreature(50, "enemy", { x: 4, y: 2 }, { currentAttack: 2, cardId: 69 });
    let s = scenario([foe], 272);
    s = { ...s, prisms: [] };
    s = playCard(s, card(272), { x: 8, y: 2 }); // Marline held off the board until the pick
    expect(s.pendingAction!.maxAttack).toBe(3);
    expect(s.pendingAction!.filter).toBe("enemy_creature");
    const marlinePos = { x: 8, y: 2 }; // Marline's summon cell
    s = resolvePendingAction(s, { x: 4, y: 2 }); // pick the enemy → Marline lands then swaps
    const marlineId = s.creatures.find((c) => c.cardId === 272)!.instanceId;
    // The enemy is now YOURS, standing on Marline's old cell, summoning-sick.
    expect(byId(s, 50)!.owner).toBe("ally");
    expect(byId(s, 50)!.position).toEqual(marlinePos);
    expect(byId(s, 50)!.hasAttacked).toBe(true);
    expect(byId(s, 50)!.movementLeft).toBe(0);
    // Marline is now the FOE's, on the enemy's old cell.
    expect(byId(s, marlineId)!.owner).toBe("enemy");
    expect(byId(s, marlineId)!.position).toEqual({ x: 4, y: 2 });
  });
  it("#272 Marline: an enemy with >3 AT is not a legal target (no swap)", () => {
    const foe = mkCreature(51, "enemy", { x: 4, y: 2 }, { currentAttack: 5, cardId: 69 });
    let s = scenario([foe], 272);
    s = { ...s, prisms: [] };
    s = playCard(s, card(272), { x: 8, y: 2 });
    expect(s.pendingAction).toBeNull();        // 5 AT > cap → no eligible target
    expect(byId(s, 51)!.owner).toBe("enemy");  // unchanged
  });
});

describe("Destroy first creature in front", () => {
  // #314 Gloutoblop: "APPARITION : Détruit la première créature devant lui si elle possède 2 AT ou
  // moins." Faces x=0 (ally); only the nearest creature ahead in its row is checked.
  it("#314 Gloutoblop: destroys the first creature in front when it has ≤2 AT", () => {
    const weakFront = mkCreature(50, "enemy", { x: 4, y: 2 }, { currentAttack: 2 });
    let s = scenario([weakFront], 314);
    s = { ...s, prisms: [] };
    s = playCard(s, card(314), { x: 8, y: 2 });
    expect(byId(s, 50)).toBeUndefined(); // 2 AT in front → destroyed
  });
  it("#314 Gloutoblop: spares a >2 AT creature in front and does not look past it", () => {
    const strongFront = mkCreature(51, "enemy", { x: 6, y: 2 }, { currentAttack: 5 });
    const weakBehind = mkCreature(52, "enemy", { x: 3, y: 2 }, { currentAttack: 1 });
    let s = scenario([strongFront, weakBehind], 314);
    s = { ...s, prisms: [] };
    s = playCard(s, card(314), { x: 8, y: 2 });
    expect(byId(s, 51)).toBeDefined(); // nearest is 5 AT → spared
    expect(byId(s, 52)).toBeDefined(); // the ≤2 AT one behind is never reached
  });
  it("#314 Gloutoblop: ignores creatures in other rows", () => {
    const otherRow = mkCreature(53, "enemy", { x: 4, y: 0 }, { currentAttack: 1 });
    let s = scenario([otherRow], 314);
    s = { ...s, prisms: [] };
    s = playCard(s, card(314), { x: 8, y: 2 }); // row 2; target sits on row 0
    expect(byId(s, 53)).toBeDefined();
  });
  it("#905 Cogneur Nimbos: APPARITION grants Shield only when an enemy is ahead on its row", () => {
    const front = mkCreature(50, "enemy", { x: 4, y: 2 }, { currentLife: 5, baseLife: 5 }); // ahead (ally forward = -x)
    let s = scenario([front], 905);
    s = { ...s, prisms: [] };
    s = playCard(s, card(905), { x: 8, y: 2 });
    expect(s.creatures.find((c) => c.cardId === 905)!.properties.has("Shield")).toBe(true);
  });
  it("#905 Cogneur Nimbos: no Shield when no enemy is ahead on its row (other row / behind only)", () => {
    const otherRow = mkCreature(50, "enemy", { x: 4, y: 0 }, { currentLife: 5, baseLife: 5 }); // different row
    const behind = mkCreature(51, "enemy", { x: 9, y: 2 }, { currentLife: 5, baseLife: 5 });    // behind (x>8)
    let s = scenario([otherRow, behind], 905);
    s = { ...s, prisms: [] };
    s = playCard(s, card(905), { x: 8, y: 2 });
    expect(s.creatures.find((c) => c.cardId === 905)!.properties.has("Shield")).toBe(false);
  });
});

describe("Zone-filtered bounce, 'dans votre camp'", () => {
  // #241 Arakne Majeure: "APPARITION : Remontez dans la main de son propriétaire une invocation située
  // dans VOTRE camp." Only creatures in the caster's territory (columns 5–8 for the ally) can be picked.
  it("#241 Arakne Majeure: bounces a creature in your camp to its owner's hand", () => {
    const inCamp = mkCreature(50, "ally", { x: 6, y: 1 }, { cardId: 69 });
    let s = scenario([inCamp], 241);
    s = { ...s, prisms: [] };
    s = playCard(s, card(241), { x: 8, y: 2 });
    expect(s.pendingAction!.zone).toBe("ownCamp");
    s = resolvePendingAction(s, { x: 6, y: 1 });
    expect(byId(s, 50)).toBeUndefined();
    expect(s.players.ally.hand).toContain(69);
  });
  it("#241 Arakne Majeure: a creature outside your camp is not eligible (no pick)", () => {
    const outCamp = mkCreature(51, "enemy", { x: 3, y: 1 }, { cardId: 40 }); // enemy half (cols 1–4)
    let s = scenario([outCamp], 241);
    s = { ...s, prisms: [] };
    s = playCard(s, card(241), { x: 8, y: 2 });
    expect(s.pendingAction).toBeNull(); // nothing in the caster's camp → trigger skips
    expect(byId(s, 51)).toBeDefined();
  });
  // #165 Arakne Brodeuse: "Remonte dans la main adverse une invocation située
  // dans votre camp ayant 2 AT ou moins." Combines zone + AT cap + opponent hand.
  it("#165 Arakne Brodeuse: sends a ≤2 AT creature in your camp to the OPPONENT's hand", () => {
    const allyInCamp = mkCreature(52, "ally", { x: 6, y: 2 }, { currentAttack: 2, cardId: 69 });
    let s = scenario([allyInCamp], 165);
    s = { ...s, prisms: [] };
    s = playCard(s, card(165), { x: 8, y: 1 });
    expect(s.pendingAction!.zone).toBe("ownCamp");
    expect(s.pendingAction!.maxAttack).toBe(2);
    s = resolvePendingAction(s, { x: 6, y: 2 });
    expect(byId(s, 52)).toBeUndefined();
    expect(s.players.enemy.hand).toContain(69);      // opponent's hand…
    expect(s.players.ally.hand).not.toContain(69);   // …not the owner's
  });
});

describe("Camp-scoped mass effects", () => {
  // #897 Phaeris: "APPARITION : Réduit au silence les invocations présentes dans
  // le camp adverse." Mass Silence over the enemy's territory (cols 1–4).
  it("#897 Phaeris: silences creatures in the enemy camp, sparing those elsewhere", () => {
    const enemyInCamp = mkCreature(50, "enemy", { x: 3, y: 2 }, { armor: 3 });      // enemy half
    const invaderYourCamp = mkCreature(51, "enemy", { x: 6, y: 2 }, { armor: 3 });  // in your camp
    let s = scenario([enemyInCamp, invaderYourCamp], 897);
    s = { ...s, prisms: [] };
    s = playCard(s, card(897), { x: 8, y: 1 }); // summon Phaeris (ally)
    expect(byId(s, 50)!.armor).toBe(0); // in enemy camp → silenced
    expect(byId(s, 51)!.armor).toBe(3); // in your camp → untouched
  });
  // #103 Veuve Noire: "APPARITION : Remonte les autres invocations situées dans
  // votre camp dans la main de leur propriétaire." Mass bounce over your camp,
  // excluding itself.
  it("#103 Veuve Noire: bounces every other creature in your camp to its owner's hand, sparing itself & outsiders", () => {
    const allyInCamp = mkCreature(50, "ally", { x: 6, y: 1 }, { cardId: 69 });
    const invaderInCamp = mkCreature(51, "enemy", { x: 7, y: 3 }, { cardId: 40 }); // enemy in your camp
    const allyOutside = mkCreature(52, "ally", { x: 3, y: 1 }, { cardId: 437 });   // in the enemy half
    let s = scenario([allyInCamp, invaderInCamp, allyOutside], 103);
    s = { ...s, prisms: [] };
    s = playCard(s, card(103), { x: 8, y: 2 }); // summon Veuve Noire (ally) in your camp
    expect(byId(s, 50)).toBeUndefined();
    expect(s.players.ally.hand).toContain(69);   // ally in camp → back to ally hand
    expect(byId(s, 51)).toBeUndefined();
    expect(s.players.enemy.hand).toContain(40);  // enemy invader → back to its (enemy) hand
    expect(byId(s, 52)).toBeDefined();           // outside your camp → untouched
    expect(s.creatures.some((c) => c.cardId === 103)).toBe(true); // Veuve Noire itself spared ("les autres")
  });
});

describe("Buff + suicide timer", () => {
  // #195 Mort Proche: "Confère +3 AT et +2 AR à une invocation. Elle meurt à la
  // fin de son tour." The buff lands now; the creature dies at the end of its
  // owner's turn (after it had the chance to act with the buff).
  it("#195 Mort Proche: buffs +3 AT/+2 AR and the creature dies at the end of its owner's turn", () => {
    const ally = mkCreature(50, "ally", { x: 6, y: 2 }, { currentAttack: 2, baseAttack: 2, armor: 0 });
    let s = scenario([ally], 195);
    s = { ...s, prisms: [] };
    s = playCard(s, card(195), { x: 6, y: 2 }); // cast on the ally
    expect(byId(s, 50)!.currentAttack).toBe(5); // 2 + 3
    expect(byId(s, 50)!.armor).toBe(2);
    expect(byId(s, 50)!.properties.has("DiesAtEndOfTurn")).toBe(true);
    expect(byId(s, 50)).toBeDefined();          // still alive before the turn ends
    s = endTurn(s);                              // end of its owner's turn → it dies
    expect(byId(s, 50)).toBeUndefined();
  });
});

describe("Temporary stat modifier", () => {
  // #1241 Sénilité: "Réduit de 2 l'AT des invocations adverses jusqu'à votre
  // prochain tour." Applied now; reverts at the start of the CASTER's next turn.
  it("#1241 Sénilité: −2 AT to enemies now; the debuff reverts at the caster's next turn", () => {
    const foe = mkCreature(50, "enemy", { x: 4, y: 2 }, { currentAttack: 5, baseAttack: 5 });
    let s = scenario([foe], 1241); // ally's turn
    s = { ...s, prisms: [] };
    s = playCard(s, card(1241), { x: 5, y: 2 }); // mass cast (target unused)
    expect(byId(s, 50)!.currentAttack).toBe(3); // 5 − 2
    s = endTurn(s); // → enemy's turn: still debuffed (expireSide is the ally)
    expect(byId(s, 50)!.currentAttack).toBe(3);
    s = endTurn(s); // → caster's (ally) next turn: reversion fires
    expect(byId(s, 50)!.currentAttack).toBe(5);
  });
  it("#1241 Sénilité: a creature with 0 AT gains nothing from the reversion (the clamp is not paid back)", () => {
    // mutateStat clamps at 0: 0 − 2 = 0, no malus taken. The old reversion still gave back +2,
    // which turned the malus spell into a permanent buff for the opponent. A Wall with 0 AT
    // (Eliacube #250), which should never strike, started dealing 2.
    const wall = mkCreature(50, "enemy", { x: 4, y: 2 }, { currentAttack: 0, baseAttack: 0 });
    let s = scenario([wall], 1241);
    s = { ...s, prisms: [] };
    s = playCard(s, card(1241), { x: 5, y: 2 });
    expect(byId(s, 50)!.currentAttack).toBe(0);
    s = endTurn(s); s = endTurn(s); // reversion on the caster's turn
    expect(byId(s, 50)!.currentAttack).toBe(0);
    s = endTurn(s); s = endTurn(s); // and still 0 two turns later
    expect(byId(s, 50)!.currentAttack).toBe(0);
  });
  it("#1241 Sénilité: a creature with 1 AT loses 1 and gets 1 back, not 2", () => {
    const weak = mkCreature(50, "enemy", { x: 4, y: 2 }, { currentAttack: 1, baseAttack: 1 });
    let s = scenario([weak], 1241);
    s = { ...s, prisms: [] };
    s = playCard(s, card(1241), { x: 5, y: 2 });
    expect(byId(s, 50)!.currentAttack).toBe(0); // 1 − 2 clamped at 0, it only lost 1
    s = endTurn(s); s = endTurn(s);
    expect(byId(s, 50)!.currentAttack).toBe(1); // only the 1 that was really taken is given back
  });
  it("#1241 Sénilité: mixed deltas in the same volley, each one given back at its own size", () => {
    const full = mkCreature(50, "enemy", { x: 4, y: 0 }, { currentAttack: 5, baseAttack: 5 });
    const weak = mkCreature(51, "enemy", { x: 4, y: 1 }, { currentAttack: 1, baseAttack: 1 });
    const wall = mkCreature(52, "enemy", { x: 4, y: 2 }, { currentAttack: 0, baseAttack: 0 });
    let s = scenario([full, weak, wall], 1241);
    s = { ...s, prisms: [] };
    s = playCard(s, card(1241), { x: 5, y: 3 });
    expect([byId(s, 50)!.currentAttack, byId(s, 51)!.currentAttack, byId(s, 52)!.currentAttack]).toEqual([3, 0, 0]);
    s = endTurn(s); s = endTurn(s);
    expect([byId(s, 50)!.currentAttack, byId(s, 51)!.currentAttack, byId(s, 52)!.currentAttack]).toEqual([5, 1, 0]);
  });
});

describe("Temporary control + exact-AT target", () => {
  // #19 Fiole de Psykoz: "Prenez le contrôle d'une invocation adverse ayant 3 AT
  // jusqu'au tour de votre adversaire." castTarget OpponentSummonEqual3AT.
  it("#19 Fiole de Psykoz: only an enemy with exactly 3 AT is a legal target", () => {
    const exact = mkCreature(50, "enemy", { x: 4, y: 1 }, { currentAttack: 3 });
    const off = mkCreature(51, "enemy", { x: 4, y: 3 }, { currentAttack: 4 });
    const ally = mkCreature(52, "ally", { x: 6, y: 1 }, { currentAttack: 3 });
    const s = scenario([exact, off, ally], 19);
    expect(canPlayCard(s, card(19), { x: 4, y: 1 })).toBeNull();     // 3 AT enemy → legal
    expect(canPlayCard(s, card(19), { x: 4, y: 3 })).not.toBeNull(); // 4 AT → rejected (not exactly 3)
    expect(canPlayCard(s, card(19), { x: 6, y: 1 })).not.toBeNull(); // ally → rejected (Opponent only)
  });
  it("#19 Fiole de Psykoz: the seized creature acts this turn as if owned, reverts at the opponent's next turn", () => {
    const foe = mkCreature(50, "enemy", { x: 4, y: 2 }, { currentAttack: 3, baseAttack: 3, movementLeft: 0, hasAttacked: true, baseMovement: 3 });
    let s = scenario([foe], 19);
    s = { ...s, prisms: [] };
    s = playCard(s, card(19), { x: 4, y: 2 });
    expect(byId(s, 50)!.owner).toBe("ally");          // seized to my side
    // "doit se comporter exactement comme si je la possédais", ready to advance/fight now,
    // not summoning-sick (otherwise it would revert before it could ever act).
    expect(byId(s, 50)!.hasAttacked).toBe(false);
    expect(byId(s, 50)!.movementLeft).toBe(3);        // refreshed to its full PM this turn
    s = endTurn(s);                                    // → opponent's turn start: control reverts
    expect(byId(s, 50)!.owner).toBe("enemy");          // handed back to its original owner
  });
});

