describe("Dynamic count buffs", () => {
  // #672 Force de l'Âge: "+1 AT et +1 AR à une invocation par Enutrof allié en jeu."
  it("#672 Force de l'Âge: buffs the target +1 AT/AR per allied Enutrof in play", () => {
    const target = mkCreature(50, "ally", { x: 6, y: 2 }, { currentAttack: 2, baseAttack: 2, armor: 0, cardId: 40 }); // Gobbal (not Enutrof)
    const enu1 = mkCreature(51, "ally", { x: 6, y: 1 }, { cardId: 756 });  // Belgodass = Enutrof
    const enu2 = mkCreature(52, "ally", { x: 6, y: 3 }, { cardId: 831 });  // Sambalinette = Enutrof
    let s = scenario([target, enu1, enu2], 672);
    s = { ...s, prisms: [] };
    s = playCard(s, card(672), { x: 6, y: 2 });
    expect(byId(s, 50)!.currentAttack).toBe(4); // 2 + 2 Enutrofs
    expect(byId(s, 50)!.armor).toBe(2);          // +2 AR
  });
  // #1391 Marquage: "+1 AT à une invocation par invocation alliée avec portée en jeu."
  it("#1391 Marquage: buffs the target +1 AT per allied RANGED creature", () => {
    const target = mkCreature(50, "ally", { x: 6, y: 2 }, { currentAttack: 2, baseAttack: 2 });
    const ranged1 = mkCreature(51, "ally", { x: 6, y: 1 }, { range: 2 });
    const ranged2 = mkCreature(52, "ally", { x: 6, y: 3 }, { range: 1 });
    const melee = mkCreature(53, "ally", { x: 6, y: 4 }, { range: 0 });
    let s = scenario([target, ranged1, ranged2, melee], 1391);
    s = { ...s, prisms: [] };
    s = playCard(s, card(1391), { x: 6, y: 2 });
    expect(byId(s, 50)!.currentAttack).toBe(4); // 2 + 2 ranged allies (melee/target excluded)
  });
  // #1250 Championne Sanglante: "APPARITION : Gagne +1 AR par invocation adverse en jeu."
  it("#1250 Championne Sanglante: APPARITION gains +1 AR per enemy invocation in play", () => {
    const e1 = mkCreature(60, "enemy", { x: 4, y: 1 }, {});
    const e2 = mkCreature(61, "enemy", { x: 4, y: 3 }, {});
    let s = scenario([e1, e2], 1250);
    s = { ...s, prisms: [] };
    s = playCard(s, card(1250), { x: 8, y: 2 }); // play Championne (deferred NÉCROME)
    s = resolvePendingAction(s, { x: 8, y: 0 }); // decline on board → land it + fire its held APPARITION
    const champ = s.creatures.find((c) => c.cardId === 1250)!;
    expect(champ.armor).toBe(2); // 2 enemy invocations × 1
  });
  it("#1250 Championne Sanglante: with a Dofus revealed first, still gains +1 AR per enemy", () => {
    const e1 = mkCreature(60, "enemy", { x: 4, y: 1 }, {});
    const e2 = mkCreature(61, "enemy", { x: 4, y: 3 }, {});
    let s = scenario([e1, e2], 1250);
    s = { ...s, prisms: [] };
    s = playCard(s, card(1250), { x: 8, y: 2 });
    // Resolve the reveal (reveal an allied Dofus) instead of declining → APPARITION still fires.
    const dofus = s.dofuses.find((d) => d.owner === "ally" && !d.revealed)!;
    s = resolvePendingAction(s, dofus.position);
    const champ = s.creatures.find((c) => c.cardId === 1250)!;
    expect(champ.armor).toBe(2); // +1 AR × 2 enemies, fired after the reveal
  });
});

describe("Hand recycle", () => {
  // #1149 Martingale: "Place votre main sous votre pioche. Piochez autant de cartes."
  it("#1149 Martingale: sends the hand to the deck bottom and draws that many fresh cards", () => {
    const base = scenario([], 1149);
    const s0 = {
      ...base,
      prisms: [],
      players: {
        ...base.players,
        ally: { ...base.players.ally, hand: [1149, 10, 20], handCostMods: [0, 0, 0], deck: [30, 40, 50] },
      },
    };
    const s = playCard(s0, card(1149), { x: 0, y: 0 });
    // After discarding the spell, hand was [10,20] (2 cards) → recycled to bottom,
    // then 2 fresh cards drawn from the top (50, 40).
    expect(s.players.ally.hand.length).toBe(2);
    expect(s.players.ally.hand).not.toContain(10); // old hand left the hand
    expect(s.players.ally.hand).not.toContain(20);
    expect(s.players.ally.deck).toContain(10);     // old hand now at the deck bottom
    expect(s.players.ally.deck).toContain(20);
    expect(s.players.ally.hand).toContain(50);     // drew the top cards
    expect(s.players.ally.hand).toContain(40);
  });
});

