describe("Flèche d'Immolation #351 (inflige 2, si la cible meurt piochez une carte)", () => {
  it("draws a card when the spell kills its target", () => {
    card(351); card(40);
    const target = mkCreature(1, "enemy", { x: 4, y: 2 }, { currentLife: 2, baseLife: 2 });
    const base = scenario([target], 351);
    const s0 = { ...base, prisms: [], players: { ...base.players, ally: { ...base.players.ally, hand: [351], handCostMods: [0], ap: 10, maxAp: 10, deck: [40] } } };
    const s = playCard(s0, card(351), { x: 4, y: 2 });
    expect(byId(s, 1)).toBeUndefined();              // target (2 PV) killed by the 2 damage
    expect(s.players.ally.hand).toContain(40);       // drew the top of the deck
    expect(s.players.ally.deck).not.toContain(40);   // deck consumed it
  });
  it("does not draw when the target survives", () => {
    card(351); card(40);
    const target = mkCreature(1, "enemy", { x: 4, y: 2 }, { currentLife: 5, baseLife: 5 });
    const base = scenario([target], 351);
    const s0 = { ...base, prisms: [], players: { ...base.players, ally: { ...base.players.ally, hand: [351], handCostMods: [0], ap: 10, maxAp: 10, deck: [40] } } };
    const s = playCard(s0, card(351), { x: 4, y: 2 });
    expect(byId(s, 1)!.currentLife).toBe(3);         // 5 − 2 = 3, survives
    expect(s.players.ally.hand).not.toContain(40);   // no draw
    expect(s.players.ally.deck).toContain(40);       // deck untouched
  });
  it("DRAWS when the flèche only WOUNDS but Emma Zone's reactive ping finishes the kill", () => {
    // Target with 3 HP. The Flèche deals 2 → 1 HP (it survives the spell alone), then Emma Zone's "quand
    // vous jouez un sort" ping deals 1 → dead. The draw must still happen: the target died from this
    // play, a reactive trigger counting as the finishing hit (settleOnKillMarkers is evaluated after
    // fireOnPlayReactions).
    card(351); card(1866); card(40);
    const emma = mkCreature(10, "ally", { x: 7, y: 2 }, { cardId: 1866, triggers: card(1866).triggers ?? [] });
    const target = mkCreature(1, "enemy", { x: 4, y: 2 }, { currentLife: 3, baseLife: 5 });
    const base = scenario([emma, target], 351);
    const s0 = { ...base, prisms: [], players: { ...base.players, ally: { ...base.players.ally, hand: [351], handCostMods: [0], ap: 10, maxAp: 10, deck: [40] } } };
    const s = playCard(s0, card(351), { x: 4, y: 2 });
    expect(byId(s, 1)).toBeUndefined();              // 3 − 2 (flèche) − 1 (Emma) = 0 → mort
    expect(s.players.ally.hand).toContain(40);       // draw triggered by the combined kill
    expect(s.players.ally.deck).not.toContain(40);
  });
});

