describe("Trouvaille #1382 (différé : 2 butins + PA consommés SEULEMENT à la 2e sélection)", () => {
  it("places nothing and spends no AP on the cast cell, both Butins and the AP land on the 2nd pick", () => {
    card(1382);
    const base = scenario([], 1382);
    const cost = card(1382).cost;
    const s0 = { ...base, prisms: [], butins: [], players: { ...base.players, ally: { ...base.players.ally, hand: [1382], handCostMods: [0], ap: 10, maxAp: 10 } } };
    // CAST on (8,1) = the first selection → nothing placed, no AP spent; only the pick opens.
    let s = playCard(s0, card(1382), { x: 8, y: 1 });
    expect(s.pendingAction).not.toBeNull();
    expect(s.pendingAction!.filter).toBe("own_empty_camp");
    expect(s.butins.length).toBe(0);    // nothing placed yet (deferred)
    expect(s.players.ally.ap).toBe(10); // no AP spent yet (refunded)
    // second selection (8,3) → both Butins drop at once and the cost is charged.
    s = resolvePendingAction(s, { x: 8, y: 3 });
    expect(s.pendingAction).toBeNull();
    expect(s.butins.length).toBe(2);
    expect(s.butins.some((b) => b.position.x === 8 && b.position.y === 1 && b.owner === "ally")).toBe(true);
    expect(s.butins.some((b) => b.position.x === 8 && b.position.y === 3 && b.owner === "ally")).toBe(true);
    expect(s.players.ally.ap).toBe(10 - cost); // AP charged only on the final selection
  });

  it("re-picking the cast cell = annulation ; une relance aboutit", () => {
    card(1382);
    const base = scenario([], 1382);
    const s0 = { ...base, prisms: [], butins: [], players: { ...base.players, ally: { ...base.players.ally, hand: [1382], handCostMods: [0], ap: 10, maxAp: 10 } } };
    let s = playCard(s0, card(1382), { x: 8, y: 1 });
    // The cell already chosen is no longer a valid pick → plain take-back (nothing was committed).
    s = resolvePendingAction(s, { x: 8, y: 1 });
    expect(s.pendingAction).toBeNull();
    expect(s.butins.length).toBe(0);
    expect(s.players.ally.ap).toBe(10);
    expect(s.players.ally.hand).toContain(1382);
    // Full new try: both butins fall and the AP is paid once.
    s = playCard(s, card(1382), { x: 8, y: 1 });
    s = resolvePendingAction(s, { x: 8, y: 3 });
    expect(s.pendingAction).toBeNull();
    expect(s.butins.length).toBe(2);
    expect(s.players.ally.ap).toBe(10 - card(1382).cost);
  });

  it("annulation en cours de sélection (clic hors plateau) = reprise totale, jamais de réaction ON_PLAY", () => {
    card(1382);
    const base = scenario([], 1382);
    const s0 = { ...base, prisms: [], butins: [], players: { ...base.players, ally: { ...base.players.ally, hand: [1382], handCostMods: [0], ap: 10, maxAp: 10 } } };
    let s = playCard(s0, card(1382), { x: 8, y: 1 });
    expect(s.pendingAction?.heldSpell?.cardId).toBe(1382);
    expect(s.players.ally.discard).toHaveLength(0); // rien engagé pendant les picks
    s = cancelPendingAction(s);
    expect(s.pendingAction).toBeNull();
    expect(s.butins.length).toBe(0);
    expect(s.players.ally.ap).toBe(10);
    expect(s.players.ally.hand).toContain(1382);
    expect(s.players.ally.discard).toHaveLength(0);
  });

  it("near-full camp whose only spare cells hold Tas d'Os never opens a dead pending", () => {
    card(1382);
    const base = scenario([], 1382);
    // 19 of the 20 ally camp cells (x 5..8 × y 0..4) carry a Tas d'Os; only (8,0) is a real
    // own_empty_camp cell. Before the fix, countFreeButinCells miscounted the 19 Tas d'Os
    // cells as "free" (it never checked state.tasDOs) → the 2-butin pick deferred, then its
    // mandatory 2nd pick had no own_empty_camp target (the filter rejects Tas d'Os) →
    // validPendingTargets empty → a NON-optional pending with zero targets → legalActions
    // returns [] → self-play freeze. countFreeButinCells now delegates to the own_empty_camp
    // filter, so the gate and the pick agree.
    const tasDOs: { position: { x: number; y: number }; owner: "ally" }[] = [];
    for (let x = 5; x <= 8; x++) for (let y = 0; y < 5; y++) {
      if (x === 8 && y === 0) continue; // leave exactly one genuine own_empty_camp cell
      tasDOs.push({ position: { x, y }, owner: "ally" });
    }
    const s0 = { ...base, prisms: [], butins: [], tasDOs, players: { ...base.players, ally: { ...base.players.ally, hand: [1382], handCostMods: [0], ap: 10, maxAp: 10 } } };
    const s = playCard(s0, card(1382), { x: 8, y: 0 });
    // With one own_empty_camp cell (< the 2 needed) the multi-pick is not deferred.
    expect(s.pendingAction).toBeNull();
    // Invariant (belt-and-suspenders): a parked pending must never be a dead non-optional pick.
    if (s.pendingAction && !(s.pendingAction as { optional?: boolean }).optional) {
      expect(validPendingTargets(s).length).toBeGreaterThan(0);
    }
  });
});

describe("Téléportation #119 (destination : case avec un objet, butin/glyphe/graine/tas d'os)", () => {
  it("can teleport a creature onto a cell holding a GLYPH (own_empty_camp would have blocked it)", () => {
    card(119);
    const mover = mkCreature(1, "ally", { x: 8, y: 2 }, {});
    const base = scenario([mover], 119);
    const s0 = { ...base, prisms: [], glyphs: [{ position: { x: 7, y: 2 }, owner: "ally" as const }], players: { ...base.players, ally: { ...base.players.ally, hand: [119], handCostMods: [0], ap: 10, maxAp: 10 } } };
    // Cast on the creature → the destination pick opens with the relaxed filter.
    let s = playCard(s0, card(119), { x: 8, y: 2 });
    expect(s.pendingAction).not.toBeNull();
    expect(s.pendingAction!.filter).toBe("own_cell_no_unit");
    expect(validPendingTargets(s).some((t) => t.x === 7 && t.y === 2)).toBe(true); // the glyph cell is a legal destination now
    // Resolve → the creature lands on the glyph cell.
    s = resolvePendingAction(s, { x: 7, y: 2 });
    expect(byId(s, 1)!.position).toEqual({ x: 7, y: 2 });
    expect((s.glyphs ?? []).some((g) => g.position.x === 7 && g.position.y === 2)).toBe(true); // own glyph persists (only enemies destroy it)
  });

  it("Picks up a Butin it teleports onto (the Butin is consumed)", () => {
    card(119);
    const mover = mkCreature(1, "ally", { x: 8, y: 2 }, {});
    const base = scenario([mover], 119);
    const s0 = { ...base, prisms: [], butins: [{ position: { x: 7, y: 2 }, owner: "ally" as const }], players: { ...base.players, ally: { ...base.players.ally, hand: [119], handCostMods: [0], ap: 10, maxAp: 10 } } };
    let s = playCard(s0, card(119), { x: 8, y: 2 });
    s = resolvePendingAction(s, { x: 7, y: 2 });
    expect(byId(s, 1)!.position).toEqual({ x: 7, y: 2 });
    expect((s.butins ?? []).some((b) => b.position.x === 7 && b.position.y === 2)).toBe(false); // butin consumed (picked up)
  });

  it("Picks up an allied Seed it teleports onto (+1 AR, seed consumed)", () => {
    card(119);
    const mover = mkCreature(1, "ally", { x: 8, y: 2 }, { armor: 0 });
    const base = scenario([mover], 119);
    const s0 = { ...base, prisms: [], seeds: [{ position: { x: 7, y: 2 }, owner: "ally" as const }], players: { ...base.players, ally: { ...base.players.ally, hand: [119], handCostMods: [0], ap: 10, maxAp: 10 } } };
    let s = playCard(s0, card(119), { x: 8, y: 2 });
    s = resolvePendingAction(s, { x: 7, y: 2 });
    expect(byId(s, 1)!.armor).toBe(1); // +1 AR from stepping onto your own seed
    expect((s.seeds ?? []).some((sd) => sd.position.x === 7 && sd.position.y === 2)).toBe(false); // seed consumed
  });

  it("still refuses a cell occupied by a creature", () => {
    card(119);
    const mover = mkCreature(1, "ally", { x: 8, y: 2 }, {});
    const blocker = mkCreature(2, "ally", { x: 7, y: 2 }, {});
    const base = scenario([mover, blocker], 119);
    const s0 = { ...base, prisms: [], players: { ...base.players, ally: { ...base.players.ally, hand: [119], handCostMods: [0], ap: 10, maxAp: 10 } } };
    const s = playCard(s0, card(119), { x: 8, y: 2 });
    expect(validPendingTargets(s).some((t) => t.x === 7 && t.y === 2)).toBe(false); // a creature still blocks the cell
  });
});

describe("Chevalier de Parme #1969 (MORT ADVERSE : gagne +1 AT, buff plat)", () => {
  it("gains +1 AT each time an enemy creature dies", () => {
    card(1969);
    const chevalier = mkCreature(1, "ally", { x: 7, y: 2 }, { cardId: 1969, currentAttack: 3, baseAttack: 3, triggers: card(1969).triggers ?? [] });
    const foe = mkCreature(2, "enemy", { x: 4, y: 2 }, { currentLife: 1, baseLife: 1 }); // created alive
    const base = scenario([chevalier, foe]);
    // Kill the enemy in the array handed to resolveDeathsAndWin (scenario keeps it alive at setup).
    const creatures = base.creatures.map((c) => (c.instanceId === 2 ? { ...c, currentLife: 0 } : c));
    const s = resolveDeathsAndWin(base, creatures, base.dofuses, [...base.log], new Set());
    expect(s.creatures.some((c) => c.instanceId === 2 && c.currentLife > 0)).toBe(false); // enemy died
    expect(byId(s, 1)!.currentAttack).toBe(4); // Chevalier +1 AT (3 → 4) on the enemy's death
  });

  it("le +AT monte À CHAQUE kill PENDANT l'avance → coup au Dofus boosté", () => {
    card(1969);
    // Parme AT 2, PM 5, clears 3 enemies with 1 HP at (4,2)(3,2)(2,2) then reaches the 5 HP Dofus at
    // (0,2). Each MORT ADVERSE must raise the AT before the next hit → AT 5 on the Dofus → killed in one
    // hit + break-through.
    const parme = mkCreature(1, "ally", { x: 5, y: 2 }, { cardId: 1969, currentLife: 5, baseLife: 5, currentAttack: 2, baseAttack: 2, movementLeft: 5, baseMovement: 5, hasAttacked: false, triggers: card(1969).triggers ?? [] });
    const mkFoe = (id: number, x: number) => mkCreature(id, "enemy", { x, y: 2 }, { currentLife: 1, baseLife: 1, currentAttack: 0, baseAttack: 0 });
    const sc = scenario([parme, mkFoe(2, 4), mkFoe(3, 3), mkFoe(4, 2)]);
    const dofuses = sc.dofuses.map((d) => (d.owner === "enemy" && d.position.x === 0 && d.position.y === 2 ? { ...d, currentLife: 5, baseLife: 5 } : d));
    const s = endTurn({ ...sc, dofuses, players: { ...sc.players, ally: { ...sc.players.ally, deck: [16, 16, 16] }, enemy: { ...sc.players.enemy, deck: [16, 16, 16] } } });
    expect(s.dofuses.some((d) => d.owner === "enemy" && d.position.x === 0 && d.position.y === 2)).toBe(false); // Dofus DÉTRUIT en un coup
    expect(byId(s, 1)).toBeUndefined(); // Parme a percé le mur (retour deck)
    expect(s.players.ally.deck).toContain(1969);
  });

  it("PAS de double-comptage : Parme qui tue en avançant mais reste sur le plateau finit à AT = base + kills", () => {
    card(1969);
    // Parme AT 2, PM 2, kills 2 enemies, stops (no Dofus behind) → AT exactly 4, not 6.
    const parme = mkCreature(1, "ally", { x: 5, y: 2 }, { cardId: 1969, currentLife: 5, baseLife: 5, currentAttack: 2, baseAttack: 2, movementLeft: 2, baseMovement: 2, hasAttacked: false, triggers: card(1969).triggers ?? [] });
    const mkFoe = (id: number, x: number) => mkCreature(id, "enemy", { x, y: 2 }, { currentLife: 1, baseLife: 1, currentAttack: 0, baseAttack: 0 });
    const sc = scenario([parme, mkFoe(2, 4), mkFoe(3, 3)]);
    const s = endTurn({ ...sc, players: { ...sc.players, ally: { ...sc.players.ally, deck: [16, 16, 16] }, enemy: { ...sc.players.enemy, deck: [16, 16, 16] } } });
    expect(byId(s, 1)!.currentAttack).toBe(4); // 2 base + 2 kills, applied once (inline), not counted again in the post pass
    expect(byId(s, 2)).toBeUndefined();
    expect(byId(s, 3)).toBeUndefined();
  });
});

