    const s = endTurn({ ...sc, players: { ...sc.players, ally: { ...sc.players.ally, deck: [16, 16, 16] }, enemy: { ...sc.players.enemy, deck: [16, 16, 16] } } });
    expect(byId(s, 1)!.currentAttack).toBe(6);
    expect(byId(s, 1)!.armor).toBe(4);
