describe("Championne Embrocheuse #1023 (APPARITION : repousse les ennemis de sa ligne vers le dofus ennemi)", () => {
  it("defers the push behind the NÉCROME reveal, pushes only after the reveal is settled", () => {
    card(1023);
    const onLine = mkCreature(1, "enemy", { x: 4, y: 2 }, { currentLife: 5, baseLife: 5 });
    const offLine = mkCreature(2, "enemy", { x: 4, y: 1 }, { currentLife: 5, baseLife: 5 });
    const base = scenario([onLine, offLine], 1023);
    const s0 = { ...base, prisms: [], players: { ...base.players, ally: { ...base.players.ally, hand: [1023], handCostMods: [0], ap: 10, maxAp: 10 } } };
    // Championne is a NÉCROME: the Dofus-reveal pick opens first; the push has not fired yet.
    let s = playCard(s0, card(1023), { x: 8, y: 2 });
    expect(s.pendingAction).not.toBeNull();               // reveal pick open
    expect(byId(s, 1)!.position).toEqual({ x: 4, y: 2 });  // enemy on the row not pushed yet
    // Decline on the board → the creature lands and its held-back APPARITION push fires now.
    s = resolvePendingAction(s, { x: 8, y: 0 });
    expect(byId(s, 1)!.position.x).toBeLessThan(4); // on-line enemy shoved toward x=0 (its own wall)
    expect(byId(s, 1)!.position.y).toBe(2);          // stays on the same line
    expect(byId(s, 2)!.position).toEqual({ x: 4, y: 1 }); // off-line enemy untouched
  });
});

describe("Glissement forcé vs case de Dofus détruit (poussée/attirance s'arrêtent avant le mur)", () => {
  it("un glissement forcé s'arrête juste AVANT la colonne-mur d'un Dofus détruit (pas de percée, pas de pioche)", () => {
    // Only the walk and the charge can put a creature on the cell of a destroyed Dofus (→ break-through
    // → under the deck). A push/pull (Championne Embrocheuse, Chacha Tyran, Trool, Uppercut…, all
    // through slideCreatureBack) stops one cell before.
    const base = scenario([]);
    const foe = mkCreature(1, "enemy", { x: 2, y: 2 }, { currentLife: 5, baseLife: 5 });
    // Enemy Dofus of row 2 (on its wall column x=0) destroyed → its cell is "free".
    const dofuses: DofusInstance[] = base.dofuses.map((d) =>
      d.owner === "enemy" && d.position.y === 2 ? { ...d, position: { ...d.position }, currentLife: 0 } : { ...d, position: { ...d.position } },
    );
    const creatures = [foe];
    const log: GameEvent[] = [];
    slideCreatureBack(foe, creatures, dofuses, 5, log); // poussée vers le mur ennemi (x=0)
    expect(foe.position.x).toBe(1);   // arrêt juste avant la colonne-mur x=0
    expect(foe.currentLife).toBe(5);  // pas de percée (toujours en vie)
    expect(creatures).toContain(foe); // still on the board (not sent back to the deck)
  });
});

describe("Percée sur case de Dofus détruit : ARRIVER en avançant remonte au deck", () => {
  // Destroyed Dofus + the creature reaches the last cell by advancing (with its PM/charge, even when it
  // spends its last PM) → back to the deck. Teleported onto it → not right away (it waits for its next
  // advance). The enemy advances toward x=9; its last cell = x=8.
  const foeToWall = (id: number, x: number, pm: number, extra: Partial<ReturnType<typeof mkCreature>> = {}) =>
    mkCreature(id, "enemy", { x, y: 4 }, { cardId: 40, currentLife: 4, baseLife: 4, currentAttack: 3, baseAttack: 3, movementLeft: pm, baseMovement: pm, hasAttacked: false, ...extra });
  const noDofusRow4 = (base: ReturnType<typeof scenario>) =>
    base.dofuses.filter((d) => !(d.owner === "ally" && d.position.x === 9 && d.position.y === 4)); // Dofus (9,4) détruit
  const enemyTurn = (creatures: ReturnType<typeof mkCreature>[], dofuses: ReturnType<typeof scenario>["dofuses"]) => {
    const base = scenario(creatures);
    return endTurn({ ...base, dofuses, activeSide: "enemy" as const, players: { ...base.players, ally: { ...base.players.ally, deck: [16, 16, 16] }, enemy: { ...base.players.enemy, deck: [16, 16, 16] } } });
  };

  it("épuise ses PM pour ARRIVER sur la dernière case (5→8, PM 3) → remonte au deck", () => {
    const f = foeToWall(1, 5, 3);
    const base = scenario([f]);
    const s = enemyTurn([f], noDofusRow4(base));
    expect(byId(s, 1)).toBeUndefined();                    // no longer on the board
    expect((s.players.enemy.deck ?? []).includes(40)).toBe(true); // remontée au deck
  });

  it("déjà sur la dernière case (8,4) et elle avance → remonte aussi (« quand ce sera son tour »)", () => {
    const f = foeToWall(1, 8, 3);
    const base = scenario([f]);
    const s = enemyTurn([f], noDofusRow4(base));
    expect(byId(s, 1)).toBeUndefined();
    expect((s.players.enemy.deck ?? []).includes(40)).toBe(true);
  });

  it("en mal d'invocation sur la dernière case (n'avance PAS ce tour) → RESTE (ne remonte pas)", () => {
    // Models "placed/teleported there, before its advance": it does not break through as long as it does
    // not advance.
    const f = foeToWall(1, 8, 3, { hasAttacked: true, movementLeft: 0 });
    const base = scenario([f]);
    const s = enemyTurn([f], noDofusRow4(base));
    expect(byId(s, 1)).toBeTruthy();
    expect(byId(s, 1)!.position).toEqual({ x: 8, y: 4 }); // toujours là
  });

  it("le Dofus est ENCORE là → pas de percée à vide : elle le frappe et reste (5→8, Dofus 5 PV)", () => {
    const f = foeToWall(1, 5, 3);
    const base = scenario([f]);
    // Dofus (9,4) intact à 5 PV → l'ennemi (ATK 3) l'attaque depuis (8,4) sans percer.
    const dofuses = base.dofuses.map((d) => (d.owner === "ally" && d.position.x === 9 && d.position.y === 4 ? { ...d, currentLife: 5, baseLife: 5 } : d));
    const s = enemyTurn([f], dofuses);
    expect(byId(s, 1)).toBeTruthy();                       // reste (le Dofus survit)
    expect(byId(s, 1)!.position).toEqual({ x: 8, y: 4 });
    expect(s.dofuses.find((d) => d.owner === "ally" && d.position.x === 9 && d.position.y === 4)!.currentLife).toBe(2); // 5 − 3
  });
});

