describe("Lilotte #579 (2*) (charge quand un prisme est ramassé/détruit, mais pas celui qu'elle ramasse en se posant)", () => {
  it("placed on a prism, she does not charge (the prism resolves before her own effect)", () => {
    card(579);
    const base = scenario([], 579);
    const s0 = { ...base,
      prisms: [{ position: { x: 8, y: 2 }, owner: "ally" as const, kind: "ap" as const }],
      players: { ...base.players, ally: { ...base.players.ally, hand: [579], handCostMods: [0], ap: 10, maxAp: 10 } } };
    const s = playCard(s0, card(579), { x: 8, y: 2 }); // summon Lilotte onto the prism
    const lilotte = s.creatures.find((c) => c.cardId === 579)!;
    expect(lilotte.position.x).toBe(8); // did not charge (would be 7 if her ON_PRISM had fired)
    expect(s.prisms.some((p) => p.position.x === 8 && p.position.y === 2)).toBe(false); // prism consumed
  });
  it("Still charges when SOMEONE else picks up a prism", () => {
    card(579); card(16);
    const lilotte = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 579, baseMovement: 3, triggers: card(579).triggers ?? [] });
    const base = scenario([lilotte], 16);
    const s0 = { ...base,
      prisms: [{ position: { x: 8, y: 0 }, owner: "ally" as const, kind: "ap" as const }],
      players: { ...base.players, ally: { ...base.players.ally, hand: [16], handCostMods: [0], ap: 10, maxAp: 10 } } };
    const s = playCard(s0, card(16), { x: 8, y: 0 }); // a different creature picks up the prism
    expect(byId(s, 1)!.position.x).toBe(5); // Lilotte (not the picker) charged 6 → 5
  });
});

