describe("Atcham #468/#146/#171 (Insensible aux dégâts des sorts)", () => {
  it("is immune to spell damage, single-target and area", () => {
    const atcham = mkCreature(1, "enemy", { x: 4, y: 2 }, { currentLife: 5, baseLife: 5, properties: new Set(["SpellDamageInsensitivity"]) });
    const creatures = [atcham];
    applyEffects(creatures, [], [], [{ type: "DamageData", Damage: 3 } as never], { casterSide: "ally", targetCell: { x: 4, y: 2 } });
    expect(creatures[0].currentLife).toBe(5); // single-target spell → nothing
    applyEffects(creatures, [], [], [{ type: "AoeDamage", amount: 3, scope: "all" } as never], { casterSide: "ally", targetCell: { x: 4, y: 2 } });
    expect(creatures[0].currentLife).toBe(5); // area spell → also nothing
  });
  it("combat damage still lands (insensible only to spells, not melee)", () => {
    const atcham = mkCreature(1, "ally", { x: 7, y: 2 }, { currentLife: 5, baseLife: 5, currentAttack: 0, baseAttack: 0, properties: new Set(["SpellDamageInsensitivity"]) });
    const attacker = mkCreature(2, "enemy", { x: 6, y: 2 }, { currentAttack: 2, baseAttack: 2, baseMovement: 1, movementLeft: 1 });
    const base = scenario([atcham, attacker]);
    const s0 = { ...base, activeSide: "enemy" as const, prisms: [] };
    const s = endTurn(s0);
    expect(byId(s, 1)!.currentLife).toBe(3); // took 2 from melee (5 → 3), combat not blocked
  });
});

