describe("Gzenah #421 (ENTERS_PLAY +1/+1 quand un Iop allié entre) × Iop à APPARITION ciblée", () => {
  it("is boosted even when the summoned Iop opens a TARGETED-APPARITION pick (Tomla Klass #72)", () => {
    card(72); card(421);
    const gzenah = mkCreature(1, "ally", { x: 7, y: 2 }, { cardId: 421, currentAttack: 3, baseAttack: 3, armor: 0, triggers: card(421).triggers ?? [] });
    const buffTarget = mkCreature(2, "ally", { x: 6, y: 2 }, { currentAttack: 2, baseAttack: 2 }); // Tomla's APPARITION buffs a creature
    const base = scenario([gzenah, buffTarget]);
    const s0 = { ...base, prisms: [], players: { ...base.players, ally: { ...base.players.ally, hand: [72], handCostMods: [0], ap: 10, maxAp: 10 } } };
    // Play Tomla Klass (a Iop), its targeted APPARITION defers it off the board + opens a pick.
    let s = playCard(s0, card(72), { x: 8, y: 1 });
    expect(s.pendingAction).not.toBeNull();
    // Resolve the APPARITION → Tomla lands → Gzenah's ENTERS_PLAY (allied Iop) fires.
    s = resolvePendingAction(s, { x: 6, y: 2 });
    const g = s.creatures.find((c) => c.instanceId === 1)!;
    expect(g.currentAttack).toBe(4); // Gzenah +1 AT (3 → 4) despite the Iop's open APPARITION pick
    expect(g.armor).toBe(1);         // Gzenah +1 AR
  });
});

describe("Padgref Démouelle #222 (cibler un de vos Dofus pour l'invoquer, 1 dégât au Dofus)", () => {
  it("held off the board until you pick one of your Dofus (no AP spent before), which then takes 1", () => {
    card(222);
    const base = scenario([], 222);
    const allyDofus = base.dofuses.find((d) => d.owner === "ally" && d.currentLife > 0)!;
    const pos = { ...allyDofus.position };
    const lifeBefore = allyDofus.currentLife;
    const s0 = { ...base, prisms: [], players: { ...base.players, ally: { ...base.players.ally, hand: [222], handCostMods: [0], ap: 10, maxAp: 10 } } };

    // Play → the Dofus pick opens; Padgref is not on the board and no AP is spent yet.
    let s = playCard(s0, card(222), { x: 8, y: 1 });
    expect(s.pendingAction).not.toBeNull();
    expect(s.pendingAction!.filter).toBe("ally_dofus");
    expect(s.creatures.some((c) => c.cardId === 222)).toBe(false);
    expect(s.players.ally.ap).toBe(10);

    // Resolve (pick your Dofus) → it takes 1, Padgref lands, the cost is charged now.
    s = resolvePendingAction(s, pos);
    expect(s.dofuses.find((d) => d.position.x === pos.x && d.position.y === pos.y)!.currentLife).toBe(lifeBefore - 1);
    expect(s.creatures.some((c) => c.cardId === 222)).toBe(true);
    expect(s.players.ally.ap).toBe(10 - card(222).cost);
  });
});

describe("Artheon #1424: APPARITION cible un Dofus, invulnérable tant qu'Artheon est en jeu", () => {
  it("held off the board until you pick a Dofus (any), which gets invulnerableBy = Artheon's id", () => {
    card(1424);
    const base = scenario([], 1424);
    const allyDofus = base.dofuses.find((d) => d.owner === "ally" && d.currentLife > 0)!;
    const pos = { ...allyDofus.position };
    const s0 = { ...base, prisms: [], players: { ...base.players, ally: { ...base.players.ally, hand: [1424], handCostMods: [0], ap: 10, maxAp: 10 } } };

    // Play → the Dofus pick opens (filter any_dofus); Artheon is not on the board yet.
    let s = playCard(s0, card(1424), { x: 8, y: 1 });
    expect(s.pendingAction).not.toBeNull();
    expect(s.pendingAction!.filter).toBe("any_dofus");
    expect(s.creatures.some((c) => c.cardId === 1424)).toBe(false); // held off until the pick

    // Resolve (pick a Dofus) → Artheon lands and the Dofus is flagged invulnerable by Artheon.
    s = resolvePendingAction(s, pos);
    const artheon = s.creatures.find((c) => c.cardId === 1424)!;
    expect(artheon).toBeDefined();
    expect(s.dofuses.find((d) => d.position.x === pos.x && d.position.y === pos.y)!.invulnerableBy).toBe(artheon.instanceId);
  });

  it("the invulnerable Dofus takes no damage while Artheon lives, and is vulnerable again when Artheon dies", () => {
    const artheon = mkCreature(700, "ally", { x: 8, y: 2 }, { cardId: 1424 });
    const dofus: DofusInstance = { position: { x: 0, y: 2 }, owner: "ally", currentLife: 5, kind: "real", invulnerableBy: artheon.instanceId };
    const creatures = [artheon];
    const dofuses = [dofus];
    // an enemy AoE that hits every ally Dofus, the protected one is skipped while Artheon lives.
    applyEffects(creatures, dofuses, [], [{ type: "AoeDamageDofus", amount: 3 }], { casterSide: "enemy" } as never);
    expect(dofuses[0].currentLife).toBe(5);
    // Artheon dies → the guard lapses (the check re-reads "still alive") → the same AoE now lands.
    creatures[0].currentLife = 0;
    applyEffects(creatures, dofuses, [], [{ type: "AoeDamageDofus", amount: 3 }], { casterSide: "enemy" } as never);
    expect(dofuses[0].currentLife).toBe(2);
  });
});

describe("Flèche Criblante #8 (3 à une invocation + 1 au Dofus adverse de SA ligne)", () => {
  it("is wired to [DamageData, DamageDofusOnTargetRow] (not a second hit on the cast cell)", () => {
    expect((card(8).effects ?? []).map((e) => e.type)).toEqual(["DamageData", "DamageDofusOnTargetRow"]);
  });

  it("the creature takes 3 and only the enemy Dofus on that creature's row takes 1", () => {
    const target = mkCreature(1, "enemy", { x: 3, y: 2 }, { currentLife: 5, baseLife: 5 });
    const dofusSameRow: DofusInstance = { position: { x: 0, y: 2 }, owner: "enemy", currentLife: 5, kind: "real" };
    const dofusOtherRow: DofusInstance = { position: { x: 0, y: 0 }, owner: "enemy", currentLife: 5, kind: "real" };
    const creatures = [target];
    const dofuses = [dofusSameRow, dofusOtherRow];
    applyEffects(creatures, dofuses, [], [{ type: "DamageData", Damage: 3 } as never, { type: "DamageDofusOnTargetRow", amount: 1 } as never], { casterSide: "ally", targetCell: { x: 3, y: 2 } });
    expect(creatures[0].currentLife).toBe(2);  // 3 to the targeted creature (5 → 2)
    expect(dofuses[0].currentLife).toBe(4);    // 1 to the enemy Dofus on row y=2
    expect(dofuses[1].currentLife).toBe(5);    // a Dofus on another row is untouched
  });

  it("the arrow still pierces to the Dofus even when the 3 kills the creature", () => {
    const target = mkCreature(1, "enemy", { x: 3, y: 2 }, { currentLife: 3, baseLife: 3 });
    const dofusSameRow: DofusInstance = { position: { x: 0, y: 2 }, owner: "enemy", currentLife: 5, kind: "real" };
    const creatures = [target];
    const dofuses = [dofusSameRow];
    applyEffects(creatures, dofuses, [], [{ type: "DamageData", Damage: 3 } as never, { type: "DamageDofusOnTargetRow", amount: 1 } as never], { casterSide: "ally", targetCell: { x: 3, y: 2 } });
    expect(creatures[0].currentLife).toBeLessThanOrEqual(0); // creature died to the 3
    expect(dofuses[0].currentLife).toBe(4);                  // Dofus on its row still took 1
  });
});

describe("Héros Impartial (aura board-wide, les DEUX camps)", () => {
  const atk = (cs: ReturnType<typeof withAuras>, id: number) => cs.find((c) => c.instanceId === id)!.currentAttack;

  it("#1132 grants +2 AT to every other creature, both camps, but not itself", () => {
    card(1132);
    const hero = mkCreature(1, "ally", { x: 6, y: 2 }, { currentAttack: 4, baseAttack: 4 });
    hero.cardId = 1132;
    const ally = mkCreature(2, "ally", { x: 6, y: 1 }, { currentAttack: 3, baseAttack: 3 });
    const foe = mkCreature(3, "enemy", { x: 3, y: 2 }, { currentAttack: 1, baseAttack: 1 });
    const cs = withAuras([hero, ally, foe]);
    expect(atk(cs, 1)).toBe(4); // self excluded
    expect(atk(cs, 2)).toBe(5); // allié +2
    expect(atk(cs, 3)).toBe(3); // enemy also +2 ("les autres", not "vos autres")
  });

  it("#1132 aura is revoked when the hero dies, and never stacks across recomputes", () => {
    card(1132);
    const hero = mkCreature(4, "ally", { x: 6, y: 2 }, { currentAttack: 4, baseAttack: 4 });
    hero.cardId = 1132;
    const ally = mkCreature(5, "ally", { x: 6, y: 1 }, { currentAttack: 3, baseAttack: 3 });
    let cs = withAuras([hero, ally]);
    cs = withAuras(cs);
    cs = withAuras(cs);
    expect(atk(cs, 5)).toBe(5); // toujours +2, pas +6
    cs.find((c) => c.instanceId === 4)!.currentLife = 0;
    cs = withAuras(cs);
    expect(atk(cs, 5)).toBe(3); // héros mort → bonus retiré
  });
});

describe("BLESSÉ (buff de stats continu tant que blessé)", () => {
  const atk = (cs: ReturnType<typeof withAuras>, id: number) => cs.find((c) => c.instanceId === id)!.currentAttack;
  const mov = (cs: ReturnType<typeof withAuras>, id: number) => cs.find((c) => c.instanceId === id)!.baseMovement;

  it("#323 Dureden gains +2 AT only while wounded, and loses it on full heal", () => {
    card(323);
    const d = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 323, currentAttack: 1, baseAttack: 1, currentLife: 4, baseLife: 4 });
    expect(atk(withAuras([d]), 1)).toBe(1); // pleine vie → pas de bonus
    d.currentLife = 2; // blessé
    const wounded = withAuras([d]);
    expect(atk(wounded, 1)).toBe(3); // +2 AT
    wounded[0].currentLife = 4; // soigné à fond → recompute retire le bonus
    expect(atk(withAuras(wounded), 1)).toBe(1);
  });

  it("#475 Arakne gains +1 PM only while wounded; idempotent across recomputes", () => {
    card(475);
    const a = mkCreature(2, "ally", { x: 6, y: 1 }, { cardId: 475, baseMovement: 2, currentLife: 3, baseLife: 3 });
    expect(mov(withAuras([a]), 2)).toBe(2); // pleine vie → base
    a.currentLife = 1; // blessé
    let cs = withAuras([a]);
    cs = withAuras(cs);
    cs = withAuras(cs);
    expect(mov(cs, 2)).toBe(3); // +1 PM, pas d'empilement (pas +3)
  });
});

describe("BLESSÉ (propriétés continues tant que blessé)", () => {
  const has = (cs: ReturnType<typeof withAuras>, id: number, p: string) => cs.find((c) => c.instanceId === id)!.properties.has(p);
  const res = (cs: ReturnType<typeof withAuras>, id: number) => cs.find((c) => c.instanceId === id)!.resistance;
  const atk = (cs: ReturnType<typeof withAuras>, id: number) => cs.find((c) => c.instanceId === id)!.currentAttack;

  it("#309 Grouilleux: initiative + AT granted only while wounded, revoked on full heal", () => {
    card(309);
    const g = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 309, currentAttack: 2, baseAttack: 2, currentLife: 3, baseLife: 3 });
    let cs = withAuras([g]);
    expect(has(cs, 1, "FirstStrike")).toBe(false); // pleine vie → pas d'initiative
    expect(atk(cs, 1)).toBe(2);
    g.currentLife = 1; // blessé
    cs = withAuras([g]);
    expect(has(cs, 1, "FirstStrike")).toBe(true); // blessé → initiative
    expect(atk(cs, 1)).toBe(3); // +1 AT
    cs[0].currentLife = 3; // soigné à fond
    cs = withAuras(cs);
    expect(has(cs, 1, "FirstStrike")).toBe(false);
    expect(atk(cs, 1)).toBe(2);
  });

  it("#1765 Maude: résistance 1 + AT only while wounded; idempotent", () => {
    card(1765);
    const m = mkCreature(2, "ally", { x: 6, y: 1 }, { cardId: 1765, currentAttack: 2, baseAttack: 2, resistance: 0, currentLife: 4, baseLife: 4 });
    let cs = withAuras([m]);
    expect(res(cs, 2)).toBe(0); // pleine vie → pas de résistance
    expect(atk(cs, 2)).toBe(2);
    m.currentLife = 2; // blessé
    cs = withAuras([m]);
    cs = withAuras(cs); // recompute → pas d'empilement
    expect(res(cs, 2)).toBe(1); // blessé → résistance 1 (pas 2)
    expect(atk(cs, 2)).toBe(4); // +2 AT
    cs[0].currentLife = 4; // soigné
    cs = withAuras(cs);
    expect(res(cs, 2)).toBe(0);
  });

  it("#309 summoned at full life has no baked FirstStrike (un-baked from bindata)", () => {
    const s0 = scenario([], 309);
    const s = playCard(s0, card(309), { x: 8, y: 2 });
    const g = s.creatures.find((c) => c.cardId === 309)!;
    expect(g.currentLife).toBe(g.baseLife); // fraîchement invoqué → plein
    expect(g.properties.has("FirstStrike")).toBe(false); // pas blessé → pas d'initiative
  });
});

