describe("Soin de Dofus (Eniripsa)", () => {
  const dofusAtTest = (s: ReturnType<typeof playCard>, x: number, y: number) =>
    s.dofuses.find((d) => d.position.x === x && d.position.y === y)!.currentLife;

  it("#650 Dollie Praan: APPARITION heals a picked Dofus by 1, capped at its départ (5)", () => {
    const mk = (life: number) => ({ ...scenario([], 650), prisms: [], dofuses: [
      { position: { x: 9, y: 2 }, owner: "ally" as const, currentLife: life, kind: "real" as const },
    ] });
    // Wounded Dofus → +1.
    let s = playCard(mk(3), card(650), { x: 8, y: 2 });
    expect(s.pendingAction).not.toBeNull();
    s = resolvePendingAction(s, { x: 9, y: 2 });
    expect(dofusAtTest(s, 9, 2)).toBe(4);
    // Full Dofus → stays capped at 5.
    let s2 = playCard(mk(5), card(650), { x: 8, y: 2 });
    s2 = resolvePendingAction(s2, { x: 9, y: 2 });
    expect(dofusAtTest(s2, 9, 2)).toBe(5);
  });

  it("#491 Mot Reconstituant heals a wounded creature or a wounded Dofus by 2", () => {
    // Creature target (castTarget SummonOrDofus → the click is the target).
    const wounded = mkCreature(240, "ally", { x: 6, y: 2 }, { currentLife: 2, baseLife: 6 });
    let sc = { ...scenario([wounded], 491), prisms: [] };
    sc = playCard(sc, card(491), { x: 6, y: 2 });
    expect(byId(sc, 240)!.currentLife).toBe(4); // 2 → 4
    // Dofus target.
    const sd = playCard({ ...scenario([], 491), prisms: [], dofuses: [
      { position: { x: 9, y: 2 }, owner: "ally" as const, currentLife: 2, kind: "real" as const },
    ] }, card(491), { x: 9, y: 2 });
    expect(dofusAtTest(sd, 9, 2)).toBe(4); // 2 → 4
  });

  it("un soin de Dofus pousse DOFUS_LIFE_HEALED (le beat de son animation), et RIEN si le Dofus est intact", () => {
    // Without an event, the heal would change the state silently: there would be no moment left to hang
    // the FX and the health bar going up on (see beat-visibility).
    const mk = (life: number) => ({ ...scenario([], 650), prisms: [], dofuses: [
      { position: { x: 9, y: 2 }, owner: "ally" as const, currentLife: life, kind: "real" as const },
    ] });
    let s = playCard(mk(3), card(650), { x: 8, y: 2 });
    s = resolvePendingAction(s, { x: 9, y: 2 });
    const healed = s.log.filter((e): e is Extract<GameEvent, { type: "DOFUS_LIFE_HEALED" }> => e.type === "DOFUS_LIFE_HEALED");
    expect(healed).toHaveLength(1);
    expect(healed[0].dofusAt).toEqual({ x: 9, y: 2 });
    expect(healed[0].heal).toBe(1);
    expect(healed[0].lifeMod).toEqual({ valueBefore: 3, valueAfter: 4, modification: 1 });
    // Dofus untouched: the heal changes nothing, so no event (no heal animation on a Dofus that lost
    // nothing).
    let full = playCard(mk(5), card(650), { x: 8, y: 2 });
    full = resolvePendingAction(full, { x: 9, y: 2 });
    expect(full.log.some((e) => e.type === "DOFUS_LIFE_HEALED")).toBe(false);
  });
});

describe("Téléport derrière l'attaquant (Sram, CONTRE-COUP)", () => {
  it("#183 Azraoël teleports behind the attacker that just hit it, regardless of line", () => {
    const sram = mkCreature(300, "ally", { x: 6, y: 3 }, { cardId: 183, currentLife: 4, baseLife: 4, triggers: card(183).triggers ?? [] });
    const attacker = mkCreature(301, "enemy", { x: 4, y: 1 }, { currentLife: 5, baseLife: 5 }); // autre ligne, plus loin
    const base = scenario([sram, attacker]);
    const s0 = { ...base, prisms: [], log: [...base.log,
      { type: "DAMAGE", sourceInstanceId: 301, targetInstanceId: 300, damage: 2 } as GameEvent,
    ] };
    const after = fireContreCoup(s0, base.log.length);
    // Attaquant ennemi en {4,1} → derrière (vers sa base, x−1) = {3,1} ; le Sram s'y pose (ignore sa propre ligne).
    expect(byId(after, 300)!.position).toEqual({ x: 3, y: 1 });
  });

  it("does not teleport when the cell behind the attacker is occupied", () => {
    const sram = mkCreature(302, "ally", { x: 6, y: 2 }, { cardId: 183, currentLife: 4, baseLife: 4, triggers: card(183).triggers ?? [] });
    const attacker = mkCreature(303, "enemy", { x: 4, y: 2 }, { currentLife: 5, baseLife: 5 });
    const blocker = mkCreature(304, "enemy", { x: 3, y: 2 }, { currentLife: 5, baseLife: 5 }); // occupe la case derrière
    const base = scenario([sram, attacker, blocker]);
    const s0 = { ...base, prisms: [], log: [...base.log,
      { type: "DAMAGE", sourceInstanceId: 303, targetInstanceId: 302, damage: 1 } as GameEvent,
    ] };
    const after = fireContreCoup(s0, base.log.length);
    expect(byId(after, 302)!.position).toEqual({ x: 6, y: 2 }); // reste sur place
  });
});

