describe("APPARITION : transforme une invocation (Magmog #44)", () => {
  it("#44 Magmog: transforms a chosen creature into a Bouftou Noir (#40), keeping its owner", () => {
    card(44);
    const enemy = mkCreature(890, "enemy", { x: 3, y: 2 }, { cardId: 9999 });
    const sc = scenario([enemy], 44);
    const base = { ...sc, prisms: [], players: { ...sc.players, ally: { ...sc.players.ally, hand: [44], handCostMods: [0], ap: 20, maxAp: 20 } } };
    const s1 = playCard(base, card(44), { x: 8, y: 2 }); // summon Magmog → target pick
    const s2 = s1.pendingAction ? resolvePendingAction(s1, { x: 3, y: 2 }) : s1;
    const transformed = s2.creatures.find((c) => c.position.x === 3 && c.position.y === 2)!;
    expect(transformed.cardId).toBe(40); // became Bouftou Noir
    expect(transformed.owner).toBe("enemy"); // kept its owner
  });
});

describe("APPARITION : réduit une invocation au silence (Justice #209)", () => {
  it("#209 Justice: silences only the picked creature (strips armor/resist/buffs), sparing the others", () => {
    card(209);
    const target = mkCreature(870, "enemy", { x: 3, y: 2 }, { cardId: 9999, armor: 3, resistance: 2, baseAttack: 5, currentAttack: 5, printedAttack: 2 });
    const other = mkCreature(871, "enemy", { x: 2, y: 1 }, { cardId: 9999, armor: 3 });
    const sc = scenario([target, other], 209);
    const base = { ...sc, prisms: [], players: { ...sc.players, ally: { ...sc.players.ally, hand: [209], handCostMods: [0], ap: 20, maxAp: 20 } } };
    const s1 = playCard(base, card(209), { x: 8, y: 2 }); // summon Justice → silence pick
    expect(s1.pendingAction).toBeTruthy(); // a single-target pick opened (not a board-wide silence)
    const s2 = resolvePendingAction(s1, { x: 3, y: 2 }); // pick the buffed enemy
    const t = byId(s2, 870)!;
    expect(t.armor).toBe(0); // silenced → armour pool stripped
    expect(t.resistance).toBe(0); // résistance stripped
    expect(t.currentAttack).toBe(2); // attack reverted to printed value
    expect(byId(s2, 871)!.armor).toBe(3); // the other enemy is untouched (single target)
  });

  it("#67 Justice: silences a creature and sets its AT to 3, both effects on a single pick", () => {
    card(67);
    // Buffed enemy: armour 3 + AT raised to 5 (printed 2). Silence strips the
    // armour and reverts AT to 2; SetAttack then overrides it to 3.
    const target = mkCreature(880, "enemy", { x: 3, y: 2 }, { cardId: 9999, armor: 3, baseAttack: 5, currentAttack: 5, printedAttack: 2 });
    const sc = scenario([target], 67);
    const base = { ...sc, prisms: [], players: { ...sc.players, ally: { ...sc.players.ally, hand: [67], handCostMods: [0], ap: 20, maxAp: 20 } } };
    const s1 = playCard(base, card(67), { x: 8, y: 2 }); // summon Justice → one pick
    expect(s1.pendingAction).toBeTruthy();
    const s2 = resolvePendingAction(s1, { x: 3, y: 2 });
    expect(s2.pendingAction).toBeNull(); // a single pick resolved both effects
    const t = byId(s2, 880)!;
    expect(t.armor).toBe(0); // silenced (armour stripped) → proves Silence applied
    expect(t.currentAttack).toBe(3); // AT set to 3 after the silence revert → proves SetAttack applied
  });
});

describe("MORT adverse : réagit à la mort d'un ennemi (Mortadella #639)", () => {
  it("#639 Mortadella: heals 1 PV per enemy death (ally deaths do not count)", () => {
    const sc = scenario([]);
    const mortadella = mkCreature(700, "ally", { x: 6, y: 2 }, { cardId: 639, currentLife: 2, baseLife: 5, triggers: card(639).triggers ?? [] });
    const deadEnemy1 = mkCreature(701, "enemy", { x: 3, y: 1 }, { cardId: 9999, currentLife: 0 });
    const deadEnemy2 = mkCreature(702, "enemy", { x: 3, y: 3 }, { cardId: 9999, currentLife: 0 });
    const deadAlly = mkCreature(703, "ally", { x: 5, y: 0 }, { cardId: 9999, currentLife: 0 });
    const res = resolveDeathsAndWin(sc, [mortadella, deadEnemy1, deadEnemy2, deadAlly], sc.dofuses, [], new Set());
    expect(res.creatures.find((c) => c.instanceId === 700)!.currentLife).toBe(4); // 2 + 2 enemy deaths (the ally death is ignored)
  });

  it("#639 Mortadella: the heal never overshoots base life", () => {
    const sc = scenario([]);
    const mortadella = mkCreature(710, "ally", { x: 6, y: 2 }, { cardId: 639, currentLife: 5, baseLife: 5, triggers: card(639).triggers ?? [] });
    const deadEnemy = mkCreature(711, "enemy", { x: 3, y: 1 }, { cardId: 9999, currentLife: 0 });
    const res = resolveDeathsAndWin(sc, [mortadella, deadEnemy], sc.dofuses, [], new Set());
    expect(res.creatures.find((c) => c.instanceId === 710)!.currentLife).toBe(5); // already full → no overheal
  });

  it("#1271 Empereur Gemene: an enemy death adds 1 PA to the owner's reserve (player-state, deferred path)", () => {
    const sc = scenario([]);
    const emp = mkCreature(720, "ally", { x: 6, y: 2 }, { cardId: 1271, triggers: card(1271).triggers ?? [] });
    const deadEnemy = mkCreature(721, "enemy", { x: 3, y: 1 }, { cardId: 9999, currentLife: 0 });
    const res = resolveDeathsAndWin(sc, [emp, deadEnemy], sc.dofuses, [], new Set());
    expect(res.players.ally.apReserve).toBe(sc.players.ally.apReserve + 1);
  });

  it("#345 Gros Nambourg: gains +1 AT per allied death (enemy deaths do not count)", () => {
    const sc = scenario([]);
    const nambourg = mkCreature(740, "ally", { x: 6, y: 2 }, { cardId: 345, currentAttack: 2, baseAttack: 2, triggers: card(345).triggers ?? [] });
    const deadAlly1 = mkCreature(741, "ally", { x: 5, y: 1 }, { cardId: 9999, currentLife: 0 });
    const deadAlly2 = mkCreature(742, "ally", { x: 5, y: 3 }, { cardId: 9999, currentLife: 0 });
    const deadEnemy = mkCreature(743, "enemy", { x: 3, y: 2 }, { cardId: 9999, currentLife: 0 });
    const res = resolveDeathsAndWin(sc, [nambourg, deadAlly1, deadAlly2, deadEnemy], sc.dofuses, [], new Set());
    expect(res.creatures.find((c) => c.instanceId === 740)!.currentAttack).toBe(4); // 2 + 2 allied deaths (the enemy death is ignored)
  });

  it("#228 Kralamor: an allied death heals your other invocations 2 PV (not itself, not enemies)", () => {
    const sc = scenario([]);
    const kralamor = mkCreature(750, "ally", { x: 6, y: 2 }, { cardId: 228, currentLife: 3, baseLife: 5, triggers: card(228).triggers ?? [] });
    const woundedAlly = mkCreature(751, "ally", { x: 7, y: 1 }, { cardId: 9999, currentLife: 2, baseLife: 5 });
    const deadAlly = mkCreature(752, "ally", { x: 5, y: 0 }, { cardId: 9999, currentLife: 0 });
    const res = resolveDeathsAndWin(sc, [kralamor, woundedAlly, deadAlly], sc.dofuses, [], new Set());
    expect(res.creatures.find((c) => c.instanceId === 751)!.currentLife).toBe(4); // other wounded ally: 2 + 2
    expect(res.creatures.find((c) => c.instanceId === 750)!.currentLife).toBe(3); // Kralamor itself not healed (excludeSelf)
  });

  it("#1478 Bébé Phorreur Armuré: gains +1 AT/+1 AR only when a PHORREUR ally dies (other families ignored)", () => {
    const sc = scenario([]);
    const bebe = mkCreature(760, "ally", { x: 6, y: 2 }, { cardId: 1478, currentAttack: 2, baseAttack: 2, armor: 0, triggers: card(1478).triggers ?? [] });
    const deadPhorreur = mkCreature(761, "ally", { x: 5, y: 1 }, { cardId: 16, currentLife: 0 });   // Phorreur family
    const deadOther = mkCreature(762, "ally", { x: 5, y: 3 }, { cardId: 9999, currentLife: 0 });     // no family
    const res = resolveDeathsAndWin(sc, [bebe, deadPhorreur, deadOther], sc.dofuses, [], new Set());
    const b = res.creatures.find((c) => c.instanceId === 760)!;
    expect(b.currentAttack).toBe(3); // +1 from the Phorreur death only (the non-Phorreur death is ignored)
    expect(b.armor).toBe(1);
  });

  it("#411 Necrom l'Ancien: a SADIDA ally death grants +1 AT and draws a card", () => {
    const sc = scenario([]);
    const necrom = mkCreature(770, "ally", { x: 6, y: 2 }, { cardId: 411, currentAttack: 2, baseAttack: 2, triggers: card(411).triggers ?? [] });
    const deadSadida = mkCreature(771, "ally", { x: 5, y: 1 }, { cardId: 362, currentLife: 0 }); // Sadida family
    const base = { ...sc, players: { ...sc.players, ally: { ...sc.players.ally, hand: [], handCostMods: [], deck: [50, 51] } } };
    const res = resolveDeathsAndWin(base, [necrom, deadSadida], base.dofuses, [], new Set());
    expect(res.creatures.find((c) => c.instanceId === 770)!.currentAttack).toBe(3); // +1 AT
    expect(res.players.ally.hand.length).toBe(1); // and drew a card
  });

  it("#616 Disciple Cochonnet: an enemy death grants +1 AT/+1 AR per allied Cochon (counts itself, ignores non-Cochons)", () => {
    const sc = scenario([]);
    const cochonnet = mkCreature(730, "ally", { x: 6, y: 2 }, { cardId: 616, currentAttack: 2, baseAttack: 2, armor: 0, triggers: card(616).triggers ?? [] });
    const otherCochon = mkCreature(731, "ally", { x: 7, y: 1 }, { cardId: 1271 }); // Cochon family, no reactive trigger on this instance
    const notCochon = mkCreature(732, "ally", { x: 5, y: 3 }, { cardId: 9999 });   // not a Cochon → not counted
    const deadEnemy = mkCreature(733, "enemy", { x: 3, y: 1 }, { cardId: 9999, currentLife: 0 });
    const res = resolveDeathsAndWin(sc, [cochonnet, otherCochon, notCochon, deadEnemy], sc.dofuses, [], new Set());
    const c = res.creatures.find((x) => x.instanceId === 730)!;
    expect(c.currentAttack).toBe(4); // 2 + (2 allied Cochons × 1)
    expect(c.armor).toBe(2);         // 0 + (2 allied Cochons × 1)
  });
});

describe("APPARITION : récupère un sort / une carte de la défausse (Bakara #418, Phorreur #255)", () => {
  it("#418 Bakara: recovers the last spell from your discard (summons are skipped)", () => {
    card(418);
    const sc = scenario([]);
    const base = { ...sc, prisms: [], players: { ...sc.players, ally: { ...sc.players.ally, hand: [418], handCostMods: [0], ap: 20, maxAp: 20, discard: [220, 6, 172] } } };
    const s = playCard(base, card(418), { x: 8, y: 2 });
    expect(s.players.ally.hand).toContain(172); // 172 (Ronces) = most recent spell → back to hand
    expect(s.players.ally.discard).toEqual([220, 6]); // 172 removed; summon (6) + older spell (220) stay
  });

  it("#255 Phorreur Domestique: recovers a card at random, no type filter (a summon counts)", () => {
    card(255);
    const sc = scenario([]);
    const base = { ...sc, prisms: [], players: { ...sc.players, ally: { ...sc.players.ally, hand: [255], handCostMods: [0], ap: 20, maxAp: 20, discard: [6] } } };
    const s = playCard(base, card(255), { x: 8, y: 2 });
    expect(s.players.ally.hand).toContain(6); // the lone discard card (a summon) returned → proves no spell-only filter
    expect(s.players.ally.discard).toEqual([]);
  });

  it("#262 Bakara: recovers the last two spells from your discard (summons skipped)", () => {
    card(262);
    const sc = scenario([]);
    const base = { ...sc, prisms: [], players: { ...sc.players, ally: { ...sc.players.ally, hand: [262], handCostMods: [0], ap: 20, maxAp: 20, discard: [220, 6, 172, 253] } } };
    const s = playCard(base, card(262), { x: 8, y: 2 });
    expect(s.players.ally.hand).toContain(172); // the 2 most recent spells (172, 253) returned
    expect(s.players.ally.hand).toContain(253);
    expect(s.players.ally.discard).toEqual([220, 6]); // oldest spell (220) + the summon (6) stay
  });

  it("#303 Bakara: recovers the last spell from each player's discard into your hand", () => {
    card(303);
    const sc = scenario([]);
    const base = { ...sc, prisms: [], players: { ...sc.players,
      ally: { ...sc.players.ally, hand: [303], handCostMods: [0], ap: 20, maxAp: 20, discard: [220, 6] },
      enemy: { ...sc.players.enemy, discard: [172] } } };
    const s = playCard(base, card(303), { x: 8, y: 2 });
    expect(s.players.ally.hand).toContain(220); // your own last spell
    expect(s.players.ally.hand).toContain(172); // And the opponent's last spell → into your hand
    expect(s.players.ally.discard).toEqual([6]); // 220 pulled; the summon stays
    expect(s.players.enemy.discard).toEqual([]); // 172 pulled from the foe's discard
  });
});

describe("APPARITION : invoque un jeton sur chaque case de sa RANGÉE (column-fill, same x)", () => {
  // "rangée" = the vertical column (same x), not the horizontal lane / "ligne".
  it("#1245 Héroïne Séculaire: fills the empty cells of its column with Bébé Phorreur Armuré #1478", () => {
    card(1245);
    const sc = scenario([]);
    const base = { ...sc, prisms: [], players: { ...sc.players, ally: { ...sc.players.ally, hand: [1245], handCostMods: [0], ap: 20, maxAp: 20 } } };
    const s = playCard(base, card(1245), { x: 8, y: 2 });
    const tokens = s.creatures.filter((c) => c.cardId === 1478 && c.owner === "ally");
    expect(tokens.length).toBe(4); // column x=8, rows 0/1/3/4 (row 2 holds the source)
    expect(tokens.every((c) => c.position.x === 8)).toBe(true);
    expect(tokens.map((c) => c.position.y).sort((a, b) => a - b)).toEqual([0, 1, 3, 4]);
  });

  it("#205 Corbeau Noir: fills its column with Corbac #56, and each token plays its innate Charge de 1 on summon", () => {
    card(205);
    const sc = scenario([]);
    const base = { ...sc, prisms: [], players: { ...sc.players, ally: { ...sc.players.ally, hand: [205], handCostMods: [0], ap: 20, maxAp: 20 } } };
    const s = playCard(base, card(205), { x: 8, y: 2 });
    const corbacs = s.creatures.filter((c) => c.cardId === 56 && c.owner === "ally");
    // Column x=8, rows 0/1/3/4 (row 2 = source). Each Corbac self-charges 1 on summon,
    // they are in different lanes so they never collide, advancing one cell forward to x=7.
    expect(corbacs.length).toBe(4);
    expect(corbacs.every((c) => c.position.x === 7)).toBe(true);
    expect(corbacs.map((c) => c.position.y).sort((a, b) => a - b)).toEqual([0, 1, 3, 4]);
  });
});

describe("COUP DE GRÂCE (Qilby #496, Sphincter Cell #18)", () => {
  it("#496 Qilby: a killing blow in combat sends that enemy's card to your hand (not its discard)", () => {
    const qilby = mkCreature(1, "ally", { x: 5, y: 2 }, { cardId: 496, currentAttack: 5, baseAttack: 5, currentLife: 5, baseLife: 5, movementLeft: 3, baseMovement: 3, hasAttacked: false, triggers: card(496).triggers ?? [] });
    const victim = mkCreature(2, "enemy", { x: 4, y: 2 }, { cardId: 6, currentAttack: 1, baseAttack: 1, currentLife: 2, baseLife: 5 });
    const baseSc = scenario([qilby, victim]);
    const sc = { ...baseSc, players: { ...baseSc.players, ally: { ...baseSc.players.ally, hand: [], handCostMods: [] } } };
    const s = endTurn(sc); // ally advance phase: Qilby (5 AT) kills the adjacent 2-life enemy and survives
    expect(s.creatures.find((c) => c.instanceId === 2)).toBeUndefined(); // victim died
    expect(s.players.ally.hand).toContain(6);          // victim's card → Qilby's hand
    expect(s.players.enemy.discard).not.toContain(6);  // and not the enemy's discard
  });

  it("#496 Qilby: no coup de grâce if Qilby dies in the exchange (kill but does not survive)", () => {
    const qilby = mkCreature(1, "ally", { x: 5, y: 2 }, { cardId: 496, currentAttack: 5, baseAttack: 5, currentLife: 2, baseLife: 5, movementLeft: 3, baseMovement: 3, hasAttacked: false, triggers: card(496).triggers ?? [] });
    const victim = mkCreature(2, "enemy", { x: 4, y: 2 }, { cardId: 6, currentAttack: 5, baseAttack: 5, currentLife: 2, baseLife: 5 }); // trades blows: both die
    const baseSc = scenario([qilby, victim]);
    const sc = { ...baseSc, players: { ...baseSc.players, ally: { ...baseSc.players.ally, hand: [], handCostMods: [] } } };
    const s = endTurn(sc);
    expect(s.creatures.find((c) => c.instanceId === 1)).toBeUndefined(); // Qilby also died
    expect(s.players.ally.hand).not.toContain(6);     // no bounce, Qilby did not survive
    expect(s.players.enemy.discard).toContain(6);     // victim went to its own discard normally
  });

  it("#18 Sphincter Cell: a killing blow recovers the last Rat from your discard", () => {
    const cell = mkCreature(1, "ally", { x: 5, y: 2 }, { cardId: 18, currentAttack: 5, baseAttack: 5, currentLife: 5, baseLife: 5, movementLeft: 3, baseMovement: 3, hasAttacked: false, triggers: card(18).triggers ?? [] });
    const victim = mkCreature(2, "enemy", { x: 4, y: 2 }, { cardId: 9999, currentAttack: 1, baseAttack: 1, currentLife: 2, baseLife: 5 });
    const baseSc = scenario([cell, victim]);
    const sc = { ...baseSc, players: { ...baseSc.players, ally: { ...baseSc.players.ally, hand: [], handCostMods: [], discard: [220, 490] } } }; // 490 Ratou (Rat), 220 Mot de Silence (not)
    const s = endTurn(sc);
    expect(s.creatures.find((c) => c.instanceId === 2)).toBeUndefined();
    expect(s.players.ally.hand).toContain(490);     // the last Rat returned
    expect(s.players.ally.discard).toEqual([220]);  // only the Rat was pulled
  });
});

describe("ConditionalStatBoost continu (Boufton Blanc #175, Rat Dechant #91)", () => {
  it("#175 Boufton Blanc: +1 AT while another allied Bouftou (Gobbal family) is in play", () => {
    card(175);
    const boufton = mkCreature(700, "ally", { x: 6, y: 2 }, { cardId: 175, currentAttack: 2, baseAttack: 2, printedAttack: 2 });
    const otherBouftou = mkCreature(701, "ally", { x: 7, y: 1 }, { cardId: 44 }); // Magmog (Gobbal/Bouftou)
    expect(withAuras([boufton, otherBouftou]).find((c) => c.instanceId === 700)!.currentAttack).toBe(3); // 2 + 1
    expect(withAuras([boufton]).find((c) => c.instanceId === 700)!.currentAttack).toBe(2);               // alone → no boost
  });

  it("#91 Rat Dechant: +1 AT while a Rat Devil (#387) is in play", () => {
    card(91);
    const dechant = mkCreature(700, "ally", { x: 6, y: 2 }, { cardId: 91, currentAttack: 2, baseAttack: 2, printedAttack: 2 });
    const devil = mkCreature(701, "ally", { x: 7, y: 1 }, { cardId: 387 });
    expect(withAuras([dechant, devil]).find((c) => c.instanceId === 700)!.currentAttack).toBe(3); // 2 + 1 (Rat Devil present)
    expect(withAuras([dechant]).find((c) => c.instanceId === 700)!.currentAttack).toBe(2);         // no Rat Devil → no boost
  });

  it("#1425 Exécuteur Endeuillé: +2 AT while standing in its own camp", () => {
    card(1425);
    const inCamp = mkCreature(700, "ally", { x: 6, y: 2 }, { cardId: 1425, currentAttack: 3, baseAttack: 3, printedAttack: 3 });
    expect(withAuras([inCamp]).find((c) => c.instanceId === 700)!.currentAttack).toBe(5); // col 6 = ally camp → 3 + 2
    const advanced = mkCreature(701, "ally", { x: 3, y: 2 }, { cardId: 1425, currentAttack: 3, baseAttack: 3, printedAttack: 3 });
    expect(withAuras([advanced]).find((c) => c.instanceId === 701)!.currentAttack).toBe(3); // col 3 = enemy camp → no boost
  });

  it("#1425 Exécuteur Endeuillé: perd le +2 AT DÈS qu'il franchit la ligne en avançant → tape à 3 hors camp", () => {
    card(1425);
    // Exécuteur at the edge of its camp (x=5, in camp → 5 AT). It advances, crosses into the enemy camp
    // and hits: the +2 must drop at the moment it crosses → 3 damage, not 5 (frozen currentAttack).
    const exec = mkCreature(700, "ally", { x: 5, y: 1 }, { cardId: 1425, currentAttack: 5, baseAttack: 5, printedAttack: 3, auraAttack: 2, inCampAtk: 2, currentLife: 5, baseLife: 5, movementLeft: 5, baseMovement: 5 });
    const foe = mkCreature(701, "enemy", { x: 2, y: 1 }, { currentLife: 9, baseLife: 9, currentAttack: 1 });
    let s = scenario([exec, foe]);
    s = { ...s, prisms: [] };
    s = endTurn(s);
    expect(byId(s, 701)!.currentLife).toBe(6); // a pris 3 (frappé depuis x=3, hors camp), PAS 5
  });

  it("#1425 Exécuteur Endeuillé: GARDE le +2 AT quand il frappe SANS quitter son camp → tape à 5", () => {
    card(1425);
    const exec = mkCreature(702, "ally", { x: 7, y: 1 }, { cardId: 1425, currentAttack: 5, baseAttack: 5, printedAttack: 3, auraAttack: 2, inCampAtk: 2, currentLife: 5, baseLife: 5, movementLeft: 5, baseMovement: 5 });
    const foe = mkCreature(703, "enemy", { x: 6, y: 1 }, { currentLife: 9, baseLife: 9, currentAttack: 1 }); // ennemi adjacent, dans le camp allié
    let s = scenario([exec, foe]);
    s = { ...s, prisms: [] };
    s = endTurn(s);
    expect(byId(s, 703)!.currentLife).toBe(4); // frappé depuis x=7 (in camp) → 5 dégâts (boost conservé)
  });

  it("#969 Canne Jalman: +1 PM while an enemy is ahead of it on the same row", () => {
    card(969);
    const canne = mkCreature(700, "ally", { x: 6, y: 2 }, { cardId: 969, baseMovement: 2, printedMovement: 2 });
    const enemyAhead = mkCreature(701, "enemy", { x: 3, y: 2 }, { cardId: 9999 }); // lower x = ahead for an ally, same row
    expect(withAuras([canne, enemyAhead]).find((c) => c.instanceId === 700)!.baseMovement).toBe(3); // 2 + 1
    expect(withAuras([canne]).find((c) => c.instanceId === 700)!.baseMovement).toBe(2);             // no enemy ahead → no boost
  });

  it("#11 Requinou: +1 AT while at least one other invocation is wounded", () => {
    card(11);
    const requinou = mkCreature(700, "ally", { x: 6, y: 2 }, { cardId: 11, currentAttack: 2, baseAttack: 2, printedAttack: 2 });
    const woundedAlly = mkCreature(701, "ally", { x: 7, y: 1 }, { cardId: 9999, currentLife: 2, baseLife: 5 });
    expect(withAuras([requinou, woundedAlly]).find((c) => c.instanceId === 700)!.currentAttack).toBe(3); // a wounded other invocation → +1
    const healthyAlly = mkCreature(702, "ally", { x: 7, y: 1 }, { cardId: 9999, currentLife: 5, baseLife: 5 });
    expect(withAuras([requinou, healthyAlly]).find((c) => c.instanceId === 700)!.currentAttack).toBe(2); // none wounded → no boost
  });
});

describe("Invoque s'il survit à des dégâts (Boo #513, Empereur Gelax #422)", () => {
  it("#513 Boo: CONTRE_COUP summons another Boo on a free LATERAL cell (same column, y±1)", () => {
    card(513);
    const boo = mkCreature(700, "ally", { x: 7, y: 2 }, { cardId: 513, triggers: card(513).triggers ?? [] });
    const s = runTrigger({ ...scenario([boo]), prisms: [] }, "CONTRE_COUP", 700);
    const spawned = s.creatures.filter((c) => c.cardId === 513 && c.instanceId !== 700);
    expect(spawned).toHaveLength(1);
    expect(spawned[0].position.x).toBe(7);            // same column
    expect([1, 3]).toContain(spawned[0].position.y);  // one of the two vertical neighbours
  });

  it("#513 Boo: no Boo summoned when both lateral (y±1) cells are occupied", () => {
    card(513);
    const boo = mkCreature(700, "ally", { x: 7, y: 2 }, { cardId: 513, triggers: card(513).triggers ?? [] });
    const up = mkCreature(701, "ally", { x: 7, y: 1 }, { cardId: 9999 });
    const down = mkCreature(702, "ally", { x: 7, y: 3 }, { cardId: 9999 });
    const s = runTrigger({ ...scenario([boo, up, down]), prisms: [] }, "CONTRE_COUP", 700);
    expect(s.creatures.filter((c) => c.cardId === 513)).toHaveLength(1); // only the original, both laterals taken
  });

  it("#422 Empereur Gelax: CONTRE_COUP summons exactly one random Jelly (never an Empereur, no apparition cascade), rng advances", () => {
    card(422);
    const gelax = mkCreature(700, "ally", { x: 7, y: 2 }, { cardId: 422, triggers: card(422).triggers ?? [] });
    for (let seed = 1; seed <= 6; seed++) {
      const base = { ...scenario([gelax]), prisms: [], rng: seed };
      const s = runTrigger(base, "CONTRE_COUP", 700);
      const spawned = s.creatures.filter((c) => c.instanceId !== 700);
      expect(spawned).toHaveLength(1);                   // One Jelly, the summon does not play its own apparition (no cascade)
      const sc = card(spawned[0].cardId);
      expect(sc.families ?? []).toContain("Jelly");      // a Jelly
      expect(sc.name).not.toBe("Empereur Gelax");        // but never itself ("une AUTRE gelée")
      expect(s.rng).not.toBe(base.rng);                  // rng advanced → each new damage rolls independently
    }
  });

  it("#422 Empereur Gelax: consecutive contre-coups vary both the Jelly and its landing cell", () => {
    card(422);
    let state = { ...scenario([mkCreature(700, "ally", { x: 7, y: 2 }, { cardId: 422, triggers: card(422).triggers ?? [] })]), prisms: [] };
    const jellies: number[] = []; const cells: string[] = [];
    for (let i = 0; i < 10; i++) {
      const s = runTrigger(state, "CONTRE_COUP", 700);
      const sp = s.creatures.filter((c) => c.instanceId !== 700).sort((a, b) => a.instanceId - b.instanceId)[0];
      jellies.push(sp.cardId); cells.push(`${sp.position.x},${sp.position.y}`);
      state = { ...s, creatures: [s.creatures.find((c) => c.instanceId === 700)!] }; // thread rng, clear the board
    }
    expect(new Set(jellies).size).toBeGreaterThan(1); // not always the same Jelly
    expect(new Set(cells).size).toBeGreaterThan(1);   // not always the same cell
  });

  it("#422 Empereur Gelax: real endTurn flow, an enemy hitting Gelax each turn yields varying Jellies", () => {
    card(422);
    const gelax = mkCreature(700, "ally", { x: 5, y: 2 }, { cardId: 422, currentLife: 80, baseLife: 80, baseMovement: 0, movementLeft: 0, triggers: card(422).triggers ?? [] });
    const e1 = mkCreature(701, "enemy", { x: 4, y: 2 }, { cardId: 9999, currentAttack: 1, baseAttack: 1, currentLife: 80, baseLife: 80, baseMovement: 1, movementLeft: 1 });
    let state = { ...scenario([gelax, e1]), prisms: [], activeSide: "enemy" as const };
    const jellies: number[] = []; let prev = 0;
    for (let t = 0; t < 12; t++) {
      state = endTurn(state);
      const js = state.creatures.filter((c) => c.owner === "ally" && c.cardId !== 422 && (card(c.cardId).families ?? []).includes("Jelly"));
      if (js.length > prev) { jellies.push(js.sort((a, b) => b.instanceId - a.instanceId)[0].cardId); prev = js.length; }
    }
    expect(jellies.length).toBeGreaterThan(2);        // several contre-coups fired
    expect(new Set(jellies).size).toBeGreaterThan(1); // and they were not all the same Jelly
  });

  // Gelax #422 (CONTRE COUP: summons a Gelée if it survives) + Gelée d'Encre #69 (MORT: +1 AT/+1 AR to
  // your other Gelées): does the newly summoned Gelée get the bonus? It depends on who is resolved
  // first: the consequences resolve one after the other, and a death does not reach a creature that did
  // not exist yet. Both directions are tested below. (Enemy sweep order: most advanced column first,
  // then L5→L1, so for the same column the largest y moves first.)
  it("#422 Gelax : l'Encre #69 meurt AVANT l'invocation → la Gelée née ensuite n'a AUCUN bonus", () => {
    card(422); card(69);
    for (let seed = 1; seed <= 40; seed++) {
      // Encre en y=4 → son tueur e2 (y=4) avance AVANT e1 (y=2), qui frappe Gelax.
      const gelax = mkCreature(700, "ally", { x: 5, y: 2 }, { cardId: 422, currentLife: 80, baseLife: 80, baseMovement: 0, movementLeft: 0, triggers: card(422).triggers ?? [] });
      const encre = mkCreature(701, "ally", { x: 5, y: 4 }, { cardId: 69, currentLife: 1, baseLife: 2, currentAttack: 1, baseMovement: 0, movementLeft: 0, triggers: card(69).triggers ?? [] });
      const e1 = mkCreature(702, "enemy", { x: 4, y: 2 }, { cardId: 9999, currentAttack: 1, baseAttack: 1, currentLife: 80, baseLife: 80, baseMovement: 1, movementLeft: 1 });
      const e2 = mkCreature(703, "enemy", { x: 4, y: 4 }, { cardId: 9998, currentAttack: 4, baseAttack: 4, currentLife: 80, baseLife: 80, baseMovement: 1, movementLeft: 1 });
      const s0 = { ...scenario([gelax, encre, e1, e2]), prisms: [], activeSide: "enemy" as const, rng: seed };
      const s = endTurn(s0);
      expect(byId(s, 701)).toBeUndefined();                  // l'Encre est morte face à e2 (1er mover)
      expect(byId(s, 700)!.currentLife).toBeGreaterThan(0);  // Gelax survived e1 → it summoned
      // Gelax was alive when the Encre died → it takes its +1 AT / +1 AR right away. The armour gained this
      // way then absorbs e1's hit (1 damage): it drops back to 0, but the hit still counts as "dégât subi"
      // (armorHit) and does fire its CONTRE COUP.
      expect(byId(s, 700)!.currentAttack).toBe(byId(s0, 700)!.currentAttack + 1); // +1 AT de l'Encre, lui, reste
      expect(byId(s, 700)!.armor).toBe(0);                                        // +1 AR gagné puis mangé par e1
      const summoned = s.creatures.find((c) => c.owner === "ally" && c.cardId !== 422 && c.cardId !== 69
        && (card(c.cardId).families ?? []).includes("Jelly")
        && Math.abs(c.position.x - 5) <= 1 && Math.abs(c.position.y - 2) <= 1);
      // We look for a clean seed: the Gelée drawn may be another Gelée d'Encre #69 (excluded by the filter),
      // a Framboise #437 (which buffs itself on entry) or a Fraise #417 (which spawns a Gélatine); in those
      // three cases the 0 we want to check would be ambiguous. All the other Gelées come in with 0 AR and
      // their base AT. If no seed fits, the final throw will say so.
      if (!summoned || summoned.cardId === 437 || summoned.cardId === 417) continue;
      expect(summoned.armor).toBe(0);                             // born after the Encre died → nothing
      expect(summoned.currentAttack).toBe(card(summoned.cardId).attack); // stats de base, aucun bonus
      return;
    }
    throw new Error("no seed produced a clean (non-Framboise/Fraise) Gelax summon");
  });

  it("#422 Gelax : l'Encre #69 meurt APRÈS l'invocation → la Gelée déjà née EST boostée", () => {
    card(422); card(69);
    for (let seed = 1; seed <= 40; seed++) {
      // Mirror of the previous test: Gelax at y=4 → its attacker e1 (y=4) advances before e2 (y=1), which
      // kills the Encre. So the Gelée is already on the board when the Encre's MORT fires.
      const gelax = mkCreature(700, "ally", { x: 5, y: 4 }, { cardId: 422, currentLife: 80, baseLife: 80, baseMovement: 0, movementLeft: 0, triggers: card(422).triggers ?? [] });
      const encre = mkCreature(701, "ally", { x: 5, y: 1 }, { cardId: 69, currentLife: 1, baseLife: 2, currentAttack: 1, baseMovement: 0, movementLeft: 0, triggers: card(69).triggers ?? [] });
      const e1 = mkCreature(702, "enemy", { x: 4, y: 4 }, { cardId: 9999, currentAttack: 1, baseAttack: 1, currentLife: 80, baseLife: 80, baseMovement: 1, movementLeft: 1 });
      const e2 = mkCreature(703, "enemy", { x: 4, y: 1 }, { cardId: 9998, currentAttack: 4, baseAttack: 4, currentLife: 80, baseLife: 80, baseMovement: 1, movementLeft: 1 });
      const s0 = { ...scenario([gelax, encre, e1, e2]), prisms: [], activeSide: "enemy" as const, rng: seed };
      const s = endTurn(s0);
      expect(byId(s, 701)).toBeUndefined();                  // l'Encre est morte face à e2 (2e mover)
      expect(byId(s, 700)!.currentLife).toBeGreaterThan(0);  // Gelax survived e1 → it summoned before
      const summoned = s.creatures.find((c) => c.owner === "ally" && c.cardId !== 422 && c.cardId !== 69
        && (card(c.cardId).families ?? []).includes("Jelly")
        && Math.abs(c.position.x - 5) <= 1 && Math.abs(c.position.y - 4) <= 1);
      // Same clean seed filter as the previous test (Encre #69 / Framboise #437 / Fraise #417).
      if (!summoned || summoned.cardId === 437 || summoned.cardId === 417) continue;
      expect(summoned.armor).toBe(1);                                        // 0 de base + le +1 AR de l'Encre
      expect(summoned.currentAttack).toBe(card(summoned.cardId).attack + 1); // base + le +1 AT de l'Encre
      return;
    }
    throw new Error("no seed produced a clean (non-Framboise/Fraise) Gelax summon");
  });
});

describe("Amalia : invoque une poupée (#362 Gonflable, #368 Folle)", () => {
  it("#362 Amalia: APPARITION lets the player PLACE La Gonflable (#5) on a chosen valid summon cell", () => {
    card(362); card(5);
    const amalia = mkCreature(700, "ally", { x: 7, y: 2 }, { cardId: 362, triggers: card(362).triggers ?? [] });
    const s1 = runTrigger({ ...scenario([amalia]), prisms: [] }, "APPARITION", 700);
    expect(s1.pendingAction?.filter).toBe("own_summon_cell"); // a pick over valid summon cells
    const s2 = resolvePendingAction(s1, { x: 8, y: 0 });      // ally spawn column (x===8)
    const gonf = s2.creatures.filter((c) => c.cardId === 5 && c.owner === "ally");
    expect(gonf).toHaveLength(1);
    expect(gonf[0].position).toEqual({ x: 8, y: 0 });          // placed exactly where chosen
  });

  it("#362 Amalia: picking a cell outside the summon zone places nothing", () => {
    card(362); card(5);
    const amalia = mkCreature(700, "ally", { x: 7, y: 2 }, { cardId: 362, triggers: card(362).triggers ?? [] });
    const s1 = runTrigger({ ...scenario([amalia]), prisms: [] }, "APPARITION", 700);
    const s2 = resolvePendingAction(s1, { x: 1, y: 0 });       // enemy spawn cell → not a valid ally summon cell
    expect(s2.creatures.filter((c) => c.cardId === 5)).toHaveLength(0);
  });

  it("#368 Amalia: APPARITION lets the player place La Folle (#481) on a chosen valid summon cell", () => {
    card(368); card(481);
    const amalia = mkCreature(700, "ally", { x: 7, y: 2 }, { cardId: 368, triggers: card(368).triggers ?? [] });
    const s1 = runTrigger({ ...scenario([amalia]), prisms: [] }, "APPARITION", 700);
    expect(s1.pendingAction?.filter).toBe("own_summon_cell");
    const s2 = resolvePendingAction(s1, { x: 8, y: 4 });
    const folle = s2.creatures.filter((c) => c.cardId === 481 && c.owner === "ally");
    expect(folle).toHaveLength(1);
    expect(folle[0].position).toEqual({ x: 8, y: 4 });
    // La Folle's unlabeled discount fires on the token-summon too
    expect(s2.players.ally.nextCardDiscount ?? 0).toBe(1);
  });
});

describe("Sacrifice (Tartanque #154, Tofu Mutant #301)", () => {
  it("#154 Tartanque: APPARITION sacrifices a picked ally → self +4 AT +2 AR", () => {
    card(154);
    const tartanque = mkCreature(700, "ally", { x: 6, y: 2 }, { cardId: 154, currentAttack: 3, baseAttack: 3, armor: 0, triggers: card(154).triggers ?? [] });
    const fodder = mkCreature(701, "ally", { x: 7, y: 1 }, { cardId: 9999 });
    const s1 = runTrigger(scenario([tartanque, fodder]), "APPARITION", 700);
    expect(s1.pendingAction).toBeTruthy();
    const s2 = resolvePendingAction(s1, { x: 7, y: 1 }); // sacrifice the fodder
    expect(s2.creatures.find((c) => c.instanceId === 701)).toBeUndefined(); // fodder destroyed
    expect(byId(s2, 700)!.currentAttack).toBe(7); // 3 + 4
    expect(byId(s2, 700)!.armor).toBe(2);          // 0 + 2
  });

  it("#301 Tofu Mutant: UNPLAYABLE without a Tofu ally on the board", () => {
    card(301); card(75);
    const base = scenario([]);
    const inHand = { ...base, players: { ...base.players, ally: { ...base.players.ally, hand: [301], ap: 99 } } };
    expect(canPlayCard(inHand, card(301), { x: 8, y: 3 })).toBe("Aucun Tofu allié à sacrifier."); // no Tofu → gated
    const withTofu = { ...inHand, creatures: [mkCreature(701, "ally", { x: 7, y: 1 }, { cardId: 75 })] };
    expect(canPlayCard(withTofu, card(301), { x: 8, y: 3 })).toBeNull(); // Tofu ally present → playable
  });

  it("#301 Tofu Mutant: APPARITION sacrifices a TOFU ally → gains its AT and PM (non-Tofu pick declines)", () => {
    card(301); card(75);
    const mutant = mkCreature(700, "ally", { x: 6, y: 2 }, { cardId: 301, currentAttack: 1, baseAttack: 1, baseMovement: 1, movementLeft: 1, triggers: card(301).triggers ?? [] });
    const tofu = mkCreature(701, "ally", { x: 7, y: 1 }, { cardId: 75, currentAttack: 3, baseAttack: 3, baseMovement: 2, movementLeft: 2 }); // #75 Tofu Male (vanilla, no aura)
    const notTofu = mkCreature(702, "ally", { x: 7, y: 0 }, { cardId: 9999, currentAttack: 9, baseAttack: 9 });
    const s1 = runTrigger(scenario([mutant, tofu, notTofu]), "APPARITION", 700);
    expect(s1.pendingAction).toBeTruthy();
    const declined = resolvePendingAction(s1, { x: 7, y: 0 }); // non-Tofu → declines
    expect(byId(declined, 702)).toBeTruthy();           // non-Tofu untouched
    expect(byId(declined, 700)!.currentAttack).toBe(1); // no gain
    const s2 = resolvePendingAction(s1, { x: 7, y: 1 }); // the Tofu → sacrificed
    expect(s2.creatures.find((c) => c.instanceId === 701)).toBeUndefined();
    expect(byId(s2, 700)!.currentAttack).toBe(4); // 1 + 3 (victim's AT)
    expect(byId(s2, 700)!.baseMovement).toBe(3);  // 1 + 2 (victim's PM)
  });

  it("#301 Tofu Mutant: the pick only offers allied Tofus (the restriction no longer comes after the fact)", () => {
    // runTrigger only passed `pickFamily` (Wa Wabbit #59) to the pendingAction, never the `family`
    // that the Sacrifice of #301 carries. The filter fell back to a bare `ally_creature` and the
    // engine highlighted every ally. A player who clicked a non-Tofu lost their APPARITION without
    // sacrificing or gaining anything, a silent cancel.
    card(301); card(75);
    const mutant = mkCreature(700, "ally", { x: 6, y: 2 }, { cardId: 301, currentAttack: 1, baseAttack: 1, triggers: card(301).triggers ?? [] });
    const tofu = mkCreature(701, "ally", { x: 7, y: 1 }, { cardId: 75 });
    const notTofu = mkCreature(702, "ally", { x: 7, y: 0 }, { cardId: 9999 });
    const s = runTrigger(scenario([mutant, tofu, notTofu]), "APPARITION", 700);
    expect(s.pendingAction!.family).toBe("Tofu");
    const tgts = validPendingTargets(s);
    expect(tgts.some((c) => c.x === 7 && c.y === 1)).toBe(true);  // the Tofu, offered
    expect(tgts.some((c) => c.x === 7 && c.y === 0)).toBe(false); // the non-Tofu, no longer offered
  });

  it("#301 Tofu Mutant: no living allied Tofu, so no pick opens", () => {
    // hasAtLeastOneTarget now filters by family: no more empty pick when the Tofu died between the
    // cast and the APPARITION.
    card(301);
    const mutant = mkCreature(700, "ally", { x: 6, y: 2 }, { cardId: 301, triggers: card(301).triggers ?? [] });
    const notTofu = mkCreature(702, "ally", { x: 7, y: 0 }, { cardId: 9999 });
    const s = runTrigger(scenario([mutant, notTofu]), "APPARITION", 700);
    expect(s.pendingAction).toBeNull();
  });
});

describe("Débuff sur une ligne/rangée (Phaeris #1750, Grokoko #531)", () => {
  it("#1750 Phaeris: APPARITION silences every creature on the picked row", () => {
    card(1750);
    const phaeris = mkCreature(700, "ally", { x: 6, y: 0 }, { cardId: 1750, triggers: card(1750).triggers ?? [] });
    const onRow = mkCreature(701, "enemy", { x: 3, y: 2 }, { cardId: 9999, resistance: 2, properties: new Set(["FirstStrike"]) });
    const offRow = mkCreature(702, "enemy", { x: 3, y: 1 }, { cardId: 9999, resistance: 2, properties: new Set(["FirstStrike"]) });
    const s1 = runTrigger(scenario([phaeris, onRow, offRow]), "APPARITION", 700);
    expect(s1.pendingAction).toBeTruthy();
    const s2 = resolvePendingAction(s1, { x: 4, y: 2 }); // pick a cell on row y=2
    expect(byId(s2, 701)!.resistance).toBe(0);                       // on-row → silenced
    expect(byId(s2, 701)!.properties.has("FirstStrike")).toBe(false);
    expect(byId(s2, 702)!.resistance).toBe(2);                       // off-row → untouched
    expect(byId(s2, 702)!.properties.has("FirstStrike")).toBe(true);
  });

  it("#531 Grokoko: APPARITION reduces AT by 1 on the picked column for creatures with >=2 AT", () => {
    card(531);
    const grokoko = mkCreature(700, "ally", { x: 6, y: 0 }, { cardId: 531, triggers: card(531).triggers ?? [] });
    const strong = mkCreature(701, "enemy", { x: 3, y: 1 }, { cardId: 9999, currentAttack: 4, baseAttack: 4 });
    const weak = mkCreature(702, "enemy", { x: 3, y: 2 }, { cardId: 9999, currentAttack: 1, baseAttack: 1 });
    const offCol = mkCreature(703, "enemy", { x: 5, y: 1 }, { cardId: 9999, currentAttack: 4, baseAttack: 4 });
    const s1 = runTrigger(scenario([grokoko, strong, weak, offCol]), "APPARITION", 700);
    expect(s1.pendingAction).toBeTruthy();
    const s2 = resolvePendingAction(s1, { x: 3, y: 0 }); // pick column x=3
    expect(byId(s2, 701)!.currentAttack).toBe(3); // 4 AT (>=2) → -1
    expect(byId(s2, 702)!.currentAttack).toBe(1); // 1 AT (<2) → untouched
    expect(byId(s2, 703)!.currentAttack).toBe(4); // off-column → untouched
  });
});

describe("Récup défausse adverse & tutor conditionnel (Fripon #73, Sufod #273)", () => {
  it("#73 Fripon: MORT recovers a random card from the OPPONENT's discard into your hand", () => {
    const sc = scenario([]);
    const fripon = mkCreature(700, "ally", { x: 6, y: 2 }, { cardId: 73, currentLife: 0, triggers: card(73).triggers ?? [] });
    const base = { ...sc, players: { ...sc.players,
      ally: { ...sc.players.ally, hand: [], handCostMods: [] },
      enemy: { ...sc.players.enemy, discard: [500] } } }; // single card → deterministic pick
    const res = resolveDeathsAndWin(base, [fripon], base.dofuses, [], new Set());
    expect(res.players.ally.hand).toContain(500);   // recovered into your hand
    expect(res.players.enemy.discard).toEqual([]);  // pulled from the enemy's discard
  });

  it("#273 Sufod: APPARITION tutors a Sram from your deck, only if your discard is not empty", () => {
    card(273);
    const sufod = mkCreature(700, "ally", { x: 6, y: 2 }, { cardId: 273, triggers: card(273).triggers ?? [] });
    const sc = scenario([sufod]);
    const withDiscard = { ...sc, players: { ...sc.players, ally: { ...sc.players.ally, hand: [], handCostMods: [], discard: [220], deck: [7, 144] } } };
    const s1 = runTrigger(withDiscard, "APPARITION", 700);
    expect(s1.players.ally.hand).toContain(144); // Sram tutored
    expect(s1.players.ally.deck).toEqual([7]);    // removed from the deck
    const noDiscard = { ...sc, players: { ...sc.players, ally: { ...sc.players.ally, hand: [], handCostMods: [], discard: [], deck: [7, 144] } } };
    const s2 = runTrigger(noDiscard, "APPARITION", 700);
    expect(s2.players.ally.hand).toEqual([]);          // no tutor (discard empty → condition fails)
    expect(s2.players.ally.deck).toEqual([7, 144]);
  });
});

