describe("Change l'AT des autres invocations (Moon #1747, Darkli Moon #602)", () => {
  it("#1747 Moon: APPARITION sets every other creature's AT to the source's AT (both camps, excludeSelf)", () => {
    card(1747);
    const moon = mkCreature(700, "ally", { x: 6, y: 2 }, { cardId: 1747, currentAttack: 4, baseAttack: 4, triggers: card(1747).triggers ?? [] });
    const ally = mkCreature(701, "ally", { x: 7, y: 1 }, { cardId: 9999, currentAttack: 1, baseAttack: 1 });
    const enemy = mkCreature(702, "enemy", { x: 3, y: 2 }, { cardId: 9999, currentAttack: 7, baseAttack: 7 });
    const s = runTrigger(scenario([moon, ally, enemy]), "APPARITION", 700);
    expect(s.creatures.find((c) => c.instanceId === 701)!.currentAttack).toBe(4); // ally → Moon's AT
    expect(s.creatures.find((c) => c.instanceId === 702)!.currentAttack).toBe(4); // enemy too (both camps)
    expect(s.creatures.find((c) => c.instanceId === 700)!.currentAttack).toBe(4); // Moon unchanged (excludeSelf)
  });

  it("#602 Darkli Moon: FIN_DE_TOUR sets every other creature's AT to its own life", () => {
    card(602);
    const darkli = mkCreature(700, "ally", { x: 6, y: 2 }, { cardId: 602, currentAttack: 2, baseAttack: 2, currentLife: 5, baseLife: 5, triggers: card(602).triggers ?? [] });
    const ally = mkCreature(701, "ally", { x: 7, y: 1 }, { cardId: 9999, currentAttack: 1, baseAttack: 1, currentLife: 3, baseLife: 5 });
    const enemy = mkCreature(702, "enemy", { x: 3, y: 2 }, { cardId: 9999, currentAttack: 9, baseAttack: 9, currentLife: 2, baseLife: 5 });
    const s = runTrigger(scenario([darkli, ally, enemy]), "FIN_DE_TOUR", 700);
    expect(s.creatures.find((c) => c.instanceId === 701)!.currentAttack).toBe(3); // AT = its own life (3)
    expect(s.creatures.find((c) => c.instanceId === 702)!.currentAttack).toBe(2); // AT = its own life (2)
    expect(s.creatures.find((c) => c.instanceId === 700)!.currentAttack).toBe(2); // Darkli unchanged (excludeSelf)
  });

  it("option A: a 'set ATK' establishes the base, a chief +1 ATK aura stacks on top, not absorbed", () => {
    // The Foul Moon #929 case: a creature carrying a chief +1 ATK aura (auraAttack 1 → currentAttack = base 5 + 1 = 6).
    // Setting its ATK to 3 must not absorb the chief: it sets the aura-FREE base to 3, and the +1 stacks → 4.
    // (Foul Moon sets the others to its own n; they then carry their own chief +1 → n+1.)
    const target = mkCreature(1, "ally", { x: 6, y: 2 }, { baseAttack: 5, currentAttack: 6, auraAttack: 1 });
    const creatures = [target];
    applyEffects(creatures, [], [], [{ type: "SetAttack", value: 3, scope: "all" }], { casterSide: "ally", targetCell: { x: 6, y: 2 } });
    expect(creatures[0].currentAttack).toBe(4); // base set to 3, chief +1 stacks → 4 (would be 3 if the aura were absorbed)
  });
});

