describe("Mot-clé FRATRIE (mill du deck adverse)", () => {
  it("FRATRIE: summoning a Fratrie creature mills all copies of a targeted enemy's card from the opponent's deck", () => {
    card(79); // Comte Harebourg, family Fratrie
    const enemyTarget = mkCreature(890, "enemy", { x: 3, y: 2 }, { cardId: 500 });
    const sc = scenario([enemyTarget]);
    const base = { ...sc, prisms: [], players: { ...sc.players,
      ally: { ...sc.players.ally, hand: [79], handCostMods: [0], ap: 20, maxAp: 20 },
      enemy: { ...sc.players.enemy, deck: [500, 500, 7, 500, 8], discard: [] } } }; // 3 copies of #500 in the enemy deck
    const s1 = playCard(base, card(79), { x: 8, y: 2 }); // FRATRIE pick opens, creature not placed yet
    expect(s1.pendingAction).toBeTruthy();
    expect(s1.creatures.some((c) => c.cardId === 79)).toBe(false); // it lands only after the pick
    const s2 = resolvePendingAction(s1, { x: 3, y: 2 }); // target the enemy creature (card 500)
    expect(s2.players.enemy.deck).toEqual([7, 8]);            // all copies of 500 removed from the deck
    expect(s2.players.enemy.discard).toEqual([500, 500, 500]); // and moved to the enemy discard
    expect(s2.creatures.some((c) => c.cardId === 79 && c.owner === "ally")).toBe(true); // Now the creature is placed
    expect(s2.creatures.find((c) => c.instanceId === 890)).toBeTruthy(); // the targeted board creature stays
  });

  it("FRATRIE: with no enemy creature on the board, the card is just played (no pick opens)", () => {
    card(79);
    const sc = scenario([]); // no creatures at all → nothing to target
    const base = { ...sc, prisms: [], players: { ...sc.players,
      ally: { ...sc.players.ally, hand: [79], handCostMods: [0], ap: 20, maxAp: 20 },
      enemy: { ...sc.players.enemy, deck: [500, 500, 7], discard: [] } } };
    const s = playCard(base, card(79), { x: 8, y: 2 });
    expect(s.pendingAction).toBeNull();                 // no FRATRIE pick, no enemy to target
    expect(s.creatures.some((c) => c.cardId === 79 && c.owner === "ally")).toBe(true); // Harebourg is simply in play
    expect(s.players.enemy.deck).toEqual([500, 500, 7]); // enemy deck untouched
  });

  it("FRATRIE: declining the pick (click off-target) mills nothing", () => {
    card(79);
    const enemyTarget = mkCreature(890, "enemy", { x: 3, y: 2 }, { cardId: 500 });
    const sc = scenario([enemyTarget]);
    const base = { ...sc, prisms: [], players: { ...sc.players,
      ally: { ...sc.players.ally, hand: [79], handCostMods: [0], ap: 20, maxAp: 20 },
      enemy: { ...sc.players.enemy, deck: [500, 500, 7], discard: [] } } };
    const s1 = playCard(base, card(79), { x: 8, y: 2 });
    const s2 = resolvePendingAction(s1, { x: 8, y: 4 }); // click an empty own cell → decline (optional)
    expect(s2.players.enemy.deck).toEqual([500, 500, 7]); // untouched
    expect(s2.pendingAction).toBeNull();
    expect(s2.creatures.some((c) => c.cardId === 79 && c.owner === "ally")).toBe(true); // creature still lands on decline
  });

  it("FRATRIE: clicking off the board cancels the play, card back to hand, AP refunded, nothing milled", () => {
    card(79);
    const enemyTarget = mkCreature(890, "enemy", { x: 3, y: 2 }, { cardId: 500 });
    const sc = scenario([enemyTarget]);
    const base = { ...sc, prisms: [], players: { ...sc.players,
      ally: { ...sc.players.ally, hand: [79], handCostMods: [0], ap: 20, maxAp: 20 },
      enemy: { ...sc.players.enemy, deck: [500, 500, 7], discard: [] } } };
    const s1 = playCard(base, card(79), { x: 8, y: 2 }); // FRATRIE pick opens, Harebourg held off-board
    expect(s1.pendingAction).toBeTruthy();
    const s2 = cancelPendingAction(s1); // click off the board → cancel the whole play
    expect(s2.pendingAction).toBeNull();
    expect(s2.players.ally.hand).toContain(79);          // card returned to hand
    expect(s2.players.ally.ap).toBe(20);                  // AP fully refunded
    expect(s2.creatures.some((c) => c.cardId === 79)).toBe(false); // never placed
    expect(s2.players.enemy.deck).toEqual([500, 500, 7]); // nothing milled
    expect(s2.players.enemy.discard).toEqual([]);
  });
});

describe("APPARITION : échange de PM (Chacha Sauvage #1276)", () => {
  it("#1276 Chacha Sauvage: swaps its movement (PM) with a picked creature", () => {
    card(1276);
    const target = mkCreature(890, "enemy", { x: 3, y: 2 }, { cardId: 9999, baseMovement: 4, movementLeft: 4 });
    const sc = scenario([target]);
    const base = { ...sc, prisms: [], players: { ...sc.players, ally: { ...sc.players.ally, hand: [1276], handCostMods: [0], ap: 20, maxAp: 20 } } };
    const s1 = playCard(base, card(1276), { x: 8, y: 2 }); // summon → pick (Chacha held off the board)
    expect(s1.pendingAction).toBeTruthy();
    const chachaBeforeMv = card(1276).movement ?? 0; // printed PM (sickness no longer zeroes it → full PM)
    const s2 = resolvePendingAction(s1, { x: 3, y: 2 });
    const chacha = s2.creatures.find((c) => c.cardId === 1276 && c.owner === "ally")!;
    const t = s2.creatures.find((c) => c.instanceId === 890)!;
    expect(chacha.baseMovement).toBe(4);                 // took the target's 4
    expect(chacha.movementLeft).toBe(4);                 // ... and its movementLeft
    expect(t.baseMovement).toBe(chachaBeforeMv);         // target got the Chacha's PM
    expect(t.movementLeft).toBe(chachaBeforeMv);         // and can use it: summoning sickness no longer passes a fake 0
  });

  it("#1276 Chacha Sauvage: swapping PM onto your own unit lets it advance", () => {
    // Reported: PM swap on one's own Poupée → it stayed stuck (it got Chacha's summoning sickness 0).
    // Now Chacha keeps its PM, so the target advances.
    card(1276);
    const doll = mkCreature(890, "ally", { x: 5, y: 2 }, { cardId: 9999, baseMovement: 3, movementLeft: 3, hasAttacked: false });
    const sc = scenario([doll]);
    const base = { ...sc, prisms: [], players: { ...sc.players, ally: { ...sc.players.ally, hand: [1276], handCostMods: [0], ap: 20, maxAp: 20 } } };
    const s1 = playCard(base, card(1276), { x: 8, y: 2 });
    const s2 = resolvePendingAction(s1, { x: 5, y: 2 }); // swap onto the doll
    const dollAfter = s2.creatures.find((c) => c.instanceId === 890)!;
    expect(dollAfter.movementLeft).toBe(card(1276).movement ?? 0); // got Chacha's PM (2), not a phantom 0
    // ... and it actually ADVANCES that many cells at end of turn (was stuck at (5,2) before the fix).
    const after = endTurn(withDecks(s2));
    const dollEnd = after.creatures.find((c) => c.instanceId === 890)!;
    expect(dollEnd.position.x).toBe(5 - (card(1276).movement ?? 0)); // ally advances toward x=0
  });
});

