describe("Rebond à bas PV (Arakne / Grougaloragran)", () => {
  it("bounces to hand when reduced to ≤ threshold PV (surviving), not above it", () => {
    card(161); // registers the pool (covers #420 too)
    const mk = (id: number, cardId: number, life: number) => {
      const cr = mkCreature(id, "ally", { x: 6, y: 2 }, { cardId, currentLife: life, baseLife: 5 });
      const sc = scenario([cr]);
      const base = { ...sc, players: { ...sc.players, ally: { ...sc.players.ally, hand: [], handCostMods: [] } }, log: [...sc.log, { type: "DAMAGE", targetInstanceId: id, damage: 3 } as GameEvent] };
      return { s: fireContreCoup(base, sc.log.length), cardId };
    };
    // Grougaloragran (#161, threshold 2) at 2 PV → bounces back to hand.
    const g = mk(820, 161, 2);
    expect(g.s.creatures.find((c) => c.instanceId === 820)).toBeUndefined();
    expect(g.s.players.ally.hand).toContain(161);
    // Grougaloragran at 3 PV → stays (above the threshold).
    const g2 = mk(821, 161, 3);
    expect(g2.s.creatures.find((c) => c.instanceId === 821)).toBeTruthy();
    expect(g2.s.players.ally.hand).not.toContain(161);
    // Arakne Spectrale (#420, threshold 1) at 1 PV → bounces.
    const a = mk(822, 420, 1);
    expect(a.s.creatures.find((c) => c.instanceId === 822)).toBeUndefined();
    expect(a.s.players.ally.hand).toContain(420);
  });
});

describe("Remonte en main à la mort (conditions)", () => {
  it("#488 Julith Jurgen: on death returns to hand if no Dofus destroyed, else to discard", () => {
    card(488);
    // All the ally's Dofus alive → recovers to hand.
    const julith = mkCreature(810, "ally", { x: 6, y: 2 }, { cardId: 488, currentLife: 0, baseLife: 4 });
    const b1 = scenario([julith]);
    const big = { ...b1, players: { ...b1.players, ally: { ...b1.players.ally, hand: [], handCostMods: [] } } };
    const s = resolveDeathsAndWin(big, [julith], big.dofuses, [], new Set());
    expect(s.players.ally.hand).toContain(488); // recovered to hand
    expect(s.players.ally.discard).not.toContain(488);
    // One ally Dofus already destroyed (removed) → condition fails → normal discard.
    const julith2 = mkCreature(811, "ally", { x: 6, y: 2 }, { cardId: 488, currentLife: 0, baseLife: 4 });
    const b2 = scenario([julith2]);
    const small = { ...b2, dofuses: b2.dofuses.filter((d) => !(d.owner === "ally" && d.position.y === 0)), players: { ...b2.players, ally: { ...b2.players.ally, hand: [], handCostMods: [] } } };
    const s2 = resolveDeathsAndWin(small, [julith2], small.dofuses, [], new Set());
    expect(s2.players.ally.discard).toContain(488);
    expect(s2.players.ally.hand).not.toContain(488);
  });
});

describe("NÉCROME (mot-clé)", () => {
  it("a Nécrome creature that dies is banished, not discarded", () => {
    card(641); // register the pool → getCard(641).families includes "Necrome"
    const necro = mkCreature(400, "ally", { x: 6, y: 2 }, { cardId: 641, currentLife: 0, baseLife: 3 }); // Soigneuse Corrompue
    const base = scenario([necro]);
    const res = resolveDeathsAndWin(base, [necro], base.dofuses, [], new Set());
    expect(res.players.ally.banished ?? []).toContain(641);
    expect(res.players.ally.discard).not.toContain(641);
  });

  it("a non-Nécrome creature that dies goes to the discard (regression)", () => {
    card(385);
    const vanilla = mkCreature(401, "ally", { x: 6, y: 2 }, { cardId: 385, currentLife: 0, baseLife: 3 });
    const base = scenario([vanilla]);
    const res = resolveDeathsAndWin(base, [vanilla], base.dofuses, [], new Set());
    expect(res.players.ally.discard).toContain(385);
    expect(res.players.ally.banished ?? []).not.toContain(385);
  });

  it("playing a Nécrome holds it off-board, then grants 1 base Orbe (#708) when it lands", () => {
    const sc = scenario([]); // #1217 Empaleur Embusqué = a plain NÉCROME (no APPARITION, no Phorzerker)
    const base = { ...sc, prisms: [], players: { ...sc.players, ally: { ...sc.players.ally, hand: [1217], handCostMods: [0], ap: 20, maxAp: 20 } } };
    const held = playCard(base, card(1217), { x: 8, y: 2 });
    expect(held.creatures.some((c) => c.cardId === 1217)).toBe(false);       // held off-board until the pick
    expect(held.players.ally.hand.filter((id) => id === 708).length).toBe(0); // no base Orbe yet
    const landed = resolvePendingAction(held, { x: 7, y: 2 });               // decline onto a board cell → land
    expect(landed.creatures.some((c) => c.cardId === 1217)).toBe(true);      // summoned at its cell
    expect(landed.players.ally.hand.filter((id) => id === 708).length).toBe(1); // +1 base Orbe at landing
  });

  it("playing a NON-Nécrome creature grants no Orbe (regression)", () => {
    const sc = scenario([]);
    const base = { ...sc, prisms: [], players: { ...sc.players, ally: { ...sc.players.ally, hand: [385], handCostMods: [0], ap: 20, maxAp: 20 } } };
    const s = playCard(base, card(385), { x: 8, y: 2 });
    expect(s.players.ally.hand.filter((id) => id === 708).length).toBe(0);
  });

  it("playing a Nécrome offers an optional reveal of an allied unrevealed Dofus → 2nd Orbe", () => {
    const sc = scenario([]); // default: 5 unrevealed Dofus per side
    const base = { ...sc, prisms: [], players: { ...sc.players, ally: { ...sc.players.ally, hand: [1217], handCostMods: [0], ap: 20, maxAp: 20 } } };
    const played = playCard(base, card(1217), { x: 8, y: 2 });
    expect(played.players.ally.hand.filter((id) => id === 708).length).toBe(0); // no Orbe yet (held off-board)
    expect(played.pendingAction?.filter).toBe("ally_unrevealed_dofus");
    expect(played.pendingAction?.optional).toBe(true);
    // The legal targets are the caster's unrevealed Dofus only (no enemy Dofus).
    const targets = validPendingTargets(played);
    expect(targets.length).toBeGreaterThan(0);
    expect(targets.every((t) => played.dofuses.some((d) => d.owner === "ally" && !d.revealed && d.position.x === t.x && d.position.y === t.y))).toBe(true);
    // Reveal one → lands the creature, flips the Dofus revealed, grants both the base + 2nd Orbe; pending clears.
    const cell = played.dofuses.find((d) => d.owner === "ally" && !d.revealed)!.position;
    const revealed = resolvePendingAction(played, cell);
    expect(revealed.dofuses.find((d) => d.position.x === cell.x && d.position.y === cell.y)!.revealed).toBe(true);
    expect(revealed.players.ally.hand.filter((id) => id === 708).length).toBe(2); // base Orbe (at landing) + 2nd (reveal)
    expect(revealed.pendingAction).toBeNull();
  });

  it("declining on the board lands the Nécrome (base Orbe), reveals nothing", () => {
    const sc = scenario([]);
    const base = { ...sc, prisms: [], players: { ...sc.players, ally: { ...sc.players.ally, hand: [1217], handCostMods: [0], ap: 20, maxAp: 20 } } };
    const played = playCard(base, card(1217), { x: 8, y: 2 });
    const declined = resolvePendingAction(played, { x: 7, y: 2 }); // a non-Dofus board cell → land without revealing
    expect(declined.pendingAction).toBeNull();
    expect(declined.creatures.some((c) => c.cardId === 1217)).toBe(true);          // landed
    expect(declined.players.ally.hand.filter((id) => id === 708).length).toBe(1);  // base Orbe only
    expect(declined.dofuses.some((d) => d.revealed)).toBe(false);
  });

  it("Orbe fusion: a 3rd Orbe granted to a hand fuses the trio into 1 Orbe Doré (#594)", () => {
    const sc = scenario([]); // #1217 = plain NÉCROME
    const base = { ...sc, prisms: [], players: { ...sc.players, ally: { ...sc.players.ally, hand: [1217, 708, 708], handCostMods: [0, 0, 0], ap: 20, maxAp: 20 } } };
    const held = playCard(base, card(1217), { x: 8, y: 2 });         // held off-board, opens the reveal pick (hand → [708,708])
    const landed = resolvePendingAction(held, { x: 7, y: 2 });       // decline onto a board cell → land + base Orbe → 3 Orbes → fuse
    const hand = landed.players.ally.hand;
    expect(hand.filter((id) => id === 708).length).toBe(0);          // the three Orbes were consumed
    expect(hand.filter((id) => id === 594).length).toBe(1);          // fused into a single Orbe Doré
  });

  it("Orbe fusion is STEPWISE: a full hand fuses the base Orbe before the reveal Orbe lands, so nothing is burned", () => {
    card(385); // vanilla filler creature
    const sc = scenario([]); // 5 unrevealed ally Dofus by default
    const hand = [1217, 708, 708, 385, 385, 385, 385, 385, 385, 385]; // 10 cards = MAX_HAND (NÉCROME + 2 Orbes + 7 fillers)
    const base = { ...sc, prisms: [], players: { ...sc.players, ally: { ...sc.players.ally, hand, handCostMods: hand.map(() => 0), ap: 20, maxAp: 20 } } };
    const held = playCard(base, card(1217), { x: 8, y: 2 });         // 1217 leaves → hand 9 ([708,708,385×7]); reveal pick opens
    const cell = held.dofuses.find((d) => d.owner === "ally" && !d.revealed)!.position;
    const s = resolvePendingAction(held, cell);                      // reveal → base Orbe (→3, fuses to golden, frees 2 slots) → reveal Orbe lands
    const h = s.players.ally.hand;
    expect(h.filter((id) => id === 594).length).toBe(1);             // base trio fused into 1 Orbe Doré
    expect(h.filter((id) => id === 708).length).toBe(1);             // the reveal Orbe landed (not burned by a full hand)
    expect(h.filter((id) => id === 385).length).toBe(7);             // fillers untouched
    expect((s.players.ally.tokenDiscard ?? []).filter((id) => id === 708).length).toBe(0); // nothing burned to the token discard
  });

  it("clicking off the board cancels the play: card back to hand, no Orbe, AP refunded", () => {
    const sc = scenario([]);
    const base = { ...sc, prisms: [], players: { ...sc.players, ally: { ...sc.players.ally, hand: [1217], handCostMods: [0], ap: 20, maxAp: 20 } } };
    const played = playCard(base, card(1217), { x: 8, y: 2 });
    const cancelled = cancelPendingAction(played);
    expect(cancelled.pendingAction).toBeNull();
    expect(cancelled.creatures.some((c) => c.cardId === 1217)).toBe(false);         // not placed
    expect(cancelled.players.ally.hand).toContain(1217);                            // card back in hand
    expect(cancelled.players.ally.hand.filter((id) => id === 708).length).toBe(0);  // no base Orbe
    expect(cancelled.players.ally.ap).toBe(20);                                     // AP refunded
    expect(cancelled.dofuses.some((d) => d.revealed)).toBe(false);
  });

  it("#665 Maître Egreneur: APPARITION adds 5 PA to the reserve only while outnumbered", () => {
    card(665);
    // Outnumbered: 1 ally (the Egreneur) vs 2 enemies → condition met.
    const eg = mkCreature(500, "ally", { x: 6, y: 2 }, { cardId: 665, triggers: card(665).triggers ?? [] });
    const e1 = mkCreature(501, "enemy", { x: 4, y: 2 }, {});
    const e2 = mkCreature(502, "enemy", { x: 4, y: 1 }, {});
    expect(runTrigger(scenario([eg, e1, e2]), "APPARITION", 500).players.ally.apReserve).toBe(5);
    // Not outnumbered: 2 allies vs 1 enemy → condition unmet, no gain.
    const eg2 = mkCreature(503, "ally", { x: 6, y: 2 }, { cardId: 665, triggers: card(665).triggers ?? [] });
    const a2 = mkCreature(504, "ally", { x: 6, y: 1 }, {});
    const e3 = mkCreature(505, "enemy", { x: 4, y: 2 }, {});
    expect(runTrigger(scenario([eg2, a2, e3]), "APPARITION", 503).players.ally.apReserve).toBe(0);
  });

  it("#634 Championne Périmée: APPARITION sets every enemy creature's PM to 2", () => {
    card(634);
    const per = mkCreature(510, "ally", { x: 6, y: 2 }, { cardId: 634, triggers: card(634).triggers ?? [] });
    const fast = mkCreature(511, "enemy", { x: 4, y: 2 }, { baseMovement: 5, movementLeft: 5 });
    const ally = mkCreature(512, "ally", { x: 6, y: 1 }, { baseMovement: 4, movementLeft: 4 });
    const s = runTrigger(scenario([per, fast, ally]), "APPARITION", 510);
    expect(byId(s, 511)!.baseMovement).toBe(2); // enemy → set to 2
    expect(byId(s, 511)!.movementLeft).toBe(2);
    expect(byId(s, 512)!.baseMovement).toBe(4); // ally unaffected
  });

  it("#1163 Disciple de l'Agonie: FIN DU TOUR deals 1 to every enemy then 1 to itself", () => {
    card(1163);
    const disc = mkCreature(520, "ally", { x: 6, y: 2 }, { cardId: 1163, currentLife: 3, baseLife: 3, triggers: card(1163).triggers ?? [] });
    const e1 = mkCreature(521, "enemy", { x: 4, y: 2 }, { currentLife: 5, baseLife: 5, armor: 0 });
    const e2 = mkCreature(522, "enemy", { x: 3, y: 1 }, { currentLife: 5, baseLife: 5, armor: 0 });
    const ally = mkCreature(523, "ally", { x: 6, y: 1 }, { currentLife: 5, baseLife: 5, armor: 0 });
    const s = runTrigger(scenario([disc, e1, e2, ally]), "FIN_DE_TOUR", 520);
    expect(byId(s, 521)!.currentLife).toBe(4); // enemy −1
    expect(byId(s, 522)!.currentLife).toBe(4); // enemy −1
    expect(byId(s, 523)!.currentLife).toBe(5); // ally unaffected
    expect(byId(s, 520)!.currentLife).toBe(2); // self −1
  });

  it("#1174 Brute Impie: COUP DE GRÂCE tutors the first Championne du Blasphème (#1451) from deck", () => {
    card(1174);
    const brute = mkCreature(530, "ally", { x: 6, y: 2 }, { cardId: 1174, triggers: card(1174).triggers ?? [] });
    const base = scenario([brute]);
    const s0 = { ...base, players: { ...base.players, ally: { ...base.players.ally, deck: [385, 1451, 385], hand: [], handCostMods: [] } } };
    const s = runTrigger(s0, "COUP_DE_GRACE", 530);
    expect(s.players.ally.hand).toContain(1451); // tutored to hand
    expect(s.players.ally.deck.filter((id) => id === 1451).length).toBe(0); // removed from deck
    expect(s.players.ally.deck.filter((id) => id === 385).length).toBe(2); // other cards untouched
  });

  it("#1687 Horlogère Gousset: MORT destroys one Fléau (#757) in the opponent's hand → their token discard", () => {
    card(1687); // MORT fires via the real death path (resolveDeathsAndWin), once.
    const horl = mkCreature(540, "ally", { x: 6, y: 2 }, { cardId: 1687, currentLife: 0, baseLife: 3, triggers: card(1687).triggers ?? [] });
    const base = scenario([horl]);
    const s0 = { ...base, players: { ...base.players, enemy: { ...base.players.enemy, hand: [757, 385, 757], handCostMods: [0, 0, 0], discard: [] } } };
    const s = resolveDeathsAndWin(s0, [horl], s0.dofuses, [], new Set());
    expect(s.players.enemy.hand.filter((id) => id === 757).length).toBe(1); // one Fléau destroyed
    // The Fléau is a token: it lands in the tokenDiscard that cannot be reached, never the pile that can
    // be recovered from.
    expect(s.players.enemy.tokenDiscard).toContain(757);
    expect(s.players.enemy.discard).not.toContain(757);
    expect(s.players.enemy.hand.filter((id) => id === 385).length).toBe(1); // filler untouched
  });

  it("#1687: MORT is a no-op when the opponent holds no Fléau", () => {
    card(1687);
    const horl = mkCreature(541, "ally", { x: 6, y: 2 }, { cardId: 1687, currentLife: 0, baseLife: 3, triggers: card(1687).triggers ?? [] });
    const base = scenario([horl]);
    const s0 = { ...base, players: { ...base.players, enemy: { ...base.players.enemy, hand: [385, 385], handCostMods: [0, 0], discard: [] } } };
    const s = resolveDeathsAndWin(s0, [horl], s0.dofuses, [], new Set());
    expect(s.players.enemy.hand.length).toBe(2);
    expect(s.players.enemy.discard.length).toBe(0);
  });

  it("#688 Apôtre Nécrosé: APPARITION deals 2 to enemies in your camp only", () => {
    card(688); // ally camp = cols 5-8
    const apotre = mkCreature(550, "ally", { x: 6, y: 2 }, { cardId: 688, triggers: card(688).triggers ?? [] });
    const enemyMyCamp = mkCreature(551, "enemy", { x: 6, y: 0 }, { currentLife: 5, baseLife: 5, armor: 0 }); // x=6 → ally camp
    const enemyTheirCamp = mkCreature(552, "enemy", { x: 3, y: 2 }, { currentLife: 5, baseLife: 5, armor: 0 }); // x=3 → enemy camp
    const allyMyCamp = mkCreature(553, "ally", { x: 7, y: 1 }, { currentLife: 5, baseLife: 5, armor: 0 });
    const s = runTrigger(scenario([apotre, enemyMyCamp, enemyTheirCamp, allyMyCamp]), "APPARITION", 550);
    expect(byId(s, 551)!.currentLife).toBe(3); // enemy in my camp → −2
    expect(byId(s, 552)!.currentLife).toBe(5); // enemy in their camp → untouched
    expect(byId(s, 553)!.currentLife).toBe(5); // ally → untouched (scope enemies)
  });

  it("#628 Griffeur Tonkino: DÉBUT DU TOUR self-damages on a coin flip (forced Pile = 1, else 1 or 2)", () => {
    card(628);
    const griff = mkCreature(560, "ally", { x: 6, y: 2 }, { cardId: 628, currentLife: 5, baseLife: 5, triggers: card(628).triggers ?? [] });
    const base = scenario([griff]);
    // Forced Pile (Trucage) → the first branch = 1 self-damage.
    const forced = { ...base, players: { ...base.players, ally: { ...base.players.ally, coinForcedPile: true } } };
    expect(byId(runTrigger(forced, "DEBUT_DE_TOUR", 560), 560)!.currentLife).toBe(4); // 5 − 1
    // Unforced → a genuine flip: either branch hurts (1 or 2).
    expect([3, 4]).toContain(byId(runTrigger(base, "DEBUT_DE_TOUR", 560), 560)!.currentLife);
  });
});

describe("Moskito (APPARITION : échange de position, AT ≤ N)", () => {
  it("#428 swaps Moskito's cell with a picked ally having ≤3 AT", () => {
    const low = mkCreature(80, "ally", { x: 6, y: 2 }, { currentAttack: 2, baseAttack: 2 });
    const high = mkCreature(81, "ally", { x: 6, y: 3 }, { currentAttack: 5, baseAttack: 5 });
    let s = scenario([low, high], 428);
    s = { ...s, prisms: [] };
    s = playCard(s, card(428), { x: 8, y: 0 }); // summon Moskito → APPARITION swap
    expect(s.pendingAction).not.toBeNull();
    expect(s.pendingAction!.filter).toBe("ally_creature");
    expect(s.pendingAction!.maxAttack).toBe(3);
    // Only the ≤3 AT ally is a legal target, not the 5-AT ally, not Moskito itself.
    const dests = validPendingTargets(s);
    expect(dests).toContainEqual({ x: 6, y: 2 });
    expect(dests).not.toContainEqual({ x: 6, y: 3 });
    expect(dests).not.toContainEqual({ x: 8, y: 0 }); // Moskito's (empty) summon cell is not a target
    // Resolve: Moskito lands on its summon cell then trades cells with the low-AT ally.
    s = resolvePendingAction(s, { x: 6, y: 2 });
    expect(s.creatures.find((c) => c.cardId === 428)!.position).toEqual({ x: 6, y: 2 });
    expect(byId(s, 80)!.position).toEqual({ x: 8, y: 0 });
    expect(s.pendingAction).toBeNull();
  });

  it("#428 with no eligible ally (only a >3 AT ally, and itself) does not prompt", () => {
    const high = mkCreature(82, "ally", { x: 6, y: 3 }, { currentAttack: 5, baseAttack: 5 });
    let s = scenario([high], 428);
    s = { ...s, prisms: [] };
    s = playCard(s, card(428), { x: 8, y: 0 });
    expect(s.pendingAction).toBeNull(); // source excluded + no other legal target
  });

  it("#428 clicking the >3 AT ally is rejected (optional decline, no swap)", () => {
    const low = mkCreature(83, "ally", { x: 6, y: 2 }, { currentAttack: 2, baseAttack: 2 });
    const high = mkCreature(84, "ally", { x: 6, y: 3 }, { currentAttack: 5, baseAttack: 5 });
    let s = scenario([low, high], 428);
    s = { ...s, prisms: [] };
    s = playCard(s, card(428), { x: 8, y: 0 }); // Moskito held off the board until the pick
    const moskitoPos = { x: 8, y: 0 }; // its summon cell
    s = resolvePendingAction(s, { x: 6, y: 3 }); // 5 AT → illegal → declines → Moskito lands, no swap
    expect(s.pendingAction).toBeNull();
    expect(s.creatures.find((c) => c.cardId === 428)!.position).toEqual(moskitoPos);
    expect(byId(s, 84)!.position).toEqual({ x: 6, y: 3 });
  });
});

describe("Seeded RNG (reproducible matches, AI foundation)", () => {
  const deckA = Array.from({ length: 30 }, (_, i) => 100 + i);
  const deckB = Array.from({ length: 30 }, (_, i) => 500 + i);

  it("same seed → identical shuffle, Dofus layout, opening hands, and rng state", () => {
    const a = createInitialState({ ally: [...deckA], enemy: [...deckB] }, { seed: 42 });
    const b = createInitialState({ ally: [...deckA], enemy: [...deckB] }, { seed: 42 });
    expect(a.players.ally.deck).toEqual(b.players.ally.deck);
    expect(a.players.enemy.deck).toEqual(b.players.enemy.deck);
    expect(a.players.ally.hand).toEqual(b.players.ally.hand);
    expect(a.dofuses.map((d) => d.kind)).toEqual(b.dofuses.map((d) => d.kind));
    expect(a.rng).toBe(b.rng);
  });

  it("different seeds → different deck order", () => {
    const a = createInitialState({ ally: [...deckA], enemy: [...deckB] }, { seed: 1 });
    const b = createInitialState({ ally: [...deckA], enemy: [...deckB] }, { seed: 2 });
    expect(a.players.ally.deck).not.toEqual(b.players.ally.deck);
  });

  it("shuffle:false keeps the given deck order (deterministic tests)", () => {
    const s = createInitialState({ ally: [...deckA], enemy: [...deckB] }, { seed: 5, shuffle: false });
    // Opening hand drew the last MULLIGAN_HAND ids; the deck keeps the rest in order.
    expect(s.players.ally.deck).toEqual(deckA.slice(0, deckA.length - 3));
  });

  it("the whole game stays reproducible: same seed + same mulligan choices → identical state", () => {
    const play = () => {
      let s = createInitialState({ ally: [...deckA], enemy: [...deckB] }, { seed: 99 });
      s = applyMulligan(s, s.mulligan!.current, [0, 2]); // player 1 returns 2
      s = applyMulligan(s, s.mulligan!.current, [1]);    // player 2 returns 1 → match starts
      return s;
    };
    expect(play()).toEqual(play());
  });
});

describe("Prism respawn, occupied cells block the prism", () => {
  it("a prism does not reappear on a cell occupied by a creature", () => {
    // Ally prism home cells are column x=8. Put a creature on (8,2).
    const onPrism = mkCreature(1, "ally", { x: 8, y: 2 });
    let s = scenario([onPrism]);
    s = { ...s, prisms: [] };
    s = startTurn(s, "ally");
    // The occupied (8,2) prism stays absent; the free ones reappear.
    expect(s.prisms.some((p) => p.position.x === 8 && p.position.y === 2)).toBe(false);
    expect(s.prisms.some((p) => p.position.x === 8 && p.position.y === 0)).toBe(true);
    expect(s.prisms.length).toBe(9); // 10 minus the blocked one
  });

  it("with every prism cell free, the full set of 10 reappears", () => {
    let s = scenario([]);
    s = { ...s, prisms: [] };
    s = startTurn(s, "ally");
    expect(s.prisms.length).toBe(10);
  });

  it("a prism does not reappear on a cell occupied by a ground object (butin), Erik Rak case", () => {
    // The reset fires whenever the board has no prisms (a state check, not a flag), and a prism cannot
    // come back on a cell holding a ground object. Erik Rak (#720) turns a prism into a Butin on that
    // same home cell, so once the board is empty the other prisms must come back, but not on top of the
    // Butin.
    let s = scenario([]);
    s = { ...s, prisms: [], butins: [{ position: { x: 8, y: 2 }, owner: "ally" }] };
    s = startTurn(s, "ally");
    expect(s.prisms.some((p) => p.position.x === 8 && p.position.y === 2)).toBe(false); // butin blocks the home cell
    expect(s.prisms.some((p) => p.position.x === 8 && p.position.y === 0)).toBe(true);  // a free home cell still respawns
    expect(s.prisms.length).toBe(9);
  });
});

describe("BoostMovement (+PM) takes effect this turn", () => {
  it("Glaie's +1 PM lets a non-sick ally advance one extra cell the same turn", () => {
    const target = mkCreature(50, "ally", { x: 6, y: 2 }, { movementLeft: 3, baseMovement: 3, hasAttacked: false });
    let s = scenario([target], 126); // Glaie (APPARITION: BoostMovement +1) in hand
    s = playCard(s, card(126), { x: 8, y: 0 }); // summon Glaie on an ally spawn cell
    if (s.pendingAction) s = resolvePendingAction(s, { x: 6, y: 2 }); // target our creature
    const c = byId(s, 50)!;
    expect(c.baseMovement).toBe(4);
    expect(c.movementLeft).toBe(4); // the +1 is usable now, not only next turn
  });

  it("does not grant the bonus this turn to a summoning-sick creature (movementLeft 0)", () => {
    const sick = mkCreature(51, "ally", { x: 6, y: 2 }, { movementLeft: 0, baseMovement: 3, hasAttacked: true });
    let s = scenario([sick], 126);
    s = playCard(s, card(126), { x: 8, y: 0 });
    if (s.pendingAction) s = resolvePendingAction(s, { x: 6, y: 2 });
    const c = byId(s, 51)!;
    expect(c.baseMovement).toBe(4);
    expect(c.movementLeft).toBe(0); // bonus correctly waits for next turn
  });
});

describe("Marcassinet (#263): +1 PM while you have a Glaie in play", () => {
  const movOf = (cs: ReturnType<typeof withAuras>, id: number) =>
    cs.find((c) => c.instanceId === id)!.baseMovement;

  it("gains +1 PM only while an allied Glaie is in play", () => {
    card(263); // register the pool + Marcassinet's ConditionalStatBoost (cardId 126)
    const marc = mkCreature(1, "ally", { x: 6, y: 2 }, { baseMovement: 3 });
    marc.cardId = 263;
    expect(movOf(withAuras([marc]), 1)).toBe(3); // no Glaie → printed 3 PM
    const glaie = mkCreature(2, "ally", { x: 6, y: 1 });
    glaie.cardId = 126;
    expect(movOf(withAuras([marc, glaie]), 1)).toBe(4); // allied Glaie in play → +1 PM
    glaie.currentLife = 0;
    expect(movOf(withAuras([marc, glaie]), 1)).toBe(3); // Glaie dead → bonus revoked
  });

  it("an enemy Glaie does not grant the bonus (your own only)", () => {
    card(263);
    const marc = mkCreature(3, "ally", { x: 6, y: 2 }, { baseMovement: 3 });
    marc.cardId = 263;
    const enemyGlaie = mkCreature(4, "enemy", { x: 4, y: 1 });
    enemyGlaie.cardId = 126;
    expect(movOf(withAuras([marc, enemyGlaie]), 3)).toBe(3);
  });
});

describe("Advance: kill-and-continue still hits the wall Dofus (percée)", () => {
  it("a creature that kills an enemy en route then runs out of movement next to the Dofus still hits it", () => {
    // Attacker (ally) at (4,2), 3 PM, 4 ATK. Enemy blocker at (1,2) it can kill.
    // It advances 4→3→2, kills the blocker at (1,2), steps in, runs out of PM
    // adjacent to the enemy Dofus (0,2), and must still strike it.
    const attacker = mkCreature(1, "ally", { x: 4, y: 2 }, { movementLeft: 3, baseMovement: 3, currentAttack: 4, currentLife: 5, baseLife: 5, hasAttacked: false });
    const blocker = mkCreature(2, "enemy", { x: 1, y: 2 }, { currentLife: 1, currentAttack: 1, hasAttacked: false });
    let s = scenario([attacker, blocker]);
    const before = s.dofuses.find((d) => d.position.x === 0 && d.position.y === 2)!.currentLife;
    s = endTurn(withDecks(s));
    expect(byId(s, 2)).toBeUndefined();                 // blocker killed en route
    const after = s.dofuses.find((d) => d.position.x === 0 && d.position.y === 2)?.currentLife ?? -1;
    expect(after).toBe(before - 4);                     // Dofus took the end-of-advance hit
  });

  it("a creature that stops on a surviving enemy does not double-hit it at the end", () => {
    // Attacker hits a tanky enemy that survives → it must not strike again.
    const attacker = mkCreature(1, "ally", { x: 2, y: 2 }, { movementLeft: 3, baseMovement: 3, currentAttack: 2, currentLife: 5, baseLife: 5, hasAttacked: false });
    const tank = mkCreature(2, "enemy", { x: 1, y: 2 }, { currentLife: 9, baseLife: 9, currentAttack: 0, hasAttacked: false });
    let s = scenario([attacker, tank]);
    s = endTurn(s);
    expect(byId(s, 2)!.currentLife).toBe(7);            // hit exactly once (9 - 2), not twice
  });
});

describe("Charge de masse (ChargeAllies)", () => {
  it("#338 Intimidation: toutes vos invocations chargent de 2 cases", () => {
    card(338); // register pool + the injected ChargeAllies effect
    const a = mkCreature(1, "ally", { x: 6, y: 1 }, { hasAttacked: false, baseMovement: 3, movementLeft: 0, currentLife: 5, baseLife: 5 });
    const b = mkCreature(2, "ally", { x: 6, y: 3 }, { hasAttacked: false, baseMovement: 3, movementLeft: 0, currentLife: 5, baseLife: 5 });
    const enemy = mkCreature(3, "enemy", { x: 2, y: 1 }, { currentLife: 5, baseLife: 5 });
    let s = scenario([a, b, enemy], 338);
    s = playCard(s, card(338), { x: 4, y: 4 }); // AlliedGod spell → empty cell is a valid cast
    expect(byId(s, 1)!.position.x).toBe(4); // ally charged 2 cells toward the enemy wall (6→4)
    expect(byId(s, 2)!.position.x).toBe(4);
    expect(byId(s, 3)!.position.x).toBe(2); // enemy untouched (only your creatures charge)
  });

  // Reported (Sacrieur against Eniripsa, turn 17): La Gerbouille #547 = "+2 AT à vos invocations
  // blessées PUIS elles chargent de 2". A wounded creature stacked behind another in its row got the
  // +2 AT but did not advance, because the charge handled it before the front ally freed the cell.
  // chargeAllies now charges front first (like the end-of-turn sweep), so the back creature advances
  // after the front one moves.
  it("#547 La Gerbouille: a wounded creature behind another still charges (front-first order)", () => {
    card(547);
    // The BACK creature (x=6) is listed first → an unsorted charge would move it before the front cleared,
    // leaving it stuck at x=6 with only the +2 AT. Front-first order lets it advance to x=4.
    const back = mkCreature(1, "ally", { x: 6, y: 2 }, { currentLife: 2, baseLife: 3, currentAttack: 1, baseAttack: 1, hasAttacked: false, movementLeft: 0, baseMovement: 3 });
    const front = mkCreature(2, "ally", { x: 5, y: 2 }, { currentLife: 2, baseLife: 3, currentAttack: 1, baseAttack: 1, hasAttacked: false, movementLeft: 0, baseMovement: 3 });
    let s = scenario([back, front], 547);
    s = { ...s, players: { ...s.players, ally: { ...s.players.ally, ap: 10 } } };
    s = playCard(s, card(547), { x: 4, y: 4 }); // non-targeted ally spell → cast on an empty cell
    expect(byId(s, 2)!.currentAttack).toBe(3); expect(byId(s, 2)!.position.x).toBe(3); // front wounded: +2 AT, 5 → 3
    expect(byId(s, 1)!.currentAttack).toBe(3); expect(byId(s, 1)!.position.x).toBe(4); // back wounded: +2 AT and 6 → 4 (not stuck)
  });
});

describe("'Vos autres X gagnent +N AT/AR' (family/ally flat stat buff on a trigger)", () => {
  it("#1354 Chacha Serval: FIN DU TOUR gives +1 AT/+1 AR to other allied Chachas only", () => {
    const serval = mkCreature(60, "ally", { x: 5, y: 1 }, { cardId: 1354, triggers: card(1354).triggers, armor: 0 });
    const allyChacha = mkCreature(61, "ally", { x: 5, y: 2 }, { cardId: 135, currentAttack: 2, baseAttack: 2, armor: 0 }); // Chacha Noir
    const allyOther = mkCreature(62, "ally", { x: 5, y: 3 }, { cardId: 9999, currentAttack: 2, baseAttack: 2, armor: 0 }); // not a Chacha
    const enemyChacha = mkCreature(63, "enemy", { x: 3, y: 2 }, { cardId: 135, currentAttack: 2, baseAttack: 2, armor: 0 });
    const s = runTrigger(scenario([serval, allyChacha, allyOther, enemyChacha]), "FIN_DE_TOUR", 60);
    expect(byId(s, 61)!.currentAttack).toBe(3); // other allied Chacha: 2 + 1
    expect(byId(s, 61)!.armor).toBe(1);
    expect(byId(s, 60)!.armor).toBe(0);         // source itself excluded ("autres")
    expect(byId(s, 62)!.currentAttack).toBe(2); // non-Chacha ally untouched (family filter)
    expect(byId(s, 62)!.armor).toBe(0);
    expect(byId(s, 63)!.armor).toBe(0);         // enemy Chacha untouched (scope allies)
  });

  it("#864 Scarafeuille Céleste: FIN DU TOUR gives +1 AR to every other allied invocation", () => {
    const scaf = mkCreature(70, "ally", { x: 5, y: 1 }, { cardId: 864, triggers: card(864).triggers, armor: 0 });
    const ally1 = mkCreature(71, "ally", { x: 5, y: 2 }, { cardId: 9999, armor: 0 });
    const ally2 = mkCreature(72, "ally", { x: 5, y: 3 }, { cardId: 135, armor: 1 });
    const enemy = mkCreature(73, "enemy", { x: 3, y: 2 }, { cardId: 9999, armor: 0 });
    const s = runTrigger(scenario([scaf, ally1, ally2, enemy]), "FIN_DE_TOUR", 70);
    expect(byId(s, 71)!.armor).toBe(1); // 0 + 1 (no family filter → any ally)
    expect(byId(s, 72)!.armor).toBe(2); // 1 + 1
    expect(byId(s, 70)!.armor).toBe(0); // source excluded
    expect(byId(s, 73)!.armor).toBe(0); // enemy excluded
  });

  it("#326 Scarador: APPARITION gives +3 AR to other allied Scaras only (the 'gagnent' phrasing, was unparsed)", () => {
    const scarador = mkCreature(80, "ally", { x: 5, y: 1 }, { cardId: 326, triggers: card(326).triggers, armor: 0 });
    const allyScara = mkCreature(81, "ally", { x: 5, y: 2 }, { cardId: 533, armor: 0 }); // Scarafon
    const allyOther = mkCreature(82, "ally", { x: 5, y: 3 }, { cardId: 9999, armor: 0 });
    const s = runTrigger(scenario([scarador, allyScara, allyOther]), "APPARITION", 80);
    expect(byId(s, 81)!.armor).toBe(3); // other allied Scara: +3
    expect(byId(s, 80)!.armor).toBe(0); // source excluded
    expect(byId(s, 82)!.armor).toBe(0); // non-Scara ally untouched
  });
});

describe("'Vos autres X chargent [de N cases]' (charge to other allies on a trigger)", () => {
  it("#196 Gligli Ancestral: DÉBUT DU TOUR charges every other ally exactly 2 cells (not itself, not enemies)", () => {
    const gligli = mkCreature(90, "ally", { x: 7, y: 0 }, { cardId: 196, triggers: card(196).triggers });
    const ally1 = mkCreature(91, "ally", { x: 6, y: 1 }, { cardId: 9999, baseMovement: 3, movementLeft: 3, hasAttacked: false });
    const ally2 = mkCreature(92, "ally", { x: 6, y: 2 }, { cardId: 135, baseMovement: 3, movementLeft: 3, hasAttacked: false });
    const enemy = mkCreature(93, "enemy", { x: 3, y: 3 }, { baseMovement: 3, movementLeft: 3 });
    const s = runTrigger({ ...scenario([gligli, ally1, ally2, enemy]), prisms: [] }, "DEBUT_DE_TOUR", 90);
    expect(byId(s, 91)!.position.x).toBe(4); // 6 → 4 (charged 2 toward the enemy wall)
    expect(byId(s, 92)!.position.x).toBe(4);
    expect(byId(s, 90)!.position.x).toBe(7); // source excluded ("autres")
    expect(byId(s, 93)!.position.x).toBe(3); // enemy untouched (scope allies)
  });

  it("#203 Gelée Citron: APPARITION makes other allied Jellies FULL-charge (whole PM, non-additive); non-Jellies untouched", () => {
    const citron = mkCreature(100, "ally", { x: 7, y: 0 }, { cardId: 203, triggers: card(203).triggers });
    const jelly = mkCreature(101, "ally", { x: 6, y: 1 }, { cardId: 69, baseMovement: 3, movementLeft: 3, hasAttacked: false }); // Gelée Encre = Jelly
    const notJelly = mkCreature(102, "ally", { x: 6, y: 2 }, { cardId: 9999, baseMovement: 3, movementLeft: 3, hasAttacked: false });
    const s = runTrigger({ ...scenario([citron, jelly, notJelly]), prisms: [] }, "APPARITION", 100);
    expect(byId(s, 101)!.position.x).toBe(3);   // 6 → 3 (full PM = 3)
    expect(byId(s, 101)!.movementLeft).toBe(0); // non-additive: PM spent, will not re-advance at end of turn
    expect(byId(s, 102)!.position.x).toBe(6);   // non-Jelly untouched (family filter)
    expect(byId(s, 100)!.position.x).toBe(7);   // source excluded
  });

  it("#390 Gligli Royal: APPARITION charges other allied Gliglis 2 cells (family + cells combo)", () => {
    const royal = mkCreature(110, "ally", { x: 7, y: 0 }, { cardId: 390, triggers: card(390).triggers });
    const gligli = mkCreature(111, "ally", { x: 6, y: 1 }, { cardId: 181, baseMovement: 3, movementLeft: 3, hasAttacked: false }); // Gligli
    const other = mkCreature(112, "ally", { x: 6, y: 2 }, { cardId: 9999, baseMovement: 3, movementLeft: 3, hasAttacked: false });
    const s = runTrigger({ ...scenario([royal, gligli, other]), prisms: [] }, "APPARITION", 110);
    expect(byId(s, 111)!.position.x).toBe(4); // Gligli charged 2
    expect(byId(s, 112)!.position.x).toBe(6); // non-Gligli untouched (family filter)
  });
});

