describe("ON_DRAW reaction ('gagne +N quand vous piochez une carte')", () => {
  it("#951 Phorreur Furieux: gains +1 AT when its owner draws a card", () => {
    const phorreur = mkCreature(790, "ally", { x: 6, y: 2 }, { cardId: 951, currentAttack: 2, baseAttack: 2, triggers: card(951).triggers ?? [] });
    const sc = scenario([phorreur]);
    const base = { ...sc, players: { ...sc.players, ally: { ...sc.players.ally, deck: [1, 2, 3] } } };
    const s = drawCard(base, "ally");
    expect(byId(s, 790)!.currentAttack).toBe(3); // +1 AT on its owner's draw
  });

  it("#951 Phorreur Furieux: does not react when the opponent draws", () => {
    const phorreur = mkCreature(790, "ally", { x: 6, y: 2 }, { cardId: 951, currentAttack: 2, baseAttack: 2, triggers: card(951).triggers ?? [] });
    const sc = scenario([phorreur]);
    const base = { ...sc, players: { ...sc.players, enemy: { ...sc.players.enemy, deck: [10, 11] } } };
    const s = drawCard(base, "enemy"); // the enemy draws, not "vous"
    expect(byId(s, 790)!.currentAttack).toBe(2); // unchanged
  });

  it("#951: a draw from an empty deck (fatigue) fires no ON_DRAW reactor", () => {
    // No card left the deck, so there is no reaction, but the fatigue still applies. The test
    // is on the deck, not the hand: a card burned because the hand is full was really drawn, so
    // it counts (covered below).
    const phorreur = mkCreature(790, "ally", { x: 6, y: 2 }, { cardId: 951, currentAttack: 2, baseAttack: 2, triggers: card(951).triggers ?? [] });
    const sc = scenario([phorreur]);
    const base = { ...sc, players: { ...sc.players, ally: { ...sc.players.ally, deck: [] } } };
    const s = drawCard(base, "ally");
    expect(byId(s, 790)!.currentAttack).toBe(2);                              // no +1 AT
    expect(s.log.some((e) => e.type === "NO_MORE_CARD_TO_DRAW")).toBe(true);  // but the fatigue applies
    expect(s.dofuses.filter((d) => d.owner === "ally").every((d) => d.currentLife === 4)).toBe(true);
  });

  it("#951: a card burned because the hand is full is still a draw, so the reactor fires", () => {
    const phorreur = mkCreature(790, "ally", { x: 6, y: 2 }, { cardId: 951, currentAttack: 2, baseAttack: 2, triggers: card(951).triggers ?? [] });
    const sc = scenario([phorreur]);
    const full = Array.from({ length: 10 }, () => 16); // MAX_HAND
    const base = { ...sc, players: { ...sc.players, ally: { ...sc.players.ally, hand: full, handCostMods: full.map(() => 0), deck: [1, 2, 3] } } };
    const s = drawCard(base, "ally");
    expect(byId(s, 790)!.currentAttack).toBe(3);
  });
});

describe("Éternité #1468: the spells of the hand are shuffled into the deck, then as many creatures come out", () => {
  // The spells of the hand are put at random places in the deck, and then as many creatures are
  // drawn in the order of the deck.
  const setup = (hand: number[], deck: number[], seed = 12345) => {
    card(1468); card(40); card(69); card(1241); card(220); card(16);
    let s = scenario([]);
    return {
      ...s, prisms: [], rng: seed,
      players: { ...s.players, ally: { ...s.players.ally, hand: [1468, ...hand], handCostMods: [1468, ...hand].map(() => 0), deck: [...deck], deckCostMods: deck.map(() => 0), ap: 20, maxAp: 20 } },
    };
  };
  const cast = (s: ReturnType<typeof scenario>) => playCard(s, card(1468), { x: 9, y: 2 });

  it("the spells leave the hand and as many creatures arrive", () => {
    // hand: Éternité + 2 spells (#1241, #220) + 1 creature (#40); deck: 3 creatures
    const s = cast(setup([1241, 220, 40], [69, 69, 69]));
    const h = s.players.ally.hand;
    expect(h).not.toContain(1241);
    expect(h).not.toContain(220);
    expect(h).toContain(40);                                   // the creature in the hand does not move
    expect(h.filter((c) => c === 69)).toHaveLength(2);          // 2 spells sent back, so 2 creatures
    expect(h).toHaveLength(3);                                  // hand size kept
  });

  it("the spells are shuffled into the deck (not discarded, not banished, not put at the bottom)", () => {
    const s = cast(setup([1241, 220], [69, 69]));
    const p = s.players.ally;
    expect(p.deck).toContain(1241);
    expect(p.deck).toContain(220);
    expect(p.discard).not.toContain(1241);   // not the discard
    expect(p.banished ?? []).not.toContain(1241);
    expect(p.deck).toHaveLength(2);          // 2 in, 2 creatures out
    expect(p.deckCostMods).toHaveLength(p.deck.length); // alignment kept
  });

  it("the shuffle is random: two different seeds give different deck orders", () => {
    const deck = [69, 69, 69, 40, 40, 40];
    const a = cast(setup([1241, 220], deck, 1)).players.ally.deck.join(",");
    const b = cast(setup([1241, 220], deck, 999)).players.ally.deck.join(",");
    expect(a).not.toBe(b);
    // …and it is reproducible with the same seed
    expect(cast(setup([1241, 220], deck, 1)).players.ally.deck.join(",")).toBe(a);
  });

  it("fewer creatures in the deck than spells sent back, so take as many as there are", () => {
    const s = cast(setup([1241, 220], [69])); // 2 spells sent back, only 1 creature available
    const h = s.players.ally.hand;
    expect(h.filter((c) => c === 69)).toHaveLength(1);
    expect(h).toHaveLength(1); // the hand gets smaller, it does not fill up with spells
    expect(s.players.ally.deck).toHaveLength(2); // both spells are in the deck
  });

  it("a hand with no other spell changes nothing (and does not use the deck)", () => {
    const s = cast(setup([40, 40], [69, 69]));
    expect(s.players.ally.hand.sort()).toEqual([40, 40]);
    expect(s.players.ally.deck).toHaveLength(2);
  });

  it("the cost stamps follow the cards both ways", () => {
    card(1468); card(40); card(69); card(1241);
    let s = scenario([]);
    s = { ...s, prisms: [], rng: 7, players: { ...s.players, ally: { ...s.players.ally,
      hand: [1468, 1241], handCostMods: [0, -2],        // the spell sent back carries a −2 discount
      deck: [69], deckCostMods: [-1],                    // the tutored creature carries −1
      ap: 20, maxAp: 20 } } };
    s = cast(s);
    const p = s.players.ally;
    expect(p.hand).toEqual([69]);
    expect(p.handCostMods).toEqual([-1]);                // the creature's discount follows it into the hand
    expect(p.deck).toEqual([1241]);
    expect(p.deckCostMods).toEqual([-2]);                // the spell's discount follows it into the deck
  });

  it("a CARD_DRAWN beat is logged for each tutored creature (otherwise it jumps in the replay)", () => {
    const s = cast(setup([1241, 220], [69, 69]));
    expect(s.log.filter((e) => e.type === "CARD_DRAWN" && (e as { cardId?: number }).cardId === 69)).toHaveLength(2);
  });
});

describe("Draw by effect: a real draw (fatigue and reactions), not a tutor", () => {
  const emptyDeck = (s: ReturnType<typeof scenario>) => ({
    ...s, prisms: [],
    players: { ...s.players, ally: { ...s.players.ally, deck: [], deckCostMods: [] } },
  });

  it("#106 Tofoune: a draw from an empty deck deals fatigue to the allied Dofus (before: nothing at all)", () => {
    card(106);
    const tofoune = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 106, triggers: card(106).triggers ?? [] });
    const s = runTrigger(emptyDeck(scenario([tofoune])), "APPARITION", 1);
    expect(s.log.some((e) => e.type === "NO_MORE_CARD_TO_DRAW")).toBe(true);
    expect(s.log.some((e) => e.type === "DOFUS_REVEALED")).toBe(true);
    expect(s.dofuses.filter((d) => d.owner === "ally").every((d) => d.currentLife === 4)).toBe(true);
  });

  it("#415 Tofu Céleste: 3 draws from an empty deck give 3 damage per Dofus (the `continue`, not the `break`)", () => {
    card(415);
    const tofu = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 415, triggers: card(415).triggers ?? [] });
    const s = runTrigger(emptyDeck(scenario([tofu])), "APPARITION", 1);
    const n = (card(415).triggers ?? []).flatMap((t) => t.effects)
      .filter((e) => e.type === "DrawFiltered")
      .reduce((acc, e) => acc + (((e as { amount?: number }).amount ?? 0) | 0), 0);
    expect(n).toBeGreaterThan(1); // the card does draw several times
    expect(s.dofuses.filter((d) => d.owner === "ally").every((d) => d.currentLife === 5 - n)).toBe(true);
  });

  it("#106 Tofoune + Phorreur Furieux #951: the reactor fires on both branches (kept and discarded)", () => {
    card(106); card(951); card(16);
    const mk = (deckTop: number) => {
      const tofoune = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 106, triggers: card(106).triggers ?? [] });
      const phorreur = mkCreature(2, "ally", { x: 7, y: 1 }, { cardId: 951, currentAttack: 2, baseAttack: 2, triggers: card(951).triggers ?? [] });
      const sc = scenario([tofoune, phorreur]);
      return { ...sc, prisms: [], players: { ...sc.players, ally: { ...sc.players.ally, deck: [deckTop], deckCostMods: [0] } } };
    };
    // discarded branch: #16 is not a Tofu
    expect(byId(runTrigger(mk(16), "APPARITION", 1), 2)!.currentAttack).toBe(3);
    // kept branch: #106 is itself a Tofu
    expect(byId(runTrigger(mk(106), "APPARITION", 1), 2)!.currentAttack).toBe(3);
  });

  it("#245 Chasseur: a draw from an empty deck deals fatigue (before: the spell did nothing at all)", () => {
    card(245);
    let s = emptyDeck(scenario([], 245));
    s = playCard(s, card(245), { x: 8, y: 2 });
    expect(s.log.some((e) => e.type === "NO_MORE_CARD_TO_DRAW")).toBe(true);
    expect(s.dofuses.filter((d) => d.owner === "ally").every((d) => d.currentLife === 4)).toBe(true);
  });

  it("#245 Chasseur + #951: the draw fires the reactor", () => {
    card(245); card(951);
    const phorreur = mkCreature(2, "ally", { x: 7, y: 1 }, { cardId: 951, currentAttack: 2, baseAttack: 2, triggers: card(951).triggers ?? [] });
    let s = scenario([phorreur], 245);
    s = { ...s, prisms: [], players: { ...s.players, ally: { ...s.players.ally, hand: [245], handCostMods: [0], deck: [16], deckCostMods: [0] } } };
    s = playCard(s, card(245), { x: 8, y: 2 });
    expect(byId(s, 2)!.currentAttack).toBe(3);
  });

  it("#245 Chasseur: the log beats for deck to hand and deck to discard exist", () => {
    // Without them the card jumps in the replay. DrawFiltered already logged them, this one did not.
    card(245); card(40); card(1241);
    const play = (deckTop: number) => {
      let s = scenario([], 245);
      s = { ...s, prisms: [], players: { ...s.players, ally: { ...s.players.ally, hand: [245], handCostMods: [0], deck: [deckTop], deckCostMods: [0] } } };
      return playCard(s, card(245), { x: 8, y: 2 });
    };
    const summon = play(40); // #40 Bouftou Noir is a creature, so it goes to the hand at 0 AP
    expect(summon.log.some((e) => e.type === "CARD_DRAWN" && e.cardId === 40)).toBe(true);
    expect(summon.players.ally.hand).toContain(40);
    const spell = play(1241); // #1241 Sénilité is a spell, so it goes to the discard
    expect(spell.log.some((e) => e.type === "CARD_MOVED" && e.cardId === 1241 && e.from === "deck" && e.to === "discard")).toBe(true);
    expect(spell.players.ally.discard).toContain(1241);
  });
});

describe("HORDE: a HORDE creature's death discounts the owner's HORDE cards (hand + deck)", () => {
  it("stamps −1 PA on HORDE cards in hand, leaves non-HORDE cards alone", () => {
    card(508); // register the card pool so the engine's getCard sees the HORDE flag
    const sc = scenario([]);
    const base = { ...sc, players: { ...sc.players, ally: { ...sc.players.ally, hand: [818, 6], handCostMods: [0, 0] } } };
    const deadHorde = mkCreature(800, "ally", { x: 5, y: 1 }, { cardId: 508, currentLife: 0 }); // Chauve Souris = HORDE
    const res = resolveDeathsAndWin(base, [deadHorde], base.dofuses, [], new Set());
    expect(effectiveCost(res.players.ally, card(818))).toBe(card(818).cost - 1); // Gargoule (HORDE) −1
    expect(effectiveCost(res.players.ally, card(6))).toBe(card(6).cost);         // Tristepin (not HORDE) unchanged
  });

  it("reaching the end of a Dofus (breakthrough → back under the deck) is not a death → no discount", () => {
    card(508);
    const sc = scenario([]);
    const base = { ...sc, players: { ...sc.players, ally: { ...sc.players.ally, hand: [818, 6], handCostMods: [0, 0] } } };
    const brokeThrough = mkCreature(800, "ally", { x: 5, y: 1 }, { cardId: 508, currentLife: 0 }); // HORDE, captured a Dofus
    const res = resolveDeathsAndWin(base, [brokeThrough], base.dofuses, [], new Set([800])); // 800 broke through (not a death)
    expect(effectiveCost(res.players.ally, card(818))).toBe(card(818).cost); // Gargoule (HORDE) not discounted, capture ≠ mort
  });

  it("also discounts HORDE cards in the deck, the −1 is carried when the card is drawn", () => {
    card(508);
    const sc = scenario([]);
    const base = { ...sc, players: { ...sc.players, ally: { ...sc.players.ally, deck: [132], deckCostMods: [0], hand: [], handCostMods: [] } } };
    const deadHorde = mkCreature(800, "ally", { x: 5, y: 1 }, { cardId: 508, currentLife: 0 });
    const afterDeath = resolveDeathsAndWin(base, [deadHorde], base.dofuses, [], new Set());
    const afterDraw = drawCard(afterDeath, "ally"); // draw the HORDE Goule from the deck
    expect(effectiveCost(afterDraw.players.ally, card(132))).toBe(card(132).cost - 1);
  });

  it("is per-OWNER: an enemy HORDE death does not discount the ally's HORDE cards", () => {
    card(508);
    const sc = scenario([]);
    const base = { ...sc, players: { ...sc.players, ally: { ...sc.players.ally, hand: [818], handCostMods: [0] } } };
    const deadEnemyHorde = mkCreature(800, "enemy", { x: 3, y: 1 }, { cardId: 508, currentLife: 0 });
    const res = resolveDeathsAndWin(base, [deadEnemyHorde], base.dofuses, [], new Set());
    expect(effectiveCost(res.players.ally, card(818))).toBe(card(818).cost); // unchanged
  });

  it("stacks across deaths but the cost is floored at 0", () => {
    card(508);
    const sc = scenario([]);
    const base = { ...sc, players: { ...sc.players, ally: { ...sc.players.ally, hand: [508], handCostMods: [0] } } }; // Chauve Souris cost 2
    const dead = [
      mkCreature(800, "ally", { x: 5, y: 0 }, { cardId: 132, currentLife: 0 }),
      mkCreature(801, "ally", { x: 5, y: 1 }, { cardId: 132, currentLife: 0 }),
      mkCreature(802, "ally", { x: 5, y: 2 }, { cardId: 132, currentLife: 0 }),
    ];
    const res = resolveDeathsAndWin(base, dead, base.dofuses, [], new Set());
    expect(effectiveCost(res.players.ally, card(508))).toBe(0); // 2 − 3 = −1 → floored to 0
  });
});

describe("Wagnar/Vampyro: APPARITION stamps a persistent −1 PA on hand+deck cards by scope", () => {
  it("#737 Wagnar (scope spell): −1 on spells in hand + deck, summons untouched", () => {
    card(737);
    const wagnar = mkCreature(810, "ally", { x: 6, y: 2 }, { cardId: 737, triggers: card(737).triggers ?? [] });
    const sc = scenario([wagnar]);
    const base = { ...sc, players: { ...sc.players, ally: { ...sc.players.ally, hand: [38, 6], handCostMods: [0, 0], deck: [757], deckCostMods: [0] } } };
    const s = runTrigger(base, "APPARITION", 810);
    expect(effectiveCost(s.players.ally, card(38))).toBe(card(38).cost - 1); // Flèche Chercheuse (Spell) −1
    expect(effectiveCost(s.players.ally, card(6))).toBe(card(6).cost);       // Tristepin (Summon) unchanged
    const afterDraw = drawCard(s, "ally");
    expect(effectiveCost(afterDraw.players.ally, card(757))).toBe(card(757).cost - 1); // deck Fléau (Spell) carried
  });

  it("#779 Vampyro (scope summon): −1 on invocations, spells untouched", () => {
    card(779);
    const vamp = mkCreature(810, "ally", { x: 6, y: 2 }, { cardId: 779, triggers: card(779).triggers ?? [] });
    const sc = scenario([vamp]);
    const base = { ...sc, players: { ...sc.players, ally: { ...sc.players.ally, hand: [6, 38], handCostMods: [0, 0] } } };
    const s = runTrigger(base, "APPARITION", 810);
    expect(effectiveCost(s.players.ally, card(6))).toBe(card(6).cost - 1); // Tristepin (Summon) −1
    expect(effectiveCost(s.players.ally, card(38))).toBe(card(38).cost);   // Flèche (Spell) unchanged
  });

  it("#697 Vampyro (scope all): −1 on both spells and summons", () => {
    card(697);
    const vamp = mkCreature(810, "ally", { x: 6, y: 2 }, { cardId: 697, triggers: card(697).triggers ?? [] });
    const sc = scenario([vamp]);
    const base = { ...sc, players: { ...sc.players, ally: { ...sc.players.ally, hand: [6, 38], handCostMods: [0, 0] } } };
    const s = runTrigger(base, "APPARITION", 810);
    expect(effectiveCost(s.players.ally, card(6))).toBe(card(6).cost - 1);  // Summon −1
    expect(effectiveCost(s.players.ally, card(38))).toBe(card(38).cost - 1); // Spell −1
  });

  it("a card TUTORED from the deck (Coqueline) keeps Vampyro's −1, and so does a later draw (alignment cascade)", () => {
    // Cards gained after Vampyro, by tutoring (Coqueline/Yugo) or draw effects (Carquois/Phorreur
    // d'Élite), must keep the −1. TutorFromDeck used to splice `deck` without `deckCostMods`, losing the
    // stamp on the tutored card and putting the array out of step so every later draw fell back to 0.
    // Both are fixed now (deckCostMods moves with the deck).
    card(779); card(680); card(16); card(130);
    const vamp = mkCreature(810, "ally", { x: 6, y: 2 }, { cardId: 779, triggers: card(779).triggers ?? [] });
    const coq = mkCreature(811, "ally", { x: 8, y: 0 }, { cardId: 680, triggers: card(680).triggers ?? [] });
    const sc = scenario([vamp, coq]);
    // Deck (bottom→top): #130 (5-cost summon), #16 (2-cost summon), Vampyro #779 stamps both summons.
    let s = { ...sc, players: { ...sc.players, ally: { ...sc.players.ally, hand: [], handCostMods: [], deck: [130, 16], deckCostMods: [0, 0] } } };
    s = runTrigger(s, "APPARITION", 810); // Vampyro stamps the deck summons −1
    s = runTrigger(s, "APPARITION", 811); // Coqueline tutors a 2-cost summon (#16)
    expect(s.players.ally.hand).toContain(16);
    expect(effectiveCost(s.players.ally, card(16))).toBe(card(16).cost - 1); // tutored card keeps Vampyro's −1
    s = drawCard(s, "ally");                                                  // draw the remaining #130
    expect(s.players.ally.hand).toContain(130);
    expect(effectiveCost(s.players.ally, card(130))).toBe(card(130).cost - 1); // drawn card keeps −1 (cascade fixed)
  });
});

describe("Rat Dominant #557, a death-summon on the death cell blocks the killer's kill-and-continue", () => {
  it("killing a Rat Dominant leaves the killer blocked on its cell, the Ratou fills the freed cell", () => {
    card(557); card(490);
    // Ally killer at x=6 (movement 4, enough to walk past), enemy Rat Dominant adjacent at x=5 (1 life).
    const killer = mkCreature(901, "ally", { x: 6, y: 2 }, { currentAttack: 9, baseAttack: 9, currentLife: 9, baseLife: 9, movementLeft: 4, baseMovement: 4, hasAttacked: false });
    const rat = mkCreature(902, "enemy", { x: 5, y: 2 }, { cardId: 557, currentLife: 1, baseLife: 3, currentAttack: 1, baseAttack: 1, triggers: card(557).triggers ?? [] });
    let s = scenario([killer, rat]);
    s = { ...s, prisms: [], players: { ...s.players, ally: { ...s.players.ally, deck: [6], deckCostMods: [0] }, enemy: { ...s.players.enemy, deck: [6], deckCostMods: [0] } } };
    s = endTurn(s); // ally combat phase
    expect(byId(s, 902)).toBeUndefined();              // Rat Dominant dead
    expect(byId(s, 901)!.position.x).toBe(6);          // killer blocked, stays at x=6 (no walk-through to x=2)
    const ratous = s.creatures.filter((c) => c.cardId === 490 && c.currentLife > 0);
    expect(ratous.length).toBe(1);                     // exactly one Ratou (no double summon)
    expect(ratous[0].position).toEqual({ x: 5, y: 2 }); // on the freed death cell
  });
  it("with no death-summon, kill-and-continue still works (the killer advances past)", () => {
    card(490);
    // A plain enemy (no MORT) at x=5, the killer should kill it and continue to x=2 (movement 4).
    const killer = mkCreature(903, "ally", { x: 6, y: 2 }, { currentAttack: 9, baseAttack: 9, currentLife: 9, baseLife: 9, movementLeft: 4, baseMovement: 4, hasAttacked: false });
    const foe = mkCreature(904, "enemy", { x: 5, y: 2 }, { cardId: 490, currentLife: 1, baseLife: 3, currentAttack: 1, baseAttack: 1 }); // Ratou: no MORT
    let s = scenario([killer, foe]);
    s = { ...s, prisms: [], players: { ...s.players, ally: { ...s.players.ally, deck: [6], deckCostMods: [0] }, enemy: { ...s.players.enemy, deck: [6], deckCostMods: [0] } } };
    s = endTurn(s);
    expect(byId(s, 904)).toBeUndefined();
    expect(byId(s, 903)!.position.x).toBe(2); // killed at x=5, continued the remaining 3 PM to x=2
  });
});

describe("Nenufar #821, a Sadida's death-seed appears at the instant of death, in the killer's path", () => {
  it("the killer walks onto the freshly-spawned enemy seed: takes 1 damage and consumes it (no seed left)", () => {
    card(129); card(821);
    // Ally killer at x=6 (atk 9, movement 4). Enemy Sadida (#129 Li Crounch, atk 0 → no counter) adjacent at x=5,
    // 1 life. Enemy Nenufar (#821) alive out of the lane → the Sadida leaves a Seed on its death cell.
    const killer = mkCreature(901, "ally", { x: 6, y: 2 }, { currentAttack: 9, baseAttack: 9, currentLife: 9, baseLife: 9, armor: 0, movementLeft: 4, baseMovement: 4, hasAttacked: false });
    const sadida = mkCreature(902, "enemy", { x: 5, y: 2 }, { cardId: 129, currentLife: 1, baseLife: 2, currentAttack: 0, baseAttack: 0 });
    const nenufar = mkCreature(903, "enemy", { x: 1, y: 4 }, { cardId: 821, currentLife: 3, baseLife: 3 });
    let s = scenario([killer, sadida, nenufar]);
    s = { ...s, prisms: [], seeds: [], players: { ...s.players, ally: { ...s.players.ally, deck: [6], deckCostMods: [0] }, enemy: { ...s.players.enemy, deck: [6], deckCostMods: [0] } } };
    s = endTurn(s); // ally combat phase
    expect(byId(s, 902)).toBeUndefined();                 // the Sadida died
    expect(byId(s, 901)!.currentLife).toBe(8);            // killer took the enemy seed's 1 damage as it stepped on
    expect(byId(s, 901)!.position.x).toBe(2);             // and continued its advance
    expect((s.seeds ?? []).some((sd) => sd.position.x === 5 && sd.position.y === 2)).toBe(false); // seed consumed, not on board
  });
  it("a Sadida killed without the killer walking over it (splash) still seeds instantly, a later sweeper hits it", () => {
    card(129); card(821);
    // Ally splash-attacker at (6,2) engages a beefy enemy in front at (5,2); its column-splash also strikes (5,1)
    // and (5,3), killing the enemy Sadida at (5,1). The attacker never steps onto (5,1), but the seed must appear
    // there now, so the later-moving ally in row 1 walks over it and takes the enemy seed's 1 damage.
    const splasher = mkCreature(921, "ally", { x: 6, y: 2 }, { currentAttack: 5, baseAttack: 5, currentLife: 9, baseLife: 9, movementLeft: 3, baseMovement: 3, hasAttacked: false, properties: new Set(["DamagesOn3CellsSameColumn"]) });
    const wall = mkCreature(922, "enemy", { x: 5, y: 2 }, { cardId: 6, currentLife: 20, baseLife: 20, currentAttack: 0, baseAttack: 0 }); // survives → splasher stays put
    const sadida = mkCreature(923, "enemy", { x: 5, y: 1 }, { cardId: 129, currentLife: 1, baseLife: 2, currentAttack: 0, baseAttack: 0 });
    const nenufar = mkCreature(924, "enemy", { x: 1, y: 4 }, { cardId: 821, currentLife: 3, baseLife: 3 });
    const sweeper = mkCreature(925, "ally", { x: 8, y: 1 }, { currentAttack: 3, baseAttack: 3, currentLife: 9, baseLife: 9, armor: 0, movementLeft: 3, baseMovement: 3, hasAttacked: false }); // 8→7→6→5: lands on the seed cell
    let s = scenario([splasher, wall, sadida, nenufar, sweeper]);
    s = { ...s, prisms: [], seeds: [], dofuses: [], players: { ...s.players, ally: { ...s.players.ally, deck: [6], deckCostMods: [0] }, enemy: { ...s.players.enemy, deck: [6], deckCostMods: [0] } } };
    s = endTurn(s); // ally combat phase: splasher (x=6) moves before sweeper (x=8)
    expect(byId(s, 923)).toBeUndefined();               // the Sadida died to splash
    expect(byId(s, 925)!.currentLife).toBe(8);          // the later sweeper walked over the freshly-spawned seed → 1 dmg
    expect((s.seeds ?? []).some((sd) => sd.position.x === 5 && sd.position.y === 1)).toBe(false); // consumed by the sweeper
  });
  it("with no Nenufar in play, no seed is created and the killer takes no seed damage", () => {
    card(129);
    const killer = mkCreature(911, "ally", { x: 6, y: 2 }, { currentAttack: 9, baseAttack: 9, currentLife: 9, baseLife: 9, armor: 0, movementLeft: 4, baseMovement: 4, hasAttacked: false });
    const sadida = mkCreature(912, "enemy", { x: 5, y: 2 }, { cardId: 129, currentLife: 1, baseLife: 2, currentAttack: 0, baseAttack: 0 });
    let s = scenario([killer, sadida]);
    s = { ...s, prisms: [], seeds: [], players: { ...s.players, ally: { ...s.players.ally, deck: [6], deckCostMods: [0] }, enemy: { ...s.players.enemy, deck: [6], deckCostMods: [0] } } };
    s = endTurn(s);
    expect(byId(s, 912)).toBeUndefined();
    expect(byId(s, 911)!.currentLife).toBe(9);            // no seed → no damage
    expect(byId(s, 911)!.position.x).toBe(2);
    expect((s.seeds ?? []).length).toBe(0);
  });
});

