describe("Goule Taka #871: APPARITION recycles hand Goules and draws that many", () => {
  it("sends hand Goules to the deck bottom and tutors the same count of Goules (top-first)", () => {
    card(871);
    const taka = mkCreature(830, "ally", { x: 6, y: 2 }, { cardId: 871, triggers: card(871).triggers ?? [] });
    const sc = scenario([taka]);
    const base = { ...sc, players: { ...sc.players, ally: { ...sc.players.ally,
      hand: [132, 818, 6], handCostMods: [0, 0, 0],       // 2 Goules (#132,#818) + a non-Goule (#6)
      deck: [38, 403, 508], deckCostMods: [0, 0, 0] } } }; // top = 508 (Goule), 403 (Goule), 38 (non-Goule, bottom)
    const s = runTrigger(base, "APPARITION", 830);
    const p = s.players.ally;
    expect(p.hand).toContain(6);        // the non-Goule stays in hand
    expect(p.hand).toContain(508);      // drew the deck's top Goule
    expect(p.hand).toContain(403);      // and the next one
    expect(p.hand).not.toContain(132);  // the hand Goules left the hand…
    expect(p.hand).not.toContain(818);
    expect(p.deck).toEqual(expect.arrayContaining([132, 818])); // …onto the deck
    expect(p.hand.length).toBe(3);      // net hand size unchanged
  });

  it("carries the HORDE cost discount with the cards (a discounted deck Goule keeps it when drawn)", () => {
    card(871);
    const taka = mkCreature(830, "ally", { x: 6, y: 2 }, { cardId: 871, triggers: card(871).triggers ?? [] });
    const sc = scenario([taka]);
    const base = { ...sc, players: { ...sc.players, ally: { ...sc.players.ally,
      hand: [132], handCostMods: [0], deck: [508], deckCostMods: [-2] } } }; // deck Goule #508 pre-discounted −2
    const s = runTrigger(base, "APPARITION", 830);
    expect(s.players.ally.hand).toContain(508);
    expect(effectiveCost(s.players.ally, card(508))).toBe(Math.max(0, card(508).cost - 2)); // discount carried into hand
  });
});

