describe("Tas d'Os (cœur) : objet de plateau, mot-clé mort→tas d'os, marche-dessus", () => {
  it("mot-clé TAS D'OS : une créature taguée morte laisse un Tas d'Os sur sa case (son camp)", () => {
    card(197); // Chafer Lancier porte le mot-clé
    const chafer = mkCreature(900, "ally", { x: 5, y: 1 }, { cardId: 197, currentLife: 0 });
    const sc = scenario([chafer]);
    const res = resolveDeathsAndWin(sc, [chafer], sc.dofuses, [], new Set());
    expect((res.tasDOs ?? []).some((t) => t.owner === "ally" && t.position.x === 5 && t.position.y === 1)).toBe(true);
  });

  it("un Chafer allié qui marche sur un Tas d'Os allié gagne +1 AT +1 AR (et le consomme)", () => {
    card(197);
    const chafer = mkCreature(901, "ally", { x: 5, y: 1 }, { cardId: 197, currentAttack: 2, baseAttack: 2, armor: 0, movementLeft: 1, baseMovement: 1 });
    let s = scenario([chafer]);
    s = { ...s, prisms: [], tasDOs: [{ position: { x: 4, y: 1 }, owner: "ally" }] };
    s = endTurn(s);
    const c = byId(s, 901)!;
    expect(c.position.x).toBe(4);            // a marché sur le tas d'os
    expect(c.currentAttack).toBe(3);         // +1 AT
    expect(c.armor).toBe(1);                 // +1 AR
    expect((s.tasDOs ?? []).length).toBe(0); // consommé
  });

  it("un allié NON-Chafer qui marche sur un Tas d'Os allié le DÉTRUIT (sans bonus)", () => {
    card(6); // Tristepin (pas un Chafer)
    const trist = mkCreature(902, "ally", { x: 5, y: 1 }, { cardId: 6, currentAttack: 2, baseAttack: 2, armor: 0, movementLeft: 1, baseMovement: 1 });
    let s = scenario([trist]);
    s = { ...s, prisms: [], tasDOs: [{ position: { x: 4, y: 1 }, owner: "ally" }] };
    s = endTurn(s);
    const c = byId(s, 902)!;
    expect(c.currentAttack).toBe(2);         // pas de bonus
    expect((s.tasDOs ?? []).length).toBe(0); // détruit
  });

  it("le TUEUR non-Chafer qui marche sur le Tas d'Os FRAIS de sa victime le DÉTRUIT dans le même balayage", () => {
    // A killer that is not a Chafer, kills a Chafer and goes on to its cell must break the new tas d'os.
    // Before, this tas d'os only appeared at the end of the sweep (invisible to the killer walking on it),
    // so it wrongly survived.
    card(6); card(197); // Tristepin (non-Chafer, ally) tue un Chafer Lancier (enemy)
    const killer = mkCreature(910, "ally", { x: 5, y: 1 }, { cardId: 6, currentAttack: 5, baseAttack: 5, currentLife: 9, baseLife: 9, movementLeft: 3, baseMovement: 3 });
    const chafer = mkCreature(911, "enemy", { x: 4, y: 1 }, { cardId: 197, currentLife: 1, baseLife: 1, currentAttack: 1 });
    let s = scenario([killer, chafer]);
    s = { ...s, prisms: [], tasDOs: [] };
    s = endTurn(s);
    expect(byId(s, 911)).toBeUndefined();    // Chafer tué
    expect((s.tasDOs ?? []).length).toBe(0); // new tas d'os destroyed by the killer walking on it
  });

  it("un Tas d'Os FRAIS qu'AUCUN marcheur ne traverse se matérialise bien en fin de balayage", () => {
    // The other half of the fix: an inline tas d'os that nobody used must appear (not be lost). An allied
    // Chafer dies while advancing against a stronger enemy; nobody walks on its death cell.
    card(197);
    const chafer = mkCreature(912, "ally", { x: 5, y: 1 }, { cardId: 197, currentLife: 1, baseLife: 1, currentAttack: 1, movementLeft: 3, baseMovement: 3 });
    const foe = mkCreature(913, "enemy", { x: 4, y: 1 }, { currentLife: 9, baseLife: 9, currentAttack: 5 });
    let s = scenario([chafer, foe]);
    s = { ...s, prisms: [], tasDOs: [] };
    s = endTurn(s);
    expect(byId(s, 912)).toBeUndefined();    // allied Chafer died in the exchange (on its cell 5,1)
    expect((s.tasDOs ?? []).some((t) => t.owner === "ally" && t.position.x === 5 && t.position.y === 1)).toBe(true);
  });
});

