    card(878); card(38);
    const tama = mkCreature(960, "ally", { x: 6, y: 2 }, { cardId: 878, currentLife: 3, baseLife: 3, triggers: card(878).triggers ?? [] });
    const enemy = mkCreature(961, "enemy", { x: 2, y: 2 }, { currentLife: 5, baseLife: 5 });
    let s = scenario([tama, enemy], 38); // Flèche Chercheuse en main
    s = { ...s, prisms: [] };
