describe("Anathar #316 : CONTRE COUP → prend le contrôle de l'agresseur (tant qu'Anathar vit)", () => {
  it("prend le contrôle de l'AGRESSEUR + pose une réversion liée à Anathar", () => {
    card(316); card(16);
    const anathar = mkCreature(1400, "ally", { x: 6, y: 2 }, { cardId: 316, triggers: card(316).triggers ?? [] });
    const attacker = mkCreature(1401, "enemy", { x: 5, y: 2 }, { cardId: 16 });
    const sc = scenario([anathar, attacker]);
    const base = { ...sc, log: [...sc.log, { type: "DAMAGE", targetInstanceId: 1400, sourceInstanceId: 1401, damage: 1 } as GameEvent] };
    const s = fireContreCoup(base, base.log.length - 1);
    expect(byId(s, 1401)!.owner).toBe("ally"); // l'agresseur passe sous contrôle ally
    expect((s.pendingReversions ?? []).some((r) => r.kind === "control" && r.instanceId === 1401 && r.linkedTo === 1400)).toBe(true);
  });

  it("l'agresseur revient à son camp d'origine quand Anathar meurt", () => {
    card(316); card(16);
    const anathar = mkCreature(1402, "ally", { x: 6, y: 2 }, { cardId: 316, currentLife: 0, baseLife: 3 }); // va mourir
    const seized = mkCreature(1403, "ally", { x: 5, y: 2 }, { cardId: 16 }); // ex-ennemi, contrôlé par Anathar
    const sc = scenario([anathar, seized]);
    const base = { ...sc, pendingReversions: [{ kind: "control" as const, instanceId: 1403, originalOwner: "enemy" as const, linkedTo: 1402 }] };
    const s = resolveDeathsAndWin(base, base.creatures, base.dofuses, [], new Set());
    expect(byId(s, 1402)).toBeUndefined();      // Anathar mort
    expect(byId(s, 1403)!.owner).toBe("enemy"); // l'agresseur revient à son camp
  });
});

