describe("Indie #454 : MORT → récupère une carte Infinite aléatoire de votre défausse (−1 PA)", () => {
  it("récupère une Infinite de la défausse (−1 PA) ; PAS elle-même, et ignore les Common", () => {
    card(454); card(65); card(890);
    const indie = mkCreature(1450, "ally", { x: 6, y: 2 }, { cardId: 454, currentLife: 0, baseLife: 3, triggers: card(454).triggers ?? [] });
    const sc = scenario([indie]);
    const base = { ...sc, players: { ...sc.players,
      ally: { ...sc.players.ally, discard: [890, 65], hand: [], handCostMods: [] } } }; // 890 Common, 65 Infinite
    // The MORT effect runs before Indie goes to the discard, so it does not recover itself.
    const s = resolveDeathsAndWin(base, base.creatures, base.dofuses, [], new Set());
    expect(s.players.ally.hand).toContain(65);       // l'autre Infinite récupérée
    expect(s.players.ally.hand).not.toContain(890);  // Common ignoré (filtre rarity)
    expect(s.players.ally.hand).not.toContain(454);  // not itself
    expect(s.players.ally.discard).toContain(454);   // Indie goes to the discard after its effect
    expect(s.players.ally.handCostMods[s.players.ally.hand.indexOf(65)]).toBe(-1); // −1 PA
  });
});

describe("Indie #305 : MORT → récupère TOUTES les Infinite de la défausse sur la pioche", () => {
  it("place toutes les cartes Infinite de la défausse sur la pioche, laisse les Common", () => {
    card(305); card(65); card(28); card(890);
    const indie = mkCreature(1460, "ally", { x: 6, y: 2 }, { cardId: 305, currentLife: 0, baseLife: 3, triggers: card(305).triggers ?? [] });
    const sc = scenario([indie]);
    const base = { ...sc, players: { ...sc.players,
      ally: { ...sc.players.ally, discard: [890, 65, 28], deck: [], hand: [], handCostMods: [] } } }; // 65+28 Infinite, 890 Common
    const s = resolveDeathsAndWin(base, base.creatures, base.dofuses, [], new Set());
    expect(s.players.ally.deck).toContain(65);        // the Infinite cards on the deck
    expect(s.players.ally.deck).toContain(28);
    expect(s.players.ally.deck).not.toContain(890);   // le Common n'y va pas
    expect(s.players.ally.discard).not.toContain(65); // retirées de la défausse
    expect(s.players.ally.discard).not.toContain(28);
    expect(s.players.ally.discard).toContain(890);    // le Common reste en défausse
  });
});

describe("Indie #509 : MORT → place dans la main la dernière carte Infinite de la pioche (−1 PA)", () => {
  it("prend la DERNIÈRE Infinite (la plus profonde, en partant de la fin), ignore les Common", () => {
    card(509); card(65); card(28); card(890);
    const indie = mkCreature(1470, "ally", { x: 6, y: 2 }, { cardId: 509, currentLife: 0, baseLife: 3, triggers: card(509).triggers ?? [] });
    const sc = scenario([indie]);
    const base = { ...sc, players: { ...sc.players,
      ally: { ...sc.players.ally, deck: [890, 65, 28], hand: [], handCostMods: [] } } }; // index0=890 Common (fond), 65 Infinite, 28 Infinite (sommet)
    const s = resolveDeathsAndWin(base, base.creatures, base.dofuses, [], new Set());
    expect(s.players.ally.hand).toContain(65);       // the last Infinite (65 = the deepest; 890 Common skipped), "partir de la fin"
    expect(s.players.ally.hand).not.toContain(28);   // PAS celle du sommet
    expect(s.players.ally.hand).not.toContain(890);  // Common ignoré (filtre rarity)
    expect(s.players.ally.deck).toContain(28);       // celle du sommet reste en pioche
    expect(s.players.ally.handCostMods[s.players.ally.hand.indexOf(65)]).toBe(-1); // −1 PA
  });
  it("#454 Indie (2*): MORT recovers a random Infinite from the discard (seeded rng), never a Common", () => {
    card(454); card(65); card(680); card(890);
    const indie = mkCreature(1471, "ally", { x: 6, y: 2 }, { cardId: 454, currentLife: 0, baseLife: 3, triggers: card(454).triggers ?? [] });
    const sc = scenario([indie]);
    const base = { ...sc, players: { ...sc.players,
      ally: { ...sc.players.ally, discard: [890, 65, 680], hand: [], handCostMods: [] } } }; // 2 Infinites (65,680) + 1 Common (890)
    const s = resolveDeathsAndWin(base, base.creatures, base.dofuses, [], new Set());
    expect([65, 680].some((x) => s.players.ally.hand.includes(x))).toBe(true); // recovered one Infinite (random pick)
    expect(s.players.ally.hand).not.toContain(890);                            // never the Common (rarity filter)
  });
});

