describe("Purpuce #34 : APPARITION → charge jusqu'au dofus adverse puis meurt", () => {
  it("charge toute la ligne (frappe le dofus adverse) puis se retire (meurt)", () => {
    const sc = scenario([], 34);
    const base = { ...sc, prisms: [], players: { ...sc.players, ally: { ...sc.players.ally, hand: [34], handCostMods: [0], ap: 20, maxAp: 20 } } };
    const enemyLifeBefore = base.dofuses.filter((d) => d.owner === "enemy").reduce((a, d) => a + d.currentLife, 0);
    const s = playCard(base, card(34), { x: 8, y: 2 });
    expect(s.creatures.some((c) => c.cardId === 34 && c.owner === "ally")).toBe(false); // a chargé PUIS est morte
    const enemyLifeAfter = s.dofuses.filter((d) => d.owner === "enemy").reduce((a, d) => a + d.currentLife, 0);
    expect(enemyLifeAfter).toBeLessThan(enemyLifeBefore); // a frappé le dofus adverse en chargeant
  });
});

describe("Miranda #107 : APPARITION → prend le contrôle des invocations adverses autour d'elle (tant qu'elle vit)", () => {
  it("prend les ennemis ADJACENTS (8 cases), pas les lointains, + réversions liées à Miranda", () => {
    card(107);
    const miranda = mkCreature(1540, "ally", { x: 5, y: 2 }, { cardId: 107, triggers: card(107).triggers ?? [] });
    const adj1 = mkCreature(1541, "enemy", { x: 5, y: 1 }, {}); // adjacent
    const adj2 = mkCreature(1542, "enemy", { x: 4, y: 2 }, {}); // adjacent (diagonale incluse)
    const far = mkCreature(1543, "enemy", { x: 5, y: 4 }, {});  // trop loin
    const sc = scenario([miranda, adj1, adj2, far]);
    const s = runTrigger(sc, "APPARITION", 1540);
    expect(byId(s, 1541)!.owner).toBe("ally");  // pris
    expect(byId(s, 1542)!.owner).toBe("ally");  // pris
    expect(byId(s, 1543)!.owner).toBe("enemy"); // trop loin → pas pris
    expect((s.pendingReversions ?? []).filter((r) => r.kind === "control" && r.linkedTo === 1540).length).toBe(2);
  });

  it("les invocations reviennent à leur camp quand Miranda meurt", () => {
    card(107);
    const miranda = mkCreature(1544, "ally", { x: 5, y: 2 }, { cardId: 107, currentLife: 0, baseLife: 3 }); // va mourir
    const seized = mkCreature(1545, "ally", { x: 5, y: 1 }, {}); // ex-ennemi, contrôlé par Miranda
    const sc = scenario([miranda, seized]);
    const base = { ...sc, pendingReversions: [{ kind: "control" as const, instanceId: 1545, originalOwner: "enemy" as const, linkedTo: 1544 }] };
    const s = resolveDeathsAndWin(base, base.creatures, base.dofuses, [], new Set());
    expect(byId(s, 1544)).toBeUndefined();      // Miranda morte
    expect(byId(s, 1545)!.owner).toBe("enemy"); // revient à son camp d'origine
  });

  it("TRANSFORMER Miranda annule aussi le contrôle : la créature revient à son camp", () => {
    card(107); card(224);
    // Miranda alive but transformed (cardId ≠ 107 ≠ the saved sourceCardId) → control broken.
    const miranda = mkCreature(1546, "ally", { x: 5, y: 2 }, { cardId: 224, currentLife: 3, baseLife: 3 });
    const seized = mkCreature(1547, "ally", { x: 5, y: 1 }, { cardId: 263 });
    const sc = scenario([miranda, seized]);
    const base = { ...sc, pendingReversions: [{ kind: "control" as const, instanceId: 1547, originalOwner: "enemy" as const, linkedTo: 1546, sourceCardId: 107, seizedCardId: 263 }] };
    const s = resolveDeathsAndWin(base, base.creatures, base.dofuses, [], new Set());
    expect(byId(s, 1546)!.owner).toBe("ally");          // Miranda transformée, toujours vivante
    expect(byId(s, 1547)!.owner).toBe("enemy");         // control broken by the transformation → goes back
    expect((s.pendingReversions ?? []).length).toBe(0); // réversion consommée
  });

  it("le SILENCE sur Miranda NE rompt PAS le contrôle", () => {
    card(107); card(263);
    const miranda = mkCreature(1548, "ally", { x: 5, y: 2 }, { cardId: 107, currentLife: 3, baseLife: 3, silenced: true });
    const seized = mkCreature(1549, "ally", { x: 5, y: 1 }, { cardId: 263 });
    const sc = scenario([miranda, seized]);
    const base = { ...sc, pendingReversions: [{ kind: "control" as const, instanceId: 1549, originalOwner: "enemy" as const, linkedTo: 1548, sourceCardId: 107, seizedCardId: 263 }] };
    const s = resolveDeathsAndWin(base, base.creatures, base.dofuses, [], new Set());
    expect(byId(s, 1549)!.owner).toBe("ally");          // still controlled despite the silence
    expect((s.pendingReversions ?? []).length).toBe(1); // réversion intacte (silence ≠ mort/transformation)
  });

  it("TRANSFORMER la créature contrôlée (Marca Or) la fixe au contrôleur : même la mort de Miranda ne la rend plus", () => {
    card(107); card(224); card(263);
    // Marca Or sweep: the controlled creature is transformed (cardId 224 ≠ seizedCardId 263) before the
    // source dies. The transformation of the controlled creature wins, so it stays with the controller.
    const miranda = mkCreature(1551, "ally", { x: 5, y: 2 }, { cardId: 107, currentLife: 0, baseLife: 3 }); // va mourir
    const seized = mkCreature(1552, "ally", { x: 5, y: 1 }, { cardId: 224 });
    const sc = scenario([miranda, seized]);
    const base = { ...sc, pendingReversions: [{ kind: "control" as const, instanceId: 1552, originalOwner: "enemy" as const, linkedTo: 1551, sourceCardId: 107, seizedCardId: 263 }] };
    const s = resolveDeathsAndWin(base, base.creatures, base.dofuses, [], new Set());
    expect(byId(s, 1551)).toBeUndefined();              // Miranda morte
    expect(byId(s, 1552)!.owner).toBe("ally");          // transformed → stays with the controller even though Miranda died
    expect((s.pendingReversions ?? []).length).toBe(0); // réversion supprimée (définitif)
  });

  it("course Marca Or (AoE hors dégâts = balayage) : la contrôlée transformée AVANT la source garde le camp ; APRÈS, elle revient", () => {
    card(107); card(224); card(263);
    // Both change in the same pass (Marca Or transforms everything in a sweep). The controller's sweep
    // order (ally: front first = smallest x, then L1→L5) decides.
    const mkRace = (seizedPos: { x: number; y: number }, mirandaPos: { x: number; y: number }) => {
      const miranda = mkCreature(1560, "ally", mirandaPos, { cardId: 224, currentLife: 3, baseLife: 3 }); // transformée (≠107)
      const seized = mkCreature(1561, "ally", seizedPos, { cardId: 224, currentLife: 3, baseLife: 3 });   // transformée (≠263)
      const sc = scenario([miranda, seized]);
      const base = { ...sc, pendingReversions: [{ kind: "control" as const, instanceId: 1561, originalOwner: "enemy" as const, linkedTo: 1560, sourceCardId: 107, seizedCardId: 263 }] };
      return resolveDeathsAndWin(base, base.creatures, base.dofuses, [], new Set());
    };
    // Controlled creature (x=4) swept before Miranda (x=5) → stays with the controller.
    expect(byId(mkRace({ x: 4, y: 2 }, { x: 5, y: 2 }), 1561)!.owner).toBe("ally");
    // Miranda (x=4) swept before the controlled creature (x=5) → control broken first → it goes back to
    // its camp.
    expect(byId(mkRace({ x: 5, y: 2 }, { x: 4, y: 2 }), 1561)!.owner).toBe("enemy");
  });
});

describe("Balayage des AoE de DÉPLACEMENT et des SILENCES", () => {
  // The sweep only holds for area moves (Flèche Tempête, Peur, Art du Fourrage) and silences, not for
  // boosts/heals/vulnérabilité/transformations (those stay simultaneous). The order holds for the
  // mechanics and the animation (the replay plays the log in the order the events are emitted).
  it("un SILENCE AoE s'applique dans l'ordre de balayage du lanceur (front → L1→L5), pas l'ordre du tableau", () => {
    // 3 allies out of order in the array, each with something to cancel (armor>0). The
    // FIGHT_OBJECT_SILENCED events must come out in ally sweep order: (5,0) → (6,1) → (7,2).
    const A = mkCreature(970, "ally", { x: 7, y: 2 }, { armor: 1 }); // arrière
    const B = mkCreature(971, "ally", { x: 5, y: 0 }, { armor: 1 }); // front, L1
    const C = mkCreature(972, "ally", { x: 6, y: 1 }, { armor: 1 }); // milieu, L2
    const log: GameEvent[] = [];
    applyEffects([A, B, C], [], log, [{ type: "Silence", scope: "allies" } as never], { casterSide: "ally" });
    const order = log.filter((e) => (e as { type: string }).type === "FIGHT_OBJECT_SILENCED").map((e) => (e as { instanceId: number }).instanceId);
    expect(order).toEqual([971, 972, 970]); // balayage, pas [970, 971, 972]
  });

  it("balayage MIROIR pour le lanceur enemy : front = x le plus grand d'abord", () => {
    const A = mkCreature(980, "enemy", { x: 2, y: 2 }, { armor: 1 }); // arrière (enemy)
    const B = mkCreature(981, "enemy", { x: 4, y: 0 }, { armor: 1 }); // front (enemy), L1
    const C = mkCreature(982, "enemy", { x: 3, y: 1 }, { armor: 1 }); // milieu
    const log: GameEvent[] = [];
    applyEffects([A, B, C], [], log, [{ type: "Silence", scope: "allies" } as never], { casterSide: "enemy" });
    const order = log.filter((e) => (e as { type: string }).type === "FIGHT_OBJECT_SILENCED").map((e) => (e as { instanceId: number }).instanceId);
    expect(order).toEqual([981, 982, 980]); // enemy : front = x max d'abord → (4,0) → (3,1) → (2,2)
  });

  it("un renvoi en main AoE (Art Du Fourrage #1446 : ReturnToHand) revient en main dans l'ordre de balayage", () => {
    // Sending back to hand is an area move → sweep. Checked through the order of FIGHT_OBJECT_REMOVED.
    card(1446); card(263);
    const A = mkCreature(990, "ally", { x: 7, y: 2 }, { cardId: 263 }); // arrière
    const B = mkCreature(991, "ally", { x: 5, y: 0 }, { cardId: 263 }); // front, L1
    const C = mkCreature(992, "ally", { x: 6, y: 1 }, { cardId: 263 }); // milieu
    const base = { ...scenario([A, B, C], 1446), prisms: [] };
    const s = playCard(base, card(1446), { x: 0, y: 0 }); // AlliedGod : la case de cast est ignorée
    const order = s.log.filter((e) => (e as { type: string }).type === "FIGHT_OBJECT_REMOVED").map((e) => (e as { instanceId?: number }).instanceId);
    expect(order).toEqual([991, 992, 990]); // balayage : (5,0) → (6,1) → (7,2)
  });
});

