describe("Shava Shavien #367 : MORT → remonte (50/50) dans votre main OU celle de l'adversaire", () => {
  const mkShava = (id: number) => mkCreature(id, "ally", { x: 5, y: 2 }, { cardId: 367, currentLife: 0, baseLife: 3, triggers: card(367).triggers ?? [] });
  it("pièce PILE : remonte dans VOTRE main", () => {
    card(367);
    const sc = scenario([mkShava(1560)]);
    const base = { ...sc, players: { ...sc.players, ally: { ...sc.players.ally, coinForcedPile: true, hand: [], handCostMods: [], discard: [] } } };
    const s = resolveDeathsAndWin(base, base.creatures, base.dofuses, [], new Set());
    expect(s.players.ally.hand).toContain(367);        // ta main
    expect(s.players.enemy.hand).not.toContain(367);
    expect(s.players.ally.discard).not.toContain(367); // jamais en défausse
  });
  it("pièce FACE : remonte dans la main de l'ADVERSAIRE", () => {
    card(367);
    const sc = scenario([mkShava(1561)]);
    const base = { ...sc, rng: 1, players: { ...sc.players, ally: { ...sc.players.ally, coinForcedPile: false, hand: [], handCostMods: [], discard: [] }, enemy: { ...sc.players.enemy, hand: [], handCostMods: [] } } }; // rng=1 → pièce FACE
    const s = resolveDeathsAndWin(base, base.creatures, base.dofuses, [], new Set());
    expect(s.players.enemy.hand).toContain(367);       // main adverse
    expect(s.players.ally.hand).not.toContain(367);
  });
  it("son lancer de MORT déclenche les réactions de lancer alliées (Sentinelle Affûtée #1606 / Atout Caché #1201)", () => {
    card(367); card(1606); card(1201);
    const shava = mkShava(1562);
    const sentinelle = mkCreature(1563, "ally", { x: 6, y: 2 }, { cardId: 1606, currentAttack: 2, baseAttack: 2, armor: 0, currentLife: 3, baseLife: 3 });
    const sc = scenario([shava, sentinelle]);
    const base = { ...sc, players: { ...sc.players, ally: { ...sc.players.ally, coinForcedPile: true, hand: [1201], handCostMods: [0], discard: [] } } };
    const s = resolveDeathsAndWin(base, base.creatures, base.dofuses, [], new Set());
    expect(byId(s, 1563)!.currentAttack).toBe(3);      // Sentinelle +1 AT (le lancer de Shava a bien compté)
    expect(byId(s, 1563)!.armor).toBe(1);              // +1 AR
    const ai = s.players.ally.hand.indexOf(1201);
    expect(s.players.ally.handCostMods[ai]).toBe(-1);  // Atout Caché −1 PA en main
  });
  it("sans lancer (pas de Shava qui meurt), la Sentinelle ne gagne rien", () => {
    card(1606);
    const sentinelle = mkCreature(1564, "ally", { x: 6, y: 2 }, { cardId: 1606, currentAttack: 2, baseAttack: 2, armor: 0, currentLife: 3, baseLife: 3 });
    const sc = scenario([sentinelle]);
    const s = resolveDeathsAndWin(sc, sc.creatures, sc.dofuses, [], new Set());
    expect(byId(s, 1564)!.currentAttack).toBe(2);      // contrôle : aucun lancer → aucune réaction
    expect(byId(s, 1564)!.armor).toBe(0);
  });
});

describe("Charge par sort (Lait de Bambou #506) sur une invocation en mal d'invocation", () => {
  it("une invocation posée ce tour, chargée par Lait de Bambou, RESTE en mal d'invocation (ne rejoue pas en fin de tour)", () => {
    card(506);
    // Invocation placed this turn = summoning sickness: hasAttacked true, movementLeft 0 (as at summon).
    const sick = mkCreature(700, "ally", { x: 6, y: 2 }, { currentAttack: 3, baseAttack: 3, currentLife: 5, baseLife: 5, baseMovement: 2, movementLeft: 0, hasAttacked: true });
    const enemy = mkCreature(701, "enemy", { x: 3, y: 2 }, { currentLife: 9, baseLife: 9, currentAttack: 0, baseAttack: 0 });
    const sc = scenario([sick, enemy]);
    const base = { ...sc, prisms: [], players: { ...sc.players, ally: { ...sc.players.ally, hand: [506], handCostMods: [0], ap: 20, maxAp: 20, deck: [6], deckCostMods: [0] }, enemy: { ...sc.players.enemy, deck: [6], deckCostMods: [0] } } };
    const afterCharge = playCard(base, card(506), { x: 6, y: 2 }); // Lait de Bambou : la créature charge de 2
    expect(byId(afterCharge, 700)!.hasAttacked).toBe(true);         // still has summoning sickness after the charge
    const lifeAfterCharge = byId(afterCharge, 701)!.currentLife;    // vie de l'ennemi après l'éventuel contact de charge
    const s = endTurn(afterCharge);
    expect(byId(s, 701)!.currentLife).toBe(lifeAfterCharge);        // at end of turn the invocation with summoning sickness does not play again (no 2nd attack)
  });
  it("contrôle : une invocation DÉJÀ EN JEU (pas malade) chargée par Lait de Bambou fait quand même son tour", () => {
    card(506);
    const ready = mkCreature(710, "ally", { x: 6, y: 2 }, { currentAttack: 3, baseAttack: 3, currentLife: 5, baseLife: 5, baseMovement: 2, movementLeft: 2, hasAttacked: false });
    const sc = scenario([ready]);
    const base = { ...sc, prisms: [], players: { ...sc.players, ally: { ...sc.players.ally, hand: [506], handCostMods: [0], ap: 20, maxAp: 20 } } };
    const afterCharge = playCard(base, card(506), { x: 6, y: 2 });
    expect(byId(afterCharge, 710)!.hasAttacked).toBe(false);        // reste actif → prendra son avance de fin de tour
    expect(byId(afterCharge, 710)!.movementLeft).toBe(2);           // budget PM restauré (charge = bonus)
  });
  it("un TIREUR fraîchement posé chargé par Lait de Bambou ne TIRE PAS en fin de tour, même avec une cible à portée", () => {
    card(506);
    // Shooter (range 2) placed this turn = summoning sickness (hasAttacked true, movementLeft 0). The
    // charge brings it closer without reaching contact (target at range 2). The old code left it awake
    // (handleCharge clears hasAttacked, the charge hits nothing, so nothing restores the sickness), so it
    // wrongly fired.
    const shooter = mkCreature(720, "ally", { x: 8, y: 2 }, { range: 2, baseMovement: 0, movementLeft: 0, hasAttacked: true, currentAttack: 3, baseAttack: 3, currentLife: 5, baseLife: 5 });
    const foe = mkCreature(721, "enemy", { x: 4, y: 2 }, { currentAttack: 0, baseAttack: 0, currentLife: 9, baseLife: 9, baseMovement: 0, movementLeft: 0 });
    const sc = scenario([shooter, foe]);
    const base = { ...sc, prisms: [], players: { ...sc.players, ally: { ...sc.players.ally, hand: [506], handCostMods: [0], ap: 20, maxAp: 20, deck: [6], deckCostMods: [0] }, enemy: { ...sc.players.enemy, deck: [6], deckCostMods: [0] } } };
    const afterCharge = playCard(base, card(506), { x: 8, y: 2 }); // charge 2 → x=6, cible à portée 2 (x=4), hors contact
    expect(byId(afterCharge, 720)!.position.x).toBe(6);            // a bien chargé
    expect(byId(afterCharge, 720)!.hasAttacked).toBe(true);        // reste malade (état d'avant-charge préservé)
    const foeLife = byId(afterCharge, 721)!.currentLife;           // non touché par la charge (hors contact)
    const s = endTurn(afterCharge);
    expect(byId(s, 721)!.currentLife).toBe(foeLife);               // pas de tir en fin de tour
  });
  it("une statique à 0 mvt prise via Fiole de Psykoz puis chargée FRAPPE en fin de tour et, si elle perce, revient à MON deck", () => {
    card(19); card(506);
    // Enemy creature with 3 AT, 0 movement, next to the enemy Dofus. We take control of it (Fiole de
    // Psykoz) then charge it (Lait de Bambou). It was already in play, so no summoning sickness, and it
    // must hit the Dofus at end of turn (the charge at 0 PM only puts it against the Dofus: 4 → 1). The
    // old code kept it asleep.
    const foe = mkCreature(1, "enemy", { x: 1, y: 2 }, { currentAttack: 3, baseAttack: 3, currentLife: 5, baseLife: 5, baseMovement: 0, movementLeft: 0 });
    const sc = withDecks(scenario([foe], 19, 506));
    const base = { ...sc, players: { ...sc.players, ally: { ...sc.players.ally, hand: [19, 506], handCostMods: [0, 0], ap: 20, maxAp: 20 } }, dofuses: sc.dofuses.map((d, i) => (i === 0 ? { ...d, owner: "enemy" as const, position: { x: 0, y: 2 }, currentLife: 4 } : d)) };
    const deckBefore = base.players.ally.deck.length;
    let s = playCard(base, card(19), { x: 1, y: 2 });   // contrôle (rafraîchit : hasAttacked false)
    s = playCard(s, card(506), { x: 1, y: 2 });          // charge → colle au Dofus, le frappe (4 → 1), reste à 0 PM
    s = endTurn(s);
    expect(byId(s, 1)).toBeUndefined();                  // a frappé le Dofus en fin de tour → capturé → a percé
    expect(s.players.ally.deck.length).toBe(deckBefore + 1); // the controlled creature that breaks through comes back into my deck
  });
});

describe("Pupuce #441 : APPARITION → devient de la famille de l'invocation ciblée (remplace Puce)", () => {
  it("adopte UNIQUEMENT la famille de la cible (familyOverride remplace Puce)", () => {
    card(441); card(122); // 122 Black Tiwabbit = famille Wabbit
    const pupuce = mkCreature(1570, "ally", { x: 5, y: 2 }, { cardId: 441, currentAttack: 2, baseAttack: 2, triggers: card(441).triggers ?? [] });
    const wabbit = mkCreature(1571, "ally", { x: 4, y: 2 }, { cardId: 122 });
    const sc = scenario([pupuce, wabbit]);
    const pend = runTrigger(sc, "APPARITION", 1570);
    expect(pend.pendingAction).not.toBeNull();              // a pick is asked for
    const s = resolvePendingAction(pend, { x: 4, y: 2 });   // on choisit le Wabbit
    expect(byId(s, 1570)!.familyOverride).toContain("Wabbit"); // a copié Wabbit
    expect(byId(s, 1570)!.familyOverride).not.toContain("Puce"); // a PERDU Puce (remplacée)
  });
});

