    const sc = scenario([ush]);
    const base = { ...sc, dofuses: [
      { position: { x: 9, y: 2 }, owner: "ally" as const, currentLife: 5, kind: "real" as const },  // on Ush's row
      { position: { x: 9, y: 0 }, owner: "ally" as const, currentLife: 5, kind: "fake" as const },
    ] };
    const pend = runTrigger(base, "APPARITION", 1610);
    expect(pend.pendingAction).not.toBeNull();                // a pick is asked for
