describe("Championne du Blasphème #1451 : nécrome APPARITION → si en sous nombre, remonte la créature la plus proche sur sa ligne", () => {
  it("en sous nombre : remonte la créature la plus proche sur la ligne (main de son propriétaire)", () => {
    card(1451); card(16);
    const champ = mkCreature(1650, "ally", { x: 6, y: 2 }, { cardId: 1451, triggers: card(1451).triggers ?? [] });
    const near = mkCreature(1651, "enemy", { x: 4, y: 2 }, { cardId: 16 });   // la plus proche (dx=2)
    const far = mkCreature(1652, "enemy", { x: 2, y: 2 }, { cardId: 16 });    // plus loin (dx=4)
    const sc = scenario([champ, near, far]); // ally=1 < enemy=2 → en sous nombre
    const s = runTrigger(sc, "APPARITION", 1650);
    expect(s.creatures.some((c) => c.instanceId === 1651)).toBe(false); // the closest one went back to hand
    expect(s.creatures.some((c) => c.instanceId === 1652)).toBe(true);  // la plus loin reste
    expect(s.players.enemy.hand).toContain(16);                         // dans la main de SON propriétaire (l'adversaire)
  });
  it("PAS en sous nombre : ne remonte rien", () => {
    card(1451); card(16);
    const champ = mkCreature(1655, "ally", { x: 6, y: 2 }, { cardId: 1451, triggers: card(1451).triggers ?? [] });
    const ally2 = mkCreature(1656, "ally", { x: 7, y: 0 }, { cardId: 16 });
    const enemy = mkCreature(1657, "enemy", { x: 4, y: 2 }, { cardId: 16 }); // ally=2 ≥ enemy=1 → PAS en sous nombre
    const sc = scenario([champ, ally2, enemy]);
    const s = runTrigger(sc, "APPARITION", 1655);
    expect(s.creatures.some((c) => c.instanceId === 1657)).toBe(true); // rien remonté (condition non remplie)
  });
});

