describe("Cycle du Temps #1460 : SORT → sacrifie une invocation alliée, ajoute son coût à la réserve", () => {
  it("détruit l'invocation ciblée et crédite son coût (2) à la réserve", () => {
    card(1460); card(16);
    const victim = mkCreature(1680, "ally", { x: 6, y: 2 }, { cardId: 16 }); // Bouftou, coût 2
    const sc = scenario([victim]);
    const base = { ...sc, activeSide: "ally" as const, players: { ...sc.players, ally: { ...sc.players.ally, hand: [1460], handCostMods: [0], ap: 20, apReserve: 0 } } };
    const s = playCard(base, card(1460), { x: 6, y: 2 }); // sacrifie le #16
    expect(s.creatures.some((c) => c.instanceId === 1680)).toBe(false); // détruit
    expect(s.players.ally.apReserve).toBe(2);                           // coût 2 → réserve
  });
  // Embaumement sacrifices one of your creatures, so it must not be castable without one.
  const withHand = (s: ReturnType<typeof scenario>) => ({ ...s, prisms: [], players: { ...s.players, ally: { ...s.players.ally, hand: [1460], handCostMods: [0], ap: 20, maxAp: 20 } } });
  const allyDof = (s: ReturnType<typeof scenario>) => s.dofuses.find((d) => d.owner === "ally")!.position;
  it("est INJOUABLE sans aucune invocation alliée (ni sur un Dofus, ni dans le vide, ni sur un ennemi)", () => {
    card(1460);
    const s = withHand(scenario([mkCreature(60, "enemy", { x: 4, y: 2 }, { currentLife: 5, baseLife: 5 })]));
    expect(canPlayCard(s, card(1460), allyDof(s))).not.toBeNull();   // un Dofus → refusé
    expect(canPlayCard(s, card(1460), { x: 6, y: 2 })).not.toBeNull(); // case vide → refusé
    expect(canPlayCard(s, card(1460), { x: 4, y: 2 })).not.toBeNull(); // un ennemi → refusé
  });
  it("avec une invocation alliée : on doit la cibler (pas un Dofus / une case vide / un ennemi)", () => {
    card(1460); card(16);
    const ally = mkCreature(70, "ally", { x: 6, y: 2 }, { cardId: 16, currentLife: 5, baseLife: 5 });
    const enemy = mkCreature(61, "enemy", { x: 4, y: 0 }, { currentLife: 5, baseLife: 5 });
    const s = withHand(scenario([ally, enemy]));
    expect(canPlayCard(s, card(1460), { x: 6, y: 2 })).toBeNull();     // l'allié → valide
    expect(canPlayCard(s, card(1460), allyDof(s))).not.toBeNull();     // un Dofus → refusé
    expect(canPlayCard(s, card(1460), { x: 7, y: 2 })).not.toBeNull(); // case vide → refusé
    expect(canPlayCard(s, card(1460), { x: 4, y: 0 })).not.toBeNull(); // un ennemi → refusé
  });
});

