describe("Boufballe #1137 : compteur « patate chaude » (renvoi / expiration)", () => {
  const withDecks5 = (s: ReturnType<typeof scenario>) => ({
    ...s,
    players: { ...s.players, ally: { ...s.players.ally, deck: [16, 16, 16] }, enemy: { ...s.players.enemy, deck: [16, 16, 16] } },
  });
  it("Kriss arme le compteur (2 tours) sur la main adverse en y déposant la Boufballe", () => {
    card(341); card(1137);
    const kriss = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 341, triggers: card(341).triggers ?? [] });
    const s = runTrigger(scenario([kriss]), "APPARITION", 1);
    expect(s.players.enemy.hand).toContain(1137);
    expect(s.players.enemy.activeTraps).toEqual([{ cardId: 1137, counter: 2, penalty: 0, buffEnemy: { attack: 2, armor: 1 } }]);
  });
  it("à l'expiration (2 fins de tour sans la renvoyer) : les invocations de l'ADVERSAIRE du porteur gagnent +2 AT/+1 AR ; la carte quitte la main", () => {
    card(341); card(1137);
    const kriss = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 341, triggers: card(341).triggers ?? [] });
    let s: ReturnType<typeof scenario> = withDecks5(scenario([kriss]));
    s = runTrigger(s, "APPARITION", 1);
    const atk0 = byId(s, 1)!.currentAttack, arm0 = byId(s, 1)!.armor;
    s = endTurn({ ...s, activeSide: "enemy" }); // compteur 2 → 1
    expect(s.players.enemy.hand).toContain(1137);          // toujours là
    expect(byId(s, 1)!.currentAttack).toBe(atk0);           // pas encore de buff
    s = endTurn({ ...s, activeSide: "enemy" }); // compteur 1 → 0 : DÉTONE
    expect(s.players.enemy.hand).not.toContain(1137);       // the Boufballe leaves the holder's hand
    expect(s.players.enemy.activeTraps).toEqual([]);        // compteur consommé
    expect(byId(s, 1)!.currentAttack).toBe(atk0 + 2);       // Kriss (adversaire du porteur) : +2 AT
    expect(byId(s, 1)!.armor).toBe(arm0 + 1);               // +1 AR
  });
  it("jouer la Boufballe la RENVOIE dans la main adverse avec un compteur frais (2) ; elle ne va PAS à la défausse", () => {
    card(341); card(1137);
    const kriss = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 341, triggers: card(341).triggers ?? [] });
    let s: ReturnType<typeof scenario> = runTrigger(scenario([kriss]), "APPARITION", 1);
    // The opponent (enemy) plays the Boufballe during its turn → sent back to the ally hand
    s = { ...s, activeSide: "enemy", players: { ...s.players, enemy: { ...s.players.enemy, ap: 10, maxAp: 10 } } };
    s = playCard(s, card(1137), { x: 9, y: 2 }); // sort AlliedGod (cible le dieu)
    expect(s.players.enemy.hand).not.toContain(1137);       // quitte la main du lanceur
    expect(s.players.enemy.activeTraps).toEqual([]);         // désamorcé chez le lanceur
    expect(s.players.enemy.discard ?? []).not.toContain(1137);       // PAS de défausse
    expect(s.players.enemy.tokenDiscard ?? []).not.toContain(1137);  // ni tokenDiscard
    expect(s.players.ally.hand).toContain(1137);             // atterrit dans la main adverse
    expect(s.players.ally.activeTraps).toEqual([{ cardId: 1137, counter: 2, penalty: 0, buffEnemy: { attack: 2, armor: 1 } }]); // compteur ré-armé à 2
  });
});

