describe("Bluff #61 : SORT → échange la position de 2 de vos dofus (chacun emporte sa couleur)", () => {
  it("échange les cases : le dofus ivoire va à la place du faux EN RESTANT ivoire", () => {
    card(61);
    const sc = scenario([]);
    const base = { ...sc, activeSide: "ally" as const,
      dofuses: [
        { position: { x: 9, y: 0 }, owner: "ally" as const, currentLife: 5, kind: "real" as const, color: 4 }, // couleur ivoire (index 4)
        { position: { x: 9, y: 2 }, owner: "ally" as const, currentLife: 3, kind: "fake" as const, color: 1 }, // autre couleur (index 1)
      ],
      players: { ...sc.players, ally: { ...sc.players.ally, hand: [61], handCostMods: [0], ap: 20 } } };
    const pend = playCard(base, card(61), { x: 9, y: 0 }); // 1er pick = dofus ivoire/réel (9,0)
    expect(pend.pendingAction).not.toBeNull();              // 2nd pick asked for
    const s = resolvePendingAction(pend, { x: 9, y: 2 });   // 2e pick = l'autre dofus/faux (9,2)
    const d0 = s.dofuses.find((d) => d.position.x === 9 && d.position.y === 0)!;
    const d2 = s.dofuses.find((d) => d.position.x === 9 && d.position.y === 2)!;
    // The ivory/real one went to (9,2) keeping its colour (index 4), not the colour of row 2
    expect(d2.color).toBe(4);
    expect(d2.kind).toBe("real");
    expect(d2.currentLife).toBe(5);
    // L'autre/faux est allé en (9,0), couleur conservée (index 1)
    expect(d0.color).toBe(1);
    expect(d0.kind).toBe("fake");
    expect(d0.currentLife).toBe(3);
  });
  it("un SEUL dofus allié éligible → Bluff est CONSOMMÉ mais aucun échange, aucun pending figé", () => {
    card(61);
    const sc = scenario([]);
    const base = { ...sc, activeSide: "ally" as const,
      dofuses: [
        { position: { x: 9, y: 2 }, owner: "ally" as const, currentLife: 5, kind: "real" as const, color: 4 }, // the only living allied dofus
        { position: { x: 0, y: 2 }, owner: "enemy" as const, currentLife: 5, kind: "real" as const, color: 0 }, // dofus adverse (hors filtre ally_dofus)
      ],
      players: { ...sc.players, ally: { ...sc.players.ally, hand: [61], handCostMods: [0], ap: 20 } } };
    const apBefore = base.players.ally.ap;
    const s = playCard(base, card(61), { x: 9, y: 2 }); // 1st pick = the only allied dofus
    // No "other" dofus to swap with → no pending (no freeze).
    expect(s.pendingAction).toBeNull();
    expect(s.players.ally.hand).not.toContain(61);
    expect(s.players.ally.discard).toContain(61);
    expect(s.players.ally.ap).toBeLessThan(apBefore);
    // Le dofus n'a pas bougé.
    expect(s.dofuses.find((d) => d.owner === "ally")!.position).toEqual({ x: 9, y: 2 });
  });
});

describe("Enfouissement #684 : SORT → la cible marquée se place SUR LE DESSUS de la pioche (pas en défausse) à sa mort", () => {
  it("marque l'invocation puis, à sa mort, la place sur le DESSUS de la pioche de son propriétaire (tirée en premier)", () => {
    card(684); card(16);
    const victim = mkCreature(1740, "ally", { x: 6, y: 2 }, { cardId: 16, currentLife: 2, baseLife: 2 });
    const sc = scenario([victim]);
    const base = { ...sc, activeSide: "ally" as const, players: { ...sc.players, ally: { ...sc.players.ally, hand: [684], handCostMods: [0], ap: 20, deck: [10], discard: [] } } };
    const marked = playCard(base, card(684), { x: 6, y: 2 }); // cible l'invocation #16
    expect(byId(marked, 1740)!.properties.has("DeckOnDeath")).toBe(true); // marquée
    const killed = { ...marked, creatures: marked.creatures.map((c) => c.instanceId === 1740 ? { ...c, currentLife: 0 } : c) };
    const s = resolveDeathsAndWin(killed, killed.creatures, killed.dofuses, [], new Set());
    expect(s.players.ally.deck).toContain(16);          // enfouie dans la pioche
    expect(s.players.ally.discard).not.toContain(16);   // not in the discard
    // On top: the top of the deck = last element (taken by pop()) → drawn before #10.
    expect(s.players.ally.deck[s.players.ally.deck.length - 1]).toBe(16);
    const drawn = drawCard(s, "ally");
    expect(drawn.players.ally.hand).toContain(16);      // bien la prochaine carte piochée
    expect(s.creatures.some((c) => c.instanceId === 1740)).toBe(false); // retirée du plateau
  });
});

