    const c1 = [joris, t1].map((c) => ({ ...c, position: { ...c.position }, properties: new Set(c.properties) }));
    applyEffects(c1, [], [], [{ type: "DamageData", Damage: 3 } as never], { casterSide: "enemy", targetCell: { x: 8, y: 2 } });
    expect(c1.find((c) => c.instanceId === 1761)!.currentLife).toBe(4); // 5 − (3−2)
