    const sc = scenario([crass, tank, frail, friendly]);
    const fullHand = Array(10).fill(16); // main pleine (MAX_HAND = 10)
    const base = { ...sc, players: { ...sc.players, ally: { ...sc.players.ally, hand: fullHand, handCostMods: fullHand.map(() => 0), deck: [10], deckCostMods: [0] } } };
