describe("Désynchronisation #377 : dépense les PA restants en dégâts ; injouable à 0 PA", () => {
  it("#377 inflige (PA restants) dégâts à la cible et consomme tous les PA", () => {
    const foe = mkCreature(1, "enemy", { x: 3, y: 2 }, { currentLife: 6, baseLife: 6 });
    let s = scenario([foe], 377);
    s = { ...s, players: { ...s.players, ally: { ...s.players.ally, ap: 4, maxAp: 4 } } };
    s = playCard(s, card(377), { x: 3, y: 2 });
    expect(byId(s, 1)!.currentLife).toBe(2); // 6 − 4
    expect(s.players.ally.ap).toBe(0);       // tous les PA consommés
  });
  it("#377 n'est PAS jouable à 0 PA (même garde qu'Heure de Gloire #296)", () => {
    const foe = mkCreature(1, "enemy", { x: 3, y: 2 });
    let s = scenario([foe], 377);
    s = { ...s, players: { ...s.players, ally: { ...s.players.ally, ap: 0, maxAp: 0 } } };
    expect(canPlayCard(s, card(377), { x: 3, y: 2 })).toBe("Aucun PA à dépenser.");
  });
  it("#377 et #296 RESTENT jouables avec tous les PA du tour (rien dépensé), seul 0 PA bloque", () => {
    const foe = mkCreature(1, "enemy", { x: 3, y: 2 }, { currentLife: 12, baseLife: 12 });
    const mine = mkCreature(2, "ally", { x: 6, y: 2 });
    let s = scenario([foe, mine], 377, 296); // scenario : 10 PA, aucun dépensé
    expect(canPlayCard(s, card(377), { x: 3, y: 2 })).toBeNull(); // Désynchro OK à pleins PA
    expect(canPlayCard(s, card(296), { x: 6, y: 2 })).toBeNull(); // Heure de Gloire OK à pleins PA
    s = playCard(s, card(377), { x: 3, y: 2 }); // played as the first action of the turn
    expect(byId(s, 1)!.currentLife).toBe(2);    // 12 − 10 : les 10 PA entiers en dégâts
    expect(s.players.ally.ap).toBe(0);
  });
});

describe("Renisurrection #483 : la créature ciblée revient en main à sa mort", () => {
  it("applique ReturnToHandOnDeath via SetPropertyData et log PROPERTY_APPLIED", () => {
    card(483);
    const target = mkCreature(1, "ally", { x: 6, y: 2 }, { currentLife: 4, baseLife: 4 });
    const s0 = scenario([target], 483);
    const s1 = playCard(s0, card(483), { x: 6, y: 2 });
    const t = byId(s1, 1)!;
    expect(t.properties.has("ReturnToHandOnDeath")).toBe(true);
    expect(s1.log.some((e) => e.type === "PROPERTY_APPLIED" && (e as { instanceId?: number }).instanceId === 1)).toBe(true);
  });
  it("la créature avec ReturnToHandOnDeath revient en main à la mort (pas en défausse)", () => {
    const dying = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 612, currentLife: 0, baseLife: 4, properties: new Set(["ReturnToHandOnDeath"]) });
    const sc = scenario([dying]);
    const base = { ...sc, players: { ...sc.players, ally: { ...sc.players.ally, hand: [], handCostMods: [] } } };
    const s = resolveDeathsAndWin(base, base.creatures, base.dofuses, [], new Set());
    expect(s.players.ally.hand).toContain(612);    // revient en main
    expect(s.players.ally.discard).not.toContain(612); // PAS en défausse
  });
  it("avec la main pleine (10/10), la créature Renisurrection va en défausse", () => {
    card(483);
    const dying = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 612, currentLife: 0, baseLife: 4, properties: new Set(["ReturnToHandOnDeath"]) });
    const sc = scenario([dying]);
    const fullHand = Array(MAX_HAND).fill(16);
    const base = { ...sc, players: { ...sc.players, ally: { ...sc.players.ally, hand: fullHand, handCostMods: fullHand.map(() => 0) } } };
    const s = resolveDeathsAndWin(base, base.creatures, base.dofuses, [], new Set());
    expect(s.players.ally.hand).toHaveLength(MAX_HAND); // main inchangée
    expect(s.players.ally.discard).toContain(612);       // défausse de débordement
  });
});

// ─── Initiative #464 ────────────────────────────────────────────────────────
describe("Initiative #464", () => {
  it("confère FirstStrike à la cible et log PROPERTY_APPLIED", () => {
    card(464);
    const target = mkCreature(1, "ally", { x: 6, y: 2 }, { currentLife: 3, baseLife: 3 });
    const s0 = scenario([target], 464);
    const s1 = playCard(s0, card(464), { x: 6, y: 2 });
    expect(byId(s1, 1)!.properties.has("FirstStrike")).toBe(true);
    expect(s1.log.some((e) => e.type === "PROPERTY_APPLIED" && (e as { instanceId?: number }).instanceId === 1)).toBe(true);
  });

  it("Cervelle de Iop #683 confère FirstStrike à toutes les invocations alliées", () => {
    card(683);
    const a = mkCreature(1, "ally",  { x: 5, y: 2 }, { currentLife: 3, baseLife: 3 });
    const b = mkCreature(2, "ally",  { x: 5, y: 4 }, { currentLife: 2, baseLife: 2 });
    const e = mkCreature(3, "enemy", { x: 2, y: 2 }, { currentLife: 4, baseLife: 4 });
    const s0 = scenario([a, b, e], 683);
    // Cervelle de Iop targets "AlliedGod", cast on any ally-side position
    const s1 = playCard(s0, card(683), { x: 9, y: 0 });
    expect(byId(s1, 1)!.properties.has("FirstStrike")).toBe(true);  // ally a
    expect(byId(s1, 2)!.properties.has("FirstStrike")).toBe(true);  // ally b
    expect(byId(s1, 3)!.properties.has("FirstStrike")).toBe(false); // enemy unaffected
  });

  // A keyword conferred from outside is permanent on its carrier. Before the fix, withAuras
  // wiped the bit at the first recompute (an unconditional delete in steps 4/4b/4c/5): the spell
  // was paid 3 AP, the card was discarded, and nothing happened at all, with no log or message,
  // on any carrier of a conditional initiative. Measured with a probe.
  const grantInitiative = (carrier: ReturnType<typeof mkCreature>, others: ReturnType<typeof mkCreature>[] = []) => {
    card(464);
    let s = scenario([carrier, ...others], 464);
    s = { ...s, prisms: [] };
    return playCard(s, card(464), { ...carrier.position });
  };

  it("#464 on Zorine #668 when not outnumbered: the initiative is set and no longer wiped", () => {
    card(668);
    const zorine = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 668 });
    const ally2 = mkCreature(2, "ally", { x: 7, y: 1 }, {});
    const foe = mkCreature(3, "enemy", { x: 3, y: 1 }, {}); // 2 allies vs 1, so not outnumbered
    const s = grantInitiative(zorine, [ally2, foe]);
    expect(byId(s, 1)!.properties.has("FirstStrike")).toBe(true);
  });

  it("#464 on a wounded Grouilleux #309: it keeps the initiative once healed to full life", () => {
    // The flip of the carrier's own condition (wounded to full) does not take back a keyword
    // that came from outside.
    card(309);
    const grouilleux = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 309, currentLife: 2, baseLife: 5 });
    let s = grantInitiative(grouilleux);
    expect(byId(s, 1)!.properties.has("FirstStrike")).toBe(true);
    s = { ...s, creatures: withAuras(s.creatures.map((c) => (c.instanceId === 1 ? { ...c, currentLife: c.baseLife } : c))) };
    expect(byId(s, 1)!.properties.has("FirstStrike")).toBe(true); // healed, it keeps what the spell granted
  });

  it("#464 on Korbax #379 alone: the initiative holds, and its conditional untargetable stays conditional", () => {
    card(379);
    const korbax = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 379 });
    const s = grantInitiative(korbax);
    expect(byId(s, 1)!.properties.has("FirstStrike")).toBe(true);   // conferred, so permanent
    expect(byId(s, 1)!.properties.has("Untargetable")).toBe(false); // no other Justicier, so still revoked
  });

  it("no regression: a Zorine with no outside grant loses the initiative when it is no longer outnumbered", () => {
    card(668);
    const zorine = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 668 });
    const foe1 = mkCreature(2, "enemy", { x: 3, y: 1 }, {});
    const foe2 = mkCreature(3, "enemy", { x: 3, y: 3 }, {});
    const outnumbered = withAuras([zorine, foe1, foe2]); // 1 vs 2, outnumbered
    expect(outnumbered.find((c) => c.instanceId === 1)!.properties.has("FirstStrike")).toBe(true);
    const even = withAuras(outnumbered.filter((c) => c.instanceId !== 3)); // 1 vs 1, no longer outnumbered
    expect(even.find((c) => c.instanceId === 1)!.properties.has("FirstStrike")).toBe(false);
  });

  it("no regression: Korbax #379 loses untargetable when the last other Justicier dies", () => {
    card(379); card(130);
    const korbax = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 379 });
    const justicier = mkCreature(2, "ally", { x: 7, y: 2 }, { cardId: 130 });
    const withMate = withAuras([korbax, justicier]);
    expect(withMate.find((c) => c.instanceId === 1)!.properties.has("Untargetable")).toBe(true);
    const alone = withAuras(withMate.map((c) => (c.instanceId === 2 ? { ...c, currentLife: 0 } : c)));
    expect(alone.find((c) => c.instanceId === 1)!.properties.has("Untargetable")).toBe(false);
  });

  it("silence takes back a conferred keyword (it wipes every property)", () => {
    card(668); card(220);
    const zorine = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 668 });
    let s = grantInitiative(zorine);
    expect(byId(s, 1)!.properties.has("FirstStrike")).toBe(true);
    s = { ...s, players: { ...s.players, ally: { ...s.players.ally, hand: [220], handCostMods: [0], ap: 20, maxAp: 20 } } };
    s = playCard(s, card(220), { x: 6, y: 2 });
    expect(byId(s, 1)!.silenced).toBe(true);
    expect(byId(s, 1)!.properties.has("FirstStrike")).toBe(false);
  });
});

describe("Empty-trigger summons (APPARITION/MORT/COUP DE GRÂCE)", () => {
  it("Deserboss #112 (APPARITION): 1 dmg to every creature in the enemy half (friendly fire), itself spared", () => {
    const deserboss = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 112, triggers: card(112).triggers ?? [] });
    const enemyInEnemyCamp = mkCreature(2, "enemy", { x: 3, y: 0 }, { currentLife: 5, baseLife: 5 });
    const enemyInAllyCamp = mkCreature(3, "enemy", { x: 7, y: 4 }, { currentLife: 5, baseLife: 5 });
    const allyInEnemyCamp = mkCreature(4, "ally", { x: 2, y: 1 }, { currentLife: 5, baseLife: 5 });
    const base = scenario([deserboss, enemyInEnemyCamp, enemyInAllyCamp, allyInEnemyCamp]);
    const s = runTrigger(base, "APPARITION", 1);
    expect(byId(s, 2)!.currentLife).toBe(4); // enemy in enemy half → −1
    expect(byId(s, 3)!.currentLife).toBe(5); // enemy in your half → untouched
    expect(byId(s, 4)!.currentLife).toBe(4); // Your creature in the enemy half → −1 (friendly fire)
    expect(byId(s, 1)!.currentLife).toBe(5); // Deserboss itself → spared
  });

  it("Dathura #600 (APPARITION): hits all enemies for (# enemies in your camp)", () => {
    const dathura = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 600, triggers: card(600).triggers ?? [] });
    const a = mkCreature(2, "enemy", { x: 7, y: 1 }, { currentLife: 9, baseLife: 9 }); // in ally camp → counted + hit
    const b = mkCreature(3, "enemy", { x: 8, y: 3 }, { currentLife: 9, baseLife: 9 }); // in ally camp → counted + hit
    const c = mkCreature(4, "enemy", { x: 3, y: 2 }, { currentLife: 9, baseLife: 9 }); // in enemy camp → not counted, still hit
    const s = runTrigger(scenario([dathura, a, b, c]), "APPARITION", 1);
    expect(byId(s, 2)!.currentLife).toBe(7); // count = 2 (a,b) → all enemies −2
    expect(byId(s, 3)!.currentLife).toBe(7);
    expect(byId(s, 4)!.currentLife).toBe(7);
  });

  it("Dathura #721 (APPARITION): hits enemies in your camp for (# enemies in play)", () => {
    const dathura = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 721, triggers: card(721).triggers ?? [] });
    const a = mkCreature(2, "enemy", { x: 7, y: 1 }, { currentLife: 9, baseLife: 9 }); // ally camp → hit
    const b = mkCreature(3, "enemy", { x: 8, y: 3 }, { currentLife: 9, baseLife: 9 }); // ally camp → hit
    const c = mkCreature(4, "enemy", { x: 3, y: 2 }, { currentLife: 9, baseLife: 9 }); // enemy camp → not hit (target ownCamp)
    const s = runTrigger(scenario([dathura, a, b, c]), "APPARITION", 1);
    expect(byId(s, 2)!.currentLife).toBe(6); // count = 3 enemies in play → −3
    expect(byId(s, 3)!.currentLife).toBe(6);
    expect(byId(s, 4)!.currentLife).toBe(9); // enemy in enemy camp untouched
  });

  it("Dathura #909 (APPARITION): hits only the first enemy ahead for (# enemies in play)", () => {
    const dathura = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 909, triggers: card(909).triggers ?? [] });
    const allyBlocker = mkCreature(2, "ally", { x: 5, y: 2 }, {});                     // ally ahead → does not block
    const front = mkCreature(3, "enemy", { x: 4, y: 2 }, { currentLife: 9, baseLife: 9 }); // first enemy ahead
    const behind = mkCreature(4, "enemy", { x: 2, y: 2 }, { currentLife: 9, baseLife: 9 }); // behind the front
    const otherRow = mkCreature(5, "enemy", { x: 3, y: 0 }, { currentLife: 9, baseLife: 9 });
    const s = runTrigger(scenario([dathura, allyBlocker, front, behind, otherRow]), "APPARITION", 1);
    expect(byId(s, 3)!.currentLife).toBe(6); // 3 enemies in play → −3 on the first ahead
    expect(byId(s, 4)!.currentLife).toBe(9); // behind → untouched
    expect(byId(s, 5)!.currentLife).toBe(9); // other row → untouched
  });

  it("Gargoule #818 (APPARITION): its AP cost to every other creature on its row (friendly fire)", () => {
    card(818); // register so the cost (12) resolves in the handler
    const gargoule = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 818, currentLife: 20, baseLife: 20, triggers: card(818).triggers ?? [] });
    const allyRow = mkCreature(2, "ally", { x: 5, y: 2 }, { currentLife: 20, baseLife: 20 });
    const enemyRow = mkCreature(3, "enemy", { x: 4, y: 2 }, { currentLife: 20, baseLife: 20 });
    const offRow = mkCreature(4, "enemy", { x: 6, y: 0 }, { currentLife: 20, baseLife: 20 });
    const s = runTrigger(scenario([gargoule, allyRow, enemyRow, offRow]), "APPARITION", 1);
    expect(byId(s, 2)!.currentLife).toBe(8);  // ally on the row → −12 (friendly fire)
    expect(byId(s, 3)!.currentLife).toBe(8);  // enemy on the row → −12
    expect(byId(s, 4)!.currentLife).toBe(20); // off-row → untouched
    expect(byId(s, 1)!.currentLife).toBe(20); // Gargoule itself → spared
  });

  it("Pisti Yeul #932 (APPARITION): its AT to the single cell in front (a creature)", () => {
    const pisti = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 932, currentAttack: 5, triggers: card(932).triggers ?? [] });
    const front = mkCreature(2, "enemy", { x: 5, y: 2 }, { currentLife: 9, baseLife: 9 });   // directly ahead
    const twoAhead = mkCreature(3, "enemy", { x: 4, y: 2 }, { currentLife: 9, baseLife: 9 }); // Not adjacent
    const s = runTrigger(scenario([pisti, front, twoAhead]), "APPARITION", 1);
    expect(byId(s, 2)!.currentLife).toBe(4); // adjacent enemy → −5 (its AT)
    expect(byId(s, 3)!.currentLife).toBe(9); // two cells ahead → untouched
  });

  it("Pisti Yeul #932 (APPARITION): hits the enemy Dofus when summoned directly in front of it", () => {
    const pisti = mkCreature(1, "ally", { x: 1, y: 2 }, { cardId: 932, currentAttack: 5, triggers: card(932).triggers ?? [] });
    const base = scenario([pisti]);
    // Front cell is x=0,y=2, the enemy Dofus column. Give it room to survive the hit.
    const dofuses: DofusInstance[] = base.dofuses.map((d) =>
      d.owner === "enemy" && d.position.x === 0 && d.position.y === 2 ? { ...d, currentLife: 9 } : d);
    const s = runTrigger({ ...base, dofuses }, "APPARITION", 1);
    expect(s.dofuses.find((d) => d.owner === "enemy" && d.position.y === 2)!.currentLife).toBe(4); // −5
  });

  it("Goultard #304 (MORT): transforms into Dark Vlad #482 on its own cell", () => {
    card(304); card(482);
    const goultard = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 304, currentLife: 1, baseLife: 1, triggers: card(304).triggers ?? [] });
    const base = scenario([goultard]);
    const creatures = base.creatures.map((c) => (c.instanceId === 1 ? { ...c, currentLife: 0 } : c)); // kill Goultard
    const s = resolveDeathsAndWin(base, creatures, base.dofuses, [...base.log], new Set());
    expect(byId(s, 1)).toBeUndefined(); // Goultard culled
    const vlad = s.creatures.find((c) => c.cardId === 482 && c.currentLife > 0);
    expect(vlad).toBeDefined();
    expect(vlad!.position).toEqual({ x: 6, y: 2 }); // appeared on Goultard's cell
    expect(vlad!.owner).toBe("ally");
  });

  it("Goultard #187 (COUP DE GRÂCE): charges its PM; firing APPARITION does not charge", () => {
    const mk = () => mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 187, baseMovement: 2, movementLeft: 0, hasAttacked: true, triggers: card(187).triggers ?? [] });
    const onKill = runTrigger(scenario([mk()]), "COUP_DE_GRACE", 1);
    expect(byId(onKill, 1)!.position).toEqual({ x: 4, y: 2 }); // charged 2 cells forward (6 → 4)
    const onSummon = runTrigger(scenario([mk()]), "APPARITION", 1);
    expect(byId(onSummon, 1)!.position).toEqual({ x: 6, y: 2 }); // APPARITION carries no charge → stays put
  });

  it("Rose Démoniaque #404 (APPARITION): stuns a picked enemy summon for 1 turn", () => {
    const rose = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 404, triggers: card(404).triggers ?? [] });
    const enemy = mkCreature(2, "enemy", { x: 3, y: 2 }, {});
    const opened = runTrigger(scenario([rose, enemy]), "APPARITION", 1);
    expect(opened.pendingAction).toBeTruthy();
    const s = resolvePendingAction(opened, { x: 3, y: 2 });
    expect(byId(s, 2)!.properties.has("Stunned")).toBe(true);
  });

  it("Rose Démoniaque #404 (APPARITION): can stun an ally too (AnySummon)", () => {
    const rose = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 404, triggers: card(404).triggers ?? [] });
    const ally = mkCreature(2, "ally", { x: 6, y: 1 }, {});
    const s = resolvePendingAction(runTrigger(scenario([rose, ally]), "APPARITION", 1), { x: 6, y: 1 });
    expect(byId(s, 2)!.properties.has("Stunned")).toBe(true);
  });

  it("Rose Démoniaque #404: does not stun itself on summon (the flat SetPropertyData is inert)", () => {
    const base = scenario([], 404);
    const s0 = { ...base, players: { ...base.players, ally: { ...base.players.ally, hand: [404], handCostMods: [0], ap: 20, maxAp: 20 } } };
    const s = playCard(s0, card(404), { x: 8, y: 2 }); // no other creature → no stun pick, just lands
    const rose = s.creatures.find((c) => c.cardId === 404);
    expect(rose).toBeDefined();
    expect(rose!.properties.has("Stunned")).toBe(false);
  });

  it("Coffre Tirelire #711 (MORT): drops an ally Butin on the start cell of its row (replacing a prism)", () => {
    card(711);
    const coffre = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 711, currentLife: 1, baseLife: 1, triggers: card(711).triggers ?? [] });
    const base = scenario([coffre]);
    const creatures = base.creatures.map((c) => (c.instanceId === 1 ? { ...c, currentLife: 0 } : c));
    const s = resolveDeathsAndWin(base, creatures, base.dofuses, [...base.log], new Set());
    expect((s.butins ?? []).some((b) => b.position.x === 8 && b.position.y === 2 && b.owner === "ally")).toBe(true);
    expect((s.prisms ?? []).some((p) => p.position.x === 8 && p.position.y === 2)).toBe(false); // prism replaced
  });

  it("Coffre Tirelire #711 (MORT): no Butin if the start cell is blocked by a creature", () => {
    card(711);
    const coffre = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 711, currentLife: 1, baseLife: 1, triggers: card(711).triggers ?? [] });
    const blocker = mkCreature(2, "ally", { x: 8, y: 2 }, {});
    const base = scenario([coffre, blocker]);
    const creatures = base.creatures.map((c) => (c.instanceId === 1 ? { ...c, currentLife: 0 } : c));
    const s = resolveDeathsAndWin(base, creatures, base.dofuses, [...base.log], new Set());
    expect((s.butins ?? []).some((b) => b.position.x === 8 && b.position.y === 2)).toBe(false);
  });

  // --- Regression tests for problems found while checking edge cases ---

  it("Goultard #187: summoning-sick the turn it lands (the stale NoSummoningSickness is stripped)", () => {
    // Real playCard path (the COUP_DE_GRACE test hand-builds the instance and masks this):
    // #187 must not act on summon, its Charge is on the killing blow, not on arrival.
    const base = scenario([], 187);
    const s0 = { ...base, players: { ...base.players, ally: { ...base.players.ally, hand: [187], handCostMods: [0], ap: 20, maxAp: 20 } } };
    const s = playCard(s0, card(187), { x: 8, y: 2 });
    const g = s.creatures.find((c) => c.cardId === 187)!;
    expect(g.properties.has("NoSummoningSickness")).toBe(false);
    expect(g.hasAttacked).toBe(true);  // cannot act the turn it lands (hasAttacked blocks its advance)
    expect(g.movementLeft).toBe(card(187).movement ?? 0); // keeps PM, sickness no longer zeroes it
  });

  it("Gargoule #818 (APPARITION): damage = the PAID cost, so a HORDE discount (playedCostMod) lowers it", () => {
    card(818);
    const gargoule = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 818, currentLife: 20, baseLife: 20, playedCostMod: -2, triggers: card(818).triggers ?? [] });
    const enemyRow = mkCreature(2, "enemy", { x: 4, y: 2 }, { currentLife: 20, baseLife: 20 });
    const s = runTrigger(scenario([gargoule, enemyRow]), "APPARITION", 1);
    expect(byId(s, 2)!.currentLife).toBe(10); // 12 printed − 2 HORDE discount = 10 dealt (not the printed 12)
  });

  it("Coffre #711 (MORT): replacing a start-cell prism fires ON_PRISM reactors (Lilotte #579 charges)", () => {
    card(579); card(711);
    const lilotte = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 579, triggers: card(579).triggers ?? [] });
    const coffre = mkCreature(2, "ally", { x: 6, y: 0 }, { cardId: 711, currentLife: 1, baseLife: 1, triggers: card(711).triggers ?? [] });
    const base = scenario([lilotte, coffre]);
    expect(base.prisms.some((p) => p.position.x === 8 && p.position.y === 0)).toBe(true); // prism on the coffre's start cell
    const creatures = base.creatures.map((c) => (c.instanceId === 2 ? { ...c, currentLife: 0 } : c)); // kill the coffre
    const s = resolveDeathsAndWin(base, creatures, base.dofuses, [...base.log], new Set());
    expect((s.butins ?? []).some((b) => b.position.x === 8 && b.position.y === 0)).toBe(true); // butin replaced the prism
    expect(s.prisms.some((p) => p.position.x === 8 && p.position.y === 0)).toBe(false);
    expect(byId(s, 1)!.position.x).toBe(5); // Lilotte charged 1 cell on the prism removal (6 → 5)
  });

  it("Coffre #711 (MORT): no prism on the start cell → no ON_PRISM reaction", () => {
    card(579); card(711);
    const lilotte = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 579, triggers: card(579).triggers ?? [] });
    const coffre = mkCreature(2, "ally", { x: 6, y: 0 }, { cardId: 711, currentLife: 1, baseLife: 1, triggers: card(711).triggers ?? [] });
    const base0 = scenario([lilotte, coffre]);
    const base = { ...base0, prisms: base0.prisms.filter((p) => !(p.position.x === 8 && p.position.y === 0)) }; // clear the start-cell prism
    const creatures = base.creatures.map((c) => (c.instanceId === 2 ? { ...c, currentLife: 0 } : c));
    const s = resolveDeathsAndWin(base, creatures, base.dofuses, [...base.log], new Set());
    expect((s.butins ?? []).some((b) => b.position.x === 8 && b.position.y === 0)).toBe(true); // butin still drops (free cell)
    expect(byId(s, 1)!.position.x).toBe(6); // no prism removed → Lilotte does not charge
  });
});

describe("Remington Smisse (Bombe à la mort / sur prisme, Roublard)", () => {
  it("#178 (MORT): dépose 1 Bombe alliée sur sa case", () => {
    card(178);
    const remi = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 178, currentLife: 1, baseLife: 1, triggers: card(178).triggers ?? [] });
    const base = { ...scenario([remi]), prisms: [], traps: [] };
    const creatures = base.creatures.map((c) => (c.instanceId === 1 ? { ...c, currentLife: 0 } : c)); // kill Remington
    const s = resolveDeathsAndWin(base, creatures, base.dofuses, [...base.log], new Set());
    expect(byId(s, 1)).toBeUndefined();                  // Remington gone
    expect((s.traps ?? []).length).toBe(1);              // 1 Bombe posée
    expect((s.traps ?? [])[0]).toMatchObject({ position: { x: 6, y: 2 }, owner: "ally", cardId: 101, damage: 2 });
  });

  it("#178 (MORT): un ENNEMI qui marche sur la Bombe subit 2", () => {
    card(178);
    const remi = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 178, currentLife: 1, baseLife: 1, triggers: card(178).triggers ?? [] });
    const base0 = { ...scenario([remi]), prisms: [], traps: [] };
    const creatures = base0.creatures.map((c) => (c.instanceId === 1 ? { ...c, currentLife: 0 } : c));
    const afterDeath = resolveDeathsAndWin(base0, creatures, base0.dofuses, [...base0.log], new Set());
    // Now an enemy advances onto (6,2) where the Bombe (owner ally) sits → −2.
    const enemy = mkCreature(780, "enemy", { x: 4, y: 2 }, { currentLife: 10, baseLife: 10, baseMovement: 2, movementLeft: 2, hasAttacked: false });
    const walkBase = { ...afterDeath, activeSide: "enemy" as const, creatures: [enemy] };
    const s = endTurn(walkBase); // enemy advances 4→5→6, steps on the ally trap
    expect(byId(s, 780)!.currentLife).toBe(8); // −2
    expect((s.traps ?? []).length).toBe(0);    // consumed
  });

  it("#334 (MORT): dépose 2 Bombes autour, priorité haut+bas si libres", () => {
    card(334);
    const remi = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 334, currentLife: 1, baseLife: 1, triggers: card(334).triggers ?? [] });
    const base = { ...scenario([remi]), prisms: [], traps: [] };
    const creatures = base.creatures.map((c) => (c.instanceId === 1 ? { ...c, currentLife: 0 } : c));
    const s = resolveDeathsAndWin(base, creatures, base.dofuses, [...base.log], new Set());
    const traps = s.traps ?? [];
    expect(traps.length).toBe(2);
    expect(traps.every((t) => t.owner === "ally" && t.cardId === 101 && t.damage === 2)).toBe(true);
    // Priorité : haut (6,1) puis bas (6,3), toutes deux libres.
    const cells = traps.map((t) => `${t.position.x},${t.position.y}`).sort();
    expect(cells).toEqual(["6,1", "6,3"]);
  });

  it("#334 (MORT): si une case adjacente (haut) est occupée, bascule sur DEVANT", () => {
    card(334);
    const remi = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 334, currentLife: 1, baseLife: 1, triggers: card(334).triggers ?? [] });
    const blocker = mkCreature(2, "ally", { x: 6, y: 1 }, {}); // occupe la case HAUT (6,1)
    const base = { ...scenario([remi, blocker]), prisms: [], traps: [] };
    const creatures = base.creatures.map((c) => (c.instanceId === 1 ? { ...c, currentLife: 0 } : c));
    const s = resolveDeathsAndWin(base, creatures, base.dofuses, [...base.log], new Set());
    const traps = s.traps ?? [];
    expect(traps.length).toBe(2);
    // Haut occupé → priorité [bas (6,3), devant (allié avance x-1 → 5,2)].
    const cells = traps.map((t) => `${t.position.x},${t.position.y}`).sort();
    expect(cells).toEqual(["5,2", "6,3"]);
  });

  it("#80 (APPARITION): pick d'un prisme → prisme retiré, Bombe alliée sur sa case", () => {
    card(80);
    const remi = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 80, triggers: card(80).triggers ?? [] });
    const base = { ...scenario([remi]), traps: [], prisms: [{ position: { x: 4, y: 1 }, owner: "enemy" as const, kind: "ap" as const }] };
    const pend = runTrigger(base, "APPARITION", 1);
    expect(pend.pendingAction).not.toBeNull();
    expect(pend.pendingAction!.filter).toBe("any_prism");
    const s = resolvePendingAction(pend, { x: 4, y: 1 }); // on choisit le prisme (camp ennemi)
    expect(s.prisms.some((p) => p.position.x === 4 && p.position.y === 1)).toBe(false); // prisme retiré
    expect((s.traps ?? []).length).toBe(1);
    // Bombe in Remington's camp (owner ally) whatever the prism's camp.
    expect((s.traps ?? [])[0]).toMatchObject({ position: { x: 4, y: 1 }, owner: "ally", cardId: 101, damage: 2 });
  });
});

describe("Milkar #46, bare 'Charge' under both APPARITION and COUP DE GRÂCE", () => {
  // Milkar's text is "APPARITION : Charge\nCOUP DE GRÂCE : Charge", a bare Charge
  // keyword under two triggers. The merge only wired the first one (APPARITION),
  // leaving COUP_DE_GRACE an empty (dead) trigger. charge_keyword_triggers now injects
  // a ChargeSelf on each trigger carrying a bare Charge.
  it("#46 Milkar: COUP DE GRÂCE charges its full PM (the previously-dead trigger)", () => {
    const milkar = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 46, baseMovement: 2, movementLeft: 0, triggers: card(46).triggers ?? [] });
    const s = runTrigger(scenario([milkar]), "COUP_DE_GRACE", 1);
    expect(byId(s, 1)!.position.x).toBe(4); // charged its 2 PM forward (6 → 4)
  });
  it("#46 Milkar: tuer PENDANT sa charge d'APPARITION déclenche le COUP DE GRÂCE", () => {
    // Reported: Milkar kills its target on its APPARITION charge but did not charge again. The charge
    // (trigger) went through runTrigger, which did not fire the COUP DE GRÂCE on its own kills. Milkar at
    // (7,2) charges 2 → (5,2), kills the adjacent prey at (4,2), then COUP DE GRÂCE: Charge 2 → (3,2).
    const milkar = mkCreature(1, "ally", { x: 7, y: 2 }, { cardId: 46, baseMovement: 2, movementLeft: 0, currentLife: 7, currentAttack: 7, triggers: card(46).triggers ?? [] });
    const prey = mkCreature(2, "enemy", { x: 4, y: 2 }, { cardId: 149, currentLife: 1, currentAttack: 1, baseMovement: 1 });
    const s = runTrigger(scenario([milkar, prey]), "APPARITION", 1);
    expect(byId(s, 2)).toBeUndefined(); // proie tuée sur la charge
    expect(byId(s, 1)!.position.x).toBe(3); // without the coup de grâce, Milkar would stay stuck at x=5
  });
  it("#46 Milkar: APPARITION charge toujours (charge imposée par effet), mais a désormais le mal d'invocation", () => {
    const milkar = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 46, baseMovement: 2, movementLeft: 0, triggers: card(46).triggers ?? [] });
    const s = runTrigger(scenario([milkar]), "APPARITION", 1);
    expect(byId(s, 1)!.position.x).toBe(4); // charge toujours ses 2 PM (6 → 4) malgré le mal d'invocation
    expect((card(46).properties ?? [])).not.toContain("NoSummoningSickness"); // plus de Charge persistante (règle mal d'invocation)
  });
});

describe("Grougaloragran fix + coverage", () => {
  // #397 Grougaloragran: "Tant qu'il est en jeu, vos Dofus sont invulnérables." The bindata mis-baked
  // SetPropertyData Invulnerable on Grougal HIMSELF (an unkillable 9 PA 6/6). The merge now rewrites it
  // into an innate ProtectsOwnDofus property → a passive aura over all the owner's Dofus (no pick),
  // reusing the Artheon #1424 dofusInvulnerable machinery; Grougal himself is killable again.
  it("#397 Grougaloragran: all your Dofus are invulnerable while he lives, vulnerable again when he dies", () => {
    const grougal = mkCreature(700, "ally", { x: 8, y: 2 }, { cardId: 397, properties: new Set(["ProtectsOwnDofus"]) });
    const d1: DofusInstance = { position: { x: 0, y: 2 }, owner: "ally", currentLife: 5, kind: "real" };
    const d2: DofusInstance = { position: { x: 0, y: 0 }, owner: "ally", currentLife: 5, kind: "real" };
    const creatures = [grougal];
    const dofuses = [d1, d2];
    // an enemy AoE that hits every ally Dofus, all of them are skipped while Grougal lives (no pick).
    applyEffects(creatures, dofuses, [], [{ type: "AoeDamageDofus", amount: 3 }], { casterSide: "enemy" } as never);
    expect(dofuses[0].currentLife).toBe(5);
    expect(dofuses[1].currentLife).toBe(5);
    // Grougal dies → the aura lapses (the check re-reads "still alive") → the same AoE now lands.
    creatures[0].currentLife = 0;
    applyEffects(creatures, dofuses, [], [{ type: "AoeDamageDofus", amount: 3 }], { casterSide: "enemy" } as never);
    expect(dofuses[0].currentLife).toBe(2);
    expect(dofuses[1].currentLife).toBe(2);
  });
  it("#397 Grougaloragran: summoned with ProtectsOwnDofus (not self-Invulnerable) → he is killable", () => {
    expect((card(397).effects ?? []).some((e) => (e as { type: string; PropertyType?: string }).type === "SetPropertyData" && (e as { PropertyType?: string }).PropertyType === "ProtectsOwnDofus")).toBe(true);
    expect((card(397).effects ?? []).some((e) => (e as { PropertyType?: string }).PropertyType === "Invulnerable")).toBe(false); // the mis-bake is gone
    const base = scenario([], 397);
    const s0 = { ...base, prisms: [], players: { ...base.players, ally: { ...base.players.ally, hand: [397], handCostMods: [0], ap: 10, maxAp: 10 } } };
    const s = playCard(s0, card(397), { x: 8, y: 2 });
    const grougal = s.creatures.find((c) => c.cardId === 397)!;
    expect(grougal.properties.has("ProtectsOwnDofus")).toBe(true);
    expect(grougal.properties.has("Invulnerable")).toBe(false); // killable, unlike the old self-Invulnerable bake
  });

  // Coverage for cards that already worked but had no test (the mechanics are already tested through
  // similar cards).
  it("#777 Arpagone: costs 1 PA less per enemy invocation in play (allies do not count)", () => {
    const arpa = card(777);
    const none = scenario([], 777);
    expect(effectiveCost(none.players.ally, arpa, none.creatures)).toBe(9); // no enemies → printed 9
    const e1 = mkCreature(1, "enemy", { x: 3, y: 2 }, { cardId: 44 });
    const e2 = mkCreature(2, "enemy", { x: 4, y: 1 }, { cardId: 44 });
    const ally = mkCreature(3, "ally", { x: 6, y: 2 }, { cardId: 6 }); // an ally must not count
    const board = scenario([e1, e2, ally], 777);
    expect(effectiveCost(board.players.ally, arpa, board.creatures)).toBe(7); // 9 − 1×2 enemies
  });
  it("#310 Goultard le Barbare: INITIATIVE + CHEF gives other allies +2 AT and +1 PM (not himself)", () => {
    card(310);
    const ally = mkCreature(60, "ally", { x: 6, y: 2 }, { currentAttack: 2, baseAttack: 2, baseMovement: 3 });
    let s = scenario([ally], 310);
    s = { ...s, prisms: [], players: { ...s.players, ally: { ...s.players.ally, ap: 10, maxAp: 10 } } };
    s = playCard(s, card(310), { x: 8, y: 2 }); // summon Goultard (CHEF +2 AT / +1 PM to other allies)
    const goultard = s.creatures.find((c) => c.cardId === 310)!;
    expect(goultard.properties.has("FirstStrike")).toBe(true); // INITIATIVE
    expect(byId(s, 60)!.currentAttack).toBe(4);  // ally +2 AT (2 → 4)
    expect(byId(s, 60)!.baseMovement).toBe(4);   // ally +1 PM (3 → 4)
    expect(goultard.currentAttack).toBe(card(310).attack ?? 0); // "autres" → Goultard does not buff himself
  });
  it("#1490 Protecteur Nimbos: +2 AR par AUTRE invocation alliée, ne se compte PAS lui-même", () => {
    card(1490); card(40);
    // placed alone → +0 AR (excludeSelf; before the fix it counted itself → +2)
    const aloneBase = scenario([], 1490);
    const a0 = { ...aloneBase, prisms: [], players: { ...aloneBase.players, ally: { ...aloneBase.players.ally, hand: [1490], handCostMods: [0], ap: 10, maxAp: 10 } } };
    const alone = playCard(a0, card(1490), { x: 8, y: 2 });
    expect(alone.creatures.find((c) => c.cardId === 1490)!.armor).toBe(0);
    // 2 AUTRES alliés en jeu → +4 AR (2 × 2, pas 3 × 2)
    const o1 = mkCreature(1, "ally", { x: 6, y: 1 }, { cardId: 40 });
    const o2 = mkCreature(2, "ally", { x: 6, y: 0 }, { cardId: 40 });
    const base = scenario([o1, o2], 1490, 40);
    const s0 = { ...base, prisms: [], players: { ...base.players, ally: { ...base.players.ally, hand: [1490], handCostMods: [0], ap: 10, maxAp: 10 } } };
    let s = playCard(s0, card(1490), { x: 8, y: 2 });
    if (s.pendingAction) s = resolvePendingAction(s, o1.position); // GuardCreature : protège un allié
    expect(s.creatures.find((c) => c.cardId === 1490)!.armor).toBe(4);
  });
});

describe("Self-count « par <famille> allié en jeu », ne compte PAS la source", () => {
  // Decided card by card: "par X allié" (without "autre") now excludes the source. Edge case that shows
  // the fix: placed alone (no other member), the bonus is 0 (before: +per, because the source, a member
  // of the family, counted itself).
  it("#177 Tofu Dominant: +1 AT par AUTRE Tofu allié, posé seul = +0 AT", () => {
    card(177);
    const base = scenario([], 177);
    const s0 = { ...base, prisms: [], players: { ...base.players, ally: { ...base.players.ally, hand: [177], handCostMods: [0], ap: 10, maxAp: 10 } } };
    const s = playCard(s0, card(177), { x: 8, y: 2 });
    expect(s.creatures.find((c) => c.cardId === 177)!.currentAttack).toBe(card(177).attack ?? 0); // +0 (était +1)
  });
  it("#364 Scaramel: +2 AR par AUTRE Scara allié, posé seul = +0 AR", () => {
    card(364);
    const base = scenario([], 364);
    const s0 = { ...base, prisms: [], players: { ...base.players, ally: { ...base.players.ally, hand: [364], handCostMods: [0], ap: 10, maxAp: 10 } } };
    const s = playCard(s0, card(364), { x: 8, y: 2 });
    expect(s.creatures.find((c) => c.cardId === 364)!.armor).toBe(0); // +0 (était +2)
  });
  it("#433 Chauve Souris Dodue: +1 AT par AUTRE Goule allié, posée seule = +0 AT", () => {
    card(433);
    const base = scenario([], 433);
    const s0 = { ...base, prisms: [], players: { ...base.players, ally: { ...base.players.ally, hand: [433], handCostMods: [0], ap: 10, maxAp: 10 } } };
    const s = playCard(s0, card(433), { x: 8, y: 2 });
    expect(s.creatures.find((c) => c.cardId === 433)!.currentAttack).toBe(card(433).attack ?? 0); // +0 (était +1)
  });
  it("#327 Requin Marteau: +2 AT par invocation BLESSÉE, posé seul (rien de blessé) = +0 AT", () => {
    // Not an excludeSelf case (scope "all") but the same double wiring: a raw +2 BoostAttackData was
    // applied on top of the count → +2 even with no wounded target. The flat one is removed.
    card(327);
    const base = scenario([], 327);
    const s0 = { ...base, prisms: [], players: { ...base.players, ally: { ...base.players.ally, hand: [327], handCostMods: [0], ap: 10, maxAp: 10 } } };
    const s = playCard(s0, card(327), { x: 8, y: 2 });
    expect(s.creatures.find((c) => c.cardId === 327)!.currentAttack).toBe(card(327).attack ?? 0); // +0 (le flat brut +2 retiré)
  });
});

describe("Cartes neutres : implémentations", () => {
  it("#456 Grand Craqueleur Chuchoté (MORT): invoque 1 Chuchoteur Arbalétrier #201 sur sa case de mort", () => {
    card(456); card(201);
    const gcc = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 456, currentLife: 1, baseLife: 1, triggers: card(456).triggers ?? [] });
    const base = scenario([gcc]);
    const creatures = base.creatures.map((c) => (c.instanceId === 1 ? { ...c, currentLife: 0 } : c)); // tue le Grand Craqueleur
    const s = resolveDeathsAndWin(base, creatures, base.dofuses, [...base.log], new Set());
    expect(byId(s, 1)).toBeUndefined(); // culled
    const chu = s.creatures.filter((c) => c.cardId === 201 && c.currentLife > 0);
    expect(chu.length).toBe(1);                       // only 1
    expect(chu[0].position).toEqual({ x: 6, y: 2 });  // sur sa case de mort
    expect(chu[0].owner).toBe("ally");
  });

  // #523 Excarnus, "Vos autres Bouftous remontent dans votre main quand ils meurent."
  const emptyHandDiscard = (s: ReturnType<typeof scenario>) => ({ ...s, players: { ...s.players, ally: { ...s.players.ally, hand: [], handCostMods: [], discard: [] } } });
  it("#523 Excarnus: un AUTRE Bouftou allié revient en main à sa mort (Excarnus vivant)", () => {
    card(523); card(40);
    const excarnus = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 523 });
    const bouftou = mkCreature(2, "ally", { x: 6, y: 1 }, { cardId: 40 }); // Bouftou Noir (Gobbal)
    const s0 = emptyHandDiscard(scenario([excarnus, bouftou]));
    const creatures = s0.creatures.map((c) => (c.instanceId === 2 ? { ...c, currentLife: 0 } : c)); // tue le Bouftou
    const s = resolveDeathsAndWin(s0, creatures, s0.dofuses, [...s0.log], new Set());
    expect(byId(s, 2)).toBeUndefined();
    expect(s.players.ally.hand).toContain(40);        // revenu en main
    expect(s.players.ally.discard).not.toContain(40); // pas en défausse
  });
  it("#523 Excarnus: Excarnus SEUL va en DÉFAUSSE à sa mort (« autres » → pas lui-même)", () => {
    card(523);
    const excarnus = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 523 });
    const s0 = emptyHandDiscard(scenario([excarnus]));
    const creatures = s0.creatures.map((c) => ({ ...c, currentLife: 0 }));
    const s = resolveDeathsAndWin(s0, creatures, s0.dofuses, [...s0.log], new Set());
    expect(s.players.ally.hand).not.toContain(523);   // PAS en main
    expect(s.players.ally.discard).toContain(523);    // en défausse
  });
  it("#523 Excarnus: 2 Excarnus alliés, l'un meurt → revient en MAIN (couvert par l'autre vivant)", () => {
    card(523);
    const e1 = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 523 });
    const e2 = mkCreature(2, "ally", { x: 6, y: 1 }, { cardId: 523 });
    const s0 = emptyHandDiscard(scenario([e1, e2]));
    const creatures = s0.creatures.map((c) => (c.instanceId === 1 ? { ...c, currentLife: 0 } : c)); // tue e1
    const s = resolveDeathsAndWin(s0, creatures, s0.dofuses, [...s0.log], new Set());
    expect(byId(s, 1)).toBeUndefined();
    expect(s.players.ally.hand).toContain(523);       // e1 revient en main (e2 vivant le couvre)
  });
  it("#523 SALVE : Excarnus et un Bouftou meurent EN MÊME TEMPS → le Bouftou revient quand même en main", () => {
    card(523); card(40);
    // The marker is judged at the moment of death: Excarnus dead in the same volley still covers.
    const excarnus = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 523, currentLife: 0, baseLife: 5 });
    const bouftou = mkCreature(2, "ally", { x: 6, y: 1 }, { cardId: 40, currentLife: 0, baseLife: 2 });
    const s0 = emptyHandDiscard(scenario([excarnus, bouftou]));
    const s = resolveDeathsAndWin(s0, s0.creatures, s0.dofuses, [...s0.log], new Set());
    expect(s.players.ally.hand).toContain(40);        // le Bouftou revient en main
    expect(s.players.ally.discard).toContain(523);    // Excarnus itself: nobody covers it → discard
  });
  it("#523 SALVE : DEUX Excarnus meurent ensemble → ils se couvrent MUTUELLEMENT, les deux reviennent en main", () => {
    card(523);
    const e1 = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 523, currentLife: 0, baseLife: 5 });
    const e2 = mkCreature(2, "ally", { x: 6, y: 1 }, { cardId: 523, currentLife: 0, baseLife: 5 });
    const s0 = emptyHandDiscard(scenario([e1, e2]));
    const s = resolveDeathsAndWin(s0, s0.creatures, s0.dofuses, [...s0.log], new Set());
    expect(s.players.ally.hand.filter((id) => id === 523).length).toBe(2); // each one is "un autre Bouftou" for the other
    expect(s.players.ally.discard).not.toContain(523);
  });

  it("#893 Goule Dorak: APPARITION bannit les Goules de la défausse + gagne +N AT/+N AR (N = bannies ; non-Goule intact)", () => {
    card(893); card(132); card(77); card(453);
    const base = scenario([], 893);
    const s0 = { ...base, prisms: [], players: { ...base.players, ally: { ...base.players.ally, hand: [893], handCostMods: [0], ap: 10, maxAp: 10, discard: [132, 77, 453], banished: [] } } };
    const s = playCard(s0, card(893), { x: 8, y: 2 });
    const dorak = s.creatures.find((c) => c.cardId === 893)!;
    expect(dorak.currentAttack).toBe((card(893).attack ?? 0) + 2); // +2 AT (2 Goules : #132, #77)
    expect(dorak.armor).toBe(2);                                   // +2 AR
    expect(s.players.ally.discard).toEqual([453]);                 // le Tofu #453 reste
    expect(s.players.ally.banished).toEqual(expect.arrayContaining([132, 77])); // Goules bannies
  });
});

describe("Otomaï #447 : tirage MORT reproductible sur le VRAI chemin de mort", () => {
  // In a real game, MORTs go through resolveDeathsAndWin (not runTrigger). Before the fix, this path
  // built the MORT context with no rng, so handleTransformAll fell back to Math.random (could not be
  // reproduced, broke sims/replays). Otomaï is really killed (currentLife→0) and resolved twice with the
  // same seed: the cost-5 draws must be the same.
  const setup = (seed: number) => {
    const ally = mkCreature(60, "ally", { x: 6, y: 1 }, { cardId: 40 }); // Bouftou Noir (coût 2)
    const foe = mkCreature(61, "enemy", { x: 4, y: 2 }, { cardId: 69 });  // Gelée Encre
    const oto = mkCreature(62, "ally", { x: 6, y: 3 }, { cardId: 447, triggers: card(447).triggers ?? [] });
    return { ...scenario([ally, foe, oto]), rng: seed };
  };
  it("transforme les autres en invoc. coût-5 ET de façon reproductible (resolveDeathsAndWin)", () => {
    const kill = (seed: number) => {
      const base = setup(seed);
      const creatures = base.creatures.map((c) => (c.instanceId === 62 ? { ...c, currentLife: 0 } : { ...c, position: { ...c.position } }));
      return resolveDeathsAndWin(base, creatures, base.dofuses.map((d) => ({ ...d, position: { ...d.position } })), [], new Set());
    };
    const a = kill(2024);
    const b = kill(2024);
    expect(card(byId(a, 60)!.cardId).cost).toBe(5); // the transform did happen on the real path
    expect(card(byId(a, 61)!.cardId).cost).toBe(5);
    expect([byId(a, 60)!.cardId, byId(a, 61)!.cardId])
      .toEqual([byId(b, 60)!.cardId, byId(b, 61)!.cardId]); // même graine → mêmes tirages (seedé)
  });
});

describe("Otomaï #447 : le MORT transform stoppe le sweep", () => {
  // The disciple that kills Otomaï at end of turn is itself transformed at the moment of its death: it
  // stops (no break-through, does not capture the Dofus) and the rest of the invocations that were
  // going to play in this sweep do not play (they are all going to be transformed). The cost-5 draw
  // happens after death in resolveDeathsAndWin.
  const dof = (x: number, y: number, owner: "ally" | "enemy", life = 5): DofusInstance =>
    ({ position: { x, y }, owner, currentLife: life, kind: "real" as const });
  const build = (seed: number) => {
    const oto = mkCreature(70, "ally", { x: 8, y: 2 }, { cardId: 447, triggers: card(447).triggers ?? [], currentLife: 2, baseLife: 6 });
    const killer = mkCreature(71, "enemy", { x: 7, y: 2 }, { movementLeft: 3, baseMovement: 3, hasAttacked: false, currentAttack: 5, currentLife: 10, baseLife: 10 });
    const trailer = mkCreature(72, "enemy", { x: 2, y: 4 }, { movementLeft: 3, baseMovement: 3, hasAttacked: false, currentAttack: 1, currentLife: 5, baseLife: 5 });
    const dofuses = [dof(9, 0, "ally"), dof(9, 2, "ally"), dof(9, 4, "ally"), dof(0, 0, "enemy"), dof(0, 2, "enemy"), dof(0, 4, "enemy")];
    return withDecks({ ...scenario([oto, killer, trailer]), prisms: [], dofuses, activeSide: "enemy" as const, rng: seed });
  };
  it("le tueur s'arrête sur place et NE capture PAS le Dofus (aucune percée)", () => {
    const s = endTurn(build(2024));
    expect(byId(s, 71)!.position).toEqual({ x: 7, y: 2 });                       // resté sur sa case, pas de (8,2)/(9,2)
    expect(s.dofuses.find((d) => d.owner === "ally" && d.position.y === 2)!.currentLife).toBe(5); // Dofus intact
  });
  it("le tueur ET l'invocation restante sont transformés en coût-5 et n'ont pas avancé", () => {
    const s = endTurn(build(2024));
    expect(card(byId(s, 71)!.cardId).cost).toBe(5);      // le tueur transformé
    expect(card(byId(s, 72)!.cardId).cost).toBe(5);      // l'autre aussi
    expect(byId(s, 72)!.position).toEqual({ x: 2, y: 4 }); // it did not play its turn (sweep cancelled)
  });
});

describe("Trool #229 : APPARITION repousse une invocation de 3 cases (any_creature)", () => {
  it("repousse une invocation ENNEMIE de 3 cases vers son mur (x décroissant)", () => {
    card(229);
    const trool = mkCreature(400, "ally", { x: 8, y: 4 }, { cardId: 229, triggers: card(229).triggers ?? [] });
    const enemy = mkCreature(401, "enemy", { x: 4, y: 2 }, { currentLife: 5, baseLife: 5 });
    let s = runTrigger(scenario([trool, enemy]), "APPARITION", 400);
    expect(s.pendingAction).toBeTruthy(); // pick « Choisissez une invocation à repousser »
    s = resolvePendingAction(s, { x: 4, y: 2 });
    expect(byId(s, 401)!.position).toEqual({ x: 1, y: 2 }); // 4 → 1 (3 cases vers le mur ennemi x=0)
  });
  it("peut aussi repousser un ALLIÉ (any_creature, aucune restriction de camp) vers son mur (x croissant)", () => {
    card(229);
    const trool = mkCreature(402, "ally", { x: 8, y: 4 }, { cardId: 229, triggers: card(229).triggers ?? [] });
    const ally = mkCreature(403, "ally", { x: 5, y: 1 }, { currentLife: 5, baseLife: 5 });
    let s = runTrigger(scenario([trool, ally]), "APPARITION", 402);
    s = resolvePendingAction(s, { x: 5, y: 1 });
    expect(byId(s, 403)!.position).toEqual({ x: 8, y: 1 }); // 5 → 8 (3 cases vers le mur allié x=9)
  });
  it("s'arrête sur le 1er obstacle (créature) avant les 3 cases", () => {
    card(229);
    const trool = mkCreature(404, "ally", { x: 8, y: 4 }, { cardId: 229, triggers: card(229).triggers ?? [] });
    const pushed = mkCreature(405, "enemy", { x: 4, y: 2 }, { currentLife: 5, baseLife: 5 });
    const wall = mkCreature(460, "enemy", { x: 2, y: 2 }, { currentLife: 5, baseLife: 5 });
    let s = runTrigger(scenario([trool, pushed, wall]), "APPARITION", 404);
    s = resolvePendingAction(s, { x: 4, y: 2 });
    expect(byId(s, 405)!.position).toEqual({ x: 3, y: 2 }); // 4 → 3, blocked by the creature at x=2
  });
});

describe("Sir Comte Flex #406 : un de VOS Dofus blessé → le Dofus adverse de sa ligne en subit autant", () => {
  const dof = (x: number, y: number, owner: "ally" | "enemy", life = 5): DofusInstance =>
    ({ position: { x, y }, owner, currentLife: life, kind: "real" });
  it("reflète le montant sur le Dofus ennemi de la MÊME ligne (woundDofus, le chokepoint)", () => {
    card(406);
    const flex = mkCreature(500, "ally", { x: 7, y: 2 }, { cardId: 406 });
    const dofuses = [dof(9, 2, "ally", 5), dof(0, 2, "enemy", 5), dof(0, 1, "enemy", 5)];
    woundDofus(dofuses[0], 2, [], [flex], dofuses);
    expect(dofuses[0].currentLife).toBe(3);                                              // Dofus allié −2
    expect(dofuses.find((d) => d.owner === "enemy" && d.position.y === 2)!.currentLife).toBe(3); // ennemi même ligne −2 (miroir)
    expect(dofuses.find((d) => d.owner === "enemy" && d.position.y === 1)!.currentLife).toBe(5); // autre ligne intacte
  });
  it("fizzle s'il n'y a aucun Dofus adverse sur la ligne", () => {
    card(406);
    const flex = mkCreature(501, "ally", { x: 7, y: 0 }, { cardId: 406 });
    const dofuses = [dof(9, 0, "ally", 5), dof(0, 1, "enemy", 5)]; // pas d'ennemi en ligne 0
    woundDofus(dofuses[0], 3, [], [flex], dofuses);
    expect(dofuses[1].currentLife).toBe(5);
  });
  it("ne boucle PAS si les deux camps ont un Sir Comte Flex (garde anti-chaîne isMirror)", () => {
    card(406);
    const allyFlex = mkCreature(502, "ally", { x: 7, y: 2 }, { cardId: 406 });
    const enemyFlex = mkCreature(503, "enemy", { x: 2, y: 2 }, { cardId: 406 });
    const dofuses = [dof(9, 2, "ally", 5), dof(0, 2, "enemy", 5)];
    woundDofus(dofuses[0], 2, [], [allyFlex, enemyFlex], dofuses);
    expect(dofuses[0].currentLife).toBe(3); // allié −2 (dégât original)
    expect(dofuses[1].currentLife).toBe(3); // ennemi −2 (miroir UNIQUE), pas −4 (pas de re-miroir)
  });
  it("#956 Héros Martyr: un Dofus allié DÉTRUIT inflige 3 aux invocations adverses (rien sur simple dégât)", () => {
    card(956);
    const martyr = mkCreature(510, "ally", { x: 8, y: 2 }, { cardId: 956 });
    const enemyC = mkCreature(511, "enemy", { x: 3, y: 2 }, { currentLife: 5, baseLife: 5 });
    // simple dégât → pas de réaction
    const d1 = [dof(9, 2, "ally", 5), dof(0, 2, "enemy", 5)];
    woundDofus(d1[0], 2, [], [martyr, enemyC], d1);
    expect(d1[0].currentLife).toBe(3);
    expect(enemyC.currentLife).toBe(5); // intact
    // destruction → 3 aux invocations adverses
    const d2 = [dof(9, 2, "ally", 5), dof(0, 2, "enemy", 5)];
    woundDofus(d2[0], 5, [], [martyr, enemyC], d2);
    expect(d2[0].currentLife).toBe(0);
    expect(enemyC.currentLife).toBe(2); // 5 - 3
  });
  it("#189 Punition: sacrifie ton Dofus (1er pick) puis inflige 3 à un Dofus adverse (2e pick)", () => {
    card(189);
    const s0 = scenario([]);
    const myDof = s0.dofuses.find((d) => d.owner === "ally")!;
    const foeDof = s0.dofuses.find((d) => d.owner === "enemy")!;
    const foeLife = foeDof.currentLife;
    let s = { ...s0, activeSide: "ally" as const, players: { ...s0.players, ally: { ...s0.players.ally, hand: [189], handCostMods: [0], ap: 20, maxAp: 20 } } };
    s = playCard(s, card(189), { ...myDof.position }); // 1er pick = ton Dofus
    expect(s.pendingAction!.filter).toBe("enemy_dofus");
    s = resolvePendingAction(s, { ...foeDof.position }); // 2e pick = Dofus adverse
    const foeAfter = s.dofuses.find((d) => d.owner === "enemy" && d.position.x === foeDof.position.x && d.position.y === foeDof.position.y);
    expect(foeAfter!.currentLife).toBe(foeLife - 3); // Dofus adverse −3
    const myAfter = s.dofuses.find((d) => d.owner === "ally" && d.position.x === myDof.position.x && d.position.y === myDof.position.y);
    expect(myAfter == null || myAfter.currentLife <= 0).toBe(true); // ton Dofus sacrifié
  });
  it("via un sort qui touche un Dofus allié (DamageData dofusTargetable) → miroir bout-en-bout", () => {
    card(406);
    const flex = mkCreature(504, "ally", { x: 7, y: 3 }, { cardId: 406 });
    const creatures = [flex];
    const dofuses = [dof(9, 3, "ally", 5), dof(0, 3, "enemy", 5)];
    applyEffects(creatures, dofuses, [], [{ type: "DamageData", Damage: 2 }], { casterSide: "enemy", targetCell: { x: 9, y: 3 }, dofusTargetable: true });
    expect(dofuses[0].currentLife).toBe(3); // Dofus allié touché −2
    expect(dofuses[1].currentLife).toBe(3); // Dofus ennemi de la ligne −2 (miroir)
  });
});

describe("Toutancoffron #633 : transforme en Butin allié les invocations qu'il détruit", () => {
  it("un kill en combat pose un Butin allié sur la case libérée par la victime", () => {
    const tout = mkCreature(600, "ally", { x: 5, y: 2 }, { cardId: 633, currentAttack: 6, baseAttack: 6, currentLife: 3, baseLife: 3, movementLeft: 3, baseMovement: 3, hasAttacked: false, triggers: card(633).triggers ?? [] });
    const victim = mkCreature(601, "enemy", { x: 4, y: 2 }, { cardId: 6, currentAttack: 1, baseAttack: 1, currentLife: 2, baseLife: 5 });
    const s = endTurn(scenario([tout, victim]));
    expect(byId(s, 601)).toBeUndefined(); // victime morte
    expect((s.butins ?? []).some((b) => b.owner === "ally" && b.position.x === 4 && b.position.y === 2)).toBe(true);
  });
  it("pas de Butin si Toutancoffron meurt dans l'échange (il doit survivre, convention COUP DE GRÂCE)", () => {
    const tout = mkCreature(602, "ally", { x: 5, y: 2 }, { cardId: 633, currentAttack: 6, baseAttack: 6, currentLife: 2, baseLife: 3, movementLeft: 3, baseMovement: 3, hasAttacked: false, triggers: card(633).triggers ?? [] });
    const victim = mkCreature(603, "enemy", { x: 4, y: 2 }, { cardId: 6, currentAttack: 6, baseAttack: 6, currentLife: 2, baseLife: 5 }); // échange mortel : les deux meurent
    const s = endTurn(scenario([tout, victim]));
    expect(byId(s, 602)).toBeUndefined();        // Toutancoffron mort aussi
    expect((s.butins ?? []).length).toBe(0);     // no Butin (the killer did not survive)
  });
});

describe("#1300/#1643 : une percée/capture ennemie ne compte PAS comme une mort (HandCostOnEvent)", () => {
  it("#1300 Galantine : une invoc. ennemie qui MEURT réduit le coût en main (−1), mais PAS une qui PERCE (brokeThroughIds)", () => {
    card(1300);
    const mk = () => {
      const enemy = mkCreature(700, "enemy", { x: 3, y: 2 }, { currentLife: 0, baseLife: 5 });
      const sc = scenario([enemy]);
      return { ...sc, players: { ...sc.players, ally: { ...sc.players.ally, hand: [1300], handCostMods: [0] } } };
    };
    // mort normale d'une invocation ennemie → −1
    const a = mk();
    const rA = resolveDeathsAndWin(a, a.creatures.map((c) => ({ ...c })), a.dofuses.map((d) => ({ ...d })), [], new Set());
    expect(rA.players.ally.handCostMods[0]).toBe(-1);
    // same invocation, but it broke through/captured (brokeThroughIds) → 0 (a capture is not a death, like the HORDE discount)
    const b = mk();
    const rB = resolveDeathsAndWin(b, b.creatures.map((c) => ({ ...c })), b.dofuses.map((d) => ({ ...d })), [], new Set([700]));
    expect(rB.players.ally.handCostMods[0]).toBe(0);
  });
  // An invocation that destroys a Dofus and goes back to the deck is not a death: no death effect fires
  // (not its MORT, not the MORT ADVERSE/ALLIÉE of others, not the "quand une invocation meurt"
  // counters). Checked here through Eliacube #250 (reserve on death).
  it("Eliacube #250 : une invoc. qui MEURT alimente la réserve (+1), mais PAS une qui PERCE/capture", () => {
    card(250);
    const mk = () => {
      const eliacube = mkCreature(950, "ally", { x: 7, y: 2 }, { cardId: 250, currentLife: 5, baseLife: 5 });
      const enemy = mkCreature(951, "enemy", { x: 3, y: 2 }, { currentLife: 0, baseLife: 5 });
      return scenario([eliacube, enemy]);
    };
    // normal death of an invocation (any camp) → the allied Eliacube adds 1 PA to the reserve
    const a = mk();
    const baseRes = a.players.ally.apReserve;
    const rA = resolveDeathsAndWin(a, a.creatures.map((c) => ({ ...c })), a.dofuses.map((d) => ({ ...d })), [], new Set());
    expect(rA.players.ally.apReserve).toBe(baseRes + 1);
    // capture/break-through (brokeThroughIds) → not a death: the reserve does not move
    const b = mk();
    const rB = resolveDeathsAndWin(b, b.creatures.map((c) => ({ ...c })), b.dofuses.map((d) => ({ ...d })), [], new Set([951]));
    expect(rB.players.ally.apReserve).toBe(baseRes);
  });
});

describe("Masse #207 : létalité symétrique (attaque ET contre-attaque), sur dégâts NON NULS", () => {
  it("tue un ennemi qu'il blesse en CONTRE-ATTAQUE (défenseur), si un autre Justicier est en jeu", () => {
    const masse = mkCreature(800, "ally", { x: 5, y: 2 }, { cardId: 207, currentAttack: 1, baseAttack: 1, currentLife: 9, baseLife: 9 });
    const otherJusticier = mkCreature(801, "ally", { x: 7, y: 0 }, { cardId: 207 }); // un AUTRE Justicier allié
    const enemy = mkCreature(802, "enemy", { x: 4, y: 2 }, { currentLife: 5, baseLife: 5, currentAttack: 3, baseAttack: 3, movementLeft: 3, baseMovement: 3, hasAttacked: false });
    const s = endTurn({ ...scenario([masse, otherJusticier, enemy]), activeSide: "enemy" as const });
    expect(byId(s, 802)).toBeUndefined(); // the enemy survived the counter (1 damage out of 5) but dies from the lethality
  });
  it("ne tue PAS si le coup est entièrement absorbé par la Résistance (0 dégât = pas blessé)", () => {
    const masse = mkCreature(810, "ally", { x: 5, y: 2 }, { cardId: 207, currentAttack: 1, baseAttack: 1, currentLife: 9, baseLife: 9, movementLeft: 3, baseMovement: 3, hasAttacked: false });
    const otherJusticier = mkCreature(811, "ally", { x: 7, y: 0 }, { cardId: 207 });
    const enemy = mkCreature(812, "enemy", { x: 4, y: 2 }, { currentLife: 5, baseLife: 5, resistance: 1 }); // résiste 1 ≥ AT 1 de Masse
    const s = endTurn(scenario([masse, otherJusticier, enemy]));
    expect(byId(s, 812)).toBeDefined();              // survit : entièrement résisté → pas « blessé »
    expect(byId(s, 812)!.currentLife).toBe(5);       // PV intacts
  });
});

