describe("conditions/passifs recâblés (#4 Moogrr Royale, #515 Ombre, #1262 Phorreur Corrompu)", () => {
  it("#4 Moogrr Royale : charge SI une invocation adverse est devant elle, sinon reste sur place", () => {
    card(4);
    const m1 = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 4, baseMovement: 3, movementLeft: 0, triggers: card(4).triggers ?? [] });
    const enemyAhead = mkCreature(2, "enemy", { x: 2, y: 2 }, { currentLife: 5, baseLife: 5 });
    const s1 = runTrigger(scenario([m1, enemyAhead]), "APPARITION", 1);
    expect(byId(s1, 1)!.position.x).toBeLessThan(6); // ennemi devant → a chargé (avancé)
    const m2 = mkCreature(3, "ally", { x: 6, y: 1 }, { cardId: 4, baseMovement: 3, movementLeft: 0, triggers: card(4).triggers ?? [] });
    const s2 = runTrigger(scenario([m2]), "APPARITION", 3);
    expect(byId(s2, 3)!.position.x).toBe(6); // aucun ennemi devant → ne charge pas (condition non remplie)
  });
  it("#4 Moogrr Royale : a le mal d'invocation, posée sans ennemi devant, elle ne bouge PAS au tour de pose", () => {
    card(4);
    expect(card(4).properties ?? []).not.toContain("NoSummoningSickness"); // pas de Charge persistante
    let s = scenario([], 4);
    s = { ...s, prisms: [] };
    const spawn = validSpawnCells(s, "ally")[0];
    s = playCard(s, card(4), spawn);
    const m = s.creatures.find((c) => c.cardId === 4)!;
    expect(m.movementLeft).toBe(card(4).movement ?? 0); // garde ses PM ; c'est hasAttacked qui bloque l'avance
    expect(m.hasAttacked).toBe(true); // summoning sickness: it will not move on the turn it is placed
    const after = endTurn(s).creatures.find((c) => c.cardId === 4)!;
    expect(after.position).toEqual(m.position); // stays on its cell at the end of the turn it was placed
  });

  it("une créature en mal d'invocation posée FACE à un ennemi ne combat PAS au tour de pose", () => {
    // Summon state = { hasAttacked:true, movementLeft:0 } (see #4 Moogrr above). Next to an enemy:
    // movementLeft:0 blocked the walk but not the standing engage at the end of the move, so the creature
    // still hit (mutual exchange). Summoning sickness must block everything.
    const fresh = mkCreature(1, "ally", { x: 6, y: 2 }, { currentLife: 5, baseLife: 5, currentAttack: 3, baseAttack: 3, movementLeft: 0, hasAttacked: true });
    const foe = mkCreature(2, "enemy", { x: 5, y: 2 }, { currentLife: 5, baseLife: 5, currentAttack: 3, baseAttack: 3, movementLeft: 0, hasAttacked: true });
    let s = withDecks(scenario([fresh, foe]));
    s = { ...s, prisms: [], seeds: [], butins: [] };
    s = endTurn(s);
    expect(byId(s, 1)!.currentLife).toBe(5); // the placed one does not hit (summoning sickness)
    expect(byId(s, 2)!.currentLife).toBe(5); // l'ennemi reste intact (pas d'échange)
  });

  it("contrôle : une créature NON malade (hasAttacked:false) adjacente à un ennemi engage bien le combat", () => {
    // Makes sure the guard does not block too much: a creature already in play (reset to
    // hasAttacked:false at the start of the turn), even with 0 PM, hits the adjacent enemy at the end of
    // the turn (mutual exchange).
    const ready = mkCreature(1, "ally", { x: 6, y: 2 }, { currentLife: 5, baseLife: 5, currentAttack: 3, baseAttack: 3, movementLeft: 0, hasAttacked: false });
    const foe = mkCreature(2, "enemy", { x: 5, y: 2 }, { currentLife: 5, baseLife: 5, currentAttack: 3, baseAttack: 3, movementLeft: 0, hasAttacked: true });
    let s = withDecks(scenario([ready, foe]));
    s = { ...s, prisms: [], seeds: [], butins: [] };
    s = endTurn(s);
    expect(byId(s, 2)!.currentLife).toBe(2); // 5 − 3 : l'ennemi est bien frappé
    expect(byId(s, 1)!.currentLife).toBe(2); // mutual exchange: ours too
  });
  it("#515 Ombre : repousse de 7 + inflige 4 SI un AUTRE justicier allié est en jeu (sinon push seul)", () => {
    card(515); card(207); // #207 Masse = famille Justicier
    const ombre = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 515, triggers: card(515).triggers ?? [] });
    const otherJusticier = mkCreature(2, "ally", { x: 7, y: 0 }, { cardId: 207 });
    const enemy = mkCreature(3, "enemy", { x: 4, y: 2 }, { currentLife: 9, baseLife: 9 });
    let s = runTrigger(scenario([ombre, otherJusticier, enemy]), "APPARITION", 1);
    s = resolvePendingAction(s, { x: 4, y: 2 });
    expect(byId(s, 3)!.currentLife).toBe(5);            // 9 − 4 (un autre justicier présent)
    expect(byId(s, 3)!.position.x).toBeLessThan(4);     // pushed toward the enemy wall
    // without another justicier (Ombre alone in the family → excludeSelf → condition not met)
    const ombre2 = mkCreature(4, "ally", { x: 6, y: 3 }, { cardId: 515, triggers: card(515).triggers ?? [] });
    const enemy2 = mkCreature(5, "enemy", { x: 4, y: 3 }, { currentLife: 9, baseLife: 9 });
    let s2 = runTrigger(scenario([ombre2, enemy2]), "APPARITION", 4);
    s2 = resolvePendingAction(s2, { x: 4, y: 3 });
    expect(byId(s2, 5)!.currentLife).toBe(9);           // aucun dégât (pas d'autre justicier)
    expect(byId(s2, 5)!.position.x).toBeLessThan(4);    // mais toujours poussé
  });
  it("#1262 Phorreur Corrompu : à la pioche, inflige 1 aux AUTRES invoc. de sa ligne (les deux camps), pas hors-ligne ni soi", () => {
    card(1262);
    const pc = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 1262, currentLife: 6, baseLife: 6, triggers: card(1262).triggers ?? [] });
    const allyRow = mkCreature(2, "ally", { x: 7, y: 2 }, { currentLife: 5, baseLife: 5 });
    const enemyRow = mkCreature(3, "enemy", { x: 3, y: 2 }, { currentLife: 5, baseLife: 5 });
    const offRow = mkCreature(4, "ally", { x: 7, y: 0 }, { currentLife: 5, baseLife: 5 });
    let s = scenario([pc, allyRow, enemyRow, offRow]);
    s = { ...s, players: { ...s.players, ally: { ...s.players.ally, deck: [6], deckCostMods: [0] } } };
    s = drawCard(s, "ally"); // l'allié pioche → ON_DRAW de Phorreur Corrompu
    expect(byId(s, 2)!.currentLife).toBe(4);            // allié sur la ligne −1
    expect(byId(s, 3)!.currentLife).toBe(4);            // enemy on the row −1 (both camps)
    expect(byId(s, 4)!.currentLife).toBe(5);            // hors ligne intact
    expect(byId(s, 1)!.currentLife).toBe(6);            // Phorreur Corrompu lui-même épargné
  });
});

