// ─────────────────────────────────────────────────────────────────────────────
// Targeting qualifiers of the original game, and the checks that make a card
// unplayable.
// ─────────────────────────────────────────────────────────────────────────────
describe("«…ThatCanCharge» (#204/#427/#440/#486/#749) : CanCharge = !Statue && !Stunned && !Rooted", () => {
  it("#427 refuse une cible Assommée (Stunned)", () => {
    const s = scenario([mkCreature(1, "ally", { x: 5, y: 2 }, { properties: new Set(["Stunned"]) })], 427);
    expect(canPlayCard(s, card(427), { x: 5, y: 2 })).not.toBeNull();
  });
  it("#427 refuse une cible Enracinée (Rooted)", () => {
    const s = scenario([mkCreature(1, "ally", { x: 5, y: 2 }, { properties: new Set(["Rooted"]) })], 427);
    expect(canPlayCard(s, card(427), { x: 5, y: 2 })).not.toBeNull();
  });
  it("#427 refuse une cible enracinée PAR AURA (Arakne à Crochets #1457, RootAllAura)", () => {
    card(1457);
    const arakne = mkCreature(1, "ally", { x: 7, y: 0 }, { cardId: 1457 });
    const victim = mkCreature(2, "ally", { x: 5, y: 2 }); // Rooted via l'aura, pas en propre
    const s = scenario([arakne, victim], 427);
    expect(canPlayCard(s, card(427), { x: 5, y: 2 })).not.toBeNull();
    expect(canPlayCard(s, card(427), { x: 7, y: 0 })).toBeNull(); // the Arakne itself is not Rooted (aura on the others)
  });
  it("#427 accepte une créature ENNEMIE ordinaire (AnySummon… : pas de contrainte de camp)", () => {
    const s = scenario([mkCreature(1, "enemy", { x: 4, y: 2 })], 427);
    expect(canPlayCard(s, card(427), { x: 4, y: 2 })).toBeNull();
  });
  it("#749 (Allied…) refuse une créature ennemie mais accepte une alliée", () => {
    const s = scenario([mkCreature(1, "enemy", { x: 4, y: 2 }), mkCreature(2, "ally", { x: 6, y: 2 })], 749);
    expect(canPlayCard(s, card(749), { x: 4, y: 2 })).not.toBeNull();
    expect(canPlayCard(s, card(749), { x: 6, y: 2 })).toBeNull();
  });
  it("#427 charge une unité 0-PM (NoMovementPoints), la charge est un bonus indépendant des PM", () => {
    // The 0-PM property blocked the charge (cannotAdvance); the original game does not test PM in
    // CanCharge, so the unit stays targetable and does its burst.
    const turret = mkCreature(1, "ally", { x: 7, y: 2 }, { properties: new Set(["NoMovementPoints"]), movementLeft: 0, baseMovement: 0, hasAttacked: false, currentAttack: 2, currentLife: 5, baseLife: 5 });
    let s = scenario([turret], 427);
    s = { ...s, prisms: [] };
    expect(canPlayCard(s, card(427), { x: 7, y: 2 })).toBeNull(); // ciblable
    s = playCard(s, card(427), { x: 7, y: 2 });
    expect(byId(s, 1)!.position.x).toBe(5);    // le burst de 2 a eu lieu
    expect(byId(s, 1)!.movementLeft).toBe(0);  // budget PM restauré (0 : elle n'avance pas en fin de tour)
  });
  it("#427 sur une invocation MALADE : ciblable, charge, mais RESTE en mal d'invocation", () => {
    const sick = mkCreature(1, "ally", { x: 7, y: 2 }, { movementLeft: 0, hasAttacked: true, currentAttack: 2, currentLife: 5, baseLife: 5 });
    let s = scenario([sick], 427);
    s = { ...s, prisms: [] };
    expect(canPlayCard(s, card(427), { x: 7, y: 2 })).toBeNull();
    s = playCard(s, card(427), { x: 7, y: 2 });
    expect(byId(s, 1)!.position.x).toBe(5);        // le burst a eu lieu
    expect(byId(s, 1)!.hasAttacked).toBe(true);    // still has summoning sickness (not woken by the charge)
  });
});

