describe("Bump #792 / Bébé Percedal #901", () => {
  it("#792 Bump : APPARITION +2 AR aux autres alliées de sa RANGÉE (même colonne x), pas les autres", () => {
    card(792);
    const bump = mkCreature(1, "ally", { x: 5, y: 2 }, { cardId: 792, triggers: card(792).triggers ?? [] });
    const sameCol = mkCreature(2, "ally", { x: 5, y: 0 }, { armor: 0 });        // même x=5
    const otherCol = mkCreature(3, "ally", { x: 3, y: 2 }, { armor: 0 });       // autre colonne
    const enemySameCol = mkCreature(4, "enemy", { x: 5, y: 4 }, { armor: 0 });  // même x mais ennemi
    const s = runTrigger(scenario([bump, sameCol, otherCol, enemySameCol]), "APPARITION", 1);
    expect(byId(s, 2)!.armor).toBe(2); // allié même rangée +2
    expect(byId(s, 3)!.armor).toBe(0); // autre rangée : rien
    expect(byId(s, 4)!.armor).toBe(0); // ennemi même rangée : rien (scope allies)
    expect(byId(s, 1)!.armor).toBe(0); // Bump : excludeSelf
  });
  it("#901 Bébé Percedal : APPARITION assomme les invocations NON-Confrérie (2 camps), épargne la Confrérie et lui-même", () => {
    card(901); card(104); card(369);
    const bebe = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 901, triggers: card(901).triggers ?? [] });
    const allyNonBro = mkCreature(2, "ally", { x: 5, y: 2 }, { cardId: 104 });   // Craqueleur (non-Confrérie)
    const enemyNonBro = mkCreature(3, "enemy", { x: 3, y: 2 }, { cardId: 104 });
    const allyBro = mkCreature(4, "ally", { x: 5, y: 0 }, { cardId: 369 });      // Tristepin (Confrérie)
    const s = runTrigger(scenario([bebe, allyNonBro, enemyNonBro, allyBro]), "APPARITION", 1);
    expect(byId(s, 2)!.properties.has("Stunned")).toBe(true);  // allié non-Confrérie assommé
    expect(byId(s, 3)!.properties.has("Stunned")).toBe(true);  // ennemi non-Confrérie assommé
    expect(byId(s, 4)!.properties.has("Stunned")).toBe(false); // Confrérie épargnée
    expect(byId(s, 1)!.properties.has("Stunned")).toBe(false); // Bébé Percedal (Confrérie) épargné
  });
});

