describe("Silo #849 : tes Fléaux coûtent 1 PA tant qu'il est en jeu", () => {
  it("réduit le coût de tes Fléaux (#757) à 1 PA, pas ceux de l'adversaire", () => {
    card(849); card(757);
    const fleau = card(757);
    const silo = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 849 });
    const sc = scenario([silo]);
    expect(effectiveCost(sc.players.ally, fleau, [])).toBe(3);            // sans Silo → coût imprimé (3)
    expect(effectiveCost(sc.players.ally, fleau, sc.creatures)).toBe(1);  // Silo allié vivant → 1 PA
    expect(effectiveCost(sc.players.enemy, fleau, sc.creatures)).toBe(3); // « VOS » Fléaux : pas ceux de l'adversaire
  });

  it("le coût FIXE de Silo PRIME sur toute réduction : un Fléau réduit à 0 PA repasse à 1", () => {
    // Silo is not a reduction but a fixed cost that wins over every other modifier. So reducing a Fléau
    // after Silo changes nothing (still 1); a Fléau already at 0 PA in the hand goes back to 1 as soon as
    // Silo is placed.
    card(849); card(757);
    const silo = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 849 });
    const sc = scenario([silo], 757); // Fléau #757 in the allied hand
    // A −3 reduction would bring the Fléau (printed cost 3) to 0 PA.
    const reduced = { ...sc, players: { ...sc.players, ally: { ...sc.players.ally, handCostMods: [-3] } } };
    expect(effectiveCost(reduced.players.ally, card(757), [])).toBe(0);              // sans Silo : la réduction joue → 0 PA
    expect(effectiveCost(reduced.players.ally, card(757), reduced.creatures)).toBe(1); // avec Silo : coût FIXE prioritaire → 1 PA, jamais 0
  });
});

describe("Pissenlit Maléfique #1041 / Pleine Lune #746", () => {
  it("#1041 : APPARITION pose un bouclier sur un Dofus allié, qui absorbe le 1er coup puis disparaît", () => {
    const d: any = { position: { x: 8, y: 2 }, owner: "ally", currentLife: 3, kind: "real", shielded: true };
    woundDofus(d, 5, [], [], [d]);
    expect(d.currentLife).toBe(3);   // coup absorbé
    expect(d.shielded).toBe(false);  // bouclier consommé
    woundDofus(d, 2, [], [], [d]);
    expect(d.currentLife).toBe(1);   // 2e coup : normal
    card(1041);
    const piss = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 1041, triggers: card(1041).triggers ?? [] });
    const dof: any = { position: { x: 8, y: 2 }, owner: "ally", currentLife: 5, kind: "real" };
    let s = runTrigger({ ...scenario([piss]), dofuses: [dof] }, "APPARITION", 1);
    expect(s.pendingAction?.filter).toBe("ally_dofus");
    s = resolvePendingAction(s, { x: 8, y: 2 });
    expect(s.dofuses.find((x) => x.position.x === 8)!.shielded).toBe(true);
  });
  it("#746 Pleine Lune : CHEF +1 AT aux Mulous + MoonGuard tant qu'une lune (FullMoon) est en jeu", () => {
    card(746); card(284);
    const lune = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 746, properties: new Set(["FullMoon"]) });
    const mulou = mkCreature(2, "ally", { x: 5, y: 2 }, { cardId: 284, currentAttack: 3, baseAttack: 3 });
    const aur = withAuras([lune, mulou]);
    const m = aur.find((c) => c.instanceId === 2)!;
    expect(m.auraAttack).toBe(1);                      // CHEF +1 AT
    expect(m.properties.has("MoonGuard")).toBe(true);  // lune en jeu → MoonGuard
    const aur2 = withAuras([mkCreature(2, "ally", { x: 5, y: 2 }, { cardId: 284 })]);
    expect(aur2[0].properties.has("MoonGuard")).toBe(false); // pas de lune → pas de MoonGuard
  });
  it("#746 : un Mulou avec MoonGuard subit 1 dégât de moins (sort ET combat)", () => {
    card(284); card(746);
    const m2 = mkCreature(1, "ally", { x: 5, y: 2 }, { cardId: 284, currentLife: 4, baseLife: 4, properties: new Set(["MoonGuard"]) });
    const arr = [m2];
    applyEffects(arr, [], [], [{ type: "DamageData", Damage: 2 } as any], { casterSide: "enemy", targetCell: { x: 5, y: 2 } });
    expect(arr[0].currentLife).toBe(3);  // sort : 4 - max(0, 2-1)
    const attacker = mkCreature(10, "ally", { x: 5, y: 2 }, { currentAttack: 3, baseAttack: 3, movementLeft: 0, hasAttacked: false });
    const mulou = mkCreature(20, "enemy", { x: 4, y: 2 }, { cardId: 284, currentLife: 9, baseLife: 9, armor: 0, movementLeft: 0, hasAttacked: true });
    const lune = mkCreature(30, "enemy", { x: 1, y: 0 }, { cardId: 746, properties: new Set(["FullMoon"]), movementLeft: 0, hasAttacked: true });
    const sc = scenario([attacker, mulou, lune]);
    const st = { ...sc, creatures: withAuras(sc.creatures), activeSide: "ally" as const, players: { ...sc.players, ally: { ...sc.players.ally, deck: [21, 21, 21] }, enemy: { ...sc.players.enemy, deck: [21, 21, 21] } } };
    const s = endTurn(st);
    expect(byId(s, 20)!.currentLife).toBe(7);  // combat : 9 - max(0, 3-1)
  });
});

