// ---------------------------------------------------------------------------------------------
// Deaths resolved one after the other during the sweep
//
// The damage of one event lands at the same time, but its consequences resolve at the moment of
// the fatal hit, before the next creature of the sweep moves. Before this fix, all the deaths of
// the sweep were set aside and resolved at the very end.
// ---------------------------------------------------------------------------------------------
describe("Morts résolues à l'instant du coup fatal", () => {
  // Exact copy of the reported game: Chuck Lapalette #1541 (MORT ADVERSE: puts a Cochon from the deck
  // in the hand) fights in melee with Maître Chuchoku #98, and both die. At that moment, Guerrier
  // Boudeur #1108 (MORT ADVERSE: 2 damage to the first enemy invocation of its row in front of it) is
  // still alive and Alibert #505 (2 HP) is in front of it on its row.
  const board = () => {
    const chuck = mkCreature(1, "ally", { x: 5, y: 2 }, { cardId: 1541, currentAttack: 5, baseAttack: 5, currentLife: 1, baseLife: 2, baseMovement: 3, movementLeft: 3, triggers: card(1541).triggers ?? [] });
    const chuchoku = mkCreature(2, "enemy", { x: 1, y: 2 }, { cardId: 98, currentAttack: 5, baseAttack: 5, currentLife: 3, baseLife: 3, triggers: card(98).triggers ?? [] });
    const boudeur = mkCreature(3, "ally", { x: 8, y: 3 }, { cardId: 1108, currentAttack: 5, baseAttack: 5, currentLife: 3, baseLife: 3, baseMovement: 3, movementLeft: 3, triggers: card(1108).triggers ?? [] });
    const alibert = mkCreature(4, "enemy", { x: 4, y: 3 }, { cardId: 505, currentAttack: 5, baseAttack: 5, currentLife: 2, baseLife: 2, triggers: card(505).triggers ?? [] });
    // Two Cochons (#148) in the allied deck: if Chuck tutors twice (the bug), the hand gets two. #16 is
    // neutral filler (it avoids end-of-deck fatigue).
    const s = scenario([chuck, chuchoku, boudeur, alibert]);
    return {
      ...s,
      players: {
        ...s.players,
        ally: { ...s.players.ally, hand: [], handCostMods: [], deck: [16, 148, 16, 148, 16] },
        enemy: { ...s.players.enemy, deck: [16, 16, 16] },
      },
    };
  };
  const isCochon = (id: number) => (card(id).families ?? []).includes("Cochon");

  it("la MORT ADVERSE du Guerrier Boudeur #1108 tue Alibert AVANT que le Boudeur n'avance, il survit", () => {
    const s = endTurn(board());
    // L'échange de Chuck : les deux meurent.
    expect(byId(s, 1)).toBeUndefined(); // Chuck Lapalette
    expect(byId(s, 2)).toBeUndefined(); // Maître Chuchoku
    // The core of the bug: when Chuchoku dies, the Boudeur (alive, at 8,3) deals its 2 damage to
    // Alibert (2 HP), who dies right away. Before, the reaction was put off to the end of the sweep: the
    // Boudeur advanced into an Alibert that was still alive and died in the exchange.
    expect(byId(s, 4)).toBeUndefined(); // Alibert, killed by the reaction
    const bd = byId(s, 3)!;
    expect(bd).toBeTruthy();            // the Boudeur survives (it used to die)
    expect(bd.currentLife).toBe(3);     // and without a scratch: it never fought
    expect(bd.position).toEqual({ x: 5, y: 3 }); // 3 PM spent on a row that is now empty
  });

  it("la réaction s'inscrit au journal AVANT le déplacement du Boudeur", () => {
    const s = endTurn(board());
    const dmgIdx = s.log.findIndex((e) => e.type === "DAMAGE" && (e as { sourceInstanceId?: number }).sourceInstanceId === 3 && (e as { targetInstanceId?: number }).targetInstanceId === 4);
    const moveIdx = s.log.findIndex((e) => e.type === "FIGHT_OBJECT_MOVED" && (e as { instanceId?: number }).instanceId === 3);
    expect(dmgIdx).toBeGreaterThanOrEqual(0);
    expect(moveIdx).toBeGreaterThanOrEqual(0);
    expect(dmgIdx).toBeLessThan(moveIdx); // the death resolves before the next creature moves
  });

  it("Chuck Lapalette #1541 ne tutorise QU'UNE fois : un mort ne réagit pas à une mort postérieure", () => {
    const s = endTurn(board());
    // Chuck dies while killing Chuchoku, and its posthumous MORT ADVERSE holds for this wave. Alibert's
    // death comes after its own (it is caused by the Boudeur's reaction), so it does not wake it up.
    // Before, the two deaths were grouped together and it drew two Cochons.
    expect(s.players.ally.hand.filter(isCochon)).toHaveLength(1);
    expect(s.players.ally.deck.filter(isCochon)).toHaveLength(1);
  });
});

// ---------------------------------------------------------------------------------------------
// Area spell: simultaneous damage, consequences resolved in a cell sweep
// (example: Pied du Sacrieur #271)
//
// "L'ensemble des créatures reçoivent les dégâts en même temps. [...] c'est seulement l'effet de
// résolution qui doit être effectué par balayage pour chaque créature."
// The sweep is absolute: y from 0 to 4, then x from 0 to 9 (from the enemy wall toward ours).
// ---------------------------------------------------------------------------------------------
describe("Sort de zone : dégâts simultanés puis résolution par cases", () => {
  // Pied du Sacrieur #271: 3 damage to the target, 1 damage to all the others.
  // Target = Gelée d'Encre #69 (2 HP → dies). On the board: Empereur Gelax #422 (6 HP, Jelly, CONTRE
  // COUP: summons another Gelée if it survives damage), which takes the 1 from the area.
  // The Encre's MORT gives +1 AT and +1 AR to your other Gelées.
  const cast = (gelaxCell: Coords, encreCell: Coords, seed: number) => {
    const gelax = mkCreature(700, "ally", gelaxCell, { cardId: 422, currentAttack: 3, baseAttack: 3, currentLife: 6, baseLife: 6, armor: 0, triggers: card(422).triggers ?? [] });
    const encre = mkCreature(701, "ally", encreCell, { cardId: 69, currentAttack: 2, baseAttack: 2, currentLife: 2, baseLife: 2, triggers: card(69).triggers ?? [] });
    const s0 = scenario([gelax, encre]);
    const s1 = { ...s0, players: { ...s0.players, ally: { ...s0.players.ally, hand: [271], handCostMods: [0], ap: 9 } }, rng: seed };
    return playCard(s1, card(271), encreCell);
  };
  const newJelly = (s: ReturnType<typeof cast>) =>
    s.creatures.find((c) => c.owner === "ally" && c.cardId !== 422 && c.cardId !== 69 && (card(c.cardId).families ?? []).includes("Jelly"));

  it("les dégâts tombent EN MÊME TEMPS : l'armure gagnée à la mort de l'Encre ne protège pas Gelax du même sort", () => {
    const s = cast({ x: 5, y: 3 }, { x: 5, y: 2 }, 3);
    expect(byId(s, 701)).toBeUndefined();               // l'Encre (2 PV) meurt des 3 dégâts
    const g = byId(s, 700)!;
    // Gelax took the 1 from the area before any resolution: 6 → 5 HP. The +1 AR from the Encre's MORT
    // reaches it after (it keeps it); it cannot go back in time to absorb the spell's damage.
    expect(g.currentLife).toBe(5);
    expect(g.armor).toBe(1);                            // le bonus, lui, est bien arrivé
    expect(g.currentAttack).toBe(3 + 1);                // et le +1 AT aussi
  });

  it("case de l'ENCRE avant celle de Gelax → la Gelée invoquée naît APRÈS la mort : aucun bonus", () => {
    // Encre en y=2, Gelax en y=3 : le balayage rencontre l'Encre d'abord.
    const s = cast({ x: 5, y: 3 }, { x: 5, y: 2 }, 3);
    const j = newJelly(s)!;
    expect(j).toBeTruthy();
    expect(j.armor).toBe(0);
    expect(j.currentAttack).toBe(card(j.cardId).attack);
  });

  it("mort / contre-coup / mort ENTRELACÉS : la Gelée née au milieu ne prend QUE la mort qui suit sa case", () => {
    // The case that needs a single sweep (and not "all deaths, then all contre-coups"):
    //   x=1  Gelée d'Encre A (2 HP), target of the spell (3 damage) → dies
    //   x=3  Empereur Gelax (6 HP), takes the 1 from the area, survives → CONTRE COUP: summons a Gelée
    //   x=5  Gelée d'Encre B (1 HP), takes the 1 from the area → dies
    // Cell order: A, Gelax, B. So A dies (Gelax +1/+1, the Gelée does not exist yet), Gelax summons,
    // then B dies and boosts all the Gelées that are there, including the new one.
    // Result: Gelax +2/+2 (both deaths), the summoned Gelée +1/+1 (the only death after its cell).
    for (let seed = 1; seed <= 20; seed++) {
      const encreA = mkCreature(701, "ally", { x: 1, y: 2 }, { cardId: 69, currentAttack: 2, baseAttack: 2, currentLife: 2, baseLife: 2, triggers: card(69).triggers ?? [] });
      const gelax = mkCreature(700, "ally", { x: 3, y: 2 }, { cardId: 422, currentAttack: 3, baseAttack: 3, currentLife: 6, baseLife: 6, armor: 0, triggers: card(422).triggers ?? [] });
      const encreB = mkCreature(702, "ally", { x: 5, y: 2 }, { cardId: 69, currentAttack: 2, baseAttack: 2, currentLife: 1, baseLife: 2, triggers: card(69).triggers ?? [] });
      const s0 = scenario([encreA, gelax, encreB]);
      const s1 = { ...s0, players: { ...s0.players, ally: { ...s0.players.ally, hand: [271], handCostMods: [0], ap: 9 } }, rng: seed };
      const s = playCard(s1, card(271), { x: 1, y: 2 });
      expect(byId(s, 701)).toBeUndefined();
      expect(byId(s, 702)).toBeUndefined();
      const g = byId(s, 700)!;
      expect(g.currentLife).toBe(5);        // the 1 from the area, taken before any resolution
      expect(g.currentAttack).toBe(3 + 2);  // les DEUX morts l'ont trouvé vivant
      expect(g.armor).toBe(2);
      const j = s.creatures.find((c) => c.owner === "ally" && c.cardId !== 422 && c.cardId !== 69 && (card(c.cardId).families ?? []).includes("Jelly"));
      if (!j || j.cardId === 437 || j.cardId === 417) continue; // graines ambiguës (auto-buff / cascade)
      expect(j.armor).toBe(1);                                  // UNE seule mort après sa naissance
      expect(j.currentAttack).toBe(card(j.cardId).attack + 1);
      return;
    }
    throw new Error("aucune graine n'a produit une Gelée invoquée propre");
  });

  it("case de GELAX avant celle de l'Encre → il invoque d'abord, et la mort de l'Encre booste la nouvelle-née", () => {
    // Gelax at y=1, Encre at y=2: the sweep meets Gelax first → its CONTRE COUP fires, the Gelée exists,
    // then the Encre dies and its MORT finds it on the board.
    const s = cast({ x: 5, y: 1 }, { x: 5, y: 2 }, 3);
    const j = newJelly(s)!;
    expect(j).toBeTruthy();
    expect(j.armor).toBe(1);                                  // +1 AR du MORT de l'Encre
    expect(j.currentAttack).toBe(card(j.cardId).attack + 1);  // +1 AT du MORT de l'Encre
  });
});

// ---------------------------------------------------------------------------------------------
// Sweep order: rangée by rangée, from the enemy wall
//
// Cell priority: `x` going up first (the whole rangée next to the enemy wall goes first), then `y`
// going up. Sorting by `y` first would sweep row by row, which is the opposite, and it only shows
// on cells on a diagonal (two reactions that differ on both axes). Hence this test: the cases
// aligned on a single axis pass with both sorts, so they prove nothing.
// ---------------------------------------------------------------------------------------------
describe("Ordre du balayage : rangée par rangée", () => {
  // Pied du Sacrieur #271 on the Gelée d'Encre #69 (3 damage → it dies); Empereur Gelax #422 takes the
  // 1 from the area, survives, and its CONTRE COUP summons a Gelée. The Encre's MORT gives +1 AT/+1 AR
  // to your other Gelées. The new one only gets it if the Encre is resolved after Gelax, so if its cell
  // has a lower priority.
  const jellyBoosted = (g: Coords, e: Coords): boolean => {
    for (let seed = 1; seed <= 25; seed++) {
      const gelax = mkCreature(700, "ally", g, { cardId: 422, currentAttack: 3, baseAttack: 3, currentLife: 6, baseLife: 6, armor: 0, triggers: card(422).triggers ?? [] });
      const encre = mkCreature(701, "ally", e, { cardId: 69, currentAttack: 2, baseAttack: 2, currentLife: 2, baseLife: 2, triggers: card(69).triggers ?? [] });
      const s0 = scenario([gelax, encre]);
      const s1 = { ...s0, players: { ...s0.players, ally: { ...s0.players.ally, hand: [271], handCostMods: [0], ap: 9 } }, rng: seed };
      const s = playCard(s1, card(271), e);
      expect(byId(s, 701)).toBeUndefined();                 // l'Encre est bien morte
      expect(byId(s, 700)!.currentLife).toBe(5);            // Gelax a bien pris le 1 de zone
      const j = s.creatures.find((c) => c.owner === "ally" && c.cardId !== 422 && c.cardId !== 69 && (card(c.cardId).families ?? []).includes("Jelly"));
      // Framboise #437 (auto-buff) et Fraise #417 (cascade) rendraient le +1/+1 ambigu : graine suivante.
      if (!j || j.cardId === 437 || j.cardId === 417) continue;
      expect(j.currentAttack).toBe(card(j.cardId).attack + (j.armor === 1 ? 1 : 0)); // AT et AR cohérents
      return j.armor === 1;
    }
    throw new Error("aucune graine n'a produit une Gelée invoquée non ambiguë");
  };

  it("DIAGONALE, Gelax plus loin du mur adverse (x plus grand) mais plus haut : l'Encre passe AVANT, la Gelée née après n'a rien", () => {
    // Gelax (6,0), Encre (5,4). Rangée x=5 before rangée x=6 → the Encre dies first.
    // A sort by row (y first) would have put Gelax first and boosted the new one: that is the bug.
    expect(jellyBoosted({ x: 6, y: 0 }, { x: 5, y: 4 })).toBe(false);
  });

  it("DIAGONALE, Gelax plus près du mur adverse (x plus petit) mais plus bas : Gelax passe AVANT, la Gelée EST boostée", () => {
    // Gelax (5,4), Encre (6,0). Rangée x=5 avant rangée x=6 → Gelax invoque, PUIS l'Encre meurt.
    expect(jellyBoosted({ x: 5, y: 4 }, { x: 6, y: 0 })).toBe(true);
  });

  it("MÊME RANGÉE, à x égal, c'est le y qui départage (haut avant bas)", () => {
    expect(jellyBoosted({ x: 5, y: 1 }, { x: 5, y: 2 })).toBe(true);  // Gelax above → it goes first
    expect(jellyBoosted({ x: 5, y: 3 }, { x: 5, y: 2 })).toBe(false); // Gelax en-dessous → l'Encre passe avant
  });

  it("MÊME LIGNE, la rangée la plus proche du mur adverse passe la première", () => {
    expect(jellyBoosted({ x: 3, y: 2 }, { x: 5, y: 2 })).toBe(true);  // Gelax plus près de l'ennemi → avant
    expect(jellyBoosted({ x: 6, y: 2 }, { x: 5, y: 2 })).toBe(false); // l'Encre plus près de l'ennemi → avant
  });
});

// ---------------------------------------------------------------------------------------------
// OMBRE #515: "APPARITION : Repoussez une invocation de 7 cases. Infligez lui 4 si vous avez un
// Justicier sur le terrain."
//
// The order of the text decides: push first, then wound. The target crosses the board, and picks up
// whatever is on the ground (prism, seed, trap), before taking the damage, and dies at its landing
// cell if it has to. The effects used to be encoded in the opposite order: the target died in place
// and the push was cancelled ("un cadavre ne se pousse pas", effects.ts).
// ---------------------------------------------------------------------------------------------
describe("Ombre #515 : pousser d'abord, blesser ensuite", () => {
  // An enemy creature at (5,2), 4 HP. Ombre pushes it toward its wall (x going down): it crosses (4,2),
  // (3,2), (2,2), (1,2) and stops in front of the wall. An enemy prism is placed at (2,2), on its path.
  // An allied Justice #67 is in play → the condition for the 4 damage is met.
  const board = () => {
    const justicier = mkCreature(1, "ally", { x: 8, y: 0 }, { cardId: 67, currentAttack: 3, currentLife: 5, baseLife: 5 });
    const cible = mkCreature(2, "enemy", { x: 5, y: 2 }, { cardId: 37, currentAttack: 2, currentLife: 4, baseLife: 4 });
    const s = scenario([justicier, cible]);
    return {
      ...s,
      prisms: [{ position: { x: 2, y: 2 }, owner: "enemy" as const, kind: "ap" as const }],
      seeds: [], butins: [],
      players: { ...s.players, ally: { ...s.players.ally, hand: [515], handCostMods: [0], ap: 9 } },
    };
  };
  const play = () => {
    const parked = playCard(board(), card(515), { x: 8, y: 2 }); // Ombre entre en jeu
    expect(parked.pendingAction).toBeTruthy();                   // « Repoussez UNE invocation » → une cible à choisir
    return resolvePendingAction(parked, { x: 5, y: 2 });         // the enemy creature is chosen
  };

  it("la cible est POUSSÉE avant d'encaisser : ses déplacements précèdent les dégâts dans le journal", () => {
    const s = play();
    const moveIdx = s.log.findIndex((e) => e.type === "FIGHT_OBJECT_MOVED" && (e as { instanceId?: number }).instanceId === 2);
    const dmgIdx = s.log.findIndex((e) => e.type === "DAMAGE" && (e as { targetInstanceId?: number }).targetInstanceId === 2);
    expect(moveIdx).toBeGreaterThanOrEqual(0); // it moved (before: it died in place, never pushed)
    expect(dmgIdx).toBeGreaterThanOrEqual(0);
    expect(moveIdx).toBeLessThan(dmgIdx);
  });

  it("elle ramasse le prisme qu'elle traverse AVANT de subir les dégâts, et meurt à sa case d'arrivée", () => {
    const before = board();
    const s = play();
    // The prism on its path is used up, and its bonus goes to the camp of the pushed creature (the
    // carrier), not to the caster.
    expect(before.prisms).toHaveLength(1);
    expect(s.prisms).toHaveLength(0);
    expect(s.players.enemy.apReserve).toBe(before.players.enemy.apReserve + 1);
    expect(byId(s, 2)).toBeUndefined(); // 4 damage on 4 HP: it dies, but after the trip
  });
});

describe("Joris #110 SpellDamageReductionAura ne touche QUE les sorts", () => {
  // "Tant qu'il est en jeu, réduit de 2 les dégâts des sorts adverses." Joris (enemy side) protects the
  // enemy invocations. An allied spell that hits an enemy invocation is reduced by 2; the "Infligez 2"
  // APPARITION of an allied creature (Black Wabbit #495) is not a spell and is not reduced.
  const build = () => [
    mkCreature(1, "enemy", { x: 3, y: 0 }, { cardId: 110, currentLife: 3, baseLife: 3 }),           // Joris (aura)
    mkCreature(2, "enemy", { x: 4, y: 2 }, { cardId: 495, currentLife: 3, baseLife: 3, armor: 0 }),  // cible enemy
    mkCreature(3, "ally", { x: 5, y: 2 }, { cardId: 495, currentLife: 3, baseLife: 3 }),             // source alliée (Summon)
  ].map((c) => ({ ...c, properties: new Set(c.properties), position: { ...c.position } }));

  it("l'APPARITION d'une créature (source = Summon sur le plateau) inflige 2, non réduits", () => {
    const cs = build();
    applyEffects(cs, [], [], [{ type: "DamageData", Damage: 2 } as never], { casterSide: "ally", targetCell: { x: 4, y: 2 }, selfInstanceId: 3 });
    expect(byId({ creatures: cs } as never, 2)!.currentLife).toBe(1); // 3 - 2, PAS réduit
  });

  it("un SORT (aucune source-créature) est bien réduit de 2 → 0 dégât", () => {
    const cs = build();
    applyEffects(cs, [], [], [{ type: "DamageData", Damage: 2 } as never], { casterSide: "ally", targetCell: { x: 4, y: 2 } });
    expect(byId({ creatures: cs } as never, 2)!.currentLife).toBe(3); // 2 - 2 = 0
  });
});

describe("spellDamageReductionAgainst, total pour l'affichage des sorts en main (Joris #110)", () => {
  const st = (creatures: ReturnType<typeof mkCreature>[]) =>
    ({ creatures: creatures.map((c) => ({ ...c, properties: new Set(c.properties), position: { ...c.position } })) } as never);

  it("somme les auras du camp ADVERSE du lanceur, planché à ce total (2 pour un Joris)", () => {
    const s = st([mkCreature(1, "enemy", { x: 3, y: 0 }, { cardId: 110, currentLife: 3, baseLife: 3 })]);
    expect(spellDamageReductionAgainst(s, "ally")).toBe(2); // mes sorts (ally) réduits par le Joris enemy
    expect(spellDamageReductionAgainst(s, "enemy")).toBe(0); // Joris does not reduce itself
  });

  it("deux Joris adverses cumulent (2+2=4)", () => {
    const s = st([
      mkCreature(1, "enemy", { x: 3, y: 0 }, { cardId: 110, currentLife: 3, baseLife: 3 }),
      mkCreature(2, "enemy", { x: 3, y: 2 }, { cardId: 110, currentLife: 3, baseLife: 3 }),
    ]);
    expect(spellDamageReductionAgainst(s, "ally")).toBe(4);
  });

  it("un Joris MORT ne compte pas", () => {
    const s = st([mkCreature(1, "enemy", { x: 3, y: 0 }, { cardId: 110, currentLife: 0, baseLife: 3 })]);
    expect(spellDamageReductionAgainst(s, "ally")).toBe(0);
  });
});

describe("Auto-dégât absorbé par le Garde du corps", () => {
  // Disciple de l'Agonie #1163 "FIN DU TOUR : … puis à lui-même". Self damage of a creature protected
  // by a Garde du corps (Silas #320) is taken by the guard instead; what goes beyond the guard's HP
  // spills over onto the protected creature, like any damage.
  it("le garde encaisse l'auto-dégât à la place de la protégée", () => {
    const guard = mkCreature(1, "ally", { x: 7, y: 1 }, { cardId: 320, currentLife: 4, baseLife: 4, armor: 0 });
    const disc = mkCreature(2, "ally", { x: 7, y: 2 }, { cardId: 1163, currentLife: 3, baseLife: 3, armor: 0, protectedByGuard: 1 });
    const cs = [guard, disc].map((c) => ({ ...c, properties: new Set(c.properties), position: { ...c.position } }));
    applyEffects(cs, [], [], [{ type: "SelfDamageData", Damage: 2 } as never], { casterSide: "ally", selfInstanceId: 2 });
    expect(byId({ creatures: cs } as never, 1)!.currentLife).toBe(2); // le garde a pris les 2
    expect(byId({ creatures: cs } as never, 2)!.currentLife).toBe(3); // the protected creature is untouched
  });

  it("le surplus au-delà des PV du garde déborde sur la protégée", () => {
    const guard = mkCreature(1, "ally", { x: 7, y: 1 }, { cardId: 320, currentLife: 1, baseLife: 1, armor: 0 });
    const disc = mkCreature(2, "ally", { x: 7, y: 2 }, { cardId: 1163, currentLife: 3, baseLife: 3, armor: 0, protectedByGuard: 1 });
    const cs = [guard, disc].map((c) => ({ ...c, properties: new Set(c.properties), position: { ...c.position } }));
    applyEffects(cs, [], [], [{ type: "SelfDamageData", Damage: 3 } as never], { casterSide: "ally", selfInstanceId: 2 });
    expect(byId({ creatures: cs } as never, 1)!.currentLife).toBeLessThanOrEqual(0); // garde mort
    expect(byId({ creatures: cs } as never, 2)!.currentLife).toBe(1); // 3 - débordement(2) = 1
  });
});

describe("Joris #110 réduit AUSSI les dégâts de sort sur un Dofus", () => {
  // "Réduit de 2 les dégâts des sorts adverses" protects the invocations and also the Dofus of Joris's
  // camp. Fléau (2 to the Dofus) under an enemy Joris = 0 damage; the display showed 0 but the Dofus
  // still took the raw damage.
  const dofus = (life: number) => [{ position: { x: 0, y: 2 }, owner: "enemy" as const, currentLife: life, kind: "real" as const }];

  it("Fléau (2) sur Dofus ennemi + Joris #110 ennemi = 0 dégât", () => {
    const cs = [mkCreature(1, "enemy", { x: 1, y: 0 }, { cardId: 110, currentLife: 3, baseLife: 3 })].map((c) => ({ ...c, properties: new Set(c.properties), position: { ...c.position } }));
    const ds = dofus(5);
    applyEffects(cs, ds as never, [], [{ type: "DamageData", Damage: 2 } as never], { casterSide: "ally", targetCell: { x: 0, y: 2 }, dofusTargetable: true });
    expect(ds[0].currentLife).toBe(5); // 2 - 2 = 0, le Dofus est intact
  });

  it("sans Joris, le Dofus prend bien les 2", () => {
    const ds = dofus(5);
    applyEffects([], ds as never, [], [{ type: "DamageData", Damage: 2 } as never], { casterSide: "ally", targetCell: { x: 0, y: 2 }, dofusTargetable: true });
    expect(ds[0].currentLife).toBe(3);
  });
});

describe("Percée du tireur au contact", () => {
  // A shooter (Portée) that destroys the adjacent Dofus (d=1, corps à corps) breaks through and goes
  // back into the deck, exactly like a melee that hits the Dofus through the engage. A ranged shot
  // (d ≥ 2) that destroys the Dofus does not break through: the shooter is not touching the wall.
  const setup = (shooterX: number) => {
    card(354); // Clara Byne, Portée 2
    const shooter = mkCreature(12, "ally", { x: shooterX, y: 2 }, {
      cardId: 354, currentLife: 2, baseLife: 2, currentAttack: 3, baseAttack: 3,
      range: 2, movementLeft: 0, baseMovement: 1,
    });
    const base0 = scenario([shooter]);
    const dofuses = base0.dofuses.map((d) =>
      d.owner === "enemy" && d.position.x === 0 && d.position.y === 2 ? { ...d, currentLife: 3 } : d);
    return withDecks({ ...base0, dofuses, players: { ...base0.players, ally: { ...base0.players.ally, hand: [], handCostMods: [] } } });
  };

  it("détruit le Dofus adjacent (d=1) : perce, retirée du plateau, remonte dans la pioche", () => {
    const s = endTurn(setup(1));
    // Dofus détruit + percée logguée
    expect(s.log.some((e) => e.type === "FIGHT_OBJECT_REMOVED" && (e as { dofusAt?: { x: number; y: number } }).dofusAt?.x === 0 && (e as { dofusAt?: { y: number } }).dofusAt?.y === 2)).toBe(true);
    expect(s.log.some((e) => e.type === "FIGHT_OBJECT_REMOVED" && (e as { instanceId?: number; brokeThrough?: boolean }).instanceId === 12 && (e as { brokeThrough?: boolean }).brokeThrough === true)).toBe(true);
    // no longer on the board, back in the deck (a capture is not a death → no discard)
    expect(s.creatures.some((c) => c.instanceId === 12 && c.currentLife > 0)).toBe(false);
    expect(s.players.ally.deck.includes(354)).toBe(true);
    expect(s.players.ally.discard.includes(354)).toBe(false);
  });

  it("détruit le Dofus à distance (d=2) : PAS de percée, la tireuse reste en jeu", () => {
    const s = endTurn(setup(2));
    expect(s.log.some((e) => e.type === "FIGHT_OBJECT_REMOVED" && (e as { dofusAt?: { x: number; y: number } }).dofusAt?.x === 0 && (e as { dofusAt?: { y: number } }).dofusAt?.y === 2)).toBe(true);
    expect(s.log.some((e) => e.type === "FIGHT_OBJECT_REMOVED" && (e as { instanceId?: number; brokeThrough?: boolean }).instanceId === 12 && (e as { brokeThrough?: boolean }).brokeThrough === true)).toBe(false);
    const clara = s.creatures.find((c) => c.instanceId === 12);
    expect(clara?.currentLife).toBe(2); // toujours en jeu, en (2,2)
    expect(clara?.position).toEqual({ x: 2, y: 2 });
  });
});

describe("Klaus #716 : COUP DE GRÂCE inline pendant l'avance", () => {
  // "COUP DE GRÂCE : Gagne +1 AT et se soigne de 2 PV." The trigger must resolve at the moment of the
  // kill, in the middle of the move, not in the deferred pass at the end of the phase. Otherwise Klaus
  // ends its move (and hits the next enemy / the Dofus) with the AT and HP it had before.
  const build = () => {
    const klaus = mkCreature(5, "ally", { x: 5, y: 4 }, {
      cardId: 716, currentLife: 1, baseLife: 5, currentAttack: 4, baseAttack: 4,
      baseMovement: 3, movementLeft: 3, hasAttacked: false, triggers: card(716).triggers ?? [],
    });
    const foe = mkCreature(6, "enemy", { x: 4, y: 4 }, { cardId: 16, currentLife: 4, baseLife: 4, currentAttack: 0, baseAttack: 0 });
    return withDecks({ ...scenario([klaus, foe]), activeSide: "ally" as const });
  };

  it("le +1 AT et le soin de 2 PV tombent AVANT la fin du déplacement", () => {
    const s0 = build();
    const from = s0.log.length;
    const s = endTurn(s0);
    const types = s.log.slice(from).map((e) => e.type);
    const kill = types.indexOf("FIGHT_OBJECT_REMOVED");
    const atk = types.indexOf("ATTACK_GAINED");
    const heal = types.indexOf("LIFE_HEALED");
    const lastMove = types.lastIndexOf("FIGHT_OBJECT_MOVED");
    expect(kill).toBeGreaterThanOrEqual(0);
    expect(atk).toBeGreaterThan(kill);   // the coup de grâce follows the kill…
    expect(heal).toBeGreaterThan(kill);
    expect(atk).toBeLessThan(lastMove);  // …and comes before the end of the move
    expect(heal).toBeLessThan(lastMove);
  });

  it("l'état final porte bien +1 AT et +2 PV", () => {
    const s = endTurn(build());
    const klaus = byId(s, 5)!;
    expect(klaus.currentAttack).toBe(5); // 4 + 1
    expect(klaus.currentLife).toBe(3);   // 1 + 2
  });
});

describe("Esquive #239 : un castTarget « …Summon… » EXIGE une invocation", () => {
  // "Repousse une invocation alliée de 4 cases": castTarget AlliedSummon, a single PushData effect.
  // PushData was in no list of validateSpellTarget, so the spell could be cast on an empty cell and was
  // used up for nothing.
  const base = () => {
    const ally = mkCreature(1, "ally", { x: 4, y: 2 }, { cardId: 16, currentLife: 3, baseLife: 3 });
    const s = withDecks({ ...scenario([ally]), activeSide: "ally" as const });
    return { ...s, players: { ...s.players, ally: { ...s.players.ally, hand: [239], ap: 10 } } };
  };

  it("refuse une case VIDE", () => {
    expect(canPlayCard(base(), card(239), { x: 6, y: 0 })).not.toBeNull();
  });

  it("accepte une invocation alliée, et la repousse", () => {
    const s0 = base();
    expect(canPlayCard(s0, card(239), { x: 4, y: 2 })).toBeNull();
    const s = playCard(s0, card(239), { x: 4, y: 2 });
    expect(byId(s, 1)!.position.x).toBeGreaterThan(4); // repoussée vers son propre mur
  });
});

describe("Patty Ceriz #31 : repousse dès qu'elle LANCE son attaque", () => {
  // "Repousse de 1 case son adversaire quand elle attaque." What triggers the push is striking the hit,
  // not the damage (a Patty with 0 AT still pushes) and not its survival (it pushes even while dying,
  // simultaneous hits). The only case left out is when it never strikes: killed by an INITIATIVE before
  // it could answer.
  // The melee exchange is mutual, so this also holds when the enemy is the one advancing onto it.
  const patty = (o: Record<string, unknown> = {}) =>
    mkCreature(1, "ally", { x: 5, y: 2 }, { cardId: 31, currentLife: 3, baseLife: 3, currentAttack: 2, baseAttack: 2, range: 3, baseMovement: 0, movementLeft: 0, hasAttacked: true, ...o });
  const foe = (o: Record<string, unknown> = {}) =>
    mkCreature(2, "enemy", { x: 4, y: 2 }, { cardId: 16, currentLife: 9, baseLife: 9, currentAttack: 1, baseAttack: 1, baseMovement: 1, movementLeft: 1, hasAttacked: false, ...o });
  const run = (p: ReturnType<typeof patty>, f: ReturnType<typeof foe>, side: "ally" | "enemy") =>
    endTurn(withDecks({ ...scenario([p, f]), activeSide: side }));

  it("elle TIRE (d≥2) : la cible recule", () => {
    const s = run(patty({ position: { x: 6, y: 2 }, hasAttacked: false }), foe({ currentAttack: 0, baseMovement: 0, movementLeft: 0 }), "ally");
    expect(byId(s, 2)!.position.x).toBe(3);
  });

  it("elle ATTAQUE au contact (d=1) : la cible recule, une seule fois", () => {
    const s = run(patty({ hasAttacked: false }), foe({ currentAttack: 0, baseMovement: 0, movementLeft: 0 }), "ally");
    expect(byId(s, 2)!.position.x).toBe(3); // 4 → 3, pas 4 → 2 (pas de double poussée)
  });

  it("elle est ATTAQUÉE et survit : son agresseur recule (l'échange est mutuel)", () => {
    const s = run(patty(), foe(), "enemy");
    expect(byId(s, 2)!.position.x).toBe(3);
  });

  it("elle repousse même à 0 AT (c'est l'attaque qui compte, pas les dégâts)", () => {
    const s = run(patty({ currentAttack: 0, baseAttack: 0 }), foe(), "enemy");
    expect(byId(s, 2)!.position.x).toBe(3);
  });

  it("elle repousse même en MOURANT (coups simultanés : son attaque est partie)", () => {
    const s = run(patty({ currentLife: 1 }), foe({ currentAttack: 5 }), "enemy");
    expect(byId(s, 1)).toBeUndefined();                       // elle est morte
    const slid = s.log.some((e) => e.type === "FIGHT_OBJECT_MOVED" && e.movementType === "SLIDE" && e.instanceId === 2);
    expect(slid).toBe(true);                                  // ... and still pushed it back
  });

  it("tuée par une INITIATIVE avant de frapper : AUCUNE poussée", () => {
    const s = run(patty({ currentLife: 1 }), foe({ currentAttack: 5, properties: new Set(["FirstStrike"]) }), "enemy");
    expect(byId(s, 1)).toBeUndefined();
    const slid = s.log.some((e) => e.type === "FIGHT_OBJECT_MOVED" && e.movementType === "SLIDE");
    expect(slid).toBe(false);
  });

  it("face à une INITIATIVE mais SURVIVANTE : elle riposte, donc elle repousse", () => {
    const s = run(patty({ currentLife: 5, baseLife: 5 }), foe({ currentAttack: 1, properties: new Set(["FirstStrike"]) }), "enemy");
    expect(byId(s, 2)!.position.x).toBe(3);
  });

  // "une patty ceriz réduite au silence ne repousse pas, vu que son effet est silence". The push is its
  // ability, and silence cancels it, like any other.
  it("SILENCÉE, elle ne repousse plus, au TIR", () => {
    const s = run(patty({ position: { x: 6, y: 2 }, hasAttacked: false, silenced: true }), foe({ currentAttack: 0, baseMovement: 0, movementLeft: 0 }), "ally");
    expect(byId(s, 2)!.position.x).toBe(4); // pas de recul
  });

  it("SILENCÉE, elle ne repousse plus, au CONTACT", () => {
    const s = run(patty({ hasAttacked: false, silenced: true }), foe({ currentAttack: 0, baseMovement: 0, movementLeft: 0 }), "ally");
    expect(byId(s, 2)!.position.x).toBe(4);
  });

  it("SILENCÉE et ATTAQUÉE : son agresseur ne recule pas non plus", () => {
    const s = run(patty({ silenced: true }), foe(), "enemy");
    expect(byId(s, 2)!.position.x).toBe(4);
  });

  it("le silence de l'AGRESSEUR n'empêche pas une Patty non silencée de le repousser", () => {
    const s = run(patty(), foe({ silenced: true }), "enemy");
    expect(byId(s, 2)!.position.x).toBe(3);
  });
});

describe("Patty Ceriz #31 : une poussée dégage la voie, elle ne fige pas l'avance", () => {
  // The engage rule is about being blocked, not about having struck: if Patty's push opens the way,
  // the move goes on with the remaining PM and a new fight can start one cell further, in both
  // directions.
  const moves = (s: ReturnType<typeof scenario>, id: number) =>
    s.log.filter((e) => e.type === "FIGHT_OBJECT_MOVED" && e.instanceId === id);
  const hits = (s: ReturnType<typeof scenario>, from: number) =>
    s.log.filter((e) => e.type === "DAMAGE" && e.sourceInstanceId === from).length;

  it("un agresseur repoussé qui garde des PM repart et REDÉCLENCHE le combat", () => {
    const patty = mkCreature(1, "ally", { x: 5, y: 2 }, { cardId: 31, currentLife: 20, baseLife: 20, currentAttack: 1, baseAttack: 1, range: 3, baseMovement: 0, movementLeft: 0, hasAttacked: true });
    const foe = mkCreature(2, "enemy", { x: 2, y: 2 }, { cardId: 16, currentLife: 20, baseLife: 20, currentAttack: 1, baseAttack: 1, baseMovement: 3, movementLeft: 3, hasAttacked: false });
    const s = endTurn(withDecks({ ...scenario([patty, foe]), activeSide: "enemy" as const }));
    expect(hits(s, 2)).toBeGreaterThan(1);                                    // il a frappé Patty plusieurs fois
    expect(moves(s, 2).some((e) => e.movementType === "SLIDE")).toBe(true);   // il a bien été repoussé
    expect(moves(s, 2).some((e) => e.movementType === "WALK" && e.from.x === 3)).toBe(true); // et il est reparti
  });

  it("Patty qui commence son tour AU CONTACT frappe, repousse, AVANCE et rengage", () => {
    const patty = mkCreature(1, "ally", { x: 5, y: 2 }, { cardId: 31, currentLife: 20, baseLife: 20, currentAttack: 1, baseAttack: 1, range: 3, baseMovement: 3, movementLeft: 3, hasAttacked: false });
    const foe = mkCreature(2, "enemy", { x: 4, y: 2 }, { cardId: 16, currentLife: 20, baseLife: 20, currentAttack: 1, baseAttack: 1, baseMovement: 0, movementLeft: 0, hasAttacked: true });
    const s = endTurn(withDecks({ ...scenario([patty, foe]), activeSide: "ally" as const }));
    expect(hits(s, 1)).toBeGreaterThan(1);            // it engaged again after each push
    expect(byId(s, 1)!.position.x).toBeLessThan(5);   // elle a bien avancé
    expect(byId(s, 2)!.position.x).toBeLessThan(4);   // et l'a repoussé à chaque fois
  });
});

// "lilotte does not work with seeds, she should tho", then "graine doit activer angèle, crapaud, tama
// hok, emma zone, etc".
// Planting a seed is playing a card, and a spell card (same reading as for the cost, where Joris
// taxes it). So the ON_PLAY reactors with no filter (#444 Lilotte, #1854 Ertan Knapz, #382 Miss Nuit)
// and those filtered on "sort" (#1257 Angèle, #238 Crapaud Mufle, #878 Tama Hok, #1866 Emma Zone,
// #466 Magislek) fire. Only the "invocation" filters (#446 Piou, #569 Lilotte), and family/rarity,
// stay silent.
describe("Planter une graine = jouer une carte", () => {
  const plantable = (creatures: CreatureInstance[], n = 2, ap = 5) => {
    const base = { ...scenario(creatures), prisms: [], seeds: [] };
    return { ...base, players: { ...base.players, ally: { ...base.players.ally, seedReserve: n, ap, maxAp: ap } } };
  };

  it("#444 Lilotte charge de 1 case quand vous plantez une graine", () => {
    const lilotte = mkCreature(1, "ally", { x: 5, y: 2 }, { cardId: 444, baseMovement: 3, movementLeft: 0, triggers: card(444).triggers ?? [] });
    const s = plantSeed(plantable([lilotte]), "ally", { x: 7, y: 0 });
    expect(s.seeds).toHaveLength(1);
    expect(byId(s, 1)!.position).toEqual({ x: 4, y: 2 }); // 5 → 4, une case vers l'objectif
  });

  it("chaque graine plantée la fait charger à nouveau", () => {
    const lilotte = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 444, baseMovement: 3, movementLeft: 0, triggers: card(444).triggers ?? [] });
    const s1 = plantSeed(plantable([lilotte]), "ally", { x: 7, y: 0 });
    const s2 = plantSeed(s1, "ally", { x: 7, y: 1 });
    expect(s2.seeds).toHaveLength(2);
    expect(byId(s2, 1)!.position.x).toBe(4); // 6 → 5 → 4
  });

  it("une plantation REFUSÉE (réserve vide, case illégale) ne déclenche rien", () => {
    const lilotte = mkCreature(1, "ally", { x: 5, y: 2 }, { cardId: 444, baseMovement: 3, movementLeft: 0, triggers: card(444).triggers ?? [] });
    const vide = plantSeed(plantable([lilotte], 0), "ally", { x: 7, y: 0 });
    expect(byId(vide, 1)!.position.x).toBe(5);
    const horsCamp = plantSeed(plantable([lilotte]), "ally", { x: 3, y: 0 }); // territoire adverse
    expect(horsCamp.seeds ?? []).toHaveLength(0);
    expect(byId(horsCamp, 1)!.position.x).toBe(5);
  });

  it("une graine EST un sort : Crapaud Mufle #238 gagne +1 AT et +1 AR", () => {
    const crapaud = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 238, currentAttack: 2, baseAttack: 2, armor: 0, triggers: card(238).triggers ?? [] });
    const s = plantSeed(plantable([crapaud]), "ally", { x: 7, y: 0 });
    expect(s.seeds).toHaveLength(1);
    expect(byId(s, 1)!.currentAttack).toBe(3);
    expect(byId(s, 1)!.armor).toBe(1);
  });

  it("une graine EST un sort : Tama Hok #878 en MEURT", () => {
    const tama = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 878, currentLife: 6, baseLife: 6, triggers: card(878).triggers ?? [] });
    const s = plantSeed(plantable([tama]), "ally", { x: 7, y: 0 });
    expect(s.seeds).toHaveLength(1);
    expect(byId(s, 1)?.currentLife ?? 0).toBeLessThanOrEqual(0);
  });

  it("une graine EST un sort : Angèle #1257 soigne vos AUTRES invocations", () => {
    const angele = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 1257, triggers: card(1257).triggers ?? [] });
    const blesse = mkCreature(2, "ally", { x: 6, y: 0 }, { currentLife: 2, baseLife: 5 });
    const s = plantSeed(plantable([angele, blesse]), "ally", { x: 7, y: 0 });
    expect(s.seeds).toHaveLength(1);
    expect(byId(s, 2)!.currentLife).toBe(3);
  });

  it("une graine EST un sort : Emma Zone #1866 tire sur la première cible adverse", () => {
    const emma = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 1866, triggers: card(1866).triggers ?? [] });
    const cible = mkCreature(2, "enemy", { x: 4, y: 2 }, { currentLife: 5, baseLife: 5 });
    const s = plantSeed(plantable([emma, cible]), "ally", { x: 7, y: 0 });
    expect(s.seeds).toHaveLength(1);
    expect(byId(s, 2)!.currentLife).toBeLessThan(5);
  });

  it("une graine n'est PAS une invocation : Lilotte #569 adverse ne charge pas", () => {
    const l569 = mkCreature(1, "enemy", { x: 4, y: 2 }, { cardId: 569, baseMovement: 3, movementLeft: 0, triggers: card(569).triggers ?? [] });
    const s = plantSeed(plantable([l569]), "ally", { x: 7, y: 0 });
    expect(s.seeds).toHaveLength(1);
    expect(byId(s, 1)!.position.x).toBe(4); // pas de charge
  });

  it("#382 Miss Nuit : l'adversaire qui plante lui remplit sa réserve de PA", () => {
    const nuit = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 382, triggers: card(382).triggers ?? [] });
    const base = { ...scenario([nuit]), prisms: [], seeds: [], activeSide: "enemy" as const };
    const st = { ...base, players: { ...base.players, enemy: { ...base.players.enemy, seedReserve: 1, ap: 5, maxAp: 5 } } };
    const before = st.players.ally.apReserve ?? 0;
    const s = plantSeed(st, "enemy", { x: 2, y: 0 });
    expect(s.seeds).toHaveLength(1);
    expect(s.players.ally.apReserve ?? 0).toBe(before + 1);
  });
});

describe("Ligne de tir bloquée par TOUTE créature", () => {
  // A shooter never fires over a creature, allied or enemy. Ally in front: no shot; the shooter
  // advances and stops behind it.
  it("un allié entre le tireur et le Dofus : PAS de tir, le tireur s'arrête derrière l'allié", () => {
    card(354); // Clara Byne, Portée 2
    const shooter = mkCreature(21, "ally", { x: 3, y: 2 }, {
      cardId: 354, currentLife: 2, baseLife: 2, currentAttack: 3, baseAttack: 3,
      range: 2, movementLeft: 2, baseMovement: 2,
    });
    const wall = mkCreature(22, "ally", { x: 2, y: 2 }, { currentAttack: 1, currentLife: 3, baseMovement: 0, movementLeft: 0, hasAttacked: true });
    const base0 = { ...scenario([shooter, wall]), prisms: [] };
    const dofuses = base0.dofuses.map((d) =>
      d.owner === "enemy" && d.position.x === 0 && d.position.y === 2 ? { ...d, currentLife: 3 } : d);
    const s = endTurn(withDecks({ ...base0, dofuses, players: { ...base0.players, ally: { ...base0.players.ally, hand: [], handCostMods: [] } } }));
    // the Dofus was not hit (the ally blocks the line)
    const dof = s.dofuses.find((d) => d.owner === "enemy" && d.position.y === 2)!;
    expect(dof.currentLife).toBe(3);
    // the shooter did not go past the ally: it stopped right behind it
    const sh = s.creatures.find((c) => c.instanceId === 21)!;
    expect(sh.position.x).toBe(3); // l'allié en (2,2) bloque déjà la case suivante
    expect(sh.hasAttacked).toBe(false); // aucun tir effectué
  });

  it("une créature ENNEMIE devant bloque aussi le tir vers le Dofus derrière elle (c'est elle la cible)", () => {
    card(354);
    const shooter = mkCreature(23, "ally", { x: 3, y: 1 }, {
      cardId: 354, currentLife: 2, baseLife: 2, currentAttack: 3, baseAttack: 3,
      range: 2, movementLeft: 0, baseMovement: 1,
    });
    const blocker = mkCreature(24, "enemy", { x: 2, y: 1 }, { currentAttack: 1, currentLife: 5, baseMovement: 0, movementLeft: 0 });
    const base0 = { ...scenario([shooter, blocker]), prisms: [] };
    const dofuses = base0.dofuses.map((d) =>
      d.owner === "enemy" && d.position.x === 0 && d.position.y === 1 ? { ...d, currentLife: 5 } : d);
    const s = endTurn(withDecks({ ...base0, dofuses, players: { ...base0.players, ally: { ...base0.players.ally, hand: [], handCostMods: [] } } }));
    // the creature took the shot, not the Dofus behind
    const dof = s.dofuses.find((d) => d.owner === "enemy" && d.position.y === 1)!;
    expect(dof.currentLife).toBe(5);
    expect(s.creatures.find((c) => c.instanceId === 24)!.currentLife).toBe(2); // 5 - 3
  });
});

// Reported: "Crasslek n'a pas infligé de dégât avec l'overdraw d'une shava". A card that goes back to
// the hand on its death and that a full hand sends to the discard is really "défaussée car la main
// d'un des joueurs est pleine". The 4 return paths (RecoverSelfToHand, ReturnToHandOnDeath,
// RecoverToHandOnDofusKill) must feed Crasslek #355 and Nain Patraque #965, exactly like the draw
// burn.
describe("Burn « main pleine » d'une remontée en main à la mort", () => {
  const fullBothHands = <T extends ReturnType<typeof scenario>>(sc: T) => {
    const full = Array(MAX_HAND).fill(16);
    return {
      ...sc,
      players: {
        ally: { ...sc.players.ally, hand: [...full], handCostMods: full.map(() => 0) },
        enemy: { ...sc.players.enemy, hand: [...full], handCostMods: full.map(() => 0) },
      },
    };
  };

  it("Shava Shavien #367 brûlée par la main pleine : Crasslek #355 tire sur les invocations adverses", () => {
    card(367); card(355);
    const shava = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 367, currentLife: 0, baseLife: 3 });
    const crass = mkCreature(2, "ally", { x: 8, y: 0 }, { cardId: 355 });
    const foe = mkCreature(3, "enemy", { x: 3, y: 1 }, { currentLife: 3, baseLife: 3 });
    const mine = mkCreature(4, "ally", { x: 7, y: 1 }, { currentLife: 2, baseLife: 2 });
    const base = fullBothHands(scenario([shava, crass, foe, mine]));
    const s = resolveDeathsAndWin(base, base.creatures, base.dofuses, [], new Set());
    expect(s.players.ally.hand).toHaveLength(MAX_HAND); // la main n'a pas bougé
    expect(s.players.enemy.hand).toHaveLength(MAX_HAND);
    expect(s.players.ally.discard).toContain(367);      // la Shava a bien brûlé
    expect(byId(s, 3)!.currentLife).toBe(2);            // 3 − 1 : Crasslek a tiré
    expect(byId(s, 4)!.currentLife).toBe(2);            // alliée du Crasslek : intacte
  });

  it("Shava #367 qui rentre dans une main NON pleine ne déclenche RIEN (pas de burn)", () => {
    card(367); card(355);
    const shava = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 367, currentLife: 0, baseLife: 3 });
    const crass = mkCreature(2, "ally", { x: 8, y: 0 }, { cardId: 355 });
    const foe = mkCreature(3, "enemy", { x: 3, y: 1 }, { currentLife: 3, baseLife: 3 });
    const sc = scenario([shava, crass, foe]);
    const base = { ...sc, players: {
      ally: { ...sc.players.ally, hand: [], handCostMods: [] },
      enemy: { ...sc.players.enemy, hand: [], handCostMods: [] },
    } };
    const s = resolveDeathsAndWin(base, base.creatures, base.dofuses, [], new Set());
    expect(byId(s, 3)!.currentLife).toBe(3); // aucune carte brûlée → aucun dégât
  });

  it("une Renisurrection #483 brûlée par la main pleine donne +1 AT/+1 AR au Nain Patraque #965", () => {
    card(965);
    const dying = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 612, currentLife: 0, baseLife: 4, properties: new Set(["ReturnToHandOnDeath"]) });
    const nain = mkCreature(2, "ally", { x: 8, y: 0 }, { cardId: 965, currentAttack: 2, baseAttack: 2, armor: 0 });
    const base = fullBothHands(scenario([dying, nain]));
    const s = resolveDeathsAndWin(base, base.creatures, base.dofuses, [], new Set());
    expect(s.players.ally.discard).toContain(612); // brûlée
    const n = byId(s, 2)!;
    expect(n.currentAttack).toBe(3); // 2 + 1
    expect(n.armor).toBe(1);         // 0 + 1
  });

  it("deux remontées brûlées dans la même salve = deux burns (Crasslek inflige 2)", () => {
    card(355);
    const a = mkCreature(1, "ally", { x: 6, y: 2 }, { cardId: 612, currentLife: 0, baseLife: 4, properties: new Set(["ReturnToHandOnDeath"]) });
    const b = mkCreature(2, "ally", { x: 6, y: 3 }, { cardId: 613, currentLife: 0, baseLife: 4, properties: new Set(["ReturnToHandOnDeath"]) });
    const crass = mkCreature(3, "ally", { x: 8, y: 0 }, { cardId: 355 });
    const foe = mkCreature(4, "enemy", { x: 3, y: 1 }, { currentLife: 5, baseLife: 5 });
    const base = fullBothHands(scenario([a, b, crass, foe]));
    const s = resolveDeathsAndWin(base, base.creatures, base.dofuses, [], new Set());
    expect(byId(s, 4)!.currentLife).toBe(3); // 5 − 2
  });
});

// Reported: "mot reconstituant ne fonctionne pas avec tsutsu". Replay: Mot Reconstituant #491 heals
// its own Dofus 3 → 5 while its Sangsuce Tsu Tsu #24 is in play. "TOUS les soins deviennent des
// dégâts", and the Dofus are no exception.
describe("Sangsuce Tsu Tsu #24 : les soins de DOFUS deviennent aussi des dégâts", () => {
  const dofusAtTest = (s: ReturnType<typeof playCard>, x: number, y: number) =>
    s.dofuses.find((d) => d.position.x === x && d.position.y === y)!.currentLife;
  const withSangsuce = (owner: "ally" | "enemy", dofusLife: number) => {
    card(24); card(491);
    const sang = mkCreature(1, owner, { x: owner === "ally" ? 8 : 1, y: 3 }, { cardId: 24, properties: new Set(["HealingsDoDamageInstead"]) });
    return { ...scenario([sang], 491), prisms: [], dofuses: [
      { position: { x: 9, y: 2 }, owner: "ally" as const, currentLife: dofusLife, kind: "real" as const },
      { position: { x: 0, y: 2 }, owner: "enemy" as const, currentLife: dofusLife, kind: "real" as const },
    ] };
  };

  it("#491 sur son PROPRE Dofus blessé le BLESSE de 2 au lieu de le soigner", () => {
    const s = playCard(withSangsuce("ally", 3), card(491), { x: 9, y: 2 });
    expect(dofusAtTest(s, 9, 2)).toBe(1); // 3 − 2, et non 3 + 2
    expect(s.log.some((e) => e.type === "DOFUS_LIFE_HEALED")).toBe(false);
  });

  it("#491 sur le Dofus ADVERSE lui inflige 2 (le combo)", () => {
    const s = playCard(withSangsuce("ally", 5), card(491), { x: 0, y: 2 });
    expect(dofusAtTest(s, 0, 2)).toBe(3); // 5 − 2
  });

  it("une Sangsuce ADVERSE retourne le soin aussi (les 2 camps, comme pour les invocations)", () => {
    const s = playCard(withSangsuce("enemy", 4), card(491), { x: 9, y: 2 });
    expect(dofusAtTest(s, 9, 2)).toBe(2); // 4 − 2
  });

  it("un Dofus PLEIN prend quand même les dégâts (le soin n'est plus un no-op de surplus)", () => {
    const s = playCard(withSangsuce("ally", 5), card(491), { x: 9, y: 2 });
    expect(dofusAtTest(s, 9, 2)).toBe(3); // 5 − 2 : plus de plafond qui absorbe
  });

  it("sans Sangsuce, #491 soigne normalement (non-régression)", () => {
    card(491);
    const s = playCard({ ...scenario([], 491), prisms: [], dofuses: [
      { position: { x: 9, y: 2 }, owner: "ally" as const, currentLife: 3, kind: "real" as const },
    ] }, card(491), { x: 9, y: 2 });
    expect(dofusAtTest(s, 9, 2)).toBe(5); // 3 + 2
  });
});

// Reported: "je crois avoir gagné qu'un PA alors que la momie a été frappée 2x". The rule: one hit =
// one contre-coup. The surviving case followed it (n hits → n triggers); the dead case lost every hit
// except the last one.
describe("CONTRE COUP : une victime frappée n fois avant de mourir en encaisse n", () => {
  // Each Disciple de l'Agonie #1163 deals 1 to the enemy invocations at FIN DU TOUR.
  const endTurnWith = (momieLife: number, disciples: number) => {
    card(360); card(1163);
    const momie = mkCreature(1, "ally", { x: 5, y: 1 }, { cardId: 360, currentLife: momieLife, baseLife: momieLife, triggers: card(360).triggers ?? [] });
    const cs = [momie];
    for (let i = 0; i < disciples; i++) {
      cs.push(mkCreature(10 + i, "enemy", { x: 2, y: i }, { cardId: 1163, currentLife: 3, baseLife: 3, triggers: card(1163).triggers ?? [], movementLeft: 0, baseMovement: 0 }));
    }
    return endTurn({ ...scenario(cs), activeSide: "enemy" as const });
  };

  it("Momie #360 à 2 PV tuée par le 2e coup rend quand même 2 PA (1 par coup)", () => {
    const s = endTurnWith(2, 2);
    expect(byId(s, 1)).toBeUndefined();        // elle meurt
    expect(s.players.ally.apReserve).toBe(2);  // … mais les DEUX coups ont payé
  });

  it("Momie à 3 PV tuée par le 3e coup rend 3 PA", () => {
    expect(endTurnWith(3, 3).players.ally.apReserve).toBe(3);
  });

  it("Momie tuée dès le PREMIER coup n'en rend qu'1 (les suivants ne la touchent plus)", () => {
    const s = endTurnWith(1, 2);
    expect(byId(s, 1)).toBeUndefined();
    expect(s.players.ally.apReserve).toBe(1);
  });

  it("non-régression : une Momie qui SURVIT encaisse toujours 1 PA par coup", () => {
    expect(endTurnWith(5, 1).players.ally.apReserve).toBe(1);
    expect(endTurnWith(5, 3).players.ally.apReserve).toBe(3);
  });
});

// Reported: "je n'ai pas pioché à la mort de Necrom". "necrom l'ancien fait piocher à sa mort": it is
// a Sadida, so "quand un de vos Sadidas meurt" applies to itself. A targeted exception: the other
// MORT ALLIÉE reactors still have to be alive.
describe("Necrom l'Ancien #411 : sa PROPRE mort le fait piocher", () => {
  const necrom = (o: Record<string, unknown> = {}) =>
    mkCreature(1, "ally", { x: 5, y: 2 }, { cardId: 411, currentLife: 0, baseLife: 6, triggers: card(411).triggers ?? [], ...o });
  const withDeck = (cs: ReturnType<typeof mkCreature>[]) => {
    const sc = scenario(cs);
    return { ...sc, players: { ...sc.players, ally: { ...sc.players.ally, hand: [], handCostMods: [], deck: [16, 16, 16], deckCostMods: [0, 0, 0] } } };
  };

  it("Necrom qui meurt pioche 1 carte", () => {
    card(411);
    const base = withDeck([necrom()]);
    const s = resolveDeathsAndWin(base, base.creatures, base.dofuses, [], new Set());
    expect(byId(s, 1)).toBeUndefined();          // il est bien mort
    expect(s.players.ally.hand).toHaveLength(1); // … et a pioché
    expect(s.players.ally.deck).toHaveLength(2);
  });

  it("il pioche AUSSI quand c'est un autre Sadida qui meurt (comportement d'origine intact)", () => {
    card(411); card(821);
    const alive = necrom({ currentLife: 6 });
    const peer = mkCreature(2, "ally", { x: 6, y: 2 }, { cardId: 821, currentLife: 0, baseLife: 3 });
    const base = withDeck([alive, peer]);
    const s = resolveDeathsAndWin(base, base.creatures, base.dofuses, [], new Set());
    expect(s.players.ally.hand).toHaveLength(1);
    expect(byId(s, 1)!.currentAttack).toBe(3); // vivant, il gagne bien son +1 AT (2 → 3)
  });

  it("une capture (perce-mur) n'est pas une mort : aucune pioche", () => {
    card(411);
    const base = withDeck([necrom()]);
    const s = resolveDeathsAndWin(base, base.creatures, base.dofuses, [], new Set([1]));
    expect(s.players.ally.hand).toHaveLength(0);
  });

  it("l'exception reste CIBLÉE : un autre réacteur MORT ALLIÉE ne se déclenche pas sur sa propre mort", () => {
    // Bébé Phorreur #1478 ("quand un PHORREUR allié meurt") is a Phorreur; with no explicit rule it keeps
    // the survival requirement.
    card(1478);
    const bebe = mkCreature(1, "ally", { x: 5, y: 2 }, { cardId: 1478, currentLife: 0, baseLife: 3, triggers: card(1478).triggers ?? [] });
    const base = withDeck([bebe]);
    const s = resolveDeathsAndWin(base, base.creatures, base.dofuses, [], new Set());
    expect(s.players.ally.hand).toHaveLength(0);
  });
});

// "rodeur sylvestre doit invoquer une graine devant lui, et sur les cases adjacentes de cette graine
// sur la même rangée, ça en fait 3 en tout". The rangée is the vertical line: the pattern is the
// column in front, not the straight row.
describe("Rôdeur Sylvestre #907 : 3 graines sur la RANGÉE devant lui", () => {
  const seedsOf = (s: ReturnType<typeof scenario>) =>
    (s.seeds ?? []).map((sd) => `${sd.position.x},${sd.position.y}`).sort();

  it("allié au milieu : la case devant + ses 2 voisines de la même rangée", () => {
    card(907);
    const rod = mkCreature(1, "ally", { x: 5, y: 2 }, { cardId: 907, triggers: card(907).triggers ?? [] });
    const s = runTrigger({ ...scenario([rod]), seeds: [] }, "APPARITION", 1);
    expect(seedsOf(s)).toEqual(["4,1", "4,2", "4,3"]);
    expect((s.seeds ?? []).every((sd) => sd.owner === "ally")).toBe(true);
  });

  it("côté ennemi : même motif, colonne de l'autre côté", () => {
    card(907);
    const rod = mkCreature(1, "enemy", { x: 3, y: 2 }, { cardId: 907, triggers: card(907).triggers ?? [] });
    const s = runTrigger({ ...scenario([rod]), seeds: [] }, "APPARITION", 1);
    expect(seedsOf(s)).toEqual(["4,1", "4,2", "4,3"]);
    expect((s.seeds ?? []).every((sd) => sd.owner === "enemy")).toBe(true);
  });

  it("au BORD du plateau il n'y a qu'une voisine : 2 graines seulement", () => {
    card(907);
    const rod = mkCreature(1, "ally", { x: 5, y: 0 }, { cardId: 907, triggers: card(907).triggers ?? [] });
    const s = runTrigger({ ...scenario([rod]), seeds: [] }, "APPARITION", 1);
    expect(seedsOf(s)).toEqual(["4,0", "4,1"]);
  });

  it("une case OCCUPÉE est sautée (il en tombe moins de 3)", () => {
    card(907);
    const rod = mkCreature(1, "ally", { x: 5, y: 2 }, { cardId: 907, triggers: card(907).triggers ?? [] });
    const blocker = mkCreature(2, "enemy", { x: 4, y: 2 }, {});
    const s = runTrigger({ ...scenario([rod, blocker]), seeds: [] }, "APPARITION", 1);
    expect(seedsOf(s)).toEqual(["4,1", "4,3"]);
  });
});

// "toute créature qui marche sur un buisson le détruit".
describe("Buisson : piétiné par n'importe quelle créature, il est détruit", () => {
  const walkOver = (bushOwner: "ally" | "enemy") => {
    const walker = mkCreature(1, "ally", { x: 5, y: 2 }, { currentAttack: 0, baseAttack: 0, baseMovement: 3, movementLeft: 3, hasAttacked: false });
    const sc = scenario([walker]);
    return endTurn(withDecks({ ...sc, prisms: [], bushes: [{ position: { x: 4, y: 2 }, owner: bushOwner }] }));
  };

  it("un buisson ADVERSE sur son chemin est détruit", () => {
    expect(walkOver("enemy").bushes ?? []).toHaveLength(0);
  });

  it("son PROPRE buisson l'est aussi (aucune exception de camp)", () => {
    expect(walkOver("ally").bushes ?? []).toHaveLength(0);
  });

  it("un buisson que personne ne piétine survit", () => {
    const walker = mkCreature(1, "ally", { x: 5, y: 2 }, { currentAttack: 0, baseAttack: 0, baseMovement: 3, movementLeft: 3, hasAttacked: false });
    const sc = scenario([walker]);
    const s = endTurn(withDecks({ ...sc, prisms: [], bushes: [{ position: { x: 4, y: 4 }, owner: "ally" as const }] }));
    expect(s.bushes ?? []).toHaveLength(1);
  });
});

// Reported: "Gemene n'a pas avancé après s'être fait Miranda". An invocation whose control is taken
// during a turn must advance at the end of that turn. PM are only given back at the start of a turn,
// and only to creatures already in the active camp, so a seized creature arrives with 0 PM (spent
// during the opponent's turn). Miranda #107 (ControlAround) must give it the "ready" state, as
// TakeControl already does.
describe("Miranda #107 : une invocation saisie avance dès la fin de ce tour", () => {
  // The target arrives with 0 PM and hasAttacked, as after an enemy end-of-turn advance.
  const setup = () => {
    card(107);
    const miranda = mkCreature(1, "ally", { x: 5, y: 2 }, { cardId: 107, triggers: card(107).triggers ?? [], effects: [] });
    const seized = mkCreature(2, "enemy", { x: 4, y: 2 }, { currentAttack: 0, baseAttack: 0, baseMovement: 2, movementLeft: 0, hasAttacked: true });
    return { ...scenario([miranda, seized]), prisms: [] };
  };

  it("la saisie retrouve ses PM à l'instant du changement de camp", () => {
    const s = runTrigger(setup(), "APPARITION", 1);
    const g = byId(s, 2)!;
    expect(g.owner).toBe("ally");
    expect(g.movementLeft).toBe(2);   // PM rendus (baseMovement)
    expect(g.hasAttacked).toBe(false); // et prête à combattre
  });

  it("… et elle AVANCE effectivement à la fin de ce tour-là", () => {
    const s = endTurn(withDecks(runTrigger(setup(), "APPARITION", 1)));
    expect(byId(s, 2)!.position.x).toBe(2); // 4 → 2: it walked its 2 PM toward the enemy camp
  });
});

// "le coup de grâce doit avoir lieu au moment où la truche tue une invocation, et donc ça peut avoir
// lieu pendant qu'elle avance. Si ça a lieu pendant qu'elle avance, alors s'il lui reste des PM, elle
// finit par consommer ses PM dans l'autre sens."
// Example: 3 PM, it moves 2 cells, meets an opponent, kills it, the switch goes against it → it turns
// around and moves one cell.
describe("Truche Foldingue #434 : la bascule tombe AU kill, et elle repart dans l'autre sens", () => {
  // Truche at x=7, prey at x=4: 2 steps (7→6→5), fight at 5 against 4, 1 PM left.
  // The Ecaflip Trucage expires before the movement phase: the draw cannot be forced here, so the seed
  // is fixed. On the stream used for switches, rng=2 gives pile (switch) and rng=0 face.
  const PILE = 2, FACE = 0;
  const setup = (opts: { rng: number; roi?: boolean }) => {
    card(434); if (opts.roi) card(282);
    const truche = mkCreature(1, "ally", { x: 7, y: 2 }, { cardId: 434, currentLife: 5, baseLife: 5, currentAttack: 5, baseAttack: 5, baseMovement: 3, movementLeft: 3, hasAttacked: false, triggers: card(434).triggers ?? [] });
    const proie = mkCreature(2, "enemy", { x: 4, y: 2 }, { currentLife: 1, baseLife: 1, currentAttack: 0, baseAttack: 0, baseMovement: 0, movementLeft: 0, hasAttacked: true });
    const cs = [truche, proie];
    if (opts.roi) cs.push(mkCreature(3, "ally", { x: 8, y: 4 }, { cardId: 282, baseMovement: 0, movementLeft: 0, hasAttacked: true }));
    return withDecks({ ...scenario(cs), prisms: [], activeSide: "ally" as const, rng: opts.rng });
  };
  const movesOf = (s: ReturnType<typeof scenario>) =>
    s.log.filter((e) => e.type === "FIGHT_OBJECT_MOVED" && e.instanceId === 1)
      .map((e) => `${(e as { from: { x: number } }).from.x}>${(e as { to: { x: number } }).to.x}`).join(",");
  const teamChanges = (s: ReturnType<typeof scenario>) =>
    s.log.filter((e) => e.type === "SUMMONING_CHANGED_TEAM").length;

  it("elle bascule au kill, se retourne et dépense son PM restant à l'envers", () => {
    const s = endTurn(setup({ rng: PILE }));
    expect(movesOf(s)).toBe("7>6,6>5,5>6"); // 2 cases en avant, kill, puis 1 case EN ARRIÈRE
    const t = byId(s, 1)!;
    expect(t.owner).toBe("enemy");   // elle a changé de camp
    expect(t.position.x).toBe(6);
    // The remaining PM was used during the advance (see the 3rd step above); at the end it is already
    // refreshed, since its new owner's turn has started.
    expect(t.movementLeft).toBe(t.baseMovement);
    expect(byId(s, 2)).toBeUndefined(); // the prey is dead: the coup de grâce did happen
  });

  it("le pile ou face n'est joué QU'UNE fois (pas de second tirage après l'avance)", () => {
    expect(teamChanges(endTurn(setup({ rng: PILE })))).toBe(1);
  });

  it("branche FACE : elle reste dans son camp et continue en avant (kill-and-continue)", () => {
    const s = endTurn(setup({ rng: FACE }));
    expect(teamChanges(s)).toBe(0);
    expect(byId(s, 1)!.owner).toBe("ally");
    expect(movesOf(s)).toBe("7>6,6>5,5>4"); // elle poursuit sa route vers l'adversaire
  });

  it("Roi des Truches #282 dans son camp : aucune bascule, même sur un pile", () => {
    const s = endTurn(setup({ rng: PILE, roi: true }));
    expect(teamChanges(s)).toBe(0);
    expect(byId(s, 1)!.owner).toBe("ally");
  });
});
